export async function loadKernel(require, db, instanceId) {
  /** Event bus with hierarchical type dispatch.
   * Subscribing to a parent event type (e.g., ITEM_EVENT) receives all child events. */
  class EventBus {
    constructor(kernel) {
      this.kernel = kernel;  // Reference for eventTypeCache access
      this.listeners = new Map();
      this.stickyEvents = new Map(); // eventTypeId → last event (for replay to late subscribers)
    }

    /** Get the stored payload for a sticky event, or null if not emitted yet.
     * @param {string} eventTypeId - Event type GUID
     * @returns {Object|null} The stored event object, or null
     */
    getStickyEvent(eventTypeId) {
      return this.stickyEvents.get(eventTypeId) || null;
    }

    /** Subscribe to an event type. Returns an unsubscribe function.
     * @param {string} eventTypeId - Event type GUID to subscribe to
     * @param {Function} handler - Called with event object {type, content, timestamp}
     * @returns {Function} Unsubscribe function
     */
    on(eventTypeId, handler) {
      // Subscribe to an event type GUID
      // Subscribing to a parent type (e.g., ITEM_EVENT) will receive all child events
      if (!this.listeners.has(eventTypeId)) {
        this.listeners.set(eventTypeId, new Set());
      }
      this.listeners.get(eventTypeId).add(handler);
      return () => this.off(eventTypeId, handler);
    }

    /** Unsubscribe a handler from an event type.
     * @param {string} eventTypeId - Event type GUID
     * @param {Function} handler - The handler to remove
     */
    off(eventTypeId, handler) {
      const handlers = this.listeners.get(eventTypeId);
      if (handlers) {
        handlers.delete(handler);
      }
    }

    /** Emit an event, dispatching to all matching subscribers (including parent types).
     * @param {Object} event - Event object with {type: eventTypeGUID, content: {...}}
     */
    /** Emit an event. Pass { sticky: true } as options to store the payload for late replay.
     * @param {Object} event - Event object with {type, content}
     * @param {Object} [options] - { sticky: boolean }
     */
    emit(event, options) {
      const eventWithTimestamp = {
        ...event,
        timestamp: event.timestamp || Date.now()
      };

      if (options?.sticky) {
        this.stickyEvents.set(event.type, eventWithTimestamp);
      }

      const emittedType = event.type;

      // Get the type chain for this event (includes ancestors)
      // If cache not ready yet (during early boot), just dispatch to exact matches
      const cacheEntry = this.kernel?.eventTypeCache?.get(emittedType);
      const typeChain = cacheEntry?.ancestors || new Set([emittedType]);

      // Dispatch to all listeners whose subscribed type is in the emitted event's type chain
      for (const [subscribedType, handlers] of this.listeners) {
        if (typeChain.has(subscribedType)) {
          for (const handler of handlers) {
            try {
              const result = handler(eventWithTimestamp);
              // Handle async handlers - catch promise rejections
              if (result && typeof result.catch === 'function') {
                result.catch(e => {
                  console.error(`Async event handler error for ${subscribedType}:`, e);
                });
              }
            } catch (e) {
              console.error(`Event handler error for ${subscribedType}:`, e);
            }
          }
        }
      }
    }

    /** Get all event type GUIDs that have active listeners.
     * @returns {string[]} Array of event type GUIDs
     */
    /** Async emit — waits for all handlers to settle. Supports { sticky: true }.
     * @param {Object} event - Event object with {type, content}
     * @param {Object} [options] - { sticky: boolean }
     */
    async emitAsync(event, options) {
      const eventWithTimestamp = {
        ...event,
        timestamp: event.timestamp || Date.now()
      };

      if (options?.sticky) {
        this.stickyEvents.set(event.type, eventWithTimestamp);
      }

      const emittedType = event.type;
      const cacheEntry = this.kernel?.eventTypeCache?.get(emittedType);
      const typeChain = cacheEntry?.ancestors || new Set([emittedType]);

      const promises = [];
      for (const [subscribedType, handlers] of this.listeners) {
        if (typeChain.has(subscribedType)) {
          for (const handler of handlers) {
            try {
              const result = handler(eventWithTimestamp);
              if (result && typeof result.then === 'function') {
                promises.push(result);
              }
            } catch (e) {
              console.error(`Event handler error for ${subscribedType}:`, e);
            }
          }
        }
      }

      await Promise.allSettled(promises);
    }

    getRegisteredEvents() {
      return [...this.listeners.keys()];
    }
  }
// [BEGIN:SEED_IDS]
  // ID constants
  const IDS = {
    // Self-referential base type
    ITEM: "00000000-0000-0000-0000-000000000000",
    // Synonym for ITEM. Sometimes useful to have a distinct name in contexts where "item" is being used generically.
    ATOM: "00000000-0000-0000-0000-000000000000",
    // Type for defining types
    TYPE_DEFINITION: "11111111-0000-0000-0000-000000000000",
    // Base type for executable items
    CODE: "22222222-0000-0000-0000-000000000000",
    // Base type for kernel modules
    KERNEL_MODULE: "33333333-0000-0000-0000-000000000000",
    KERNEL_CORE: "33333333-1111-0000-0000-000000000000",
    KERNEL_STORAGE: "33333333-2222-0000-0000-000000000000",
    KERNEL_MODULE_SYSTEM: "33333333-4444-0000-0000-000000000000",
    KERNEL_SAFE_MODE: "33333333-7777-0000-0000-000000000000",
    KERNEL_STYLES: "33333333-8888-0000-0000-000000000000",
    // Base type for reusable code modules
    LIBRARY: "66666666-0000-0000-0000-000000000000",
    // Unified view system
    VIEW: "aaaaaaaa-0000-0000-0000-000000000000",
    DEFAULT_VIEW: "aaaaaaaa-1111-0000-0000-000000000000",
    // VIEW_SPEC removed - rendering system discovers by name
    // FIELD_VIEW removed - not used by kernel, userland items use the GUID directly
    // Event definition types
    EVENT_DEFINITION: "e0e00000-0000-0000-0000-000000000000"
  };

  // Event IDs - for subscribing and emitting events
  const EVENT_IDS = {
    // Base type (subscribe to this for ALL events)
    EVENT_DEFINITION: "e0e00000-0000-0000-0000-000000000000",

    // Event group types (subscribe to these for categories)
    ITEM_EVENT:   "e0e00000-0001-0000-0000-000000000000",
    SYSTEM_EVENT: "e0e00000-0002-0000-0000-000000000000",
    // VIEWPORT_EVENT removed - defined by userland viewport-manager

    // Specific item events
    ITEM_CREATED: "e0e00000-0001-0001-0000-000000000000",
    ITEM_UPDATED: "e0e00000-0001-0002-0000-000000000000",
    ITEM_DELETED: "e0e00000-0001-0003-0000-000000000000",

    // Specific system events
    SYSTEM_ERROR:         "e0e00000-0002-0001-0000-000000000000",
    SYSTEM_BOOT_COMPLETE: "e0e00000-0002-0002-0000-000000000000"
    // VIEWPORT_* events removed - defined by userland viewport-manager
  };
// [END:SEED_IDS]

  const { Storage } = await require(IDS.KERNEL_STORAGE);
  // KERNEL_VIEWPORT removed - viewport state now managed by userland viewport-manager
  const { ModuleSystem } = await require(IDS.KERNEL_MODULE_SYSTEM);
  const { SafeMode } = await require(IDS.KERNEL_SAFE_MODE);

  // parseSourceLocation, createElement — moved to viewport-rendering enrichAPI

  /** Sort items in dependency order for import (types before their instances).
   * Uses topological sort based on type and extends fields.
   * @param {Object[]} items - Items to sort
   * @returns {Object[]} Sorted items
   */
  function sortItemsForImport(items) {
    const itemMap = new Map(items.map(i => [i.id, i]));
    const itemIds = new Set(items.map(i => i.id));

    // Build dependency graph
    // dependsOn[A] = [B, C] means A depends on B and C (they must be saved first)
    const dependsOn = new Map();

    for (const item of items) {
      const deps = [];

      // Type dependency (required for validation)
      if (item.type && itemIds.has(item.type) && item.type !== item.id) {
        deps.push(item.type);
      }

      // Extends dependency (for completeness)
      if (item.extends && itemIds.has(item.extends) && item.extends !== item.id) {
        deps.push(item.extends);
      }

      dependsOn.set(item.id, deps);
    }

    // Topological sort using Kahn's algorithm
    // Build reverse graph: mustComeBefore[B] = [A, D] means B must come before A and D
    const mustComeBefore = new Map();
    const inDegree = new Map();

    for (const item of items) {
      inDegree.set(item.id, dependsOn.get(item.id).length);

      for (const dep of dependsOn.get(item.id)) {
        if (!mustComeBefore.has(dep)) mustComeBefore.set(dep, []);
        mustComeBefore.get(dep).push(item.id);
      }
    }

    // Start with items that have no dependencies in the import set
    const queue = [];
    for (const [id, degree] of inDegree) {
      if (degree === 0) queue.push(id);
    }

    const result = [];
    while (queue.length > 0) {
      const id = queue.shift();
      result.push(itemMap.get(id));

      for (const dependent of (mustComeBefore.get(id) || [])) {
        const newDegree = inDegree.get(dependent) - 1;
        inDegree.set(dependent, newDegree);
        if (newDegree === 0) {
          queue.push(dependent);
        }
      }
    }

    // Handle cycles: append remaining items (they may fail validation)
    if (result.length < items.length) {
      const resultIds = new Set(result.map(i => i.id));
      for (const item of items) {
        if (!resultIds.has(item.id)) {
          result.push(item);
        }
      }
      console.warn(`[import] Circular dependencies detected - some items may fail validation`);
    }

    return result;
  }

  /** Core kernel — manages storage, events, and the unified API. */
  class Kernel {
    constructor() {
      this.IDS = IDS;
      this.EVENT_IDS = EVENT_IDS;
      this.storage = new Storage(db, instanceId);
      // viewport instance removed - state managed by userland viewport-manager
      this.moduleSystem = new ModuleSystem(this);
      this.safeMode = new SafeMode(this);
      this.events = new EventBus(this);

      // Initialize module system event listeners for cache invalidation
      this.moduleSystem.initEventListeners();

      // currentRoot removed - managed by userland viewport-manager
      this._safeMode = false;
      this.debugMode = false;

      // Index of item IDs that have watches (for efficient event dispatch)
      this.watcherIndex = new Set();

      this.rootElement = document.createElement('div');
      this.rootElement.id = 'app';
      this.rootElement.innerHTML = '<div id="main-view"></div>';
    }

    /** Initialize the kernel: storage, seed items, event cache, watches, and first render. */
    async boot() {
      await this.storage.initialize();
      await this.ensureSeedItems();

      // Check for safe mode and debug mode
      const params = new URLSearchParams(window.location.search);
      this._safeMode = params.get('safe') === '1';
      this.debugMode = params.has('debug');

      // Hardcoded safe-mode escape hatch (Ctrl+Shift+S) - always works even if userland is broken
      if (!window._safeModeShortcut) {
        window._safeModeShortcut = (e) => {
          if (e.ctrlKey && e.shiftKey && e.key === 'S') {
            e.preventDefault();
            const params = new URLSearchParams(window.location.search);
            params.set('safe', '1');
            window.location.href = window.location.pathname + '?' + params.toString();
          }
        };
        document.addEventListener('keydown', window._safeModeShortcut);
      }

      // Always render safe mode as the default screen.
      // In normal boot, viewport-manager replaces it after boot-complete.
      // If no userland is present, safe mode stays visible for recovery.
      await this.applyStyles();
      this.safeMode.render(this.rootElement.querySelector('#main-view'));

      if (this._safeMode) {
        // Explicit safe mode — skip userland entirely
      } else {
        // REPL container is now created by userland repl-ui library via kernel:boot-complete

        // Global error handlers for uncaught errors and promise rejections
        if (!window._globalErrorHandler) {
          window._globalErrorHandler = (event) => {
            window.kernel?.captureError(event.error || new Error(event.message), {
              operation: 'uncaught',
              filename: event.filename,
              lineno: event.lineno,
              colno: event.colno
            });
          };
          window.addEventListener('error', window._globalErrorHandler);
        }

        if (!window._unhandledRejectionHandler) {
          window._unhandledRejectionHandler = (event) => {
            const error = event.reason instanceof Error
              ? event.reason
              : new Error(String(event.reason));
            window.kernel?.captureError(error, {
              operation: 'unhandled-rejection'
            });
          };
          window.addEventListener('unhandledrejection', window._unhandledRejectionHandler);
        }

        // Keyboard shortcuts are handled by userland keyboard-shortcuts library
        // Only safe-mode shortcut (Ctrl+Shift+S) remains hardcoded in kernel

        // Popstate handler removed - managed by userland viewport-manager

        // Build event type cache for hierarchical event dispatch (Phase 1 prep)
        await this.buildEventTypeCache();

        // Setup declarative event watches BEFORE first render
        // so error handlers are active during boot
        this.setupDeclarativeWatches();

        // Emit kernel:boot-complete — viewport-manager initializes rendering
        // and performs the first render during this async emit
        await this.events.emitAsync({
          type: EVENT_IDS.SYSTEM_BOOT_COMPLETE,
          content: {
            safeMode: this._safeMode,
            debugMode: this.debugMode,
            lateActivation: false,
            rootElement: this.rootElement
          }
        }, { sticky: true });
      }
    }

    /** Verify seed items exist in storage (warns if missing). */
    async ensureSeedItems() {
      // Check if seeds exist
      try {
        await this.storage.get(IDS.ATOM);
      } catch (e) {
        // Seeds missing - should have been imported via initial-kernel.json
        console.warn('Seed items not found. Please import initial-kernel.json');
      }
    }

    // -------------------------------------------------------------------------
    // Event Type Cache (for hierarchical event dispatch)
    // -------------------------------------------------------------------------

    /** Build a cache mapping event type IDs to their ancestor chains and names.
     * Also builds the watcher index for efficient event dispatch. */
    async buildEventTypeCache() {
      // Build a cache mapping each event definition ID to:
      // - ancestors: Set of all type IDs in the chain (for type hierarchy dispatch)
      // - name: The event's name string (for handler name derivation in declarative watches)
      // This enables O(1) lookups during emit().
      // Also builds the watcher index for efficient event dispatch.
      this.eventTypeCache = new Map();
      this.watcherIndex = new Set();

      try {
        // Load all items once, then do sync lookups (avoids O(N×M) async calls)
        const allItems = await this.storage.getAll();
        const itemMap = new Map(allItems.map(i => [i.id, i]));
        const eventDefs = [];

        for (const item of allItems) {
          if (this._typeChainIncludesSync(item.type, EVENT_IDS.EVENT_DEFINITION, itemMap)) {
            eventDefs.push(item);
          }
          // Also include the event-definition type itself
          if (item.id === EVENT_IDS.EVENT_DEFINITION) {
            eventDefs.push(item);
          }

          // Build watcher index: items with top-level watches array
          if (item.watches && Array.isArray(item.watches) && item.watches.length > 0) {
            this.watcherIndex.add(item.id);
          }
        }

        // For each event definition, compute its full type chain and cache name
        for (const eventDef of eventDefs) {
          const ancestors = this._getTypeChainSync(eventDef.id, itemMap);
          this.eventTypeCache.set(eventDef.id, {
            ancestors: new Set(ancestors),
            name: eventDef.name  // e.g., "item:created", "error-event"
          });
        }
      } catch (e) {
        // If event definitions don't exist yet, cache will be empty
        // This is fine during early boot
        console.debug('Event type cache: no event definitions found yet');
      }
    }

    // Sync version of moduleSystem.typeChainIncludes using pre-loaded itemMap
    _typeChainIncludesSync(typeId, targetId, itemMap) {
      const chain = [];
      let current = typeId;
      const visited = new Set();

      while (current && !visited.has(current)) {
        chain.push(current);
        visited.add(current);
        if (current === IDS.ITEM) break;

        const typeItem = itemMap.get(current);
        if (!typeItem) break;

        if (typeItem.extends) {
          current = typeItem.extends;
        } else {
          if (typeItem.type === IDS.TYPE_DEFINITION) break;
          current = typeItem.type;
        }
      }

      return chain.includes(targetId);
    }

    // Sync version of getTypeChain using pre-loaded itemMap
    _getTypeChainSync(itemId, itemMap) {
      const chain = [itemId];
      let currentId = itemId;
      const visited = new Set();

      while (currentId && !visited.has(currentId)) {
        visited.add(currentId);
        const item = itemMap.get(currentId);
        if (!item) break;
        if (item.type && item.type !== currentId) {
          chain.push(item.type);
          currentId = item.type;
        } else {
          break;
        }
      }

      return chain;
    }

    /** Get the full type chain from an item up to atom.
     * @param {string} itemId - Starting item GUID
     * @returns {Promise<string[]>} Array of type GUIDs
     */
    async getTypeChain(itemId) {
      // Returns array of all type IDs from this item up to atom (inclusive)
      const chain = [itemId];
      let currentId = itemId;
      const visited = new Set();

      while (currentId && !visited.has(currentId)) {
        visited.add(currentId);

        try {
          const item = await this.storage.get(currentId);
          if (item.type && item.type !== currentId) {
            chain.push(item.type);
            currentId = item.type;
          } else {
            break; // Reached atom (self-referential) or no type
          }
        } catch {
          break; // Item not found
        }
      }

      return chain;
    }

    /** Load and apply kernel CSS styles from the kernel:styles item. */
    async applyStyles() {
      // Remove existing kernel styles if present (allows hot-reload)
      const existing = document.getElementById('kernel-styles');
      if (existing) existing.remove();

      const style = document.createElement('style');
      style.id = 'kernel-styles';

      try {
        const stylesItem = await this.storage.get(IDS.KERNEL_STYLES);
        style.textContent = stylesItem.content.code.replace(
          /\{\{content\.(\w+)\}\}/g,
          (_, key) => stylesItem.content[key] ?? ''
        );
      } catch (e) {
        // Fallback to minimal styles
        style.textContent = `
          * { box-sizing: border-box; }
          html, body { height: 100%; margin: 0; }
          body { font-family: system-ui, sans-serif; padding: 20px; background: #f5f5f5; }
          #app { height: 100%; display: flex; flex-direction: column; }
          #main-view { flex: 1; background: white; border-radius: 8px; padding: 20px; overflow: auto; }
        `;
      }

      document.head.appendChild(style);
    }

    // getStartingRoot() removed - viewport-view reads URL directly
    // navigateToItem() removed - use userland viewport-manager.navigate()
    // renderViewport() removed - owned by viewport-rendering library

    // showItemList() removed - use userland item-palette via enrichAPI
    // showHelp() removed - use userland help-dialog via keyboard-shortcuts
    // editItemRaw() removed - use enrichAPI editRaw via viewport-rendering

    /** Download an object as a JSON file.
     * @param {*} thing - Object to serialize
     * @param {string} filename - Download filename
     */
    saveJson(thing, filename) {
        const json = JSON.stringify(thing, null, 2);
        const blob = new Blob([json], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = filename;
        a.click();
        URL.revokeObjectURL(url);
    }

    /** Export all items as JSON download(s).
     * @param {boolean} [singleFile=true] - Single backup file or one per item
     * @returns {Promise<number>} Number of items exported
     */
    async export(singleFile = true) {
        console.log("api.export:", singleFile);
        const items = await this.storage.getAllRaw();
        const itemsWithBlobs = await Promise.all(items.map(async item => {
          try {
            const blob = await this.storage.getBlob(item.id);
            const dataUrl = await new Promise((resolve, reject) => {
              const reader = new FileReader();
              reader.onload = () => resolve(reader.result);
              reader.onerror = reject;
              reader.readAsDataURL(blob);
            });
            return { ...item, _blob: dataUrl };
          } catch {
            return item;
          }
        }));
        if (singleFile) {
          this.saveJson(itemsWithBlobs, `backup-${Date.now()}.json`);
        } else {
          for (const item of itemsWithBlobs) {
            this.saveJson(item, `${item.id}.json`);
          }
        }

        return items.length;
    }

    // -------------------------------------------------------------------------
    // Unified API
    // -------------------------------------------------------------------------

    /** Create the unified API object. When containerItem is provided, adds context-specific methods.
     * @param {Object|null} [containerItem] - The item being rendered (adds context methods)
     * @param {Object} [context] - Render context (parentId, viewId, viewConfig, etc.)
     * @returns {Object} The API object
     */
    createAPI(containerItem = null, context = {}) {
      const kernel = this;

      const api = {
        // Base createElement (without debug context) — set by viewport-rendering before boot-complete.
        // Per-render enrichAPI overrides this with a debug-attributed version.
        createElement: kernel._baseCreateElement,

        // --- Storage operations ---

        /** Retrieve an item by ID from storage.
         * @param {string} id - Item GUID
         * @returns {Promise<Object>} The item
         */
        get: (id) => kernel.storage.get(id),

        /** Save or insert an item. Emits item:created or item:updated events.
         * @param {Object} item - The item to save (must have an id)
         * @param {Object} [options] - Save options
         * @param {boolean} [options.silent] - If true, suppress events and re-render
         * @returns {Promise<string>} The item's id
         */
        set: async (item, options) => {
          await kernel.saveItem(item, options);
          return item.id;
        },
        /** Save an item (alias for set — reactivity handles re-render).
         * @param {Object} item - The item to save
         * @returns {Promise<string>} The item's id
         */
        update: async (item) => {
          await kernel.saveItem(item);
          return item.id;
        },

        /** Save without events or re-render (for layout/position saves).
         * @deprecated Use set(item, {silent: true}) instead
         * @param {Object} item - The item to save
         * @returns {Promise<string>} The item's id
         */
        updateSilent: async (item) => {
          await kernel.saveItem(item, { silent: true });
          return item.id;
        },

        /** Delete an item, detaching from all parents. Emits item:deleted.
         * @param {string} id - Item GUID to delete
         */
        delete: (id) => kernel.deleteItem(id),

        /** Batch-delete all items whose ID starts with prefix.
         * Skips per-item events — does one cache clear + render at the end.
         * @param {string} prefix - ID prefix to match (e.g., nested instance prefix)
         * @returns {Promise<number>} Number of items deleted
         */
        deleteByPrefix: async (prefix) => {
          const count = await kernel.storage.deleteByPrefix(prefix);
          await kernel.storage.deleteBlobsByPrefix(prefix);
          if (count > 0) {
            kernel.moduleSystem.clearCache();
          }
          return count;
        },
        /** Find items matching a filter object (key-value pairs matched against item fields).
         * @param {Object} filter - Filter object, e.g. {type: "...", name: "..."}
         * @returns {Promise<Object[]>} Matching items
         */
        query: (filter) => kernel.storage.query(filter),

        /** Get all items (excludes nested instance items).
         * @returns {Promise<Object[]>}
         */
        getAll: () => kernel.storage.getAll(),

        /** Get all items including nested instance items.
         * @returns {Promise<Object[]>}
         */
        getAllRaw: () => kernel.storage.getAllRaw(),

        // --- History operations ---

        /** Get history entries for an item (timestamps and metadata, no snapshots).
         * @param {string} id - Item GUID
         * @returns {Promise<Array<{itemId, timestamp, deleted}>>}
         */
        getHistory: (id) => kernel.storage.getHistory(id),

        /** Get the full item snapshot at a specific history timestamp.
         * @param {string} id - Item GUID
         * @param {number} timestamp - Exact timestamp of the history entry
         * @returns {Promise<Object>} The item as it was at that point
         */
        viewAt: async (id, timestamp) => {
          const entry = await kernel.storage.getHistoryEntry(id, timestamp);
          if (!entry) throw new Error(`No history entry for ${id} at ${timestamp}`);
          return entry.snapshot;
        },

        /** Restore an item to a previous state. The revert itself is recorded in history.
         * @param {string} id - Item GUID
         * @param {number} timestamp - Timestamp of the version to restore
         * @returns {Promise<Object>} The restored item
         */
        revertTo: async (id, timestamp) => {
          const entry = await kernel.storage.getHistoryEntry(id, timestamp);
          if (!entry) throw new Error(`No history entry for ${id} at ${timestamp}`);
          const restored = { ...entry.snapshot };
          await kernel.saveItem(restored);
          return restored;
        },

        /** Get all deletion records since a given timestamp.
         * @param {number} since - Timestamp threshold
         * @returns {Promise<Array<{itemId, timestamp}>>}
         */
        getDeletedSince: (since) => kernel.storage.getDeletedSince(since),

        /** Retrieve a Blob by item ID.
         * @param {string} id - Item GUID
         * @returns {Promise<Blob>}
         */
        getBlob: (id) => kernel.storage.getBlob(id),

        /** Store a Blob keyed by item ID.
         * @param {string} id - Item GUID
         * @param {Blob} blob - The binary blob to store
         */
        setBlob: (id, blob) => kernel.storage.setBlob(id, blob),

        /** Delete a Blob by item ID. Silent no-op if not found.
         * @param {string} id - Item GUID
         */
        deleteBlob: (id) => kernel.storage.deleteBlob(id),

        // --- Code operations ---

        /** Load a library or code module by name or ID.
         * @param {string} name - Item name (e.g. 'markdown-it') or GUID
         * @returns {Promise<Object>} The module's exports
         */
        require: (name) => kernel.moduleSystem.require(name),

        /** Check if a type's inheritance chain includes a target type.
         * @param {string} typeId - The type to check
         * @param {string} targetId - The target type to look for in the chain
         * @returns {Promise<boolean>}
         */
        typeChainIncludes: (typeId, targetId) => kernel.moduleSystem.typeChainIncludes(typeId, targetId),

        // --- Parent-child operations (arity-detecting) ---

        /** Attach a child item to a parent.
         * 1-arg form (in view context): attach(itemId) — uses containerItem as parent.
         * 2-arg form: attach(parentId, itemId).
         * @param {...string} args - (itemId) or (parentId, itemId)
         */
        attach: (...args) => args.length === 1 && containerItem
          ? kernel.attach(containerItem.id, args[0])
          : kernel.attach(args[0], args[1]),
        /** Detach a child from a parent.
         * 1-arg form (in view context): detach(itemId) — uses containerItem as parent.
         * 2-arg form: detach(parentId, itemId).
         * @param {...string} args - (itemId) or (parentId, itemId)
         */
        detach: (...args) => args.length === 1 && containerItem
          ? kernel.detach(containerItem.id, args[0])
          : kernel.detach(args[0], args[1]),
        // setAttachmentView — added by viewport-rendering enrichAPI
        /** Find the parent item that contains a given item in its attachments.
         * @param {string} itemId - Child item GUID
         * @returns {Promise<Object|null>} The parent item, or null if not attached
         */
        findContainerOf: (itemId) => kernel.findContainerOf(itemId),

        /** Check if attaching an item as a child would create a cycle.
         * @param {string} parentId - Prospective parent GUID
         * @param {string} attachmentId - Prospective child GUID
         * @returns {Promise<boolean>}
         */
        wouldCreateCycle: (parentId, attachmentId) => kernel.wouldCreateCycle(parentId, attachmentId),

        /** Check if an item's descendant graph contains any cycles.
         * @param {string} itemId - Item GUID to check
         * @returns {Promise<boolean>}
         */
        hasCycle: (itemId) => kernel.hasCycle(itemId),

        // --- Import/Export ---

        /** Export all items as JSON download(s).
         * @param {boolean} [singleFile=true] - If true, one backup file; if false, one file per item
         * @returns {Promise<number>} Number of items exported
         */
        export: async (singleFile = true) => {
          console.log("api.export:", singleFile);
          return kernel.export(singleFile);
        },
        /** Import items from JSON file(s) with smart refresh.
         * Opens a file picker, then imports items with dependency-order sorting.
         * @returns {Promise<{created: number, updated: number, skipped: number, action: string}>}
         */
        import: async () => {
          return new Promise((resolve, reject) => {
            const input = document.createElement("input");
            input.type = "file";
            input.accept = ".json";
            input.setAttribute("multiple", "");
            document.body.appendChild(input);

            input.onchange = async (e) => {
              document.body.removeChild(input);
              const files = Array.from(e.target.files);
              if (files.length === 0) {
                reject(new Error("No file selected"));
                return;
              }

              try {
                // Combine items from all selected files
                let items = [];
                for (const file of files) {
                  const text = await file.text();
                  const data = JSON.parse(text);
                  const fileItems = Array.isArray(data) ? data : [data];
                  items = items.concat(fileItems);
                }

                resolve(await kernel.importItems(items));
              } catch (error) {
                reject(error);
              }
            };

            input.addEventListener('cancel', () => {
              document.body.removeChild(input);
              resolve({ created: 0, updated: 0, skipped: 0, action: 'cancelled' });
            });

            input.click();
          });
        },

        /** Event system — subscribe, unsubscribe, emit, and list events. */
        events: {
          /** Subscribe to an event type. Returns an unsubscribe function.
           * @param {string} eventTypeId - Event type GUID
           * @param {Function} handler - Called with {type, content, timestamp}
           * @returns {Function} Unsubscribe function
           */
          on: (eventTypeId, handler) => kernel.events.on(eventTypeId, handler),

          /** Unsubscribe a handler from an event type.
           * @param {string} eventTypeId - Event type GUID
           * @param {Function} handler - The handler to remove
           */
          off: (eventTypeId, handler) => kernel.events.off(eventTypeId, handler),

          /** Emit an event to all matching subscribers.
           * @param {Object} event - {type: eventTypeGUID, content: {...}}
           */
          emit: (event) => kernel.events.emit(event),

          /** List all event type GUIDs that have active listeners.
           * @returns {string[]}
           */
          list: () => kernel.events.getRegisteredEvents()
        },

        // editRaw removed - provided by enrichAPI (viewport-rendering)
        // showItemList removed - provided by enrichAPI (viewport-rendering)

        /** Create a context-free API object (for REPL use).
         * @returns {Object} API without containerItem context
         */
        createREPLContext: () => kernel.createAPI(),

        /** Well-known item GUIDs (ITEM, TYPE_DEFINITION, CODE, VIEW, etc.). */
        IDS,

        /** Well-known event type GUIDs (ITEM_CREATED, ITEM_UPDATED, SYSTEM_ERROR, etc.). */
        EVENT_IDS,

        /** Get the nested instance ID (null for main instance).
         * @returns {string|null}
         */
        getInstanceId: () => kernel.storage.instanceId,

        /** Check if debug mode is active.
         * @returns {boolean}
         */
        isDebugMode: () => context.debug || kernel.debugMode,

        /** Convenience helpers for common item operations. */
        helpers: {
          /** Find an item by name.
           * @param {string} name - Item name to search for
           * @returns {Promise<Object|null>} The first matching item, or null
           */
          findByName: async (name) => {
            const items = await kernel.storage.query({ name });
            return items.length > 0 ? items[0] : null;
          },
          /** List all items of a given type.
           * @param {string} typeId - Type GUID
           * @returns {Promise<Object[]>}
           */
          listByType: async (typeId) => {
            return await kernel.storage.query({ type: typeId });
          },

          /** Create a new type definition item.
           * @param {string} name - Type name
           * @param {string} [description] - Type description
           * @returns {Promise<string>} The new type's GUID
           */
          createType: async (name, description) => {
            const id = crypto.randomUUID();
            await kernel.saveItem({
              id,
              name,
              type: IDS.TYPE_DEFINITION,
              attachments: [],
              content: { description }
            });
            return id;
          }
        },

      };

      // --- Context layer (only when containerItem provided) ---
      if (containerItem) {
        /** Get the parent item ID in the current render context.
         * @returns {string|null}
         */
        api.getParentId = () => context.parentId || null;

        /** Get the view ID used to render this item.
         * @returns {string|null}
         */
        api.getViewId = () => context.viewId || null;

        /** Get the navigateTo target (item GUID to navigate on click, set by parent).
         * @returns {string|null}
         */
        api.getNavigateTo = () => context.navigateTo || null;

        /** Get the item being rendered.
         * @returns {Object} The container item
         */
        api.getCurrentItem = () => containerItem;

        /** Create a new item, optionally attaching it as a child of the current item.
         * @param {Object} item - Item data (id auto-generated if missing)
         * @param {boolean} [addAsChild=false] - If true, attach to current item
         * @returns {Promise<string>} The new item's GUID
         */
        api.create = async (item, addAsChild = false) => {
          const newItem = {
            ...item,
            id: item.id || crypto.randomUUID(),
            attachments: item.attachments || []
          };

          await kernel.saveItem(newItem);

          if (addAsChild) {
            await kernel.attach(containerItem.id, newItem.id);
          }

          return newItem.id;
        };

        /** Create a child item of a given type and attach it.
         * @param {string} type - Type GUID for the new item
         * @param {Object} [content] - Initial content for the new item
         * @returns {Promise<string>} The new item's GUID
         */
        api.createChild = async (type, content = {}) => {
          const newItem = {
            type,
            content,
            attachments: []
          };
          return await api.create(newItem, true);
        };
      }

      return api;
    }

    // -------------------------------------------------------------------------
    // Parent-child operations
    // -------------------------------------------------------------------------

    /** Attach a child item to a parent's attachments array.
     * @param {string} parentId - Parent item GUID
     * @param {string|Object} childIdOrObj - Child GUID string, or attachment object { id, view? }
     */
    async attach(parentId, childIdOrObj) {
      const attachment = typeof childIdOrObj === 'string'
        ? { id: childIdOrObj }
        : childIdOrObj;
      const childId = attachment.id;

      const parent = await this.storage.get(parentId);
      if (!parent.attachments) parent.attachments = [];

      const existingIdx = parent.attachments.findIndex(c => c.id === childId);
      if (existingIdx >= 0) {
        // Re-attach: apply caller's data, resetting any existing view config.
        // This lets the parent's view restore context-appropriate state
        // from the old attachment (available via the item-updated event).
        parent.attachments[existingIdx] = attachment;
      } else {
        parent.attachments.push(attachment);
      }

      parent.modified = Date.now();
      await this.saveItem(parent); // Non-silent — triggers re-render
    }

    /** Detach a child item from a parent's attachments array.
     * @param {string} parentId - Parent item GUID
     * @param {string} itemId - Child item GUID to detach
     */
    async detach(parentId, itemId) {
      const parent = await this.storage.get(parentId);
      const updated = {
        ...parent,
        attachments: parent.attachments.filter(c => c.id !== itemId)
      };
      updated.modified = Date.now();
      await this.saveItem(updated); // Non-silent — triggers re-render (consistent with attach)
    }

    // setAttachmentView — moved to viewport-rendering enrichAPI

    /** Find the parent item that contains a given item in its attachments.
     * @param {string} itemId - Child item GUID
     * @returns {Promise<Object|null>} The parent item, or null
     */
    async findContainerOf(itemId) {
      const allItems = await this.storage.getAll();
      for (const item of allItems) {
        if (item.attachments && item.attachments.some(c => c.id === itemId)) {
          return item;
        }
      }
      return null;
    }

    /** Check if attaching newChildId under parentId would create a cycle.
     * @param {string} parentId - Prospective parent
     * @param {string} newChildId - Prospective child
     * @returns {Promise<boolean>}
     */
    async wouldCreateCycle(parentId, newChildId) {
      const canReach = async (fromId, toId, visited = new Set()) => {
        if (fromId === toId) return true;
        if (visited.has(fromId)) return false;

        visited.add(fromId);

        try {
          const item = await this.storage.get(fromId);
          for (const child of (item.attachments || [])) {
            if (await canReach(child.id, toId, visited)) {
              return true;
            }
          }
        } catch {
          // Item doesn't exist
        }

        return false;
      };

      return await canReach(newChildId, parentId);
    }

    /** Check if an item's descendant graph contains any cycles.
     * @param {string} itemId - Item GUID to check
     * @returns {Promise<boolean>}
     */
    async hasCycle(itemId) {
      const visited = new Set();
      const recursionStack = new Set();

      const detectCycle = async (id) => {
        if (recursionStack.has(id)) {
          return true; // Found a cycle
        }
        if (visited.has(id)) {
          return false; // Already fully explored this branch
        }

        visited.add(id);
        recursionStack.add(id);

        try {
          const item = await this.storage.get(id);
          for (const child of (item.attachments || [])) {
            if (await detectCycle(child.id)) {
              return true;
            }
          }
        } catch {
          // Item doesn't exist
        }

        recursionStack.delete(id);
        return false;
      };

      return await detectCycle(itemId);
    }

    /** Import items with dependency-order sorting and smart refresh.
     * @param {Object[]} items - Array of item objects to import
     * @returns {Promise<{created: number, updated: number, skipped: number, action: string}>}
     */
    async importItems(items) {
      // Sort items in dependency order (types/extends before their dependents)
      items = sortItemsForImport(items);

      let created = 0;
      let updated = 0;
      let skipped = 0;

      for (const item of items) {
        if (!item.id) {
          item.id = crypto.randomUUID();
        }

        // Extract and store blob if present
        if (item._blob) {
          try {
            const dataUrl = item._blob;
            const mimeType = dataUrl.match(/^data:([^;]+);/)?.[1] || 'application/octet-stream';
            const base64 = dataUrl.split(',')[1];
            const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
            await this.storage.setBlob(item.id, new Blob([bytes], { type: mimeType }));
          } catch (e) {
            console.warn(`Failed to import blob for ${item.id}: ${e.message}`);
          }
          delete item._blob;
        }

        try {
          const exists = await this.storage.exists(item.id);

          // Ensure created timestamp for new items
          if (!exists && !item.created) item.created = Date.now();

          await this.saveItem(item);
          // Module cache invalidation handled by ITEM_UPDATED event in moduleSystem.initEventListeners()

          if (exists) {
            updated++;
          } else {
            created++;
          }
        } catch (error) {
          console.warn(`Failed to import item ${item.id}: ${error.message}`);
          skipped++;
        }
      }

      // Smart refresh based on what was imported
      const result = { created, updated, skipped };

      // Check for kernel modules - requires full reload
      const hasKernelModule = items.some(i => i.type === IDS.KERNEL_MODULE);
      if (hasKernelModule) {
        result.action = 'reload';
        this.reloadKernel();
        return result;
      }

      // Check for styles - hot-reload CSS
      const hasStyles = items.some(i => i.id === IDS.KERNEL_STYLES);
      if (hasStyles) {
        await this.applyStyles();
      }

      // Rendering refresh is handled by reactivity (ITEM_UPDATED events)
      // Library imports are a known gap — no full re-render triggered
      result.action = hasStyles ? 'styles-only' : 'none';
      return result;
    }

    /** Delete an item: detach from all parents, remove from storage, emit item:deleted.
     * @param {string} itemId - Item GUID to delete
     */
    async deleteItem(itemId) {
      // Protect seed items from deletion
      const seedIds = Object.values(IDS);
      if (seedIds.includes(itemId)) {
        const error = new Error(`Cannot delete seed item ${itemId}. Seed items are protected.`);
        await this.captureError(error, { operation: 'delete', itemId });
        throw error;
      }

      // Get the item before deleting (for event and history)
      const item = await this.storage.get(itemId);

      // Record deletion in history
      await this.storage.writeHistory(itemId, Date.now(), item, true);

      // Find all parents
      const allItems = await this.storage.getAll();
      const parents = allItems.filter(parentItem => {
        if (!parentItem.attachments) return false;
        return parentItem.attachments.some(child => child.id === itemId);
      });

      // Remove from all parents
      for (const parent of parents) {
        await this.detach(parent.id, itemId);
      }

      // Delete the item
      await this.storage.delete(itemId);
      // Delete associated blob (silent no-op if item has no blob)
      await this.storage.deleteBlob(itemId);

      // Remove from watcher index
      this.watcherIndex.delete(itemId);

      // Emit deletion event — await so cascade-delete watchers complete before re-render
      await this.events.emitAsync({ type: EVENT_IDS.ITEM_DELETED, content: { id: itemId, item } });

      // Targeted cache invalidation for deleted code items
      if (await this.isCodeItem(item)) {
        this.moduleSystem.moduleCache.delete(itemId);
        for (const [name, cachedId] of this.moduleSystem.nameCache) {
          if (cachedId === itemId) { this.moduleSystem.nameCache.delete(name); break; }
        }
      }
      // Reactivity handles re-render via ITEM_DELETED event
    }

    /** Check if an item is a code item (its type chain includes CODE).
     * @param {Object} item - The item to check
     * @returns {Promise<boolean>}
     */
    async isCodeItem(item) {
      return await this.moduleSystem.isCodeItem(item);
    }

    // -------------------------------------------------------------------------
    // Item Save with Events
    // -------------------------------------------------------------------------

    /** Save an item to storage, emitting created/updated events.
     * @param {Object} item - The item to save
     * @param {Object} [options]
     * @param {boolean} [options.silent] - Suppress events and late-activation
     * @returns {Promise<Object>} The saved item
     */
    async saveItem(item, options = {}) {
      const { silent = false, preserveModified = false } = options;

      const exists = await this.storage.exists(item.id);
      const previous = exists ? await this.storage.get(item.id) : null;

      if (!exists && item.type) {
        const templateFields = {};
        let typeId = item.type;
        const seen = new Set();
        while (typeId && !seen.has(typeId)) {
          seen.add(typeId);
          const typeDef = await this.storage.get(typeId);
          if (!typeDef) break;
          if (typeDef.template) {
            for (const [k, v] of Object.entries(typeDef.template)) {
              if (!(k in templateFields)) templateFields[k] = v;
            }
          }
          typeId = typeDef.extends ?? null;
        }
        if (Object.keys(templateFields).length > 0) {
          item = { ...item, content: { ...templateFields, ...(item.content || {}) } };
        }
      }

      // Capture previous state in history before overwriting
      if (previous) {
        await this.storage.writeHistory(item.id, previous.modified, previous, false);
      }

      if (!preserveModified) {
        item.modified = Date.now();
      }
      if (!exists && !item.created) {
        item.created = Date.now();
      }

      await this.storage.set(item, this);

      // Update watcher index
      if (item.watches && Array.isArray(item.watches) && item.watches.length > 0) {
        this.watcherIndex.add(item.id);
      } else {
        this.watcherIndex.delete(item.id);
      }

      // Module cache invalidation — always runs, even when silent, but only
      // when content.code actually changed. silent suppresses events and watchers,
      // but a stale module cache is a correctness issue (e.g. sync saves with
      // silent:true must still pick up new code on next require()). Data-only
      // saves (e.g. updating lastSyncTimestamp) must not evict the module.
      const cached = this.moduleSystem.moduleCache.get(item.id);
      if (cached && (!previous || previous.content?.code !== item.content?.code)) {
        if (typeof cached.module?.cleanup === 'function') {
          try { await cached.module.cleanup(); } catch(e) {
            console.warn(`Cleanup for ${item.name || item.id} failed:`, e);
          }
        }
        this.moduleSystem.moduleCache.delete(item.id);
        for (const [name, cachedId] of this.moduleSystem.nameCache) {
          if (cachedId === item.id) { this.moduleSystem.nameCache.delete(name); break; }
        }
      }

      if (!silent) {
        if (exists) {
          this.events.emit({ type: EVENT_IDS.ITEM_UPDATED, content: { id: item.id, item, previous } });
        } else {
          this.events.emit({ type: EVENT_IDS.ITEM_CREATED, content: { id: item.id, item } });
        }

        // Replay any sticky events this item watches (e.g., boot-complete, viewport:ready).
        // This enables newly-created/edited watcher items to activate without reload.
        if (item.watches?.length > 0) {
          for (const watch of item.watches) {
            const stickyEvent = this.events.getStickyEvent(watch.event);
            if (stickyEvent) {
              try {
                const replayEvent = { ...stickyEvent, content: { ...stickyEvent.content, lateActivation: true } };
                await this.callWatchHandler(item, replayEvent);
              } catch (e) {
                console.warn(`Sticky replay for ${item.name || item.id} (${watch.event}) failed:`, e);
              }
            }
          }
        }
      }

      return item;
    }

    // -------------------------------------------------------------------------
    // Declarative Event Watches (Phase 2: Type hierarchy based)
    // -------------------------------------------------------------------------

    /** Subscribe a single root listener that dispatches all events to declarative watchers. */
    setupDeclarativeWatches() {
      // Single subscription to root event type — receives ALL events
      // (item, system, viewport, userland, etc.)
      this.events.on(EVENT_IDS.EVENT_DEFINITION, async (event) => {
        await this.dispatchToWatchers(event);
      });
    }

    /** Dispatch an event to all matching declarative watch handlers.
     * @param {Object} event - {type, content, timestamp}
     */
    async dispatchToWatchers(event) {
      // event = { type: eventTypeId, content: {...}, timestamp }
      try {
        // Get watcher items from index (O(k) where k = number of watchers)
        const watcherItems = await Promise.all(
          [...this.watcherIndex].map(id => this.storage.get(id).catch(() => null))
        );

        // Get the emitted event's type chain for matching
        const eventTypeChain = this.eventTypeCache?.get(event.type)?.ancestors || new Set([event.type]);

        // Find and call all matching watchers
        let handled = false;
        for (const watcherItem of watcherItems) {
          if (!watcherItem || !watcherItem.watches) continue;

          // A watch matches if the emitted event's type chain includes the watch's event field
          const matchingWatches = watcherItem.watches.filter(w =>
            eventTypeChain.has(w.event)
          );

          for (const watch of matchingWatches) {
            // Evaluate filter against the event's item (from content)
            const matches = await this.evaluateWatchFilter(watch, event.content?.item);

            if (matches) {
              await this.callWatchHandler(watcherItem, event);
              handled = true;
              break; // Only call handler once per watcher item, even if multiple watches match
            }
          }
        }

        // Fallback for unhandled system errors
        if (!handled && event.type === EVENT_IDS.SYSTEM_ERROR) {
          this.showFallbackErrorUI(event.content?.error, event.content?.context);
        }
      } catch (error) {
        console.error('Error dispatching to declarative watchers:', error);
        if (event.type === EVENT_IDS.SYSTEM_ERROR) {
          this.showFallbackErrorUI(event.content?.error, event.content?.context);
        }
      }
    }

    /** Evaluate a watch's filter conditions against an item.
     * @param {Object} watch - Watch spec {event, type?, typeExtends?, id?}
     * @param {Object|null} item - The item affected by the event
     * @returns {Promise<boolean>} True if all filters match
     */
    async evaluateWatchFilter(watch, item) {
      // No filters specified — always match (works for all event types)
      if (!watch.type && !watch.typeExtends && !watch.id) return true;

      // Filters require an item to evaluate against
      if (!item) return false;

      // Check exact type match (against the item being affected, not the event type)
      if (watch.type && item.type !== watch.type) {
        return false;
      }

      // Check type chain (typeExtends)
      if (watch.typeExtends) {
        const inChain = await this.moduleSystem.typeChainIncludes(item.type, watch.typeExtends);
        if (!inChain) {
          return false;
        }
      }

      // Check specific item ID
      if (watch.id && item.id !== watch.id) {
        return false;
      }

      // All filters passed
      return true;
    }

    /** Load a watcher's module and call the derived handler (e.g., onItemUpdated).
     * @param {Object} watcherItem - The item with watches array
     * @param {Object} event - {type, content, timestamp}
     */
    async callWatchHandler(watcherItem, event) {
      // event = { type: eventTypeId, content: {...}, timestamp }
      try {
        // Get event name from cache for handler name derivation
        const eventName = this.eventTypeCache?.get(event.type)?.name;
        if (!eventName) {
          console.warn(`Unknown event type ${event.type} - no cached name for handler derivation`);
          return;
        }

        // Convert event name to handler name: "item:deleted" -> "onItemDeleted"
        const handlerName = this.eventToHandlerName(eventName);

        // Load the watcher module
        const module = await this.moduleSystem.require(watcherItem.id);

        if (typeof module[handlerName] !== 'function') {
          console.warn(`Watcher ${watcherItem.name || watcherItem.id} has no ${handlerName} handler`);
          return;
        }

        // Use full REPL API for watch handlers (libraries need full access)
        // Renderer API is too limited - it lacks import, export, etc.
        const api = this.createAPI();

        // Call the handler with event content (preserves existing handler signatures)
        await module[handlerName](event.content, api);
      } catch (error) {
        console.error(`Error calling watch handler on ${watcherItem.name || watcherItem.id}:`, error);
      }
    }

    /** Convert an event name to a handler function name (e.g., "item:deleted" → "onItemDeleted").
     * @param {string} eventName - Event name (e.g., "item:deleted", "kernel:boot-complete")
     * @returns {string} Handler name (e.g., "onItemDeleted")
     */
    eventToHandlerName(eventName) {
      // "item:deleted" -> "onItemDeleted"
      // "item:created" -> "onItemCreated"
      // "error-event" -> "onErrorEvent"
      // "kernel:boot-complete" -> "onKernelBootComplete"
      // Split by : and - then capitalize each part
      const parts = eventName.split(/[:-]/);
      const camelParts = parts.map(part =>
        part.charAt(0).toUpperCase() + part.slice(1).toLowerCase()
      );
      return 'on' + camelParts.join('');
    }

    // -------------------------------------------------------------------------
    // Error Capture System
    // -------------------------------------------------------------------------

    /** Capture an error and emit it as a system error event.
     * @param {Error} error - The error to capture
     * @param {Object} [context] - Additional context (operation, itemId, itemName, etc.)
     */
    async captureError(error, context = {}) {
      // Don't capture errors in safe mode
      if (this._safeMode) {
        console.error('[Safe Mode] Error:', error);
        return;
      }

      try {
        // Emit error-event event - user handlers will process
        const errorContent = {
          error: {
            name: error.name || 'Error',
            message: error.message || String(error),
            stack: error.stack || ''
          },
          context: {
            operation: 'unknown',
            ...context
          }
        };
        // Preserve structured Hob error data when available
        if (error.hobStack && error.hobStack.length > 0) {
          errorContent.hobStack = error.hobStack;
        }
        if (error.hobExpr != null) {
          errorContent.hobExpr = error.hobExpr;
        }
        this.events.emit({
          type: EVENT_IDS.SYSTEM_ERROR,
          content: errorContent
        });
      } catch (eventError) {
        // Ultimate fallback if event system fails
        console.error('Error capture failed:', eventError);
        console.error('Original error:', error);
        this.showFallbackErrorUI(error, context);
      }
    }

    /** Show a persistent error banner at the top of the page (last-resort fallback). */
    showFallbackErrorUI(error, context = {}) {
      // Remove any existing fallback banners
      const existing = document.querySelector('.kernel-error-fallback');
      if (existing) existing.remove();

      // Create persistent error banner at top of viewport
      const banner = document.createElement('div');
      banner.className = 'kernel-error-fallback';
      banner.style.cssText = `
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        background: #ffebee;
        border-bottom: 2px solid #c62828;
        padding: 12px 20px;
        z-index: 10000000;
        font-family: system-ui, sans-serif;
      `;

      const contextInfo = context.itemName ? ` in ${context.itemName}` : '';
      const errorMessage = error?.message || String(error);

      banner.innerHTML = `
        <div style="display: flex; align-items: center; gap: 12px;">
          <span style="font-size: 1.25rem;">⚠️</span>
          <div style="flex: 1;">
            <strong>System Error</strong>${contextInfo}: ${errorMessage}
          </div>
          <button onclick="this.closest('.kernel-error-fallback').remove()"
                  style="padding: 4px 12px; cursor: pointer; border: 1px solid #999; background: white; border-radius: 4px;">
            Dismiss
          </button>
        </div>
      `;

      document.body.insertBefore(banner, document.body.firstChild);
    }

    /** Clean up global handlers and trigger a full kernel reload via postMessage. */
    reloadKernel() {
      // Clean up global handlers before reload
      if (window._globalErrorHandler) {
        window.removeEventListener('error', window._globalErrorHandler);
        delete window._globalErrorHandler;
      }
      if (window._unhandledRejectionHandler) {
        window.removeEventListener('unhandledrejection', window._unhandledRejectionHandler);
        delete window._unhandledRejectionHandler;
      }
      if (window._replKeyboardHandler) {
        document.removeEventListener('keydown', window._replKeyboardHandler);
        delete window._replKeyboardHandler;
      }
      if (window._userKeyboardHandler) {
        document.removeEventListener('keydown', window._userKeyboardHandler);
        delete window._userKeyboardHandler;
      }
      if (window._hobsonPopstateHandler) {
        window.removeEventListener('popstate', window._hobsonPopstateHandler);
        delete window._hobsonPopstateHandler;
      }
      if (window._safeModeShortcut) {
        document.removeEventListener('keydown', window._safeModeShortcut);
        delete window._safeModeShortcut;
      }

      window.postMessage({type: 'reload-kernel'}, '*');
    }
  }

  return Kernel;
}

// kernel-storage module
// See [Architecture Overview - Storage Architecture](item://a0a0a0a0-d0c0-4000-8000-000000000003#Storage-Architecture)
// Owns IndexedDB access and ID prefixing for nested instance isolation.

// [BEGIN:Storage]
/** Storage layer — wraps IndexedDB with ID-prefix isolation and in-memory caching. */
export class Storage {
  constructor(db, instanceId) {
    this._db = db;
    this._instanceId = instanceId || null;
    this._cache = new Map();
    this._allCached = false;
  }

  /** Get the nested instance ID (null for main instance).
   * @returns {string|null}
   */
  get instanceId() {
    return this._instanceId;
  }

  /** Initialize storage (no-op — db is already open). */
  async initialize() {
    // db is already open, passed from the bootloader
  }

  // --- Private: ID prefixing for nested instance isolation ---

  _prefixId(id) {
    return this._instanceId ? `${this._instanceId}:${id}` : id;
  }

  _stripPrefix(id) {
    if (!this._instanceId) return id;
    const prefix = `${this._instanceId}:`;
    return id.startsWith(prefix) ? id.slice(prefix.length) : id;
  }

  _stripItemPrefix(item) {
    if (!this._instanceId || !item) return item;
    return { ...item, id: this._stripPrefix(item.id) };
  }

  // --- Private: IndexedDB operations ---

  _idbGet(id) {
    const actualId = this._prefixId(id);
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('items', 'readonly');
      const req = tx.objectStore('items').get(actualId);
      req.onsuccess = () => resolve(this._stripItemPrefix(req.result));
      req.onerror = () => reject(req.error);
    });
  }

  _idbSet(item) {
    const toStore = this._instanceId
      ? { ...item, id: this._prefixId(item.id) }
      : item;
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('items', 'readwrite');
      const req = tx.objectStore('items').put(toStore);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }

  _idbDelete(id) {
    const actualId = this._prefixId(id);
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('items', 'readwrite');
      const req = tx.objectStore('items').delete(actualId);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }

  /** Fetch all items in this instance's namespace (with prefixes stripped). */
  _idbGetAll() {
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('items', 'readonly');
      const req = tx.objectStore('items').getAll();
      req.onsuccess = () => {
        let items = req.result;
        if (this._instanceId) {
          const prefix = `${this._instanceId}:`;
          items = items
            .filter(item => item.id.startsWith(prefix))
            .map(item => this._stripItemPrefix(item));
        }
        resolve(items);
      };
      req.onerror = () => reject(req.error);
    });
  }

  // --- Public API ---

  /** Retrieve an item by ID. Throws if not found.
   * @param {string} id - Item GUID
   * @returns {Promise<Object>} The item
   */
  async get(id) {
    const cached = this._cache.get(id);
    if (cached) return cached;
    const result = await this._idbGet(id);
    if (!result) {
      throw new Error(`Item not found: ${id}`);
    }
    this._cache.set(id, result);
    return result;
  }

  /** Validate and persist an item.
   * @param {Object} item - The item to save
   * @param {Object} [kernel] - Kernel reference for validation context
   */
  async set(item, kernel) {
    await this._validateItem(item, kernel);
    await this._idbSet(item);
    this._cache.set(item.id, item);
  }

  /** Delete an item from storage and cache.
   * @param {string} id - Item GUID to delete
   */
  async delete(id) {
    this._cache.delete(id);
    return this._idbDelete(id);
  }

  /** Find items matching a filter object (key-value pairs matched against item fields).
   * @param {Object} filter - e.g. {type: "...", name: "..."}
   * @returns {Promise<Object[]>} Matching items (excludes nested instance items)
   */
  async query(filter) {
    if (this._allCached) {
      // Exclude nested instance items (have ':' in ID)
      const items = [];
      for (const item of this._cache.values()) {
        if (!item.id.includes(':')) items.push(item);
      }
      return items.filter(item => {
        for (const [key, value] of Object.entries(filter)) {
          if (item[key] !== value) return false;
        }
        return true;
      });
    }
    const allItems = await this.getAll();
    return allItems.filter(item => {
      for (const [key, value] of Object.entries(filter)) {
        if (item[key] !== value) return false;
      }
      return true;
    });
  }

  /** Get all items (excludes nested instance items). Populates cache on first call.
   * @returns {Promise<Object[]>}
   */
  async getAll() {
    if (this._allCached) {
      const items = [];
      for (const item of this._cache.values()) {
        if (!item.id.includes(':')) items.push(item);
      }
      return items;
    }
    const allItems = await this._idbGetAll();
    // Filter out nested instance items (items with ':' in their stripped ID)
    const items = allItems.filter(item => !item.id.includes(':'));
    for (const item of items) {
      this._cache.set(item.id, item);
    }
    this._allCached = true;
    return items;
  }

  /** Get all items including nested instance items.
   * @returns {Promise<Object[]>}
   */
  async getAllRaw() {
    return this._idbGetAll();
  }

  /** Delete all items whose ID starts with a prefix.
   * @param {string} prefix - ID prefix to match
   * @returns {Promise<number>} Number of items deleted
   */
  async deleteByPrefix(prefix) {
    const allItems = await this.getAllRaw();
    const toDelete = allItems.filter(item => item.id.startsWith(prefix));
    for (const item of toDelete) {
      await this.delete(item.id);
    }
    return toDelete.length;
  }

  /** Check if an item exists in storage.
   * @param {string} id - Item GUID
   * @returns {Promise<boolean>}
   */
  async exists(id) {
    if (this._cache.has(id)) return true;
    try {
      await this.get(id);
      return true;
    } catch {
      return false;
    }
  }

  // --- History operations (item-history IDB store) ---

  /** Write a history entry (previous state before an update or deletion).
   * @param {string} itemId - Item GUID
   * @param {number} timestamp - Timestamp for this entry (previous.modified or Date.now() for deletions)
   * @param {Object} snapshot - Full item state at this point
   * @param {boolean} [deleted=false] - True if this records a deletion
   */
  async writeHistory(itemId, timestamp, snapshot, deleted = false) {
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('item-history', 'readwrite');
      const req = tx.objectStore('item-history').put({ itemId, timestamp, snapshot, deleted });
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }

  /** Get history entries for an item (without snapshots, for listing).
   * @param {string} itemId - Item GUID
   * @returns {Promise<Array<{itemId, timestamp, deleted}>>}
   */
  async getHistory(itemId) {
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('item-history', 'readonly');
      const index = tx.objectStore('item-history').index('itemId');
      const req = index.getAll(itemId);
      req.onsuccess = () => {
        resolve(req.result.map(e => ({ itemId: e.itemId, timestamp: e.timestamp, deleted: !!e.deleted })));
      };
      req.onerror = () => reject(req.error);
    });
  }

  /** Get a specific history entry with full snapshot.
   * @param {string} itemId - Item GUID
   * @param {number} timestamp - Exact timestamp of the entry
   * @returns {Promise<Object|null>} The full history entry or null
   */
  async getHistoryEntry(itemId, timestamp) {
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('item-history', 'readonly');
      const req = tx.objectStore('item-history').get([itemId, timestamp]);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => reject(req.error);
    });
  }

  /** Get all deletion records since a given timestamp.
   * Used by sync to inform the other device about deleted items.
   * @param {number} since - Timestamp threshold
   * @returns {Promise<Array<{itemId, timestamp}>>}
   */
  async getDeletedSince(since) {
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('item-history', 'readonly');
      const req = tx.objectStore('item-history').getAll();
      req.onsuccess = () => {
        const deletions = req.result
          .filter(e => e.deleted && e.timestamp > since)
          .map(e => ({ itemId: e.itemId, timestamp: e.timestamp }));
        resolve(deletions);
      };
      req.onerror = () => reject(req.error);
    });
  }

  // [BEGIN:validateItem]
  /** Validate an item before storage — checks type chain and code name uniqueness.
   * @param {Object} item - The item to validate
   * @param {Object} [kernel] - Kernel reference for code item checks
   */
  async _validateItem(item, kernel) {
    // See [item/atom](item://00000000-0000-0000-0000-000000000000)
    const ITEM_ID = kernel?.IDS?.ITEM || "00000000-0000-0000-0000-000000000000";
    const TYPE_DEFINITION_ID = kernel?.IDS?.TYPE_DEFINITION || "11111111-0000-0000-0000-000000000000";

    // Validate type chain (must reach a valid root, no unexpected cycles)
    await this._validateTypeChain(item.type, new Set(), ITEM_ID, TYPE_DEFINITION_ID);

    // If code item, validate name uniqueness within the same namespace
    if (kernel && await kernel.isCodeItem(item)) {
      if (!item.name) {
        throw new Error(`Code item ${item.id} must have a name`);
      }

      const itemNamespace = item.id.includes(':') ? item.id.split(':')[0] : '';
      const existing = await this.query({ name: item.name });
      const conflict = existing.find(i => {
        if (i.id === item.id) return false;
        const existingNamespace = i.id.includes(':') ? i.id.split(':')[0] : '';
        return existingNamespace === itemNamespace;
      });

      if (conflict) {
        throw new Error(`Code item named '${item.name}' already exists in this namespace (id: ${conflict.id})`);
      }
    }
  }
  // [END:validateItem]

  // [BEGIN:validateTypeChain]
  async _validateTypeChain(typeId, visited, ITEM_ID, TYPE_DEFINITION_ID) {
    // Valid termination points:
    // - ITEM (old model: atom.type = atom)
    // - TYPE_DEFINITION (new model: type-definition.type = type-definition)
    if (typeId === ITEM_ID || typeId === TYPE_DEFINITION_ID) {
      return;
    }

    if (visited.has(typeId)) {
      throw new Error(`Circular type chain detected at: ${typeId}`);
    }

    visited.add(typeId);

    try {
      const typeItem = await this.get(typeId);
      await this._validateTypeChain(typeItem.type, visited, ITEM_ID, TYPE_DEFINITION_ID);
    } catch (error) {
      if (error.message.includes("not found")) {
        throw new Error(`Type chain broken - item '${typeId}' not found`);
      }
      throw error;
    }
  }
  // [END:validateTypeChain]

  // --- Blob storage ---

  /** Store a Blob keyed by item ID (with instance prefix).
   * @param {string} id - Item GUID
   * @param {Blob} blob - The binary blob to store
   */
  setBlob(id, blob) {
    const actualId = this._prefixId(id);
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('blobs', 'readwrite');
      const req = tx.objectStore('blobs').put({ id: actualId, blob });
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }

  /** Retrieve a Blob by item ID.
   * @param {string} id - Item GUID
   * @returns {Promise<Blob>} The blob
   */
  getBlob(id) {
    const actualId = this._prefixId(id);
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('blobs', 'readonly');
      const req = tx.objectStore('blobs').get(actualId);
      req.onsuccess = () => {
        if (!req.result) reject(new Error(`Blob not found: ${id}`));
        else resolve(req.result.blob);
      };
      req.onerror = () => reject(req.error);
    });
  }

  /** Delete a Blob by item ID. Silent no-op if not found.
   * @param {string} id - Item GUID
   */
  deleteBlob(id) {
    const actualId = this._prefixId(id);
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('blobs', 'readwrite');
      const req = tx.objectStore('blobs').delete(actualId);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }

  /** Delete all blobs whose ID starts with a prefix.
   * @param {string} prefix - ID prefix to match
   * @returns {Promise<number>} Number of blobs deleted
   */
  deleteBlobsByPrefix(prefix) {
    return new Promise((resolve, reject) => {
      const tx = this._db.transaction('blobs', 'readwrite');
      const store = tx.objectStore('blobs');
      const req = store.getAll();
      req.onsuccess = () => {
        const toDelete = req.result.filter(entry => entry.id.startsWith(prefix));
        for (const entry of toDelete) {
          store.delete(entry.id);
        }
        tx.oncomplete = () => resolve(toDelete.length);
        tx.onerror = () => reject(tx.error);
      };
      req.onerror = () => reject(req.error);
    });
  }
}
// [END:Storage]

// Module System - See [Core Concepts - Code as Data](item://a0a0a0a0-d0c0-4000-8000-000000000002#description?region=Code)

// [BEGIN:ModuleSystem]
/** Module system — loads code items as ES modules with caching and circular dependency detection. */
export class ModuleSystem {
  constructor(kernel) {
    this.kernel = kernel;
    this.moduleCache = new Map(); // itemId -> { module, timestamp, name }
    this.nameCache = new Map(); // name -> itemId (cached name resolution)
    this.loadingPromises = new Map(); // itemId -> Promise (tracks in-flight loads)
    this.moduleMetadata = new WeakMap(); // module object → { itemId, itemName }
    this.blobUrlToName = new Map(); // blob URL → item name (for source attribution in Tauri)
  }

  /** Initialize event listeners for cache invalidation on item updates. */
  initEventListeners() {
    // Listen for item updates to invalidate module cache
    this.kernel.events.on(this.kernel.EVENT_IDS.ITEM_UPDATED, (event) => {
      const id = event.content?.id;
      if (!id) return;

      // Invalidate module cache for changed item
      const cached = this.moduleCache.get(id);
      if (cached) {
        // Call cleanup() on the old module before eviction (tears down singletons, event subscriptions, etc.)
        if (typeof cached.module?.cleanup === 'function') {
          try { cached.module.cleanup(); } catch (e) {
            console.warn(`[module-system] cleanup() failed for ${cached.name || id}:`, e);
          }
        }
        this.moduleCache.delete(id);
      }
      // Invalidate name cache if this item's name was cached
      for (const [name, cachedId] of this.nameCache) {
        if (cachedId === id) {
          this.nameCache.delete(name);
          break;
        }
      }
    });
  }

  // [BEGIN:require]
  /** Load a code item as an ES module by name or ID. Caches results.
   * @param {string} nameOrId - Item name (e.g. 'markdown-it') or GUID
   * @param {Set} [callStack] - Internal: tracks loading chain for circular dependency detection
   * @returns {Promise<Object>} The module's exports
   */
  async require(nameOrId, callStack = new Set()) {
    // Resolve name to ID if necessary
    let itemId = nameOrId;

    // Check if it's a name (not a UUID pattern)
    if (!nameOrId.includes("-") || nameOrId.length < 36) {
      // Check name cache first (avoids storage.query)
      const cachedId = this.nameCache.get(nameOrId);
      if (cachedId) {
        itemId = cachedId;
      } else {
        const items = await this.kernel.storage.query({ name: nameOrId });
        if (items.length === 0) {
          throw new Error(`Code item not found: ${nameOrId}`);
        }
        itemId = items[0].id;
        this.nameCache.set(nameOrId, itemId);
      }
    }

    // Check for circular dependencies
    if (callStack.has(itemId)) {
      const chain = Array.from(callStack).join(" -> ");
      throw new Error(`Circular dependency detected: ${chain} -> ${itemId}`);
    }

    // Check module cache first (avoids storage.get for cached modules)
    // Cache is invalidated via item:updated events, so we trust it
    const cached = this.moduleCache.get(itemId);
    if (cached) {
      return cached.module;
    }

    // Check if this module is already being loaded (prevents race condition)
    // This handles the case where multiple concurrent calls try to load the same module
    const inFlight = this.loadingPromises.get(itemId);
    if (inFlight) {
      return inFlight;
    }

    // Create the loading promise immediately to prevent race conditions
    // Other concurrent requires will hit the inFlight check above
    callStack.add(itemId);
    const loadPromise = (async () => {
      const item = await this.kernel.storage.get(itemId);
      const originalName = nameOrId !== itemId ? nameOrId : item.name;
      const module = await this.evaluateCodeItem(item, callStack);
      // Update cache on success
      this.moduleCache.set(itemId, {
        module,
        timestamp: item.modified,
        name: originalName
      });
      try { this.moduleMetadata.set(module, { itemId: item.id, itemName: item.name || item.id }); } catch(e) { /* non-extensible */ }
      return module;
    })().finally(() => {
      // Always clean up in-flight tracking
      this.loadingPromises.delete(itemId);
      callStack.delete(itemId);
    });

    this.loadingPromises.set(itemId, loadPromise);
    return loadPromise;
  }
  // [END:require]

  // [BEGIN:evaluateCodeItem]
  /** Compile and execute a code item as an ES module via blob URL.
   * @param {Object} item - Code item with content.code
   * @returns {Promise<Object>} The module's exports
   */
  async evaluateCodeItem(item) {
    if (!item.content?.code) {
      throw new Error(`Item ${item.id} has no code to evaluate`);
    }

    const code = `
      "use strict";
      ${item.content.code}
      //# sourceURL=${item.name || item.id}.js
    `;

    const blob = new Blob([code], { type: "application/javascript" });
    const url = URL.createObjectURL(blob);
    this.blobUrlToName.set(url, item.name || item.id);

    try {
      const module = await import(url);
      return module;
    } catch (error) {
      const wrappedError = new Error(`Failed to evaluate code item ${item.id} (${item.name}): ${error.message}`, { cause: error });
      wrappedError.stack = error.stack;
      throw wrappedError;
    } finally {
      URL.revokeObjectURL(url);
    }
  }
  // [END:evaluateCodeItem]

  /** Check if an item is a code item (type chain includes CODE).
   * @param {Object} item - The item to check
   * @returns {Promise<boolean>}
   */
  async isCodeItem(item) {
    return await this.typeChainIncludes(item.type, this.kernel.IDS.CODE);
  }

  /** Build the extends chain for a type (from the given type up to ITEM root).
   * Falls back to walking 'type' field if 'extends' is not present.
   * @param {string} typeId - Type GUID to start from
   * @returns {Promise<string[]>} Array of type GUIDs in chain order
   */
  async buildExtendsChain(typeId) {
    const chain = [];
    let current = typeId;
    const visited = new Set();

    while (current && !visited.has(current)) {
      chain.push(current);
      visited.add(current);

      // Stop at ITEM (root)
      if (current === this.kernel.IDS.ITEM) break;

      try {
        const typeItem = await this.kernel.storage.get(current);

        // Prefer 'extends' field (new model)
        if (typeItem.extends !== undefined) {
          // null means root reached
          if (typeItem.extends === null) break;
          current = typeItem.extends;
        } else {
          // Fallback to 'type' field (old model) for backwards compatibility
          // Stop at TYPE_DEFINITION boundary to avoid meta-level (old heuristic)
          if (typeItem.type === this.kernel.IDS.TYPE_DEFINITION) break;
          current = typeItem.type;
        }
      } catch {
        break;
      }
    }

    return chain;
  }

  // [BEGIN:typeChainIncludes]
  /** Check if a type's extends chain includes a target type.
   * @param {string} typeId - The type to check
   * @param {string} targetId - The target type to look for
   * @returns {Promise<boolean>}
   */
  async typeChainIncludes(typeId, targetId) {
    const chain = await this.buildExtendsChain(typeId);
    return chain.includes(targetId);
  }
  // [END:typeChainIncludes]

  /** Get a cached module synchronously (returns null if not cached).
   * Use for synchronous code paths that can't await require().
   * @param {string} nameOrId - Item name or GUID
   * @returns {Object|null} Cached module or null
   */
  getCached(nameOrId) {
    // For name lookups, we can't do async storage query, so only works with IDs
    // or if we've seen this name before in the cache (stored during require)
    for (const [itemId, cached] of this.moduleCache) {
      // Check if this cache entry matches by name (from previous load) or ID
      if (cached.name === nameOrId || itemId === nameOrId) {
        return cached.module;
      }
    }
    return null;
  }

  /** Get metadata (itemId, itemName) for a loaded module object.
   * @param {Object} obj - A module object returned by require()
   * @returns {{itemId: string, itemName: string}|null}
   */
  getModuleInfo(obj) {
    if (!obj || typeof obj !== 'object') return null;
    return this.moduleMetadata.get(obj) || null;
  }

  /** Look up the item name for a blob URL (for source attribution in environments where
   * //# sourceURL is not honored in stack traces, e.g. Tauri).
   * @param {string} url - A blob URL
   * @returns {string|null} Item name, or null if not found
   */
  getNameForBlobUrl(url) {
    return this.blobUrlToName.get(url) ?? null;
  }

  /** Clear all module and name caches (forces fresh evaluation on next require). */
  clearCache() {
    this.moduleCache.clear();
    this.nameCache.clear();
    this.loadingPromises.clear();
    this.blobUrlToName.clear();
  }
}
// [END:ModuleSystem]

// kernel-safe-mode module
// See [Architecture Overview - Safe Mode](item://a0a0a0a0-d0c0-4000-8000-000000000003#Safe-Mode)

// [BEGIN:SafeMode]
export class SafeMode {
  constructor(kernel) {
    this.kernel = kernel;
  }

  // [BEGIN:render]
  render(rootElement) {
    rootElement.innerHTML = `
      <div id="safe-mode">
        <h1>⚠️ Safe Mode</h1>
        <p>Booted with minimal kernel only. No user code items loaded.</p>
        <p>Use this mode to fix broken code items.</p>
        <p style="color: #666; font-size: 0.75rem;">Access safe mode anytime by adding <code>?safe=1</code> to the URL.</p>

        <div class="actions">
          <button onclick="kernel.safeMode.listAllItems()">View All Items</button>
          <button onclick="kernel.safeMode.listCodeItems()">View Code Items Only</button>
          <button onclick="kernel.safeMode.exportData(false)">Export All Data</button>
          <button onclick="kernel.safeMode.importData()">Import Data</button>
          <button onclick="kernel.safeMode.resetSystem()">Reset System (Dangerous!)</button>
          <button onclick="(function() { var p = new URLSearchParams(window.location.search); p.delete('safe'); var qs = p.toString(); window.location.href = window.location.pathname + (qs ? '?' + qs : ''); })()">Exit Safe Mode</button>
        </div>

        <div id="item-list" class="item-list"></div>
      </div>
    `;
  }

  async listAllItems() {
    const items = await this.kernel.storage.getAll();
    this._renderItemList(items, "All Items");
  }

  async listCodeItems() {
    const items = await this.kernel.storage.getAll();
    const codeItems = [];

    for (const item of items) {
      if (await this.kernel.isCodeItem(item)) {
        codeItems.push(item);
      }
    }

    this._renderItemList(codeItems, "Code Items");
  }
  // [END:render]

  _renderItemList(items, title) {
    const listEl = document.getElementById("item-list");
    if (!listEl) return;

    listEl.innerHTML = `<h2>${title} (${items.length})</h2>`;

    items.sort((a,b) => (a.name || '').localeCompare(b.name || ''));

    for (const item of items) {
      const preview = document.createElement("div");
      preview.className = "item-preview";
      preview.innerHTML = `
        <div class="item-info">
          <div class="item-name">${this._escapeHtml(item.name || item.id)}</div>
          <div class="item-type">Type: ${this._escapeHtml(item.type)}</div>
        </div>
        <div>
          <button onclick="kernel.safeMode.editItem('${item.id}')">Edit as JSON</button>
          <button onclick="kernel.safeMode.deleteItem('${item.id}')" style="color: red;">Delete</button>
        </div>
      `;
      listEl.appendChild(preview);
    }
  }

  // [BEGIN:editItem]
  async editItem(itemId) {
    const item = await this.kernel.storage.get(itemId);
    const json = JSON.stringify(item, null, 2);

    const rootElement = this.kernel.rootElement;
    rootElement.innerHTML = `
      <div class="raw-editor">
        <h2>Editing: ${this._escapeHtml(item.name || item.id)}</h2>
        <textarea id="raw-json" rows="30">${this._escapeHtml(json)}</textarea>
        <div class="actions">
          <button onclick="kernel.safeMode.saveItem('${itemId}')">Save</button>
          <button onclick="kernel.safeMode.render(kernel.rootElement)">Cancel</button>
        </div>
      </div>
    `;
  }

  async saveItem(itemId) {
    const textarea = document.getElementById("raw-json");
    if (!textarea) return;

    try {
      const updated = JSON.parse(textarea.value);
      await this.kernel.saveItem(updated);
      this.kernel.moduleSystem.clearCache();
      alert("Saved successfully");
      this.render(this.kernel.rootElement);
    } catch (error) {
      alert(`Error: ${error.message}`);
    }
  }
  // [END:editItem]

  async deleteItem(itemId) {
    if (!confirm(`Delete item ${itemId}? This cannot be undone.`)) {
      return;
    }

    await this.kernel.storage.delete(itemId);
    await this.listAllItems();
  }

  async exportData(singleFile = true) {
    const count = await this.kernel.export(singleFile);
    alert(`Exported ${count} items`);
  }

  importData() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.setAttribute('multiple', '');

    input.onchange = async (e) => {
      const files = Array.from(e.target.files);
      if (files.length === 0) return;

      try {
        let items = [];
        for (const file of files) {
          const text = await file.text();
          const data = JSON.parse(text);
          if (Array.isArray(data)) {
            items = items.concat(data);
          } else {
            items.push(data);
          }
        }

        let created = 0, updated = 0;

        for (const item of items) {
          const exists = await this.kernel.storage.exists(item.id);
          await this.kernel.saveItem(item);
          if (exists) {
            updated++;
          } else {
            created++;
          }
        }

        // Clear module cache
        this.kernel.moduleSystem.clearCache();

        alert(`Import complete!\nCreated: ${created}\nUpdated: ${updated}`);
        this.render(this.kernel.rootElement);

      } catch (error) {
        alert(`Import failed: ${error.message}`);
      }
    };

    input.click();
  }

  // [BEGIN:resetSystem]
  async resetSystem() {
    if (!confirm("WARNING: This will delete ALL your data!\n\nOnly the seed items will remain.\n\nHave you exported your data? This cannot be undone!")) {
      return;
    }

    const items = await this.kernel.storage.getAll();
    for (const item of items) {
      await this.kernel.storage.delete(item.id);
    }

    await this.kernel.ensureSeedItems();
    this.render(this.kernel.rootElement);
    alert("System reset complete");
  }
  // [END:resetSystem]

  _escapeHtml(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }
}
// [END:SafeMode]

