/* === THEME CONFIGURATION === */
/* Change these two values to theme the entire UI */
:root {
  --base-hue: {{content.hue}};        /* 0-360: Blue=220, Green=145, Purple=280, Orange=30, Teal=180, Red=0 */
  --tint-strength: {{content.tintStrength}};  /* 0=pure gray, 0.02=subtle tint, 0.05=noticeable, 0.1=strong */

  /* === DERIVED COLORS (auto-generated from base-hue) === */

  /* Primary accent */
  --color-primary: oklch(55% 0.2 var(--base-hue));
  --color-primary-hover: oklch(45% 0.22 var(--base-hue));
  --color-primary-light: oklch(92% 0.05 var(--base-hue));

  /* Backgrounds */
  --color-bg-body: oklch(93% var(--tint-strength) var(--base-hue));
  --color-bg-surface: oklch(100% 0 0);  /* white */
  --color-bg-surface-alt: oklch(100% var(--tint-strength) var(--base-hue));
  --color-bg-hover: oklch(91% var(--tint-strength) var(--base-hue));
  --color-bg-chrome: oklch(96% var(--tint-strength) var(--base-hue));

  /* Borders */
  --color-border: oklch(80% var(--tint-strength) var(--base-hue));
  --color-border-light: oklch(88% var(--tint-strength) var(--base-hue));
  --color-border-dark: oklch(65% var(--tint-strength) var(--base-hue));

  /* Text */
  --color-text: oklch(25% var(--tint-strength) var(--base-hue));
  --color-text-secondary: oklch(45% var(--tint-strength) var(--base-hue));
  --color-text-tertiary: oklch(60% var(--tint-strength) var(--base-hue));

  /* Semantic colors (fixed hues for meaning) */
  --color-success: oklch(55% 0.18 145);
  --color-success-light: oklch(92% 0.05 145);
  --color-warning: oklch(75% 0.15 85);
  --color-warning-light: oklch(94% 0.08 85);
  --color-danger: oklch(55% 0.2 25);
  --color-danger-light: oklch(92% 0.06 25);

  /* Selection */
  --color-selection: oklch(65% 0.12 var(--base-hue));

  /* UI tokens */
  --border-radius: 4px;
  --border-radius-lg: 8px;
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.06), 0 2px 8px oklch(0% 0 0 / 0.04);
  --shadow-md: 0 2px 4px oklch(0% 0 0 / 0.08), 0 8px 24px oklch(0% 0 0 / 0.08);
}

/* === BASE STYLES === */
* {
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
}

html {
  font-size: {{content.baseFontSize}}px;
}

html, body {
  height: 100%;
  margin: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: var(--color-bg-body);
  color: var(--color-text);
  display: flex;
  flex-direction: column;
}

#app {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

#main-view {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--color-bg-surface-alt);
  border-radius: var(--border-radius-lg);
  padding: 2px;
  box-shadow: var(--shadow-sm);
  min-height: 0;
  overflow: auto;
}

.render-error {
  background: var(--color-danger-light);
  border: 1px solid var(--color-danger);
  padding: 15px;
  border-radius: var(--border-radius);
}

.render-error h3 {
  color: var(--color-danger);
  margin-top: 0;
}

.render-error pre {
  background: var(--color-bg-surface);
  padding: 10px;
  overflow-x: auto;
  font-size: 0.75rem;
}

.json-view {
  background: var(--color-bg-surface-alt);
  padding: 10px;
  border-radius: var(--border-radius);
  overflow-x: auto;
  font-size: 0.75rem;
}

/* CodeMirror: restore monospace default that explicit html font-size overrides */
.CodeMirror {
  font-size: 0.8125rem;
}

/* Selection indicator */
[data-item-id] {
  cursor: pointer;
}

[data-item-id].item-selected {
  outline: 2px outset var(--color-selection);
  outline-offset: 0px;
}

[data-item-id]:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Safe Mode Styles */
#safe-mode {
  max-width: 800px;
  margin: 0 auto;
}

#safe-mode h1 {
  color: var(--color-warning);
}

#safe-mode .actions {
  display: flex;
  gap: 10px;
  margin: 20px 0;
  flex-wrap: wrap;
}

#safe-mode button {
  padding: 10px 20px;
  font-size: 0.875rem;
  cursor: pointer;
  border: 1px solid var(--color-border);
  background: var(--color-bg-surface);
  border-radius: var(--border-radius);
}

#safe-mode button:hover {
  background: var(--color-bg-hover);
}

.item-list {
  margin-top: 20px;
}

.item-preview {
  padding: 10px;
  border: 1px solid var(--color-border-light);
  margin-bottom: 8px;
  border-radius: var(--border-radius);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--color-bg-surface);
}

.item-preview .item-info {
  flex: 1;
}

.item-preview .item-name {
  font-weight: bold;
}

.item-preview .item-type {
  font-size: 0.75rem;
  color: var(--color-text-secondary);
}

/* Raw Editor Styles */
.raw-editor {
  max-width: 1000px;
  margin: 0 auto;
}

.raw-editor textarea {
  width: 100%;
  font-family: 'SF Mono', Monaco, 'Courier New', monospace;
  font-size: 0.8125rem;
  padding: 15px;
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius);
}

.raw-editor .actions {
  margin-top: 10px;
  display: flex;
  gap: 10px;
}

/* Navigation */
.nav-bar {
  display: flex;
  gap: 10px;
  margin-bottom: 15px;
  padding-bottom: 15px;
  border-bottom: 1px solid var(--color-border-light);
}

.nav-bar button {
  padding: 8px 16px;
  cursor: pointer;
  border: 1px solid var(--color-border);
  background: var(--color-bg-surface);
  border-radius: var(--border-radius);
}

.nav-bar button:hover {
  background: var(--color-bg-hover);
}

/* REPL Bottom Panel */
#repl-panel {
  display: flex;
  flex-direction: column;
  background: var(--color-bg-surface);
  border-top: 1px solid var(--color-border);
  min-height: 36px;
}

#repl-panel.collapsed {
  flex: 0 0 36px;
}

#repl-panel.expanded {
  flex: 0 0 300px;
}

/* Collapse bar - always visible */
.repl-collapse-bar {
  height: 36px;
  display: flex;
  align-items: center;
  padding: 0 16px;
  background: var(--color-bg-body);
  cursor: pointer;
  flex-shrink: 0;
  border-bottom: 1px solid var(--color-border-light);
  gap: 12px;
}

.repl-collapse-bar:hover {
  background: var(--color-bg-hover);
}

.repl-collapse-bar .repl-title {
  font-weight: 600;
  font-size: 0.8125rem;
  color: var(--color-text);
}

.repl-collapse-bar .repl-hint {
  font-size: 0.75rem;
  color: var(--color-text-tertiary);
}

.repl-collapse-bar .repl-expand-icon {
  margin-left: auto;
  font-size: 0.75rem;
  color: var(--color-text-secondary);
}

/* Panel content - horizontal layout */
#repl-panel.collapsed .repl-panel-content {
  display: none;
}

.repl-panel-content {
  display: flex;
  flex-direction: row;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

/* Input section (left) */
.repl-input-section {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 200px;
  border-right: 1px solid var(--color-border-light);
}

.repl-input-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
}

#repl-input {
  width: 100%;
  height: 100%;
  min-height: 80px;
  font-family: 'SF Mono', Monaco, Menlo, 'Courier New', monospace;
  font-size: 0.8125rem;
  line-height: 1.5;
  padding: 12px;
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius);
  resize: none;
  tab-size: 2;
  -moz-tab-size: 2;
  box-sizing: border-box;
}

.repl-actions {
  display: flex;
  gap: 10px;
  padding: 10px 12px;
  align-items: center;
  background: var(--color-bg-surface);
  border-top: 1px solid var(--color-border-light);
  flex-shrink: 0;
}

.repl-actions button {
  padding: 6px 14px;
  font-size: 0.8125rem;
  cursor: pointer;
  border: 1px solid var(--color-border);
  background: var(--color-bg-surface);
  border-radius: var(--border-radius);
}

.repl-actions button:hover {
  background: var(--color-bg-hover);
}

.repl-actions button.primary {
  background: var(--color-primary);
  color: var(--color-bg-surface);
  border-color: var(--color-primary);
}

.repl-actions button.primary:hover {
  background: var(--color-primary-hover);
}

/* Vertical splitter between input and output */
.repl-vertical-splitter {
  width: 6px;
  background: var(--color-border);
  cursor: col-resize;
  flex-shrink: 0;
}

.repl-vertical-splitter:hover {
  background: var(--color-border-dark);
}

/* Output section (right) */
.repl-output-section {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 200px;
  overflow: hidden;
}

.repl-transcript-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  border-bottom: 1px solid var(--color-border-light);
  flex-shrink: 0;
}

.repl-transcript-header h4 {
  margin: 0;
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
}

.repl-transcript-header button {
  padding: 4px 10px;
  font-size: 0.75rem;
  cursor: pointer;
  border: 1px solid var(--color-border);
  background: var(--color-bg-surface);
  border-radius: var(--border-radius);
}

.repl-transcript-header button:hover {
  background: var(--color-bg-hover);
}

#repl-transcript-entries {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
}

.repl-entry {
  margin-bottom: 12px;
  padding: 10px;
  background: var(--color-bg-surface-alt);
  border-radius: var(--border-radius);
  border-left: 3px solid var(--color-border);
}

.repl-entry.error {
  background: var(--color-danger-light);
  border-left-color: var(--color-danger);
}

.repl-entry.success {
  border-left-color: var(--color-success);
}

.repl-entry-code {
  font-family: 'SF Mono', Monaco, 'Courier New', monospace;
  font-size: 0.75rem;
  color: var(--color-text);
  margin-bottom: 8px;
  white-space: pre-wrap;
}

.repl-entry-console {
  font-family: 'SF Mono', Monaco, 'Courier New', monospace;
  font-size: 0.75rem;
  color: var(--color-text-secondary);
  white-space: pre-wrap;
  margin-bottom: 4px;
  padding: 4px 0;
  border-bottom: 1px solid var(--color-border);
  opacity: 0.8;
}

.repl-entry-output {
  font-family: 'SF Mono', Monaco, 'Courier New', monospace;
  font-size: 0.75rem;
  color: var(--color-text-secondary);
  white-space: pre-wrap;
  max-height: 200px;
  overflow-y: auto;
}

.repl-entry-error {
  font-family: 'SF Mono', Monaco, 'Courier New', monospace;
  font-size: 0.75rem;
  color: var(--color-danger);
  white-space: pre-wrap;
}

/* Panel height resize handle */
#repl-panel-splitter {
  height: 6px;
  background: var(--color-border);
  cursor: row-resize;
  flex-shrink: 0;
}

#repl-panel-splitter:hover {
  background: var(--color-border-dark);
}

#repl-panel.collapsed ~ #repl-panel-splitter {
  display: none;
}

/* === MOBILE ENVIRONMENT === */
/* Android WebView doesn't report env(safe-area-inset-*), so MainActivity.kt
   injects --android-nav-height and --android-status-height as CSS variables. */
.env-mobile #main-view {
  border-radius: 0;
  padding: 0;
  box-shadow: none;
}

.env-mobile #app {
  padding: env(safe-area-inset-top) env(safe-area-inset-right) 0 env(safe-area-inset-left);
}


.env-mobile button,
.env-mobile .item-preview,
.env-mobile .repl-collapse-bar {
  min-height: 44px;
}

/* Context menu submenus: inline and always expanded on mobile */
.env-mobile .context-menu-submenu-items {
  position: static;
  display: block;
  border: none;
  box-shadow: none;
  padding-left: 16px;
  min-width: 0;
}
.env-mobile .context-menu-submenu::after {
  display: none;
}
.env-mobile .context-menu-item {
  min-height: 44px;
}

/* Element Inspector */
.hobson-inspect-mode { cursor: crosshair !important; }
.hobson-inspect-mode * { cursor: crosshair !important; }
.hobson-inspect-highlight { outline: 2px solid var(--color-primary) !important; outline-offset: 1px; }

// Related Items View — JS watch handler triggers re-render on selection change

const WIDGET_TYPE_ID = '1e9ffc8d-0e0d-4020-9865-b4ca6a05cbae';

// State survives moduleSystem.clearCache()
const CACHE_KEY = '__relatedItemsView__';
if (!globalThis[CACHE_KEY]) {
  globalThis[CACHE_KEY] = { rendering: false, pending: false };
}
const S = globalThis[CACHE_KEY];

export async function onViewportSelectionChanged(payload, api) {
  const selectedId = payload?.current?.itemId;
  if (selectedId) {
    let item;
    try { item = await api.get(selectedId); } catch (e) { item = null; }
    if (item && item.type === WIDGET_TYPE_ID) return;
  }
  // Serialize re-renders: if one is in progress, mark pending and let
  // the current cycle pick it up. Prevents concurrent morphdom passes
  // on the same DOM node which can cause visual duplicates.
  if (S.rendering) {
    S.pending = true;
    return;
  }
  S.rendering = true;
  try {
    do {
      S.pending = false;
      const vpMgr = await api.require('viewport-manager');
      const rendering = vpMgr.getRendering();
      if (rendering) await rendering.rerenderByType(WIDGET_TYPE_ID);
    } while (S.pending);
  } finally {
    S.rendering = false;
  }
}

export async function render(item, api) {
  const genericView = await api.require('generic-view');
  return genericView.render(item, api);
}

export async function render(item, api) {
  const genericView = await api.require('generic-view');
  return genericView.render(item, api);
}

export async function render(value, options, api) {
  const opts = options || {};
  const { onChange, label, placeholder } = opts;
  const isEditable = !!onChange;

  const hob = await api.require('hob-interpreter');

  const wrapper = api.createElement('div', { className: 'field-view-hob-text' });
  wrapper.style.cssText = 'display: flex; flex-direction: column; gap: 6px;';

  if (label) {
    const labelEl = api.createElement('label');
    labelEl.textContent = label;
    labelEl.style.cssText = 'font-weight: 500; font-size: 0.875rem; color: var(--color-text);';
    wrapper.appendChild(labelEl);
  }

  // Render AST to source text. value should be a compact JSON AST array.
  let initialSource = '';
  try {
    initialSource = hob.prettyPrintAll(value || []);
  } catch (e) {
    initialSource = ';; error rendering AST: ' + (e.message || String(e)) + '\n';
  }

  if (!isEditable) {
    const pre = api.createElement('pre');
    pre.textContent = initialSource;
    pre.style.cssText = 'margin: 0; padding: 10px; background: var(--color-bg-surface-alt); border: 1px solid var(--color-border-light); border-radius: var(--border-radius); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.8125rem; white-space: pre-wrap; overflow-x: auto; color: var(--color-text);';
    wrapper.appendChild(pre);
    return wrapper;
  }

  const textarea = api.createElement('textarea');
  textarea.value = initialSource;
  if (placeholder) textarea.placeholder = placeholder;
  textarea.spellcheck = false;
  textarea.setAttribute('autocapitalize', 'off');
  textarea.setAttribute('autocomplete', 'off');
  textarea.setAttribute('autocorrect', 'off');
  textarea.style.cssText = 'width: 100%; min-height: 120px; padding: 10px; background: var(--color-bg-surface); border: 1px solid var(--color-border); border-radius: var(--border-radius); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.8125rem; color: var(--color-text); resize: vertical; box-sizing: border-box;';
  wrapper.appendChild(textarea);

  // Error banner — hidden until a parse fails
  const errorBanner = api.createElement('div');
  errorBanner.style.cssText = 'display: none; padding: 6px 10px; background: rgba(220, 50, 50, 0.1); color: var(--color-danger); border: 1px solid var(--color-danger); border-radius: var(--border-radius); font-size: 0.75rem; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; white-space: pre-wrap;';
  wrapper.appendChild(errorBanner);

  function showError(msg) {
    errorBanner.textContent = msg;
    errorBanner.style.display = 'block';
  }
  function clearError() {
    errorBanner.style.display = 'none';
    errorBanner.textContent = '';
  }

  // Debounced parse-and-emit. HobError messages already include "at line X, col Y".
  let debounceTimer = null;
  textarea.addEventListener('input', () => {
    if (debounceTimer) clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => {
      debounceTimer = null;
      try {
        const newAst = hob.readAll(textarea.value);
        clearError();
        onChange(newAst);
      } catch (e) {
        showError(e.message || String(e));
      }
    }, 200);
  });

  // Toolbar — Format reformats the textarea in place.
  const toolbar = api.createElement('div');
  toolbar.style.cssText = 'display: flex; gap: 6px;';

  const formatBtn = api.createElement('button');
  formatBtn.type = 'button';
  formatBtn.textContent = 'Format';
  formatBtn.style.cssText = 'padding: 4px 10px; font-size: 0.75rem; background: var(--color-bg-surface-alt); border: 1px solid var(--color-border); border-radius: var(--border-radius); color: var(--color-text); cursor: pointer;';
  formatBtn.addEventListener('click', () => {
    try {
      const ast = hob.readAll(textarea.value);
      textarea.value = hob.prettyPrintAll(ast);
      clearError();
      onChange(ast);
    } catch (e) {
      showError(e.message || String(e));
    }
  });
  toolbar.appendChild(formatBtn);

  wrapper.appendChild(toolbar);

  return wrapper;
}

// Hob Language Interpreter — Phase 5
// A Lisp interpreter for the Hobson item system
// Phase 1: Reader, evaluator, printer, environment, stdlib, item ops
// Phase 2: Macros, quasiquote, destructuring, multi-arity, atoms, concurrency, error handling
// Phase 3: DOM runtime (hiccupToDOM, parseTag), view ops, def-view macro
// Phase 4: Watches and events (def-watch, emit!, hobToJs, JS interop fix)
// Phase 5: Reactivity (selector-based, via api._renderItemId/_selectorInfo) 

// ============================================================
// Error types
// ============================================================

class HobError extends Error {
  constructor(message, hobExpr, hobStack) {
    super(message);
    this.name = 'HobError';
    this.hobExpr = hobExpr ?? null;
    // Snapshot the stack (slice last 10 frames, copy each frame's data)
    this.hobStack = (hobStack || []).slice(-10).map(f => ({
      name: f.name || null,
      expr: f.expr || null
    }));
  }
}

function hobError(msg, node, callStack, expr) {
  const line = node?.line ?? null;
  const col = node?.col ?? null;
  const locStr = line != null ? ` at line ${line}, col ${col}` : '';
  return new HobError(`${msg}${locStr}`, expr, callStack);
}

// ============================================================
// Tokenizer
// ============================================================

const TOKEN = {
  NUMBER: 'number',
  STRING: 'string',
  KEYWORD: 'keyword',
  SYMBOL: 'symbol',
  BOOLEAN: 'boolean',
  NIL: 'nil',
  ITEM_REF: 'item-ref',
  LPAREN: '(',
  RPAREN: ')',
  LBRACKET: '[',
  RBRACKET: ']',
  LBRACE: '{',
  RBRACE: '}',
  QUOTE: 'quote',
  HASH_LBRACE: '#{',
  QUASIQUOTE: 'quasiquote',
  UNQUOTE: 'unquote',
  UNQUOTE_SPLICING: 'unquote-splicing',
  ANON_FN: 'anon-fn',
};

function tokenize(source) {
  const tokens = [];
  let i = 0;
  let line = 1;
  let col = 0;
  const len = source.length;

  function ch() { return source[i]; }
  function advance() {
    if (source[i] === '\n') { line++; col = 0; }
    else { col++; }
    i++;
  }

  function isWhitespace(c) { return c === ' ' || c === '\t' || c === '\n' || c === '\r' || c === ','; }
  function isDigit(c) { return c >= '0' && c <= '9'; }
  function isSymbolChar(c) {
    return c && !isWhitespace(c) && c !== '(' && c !== ')' && c !== '[' && c !== ']'
      && c !== '{' && c !== '}' && c !== '"' && c !== ';' && c !== '@' && c !== '\''
      && c !== '`' && c !== '~' && c !== '#';
  }

  while (i < len) {
    // Skip whitespace
    if (isWhitespace(ch())) { advance(); continue; }

    // Skip comments
    if (ch() === ';') {
      while (i < len && ch() !== '\n') advance();
      continue;
    }

    const startLine = line;
    const startCol = col;

    // String
    if (ch() === '"') {
      advance(); // skip opening quote
      let str = '';
      while (i < len && ch() !== '"') {
        if (ch() === '\\') {
          advance();
          if (i >= len) throw hobError('Unterminated string escape', { line: startLine, col: startCol });
          const esc = ch();
          if (esc === 'n') str += '\n';
          else if (esc === 't') str += '\t';
          else if (esc === '\\') str += '\\';
          else if (esc === '"') str += '"';
          else str += esc;
          advance();
        } else {
          str += ch();
          advance();
        }
      }
      if (i >= len) throw hobError('Unterminated string', { line: startLine, col: startCol });
      advance(); // skip closing quote
      tokens.push({ type: TOKEN.STRING, value: str, line: startLine, col: startCol });
      continue;
    }

    // Delimiters
    if (ch() === '(') { tokens.push({ type: TOKEN.LPAREN, value: '(', line: startLine, col: startCol }); advance(); continue; }
    if (ch() === ')') { tokens.push({ type: TOKEN.RPAREN, value: ')', line: startLine, col: startCol }); advance(); continue; }
    if (ch() === '[') { tokens.push({ type: TOKEN.LBRACKET, value: '[', line: startLine, col: startCol }); advance(); continue; }
    if (ch() === ']') { tokens.push({ type: TOKEN.RBRACKET, value: ']', line: startLine, col: startCol }); advance(); continue; }
    if (ch() === '{') { tokens.push({ type: TOKEN.LBRACE, value: '{', line: startLine, col: startCol }); advance(); continue; }
    if (ch() === '}') { tokens.push({ type: TOKEN.RBRACE, value: '}', line: startLine, col: startCol }); advance(); continue; }

    // Quote shorthand
    if (ch() === '\'') { tokens.push({ type: TOKEN.QUOTE, value: '\'', line: startLine, col: startCol }); advance(); continue; }

    // Quasiquote
    if (ch() === '`') { tokens.push({ type: TOKEN.QUASIQUOTE, value: '`', line: startLine, col: startCol }); advance(); continue; }

    // Unquote-splicing (~@) must come before unquote (~)
    if (ch() === '~' && i + 1 < len && source[i + 1] === '@') {
      tokens.push({ type: TOKEN.UNQUOTE_SPLICING, value: '~@', line: startLine, col: startCol });
      advance(); advance();
      continue;
    }

    // Unquote
    if (ch() === '~') { tokens.push({ type: TOKEN.UNQUOTE, value: '~', line: startLine, col: startCol }); advance(); continue; }

    // Anonymous function shorthand #(...)
    if (ch() === '#' && i + 1 < len && source[i + 1] === '(') {
      tokens.push({ type: TOKEN.ANON_FN, value: '#(', line: startLine, col: startCol });
      advance(); // consume # only, leave ( in stream
      continue;
    }

    // Hash set literal (produce error token)
    if (ch() === '#' && i + 1 < len && source[i + 1] === '{') {
      tokens.push({ type: TOKEN.HASH_LBRACE, value: '#{', line: startLine, col: startCol });
      advance(); advance();
      continue;
    }

    // Item reference @name or @uuid
    if (ch() === '@') {
      advance(); // skip @
      let ref = '';
      while (i < len && isSymbolChar(ch())) {
        ref += ch();
        advance();
      }
      if (!ref) throw hobError('Empty item reference', { line: startLine, col: startCol });
      tokens.push({ type: TOKEN.ITEM_REF, value: ref, line: startLine, col: startCol });
      continue;
    }

    // Keyword
    if (ch() === ':') {
      advance(); // skip :
      let kw = '';
      while (i < len && isSymbolChar(ch())) {
        kw += ch();
        advance();
      }
      if (!kw) throw hobError('Empty keyword', { line: startLine, col: startCol });
      tokens.push({ type: TOKEN.KEYWORD, value: kw, line: startLine, col: startCol });
      continue;
    }

    // Number or symbol starting with - or +
    if (ch() === '-' || ch() === '+') {
      const next = source[i + 1];
      if (next && isDigit(next)) {
        // Negative/positive number
        let num = ch();
        advance();
        while (i < len && (isDigit(ch()) || ch() === '.')) { num += ch(); advance(); }
        // Check it's not followed by symbol chars (e.g. -foo is a symbol)
        if (i < len && isSymbolChar(ch())) {
          // It's a symbol like -foo
          while (i < len && isSymbolChar(ch())) { num += ch(); advance(); }
          tokens.push({ type: TOKEN.SYMBOL, value: num, line: startLine, col: startCol });
        } else {
          tokens.push({ type: TOKEN.NUMBER, value: parseFloat(num), line: startLine, col: startCol });
        }
        continue;
      }
      // Fall through to symbol
    }

    // Number
    if (isDigit(ch())) {
      let num = '';
      while (i < len && (isDigit(ch()) || ch() === '.')) { num += ch(); advance(); }
      tokens.push({ type: TOKEN.NUMBER, value: parseFloat(num), line: startLine, col: startCol });
      continue;
    }

    // Symbol (including +, -, *, /, etc.)
    if (isSymbolChar(ch())) {
      let sym = '';
      while (i < len && isSymbolChar(ch())) { sym += ch(); advance(); }

      // Check for special symbols
      if (sym === 'true') {
        tokens.push({ type: TOKEN.BOOLEAN, value: true, line: startLine, col: startCol });
      } else if (sym === 'false') {
        tokens.push({ type: TOKEN.BOOLEAN, value: false, line: startLine, col: startCol });
      } else if (sym === 'nil') {
        tokens.push({ type: TOKEN.NIL, value: null, line: startLine, col: startCol });
      } else {
        tokens.push({ type: TOKEN.SYMBOL, value: sym, line: startLine, col: startCol });
      }
      continue;
    }

    throw hobError(`Unexpected character '${ch()}'`, { line: startLine, col: startCol });
  }

  return tokens;
}

// ============================================================
// Parser
// ============================================================

const INFIX_OPS = new Set(['+', '-', '*', '/', '%', 'mod', 'rem',
  '>', '<', '>=', '<=', '=', '!=', 'not=']);

function createParser(tokens) {
  let pos = 0;

  function peek() { return tokens[pos]; }
  function next() { return tokens[pos++]; }

  function wrapInForm(formName, tok) {
    next();
    const expr = parseExpr();
    return {
      type: 'list',
      elements: [
        { type: 'symbol', value: formName, line: tok.line, col: tok.col },
        expr
      ],
      line: tok.line,
      col: tok.col
    };
  }

  function parseExpr() {
    const tok = peek();
    if (!tok) throw hobError('Unexpected end of input', { line: 0, col: 0 });

    switch (tok.type) {
      case TOKEN.NUMBER:
      case TOKEN.STRING:
      case TOKEN.BOOLEAN:
      case TOKEN.NIL:
      case TOKEN.KEYWORD:
      case TOKEN.ITEM_REF:
        next();
        return { type: tok.type, value: tok.value, line: tok.line, col: tok.col };

      case TOKEN.SYMBOL:
        next();
        return { type: 'symbol', value: tok.value, line: tok.line, col: tok.col };

      case TOKEN.QUOTE:
        return wrapInForm('quote', tok);

      case TOKEN.QUASIQUOTE:
        return wrapInForm('quasiquote', tok);

      case TOKEN.UNQUOTE:
        return wrapInForm('unquote', tok);

      case TOKEN.UNQUOTE_SPLICING:
        return wrapInForm('unquote-splicing', tok);

      case TOKEN.ANON_FN:
        return parseAnonFn();

      case TOKEN.LPAREN:
        return parseList();

      case TOKEN.LBRACKET:
        return parseVector();

      case TOKEN.LBRACE:
        return parseMap();

      case TOKEN.HASH_LBRACE:
        throw hobError('Sets (#{...}) are not yet supported', { line: tok.line, col: tok.col });

      case TOKEN.RPAREN:
      case TOKEN.RBRACKET:
      case TOKEN.RBRACE:
        throw hobError(`Unexpected '${tok.value}'`, { line: tok.line, col: tok.col });

      default:
        throw hobError(`Unexpected token: ${tok.type}`, { line: tok.line, col: tok.col });
    }
  }

  function parseList() {
    const open = next(); // consume (
    const elements = [];
    while (peek() && peek().type !== TOKEN.RPAREN) {
      elements.push(parseExpr());
    }
    if (!peek()) throw hobError('Unterminated list — expected )', { line: open.line, col: open.col });
    next(); // consume )
    return { type: 'list', elements, line: open.line, col: open.col };
  }

  function parseVector() {
    const open = next(); // consume [
    const elements = [];
    while (peek() && peek().type !== TOKEN.RBRACKET) {
      elements.push(parseExpr());
    }
    if (!peek()) throw hobError('Unterminated vector — expected ]', { line: open.line, col: open.col });
    next(); // consume ]
    return { type: 'vector', elements, line: open.line, col: open.col };
  }

  function parseMap() {
    const open = next(); // consume {

    // Empty {} → empty map
    if (peek() && peek().type === TOKEN.RBRACE) {
      next();
      return { type: 'map', entries: [], line: open.line, col: open.col };
    }

    // Collect all forms, then decide map vs curly-infix
    const forms = [];
    while (peek() && peek().type !== TOKEN.RBRACE) {
      forms.push(parseExpr());
    }
    if (!peek()) throw hobError('Unterminated expression — expected }', { line: open.line, col: open.col });
    next(); // consume }

    // Single form: {x} → x
    if (forms.length === 1) return forms[0];

    // Curly-infix if second token is a known operator (binary/n-ary),
    // or first token is a known operator with exactly two forms (unary).
    const isInfix =
      (forms.length >= 3 && forms[1].type === 'symbol' && INFIX_OPS.has(forms[1].value)) ||
      (forms.length === 2 && forms[0].type === 'symbol' && INFIX_OPS.has(forms[0].value));

    if (!isInfix) {
      if (forms.length % 2 !== 0) {
        throw hobError('Map literal must have an even number of forms', forms[forms.length - 1]);
      }
      const entries = [];
      for (let i = 0; i < forms.length; i += 2) entries.push([forms[i], forms[i + 1]]);
      return { type: 'map', entries, line: open.line, col: open.col };
    }

    // All infix (unary, uniform, and mixed) → curly-infix node preserving natural order
    return { type: 'curly-infix', forms, line: open.line, col: open.col };
  }

  function parseAnonFn() {
    const tok = next(); // consume #( token
    // Now parse the following list (the ( is still in the token stream)
    const body = parseList();
    // Scan for % params
    const params = new Set();
    scanForParams(body, params);
    // Rewrite bare % to %1
    rewriteBarePercent(body);
    // Determine max param number
    let maxParam = 0;
    let hasRest = false;
    for (const p of params) {
      if (p === '%&') { hasRest = true; continue; }
      const name = p === '%' ? '%1' : p;
      const num = parseInt(name.slice(1), 10);
      if (!isNaN(num) && num > maxParam) maxParam = num;
    }
    // Build parameter vector
    const paramElements = [];
    for (let i = 1; i <= maxParam; i++) {
      paramElements.push({ type: 'symbol', value: '%' + i, line: tok.line, col: tok.col });
    }
    if (hasRest) {
      paramElements.push({ type: 'symbol', value: '&', line: tok.line, col: tok.col });
      paramElements.push({ type: 'symbol', value: '%&', line: tok.line, col: tok.col });
    }
    return {
      type: 'list',
      elements: [
        { type: 'symbol', value: 'fn', line: tok.line, col: tok.col },
        { type: 'vector', elements: paramElements, line: tok.line, col: tok.col },
        body
      ],
      line: tok.line,
      col: tok.col
    };
  }

  return { parseExpr, peek, next, getPos: () => pos };
}

function scanForParams(node, params) {
  if (!node) return;
  if (node.type === 'symbol' && node.value.startsWith('%')) {
    params.add(node.value);
  }
  if (node.elements) {
    for (const el of node.elements) scanForParams(el, params);
  }
  if (node.entries) {
    for (const [k, v] of node.entries) {
      scanForParams(k, params);
      scanForParams(v, params);
    }
  }
}

function rewriteBarePercent(node) {
  if (!node) return;
  if (node.type === 'symbol' && node.value === '%') {
    node.value = '%1';
  }
  if (node.elements) {
    for (const el of node.elements) rewriteBarePercent(el);
  }
  if (node.entries) {
    for (const [k, v] of node.entries) {
      rewriteBarePercent(k);
      rewriteBarePercent(v);
    }
  }
}

function parse(tokens) {
  const parser = createParser(tokens);
  const expr = parser.parseExpr();
  if (parser.peek()) {
    const extra = parser.peek();
    throw hobError(`Unexpected token after expression: ${extra.value}`, { line: extra.line, col: extra.col });
  }
  return expr;
}

function read(source) {
  const trimmed = source.trim();
  if (!trimmed) throw hobError('Empty input', { line: 1, col: 0 });
  const tokens = tokenize(trimmed);
  if (tokens.length === 0) throw hobError('Empty input', { line: 1, col: 0 });
  return compactify(parse(tokens));
}

// Read multiple top-level expressions — always returns compact JSON
function readAll(source) {
  if (Array.isArray(source)) return source;  // already compact JSON

  const trimmed = source.trim();
  if (!trimmed) return [];
  const tokens = tokenize(trimmed);
  if (tokens.length === 0) return [];

  const parser = createParser(tokens);
  const exprs = [];
  while (parser.peek()) exprs.push(compactify(parser.parseExpr()));
  return exprs;
}

// ============================================================
// Compact JSON AST — bridge between storage format and internal AST
// ============================================================

// Internal AST node → compact JSON
function compactify(node) {
  switch (node.type) {
    case 'number':
    case 'boolean':
      return node.value;
    case 'nil':
      return null;
    case 'symbol':
      return node.value;
    case 'keyword':
      return ':' + node.value;
    case 'item-ref':
      return '@' + node.value;
    case 'string':
      return { s: node.value };
    case 'list':
      return node.elements.map(compactify);
    case 'curly-infix':
      return { ci: node.forms.map(compactify) };
    case 'vector':
      return { v: node.elements.map(compactify) };
    case 'map':
      return { m: node.entries.map(([k, v]) => [compactify(k), compactify(v)]) };
    default:
      throw new Error(`compactify: unknown node type '${node.type}'`);
  }
}

// Convenience: parse s-expression text → compact JSON array
function compactifyAll(source) { return readAll(source); }

// Compact JSON → pretty-printed s-expression text
// Handles let bindings, body forms, hiccup vectors, and maps idiomatically.

const BODY_FORMS = new Set([
  'let', 'when', 'if', 'do', 'fn', 'defn', 'for', 'doseq', 'cond',
  'when-let', 'loop', 'try', 'catch', 'def', 'defmacro', 'plet',
  '->', '->>', 'as->', 'defmacro', 'quote', 'quasiquote',
]);

const BINDING_FORMS = new Set(['let', 'loop', 'when-let', 'plet']);

function ppStr(s) {
  return '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n').replace(/\t/g, '\\t') + '"';
}

function prettyPrint(json, indent = 0) {
  if (json === null) return 'nil';
  if (typeof json === 'number') return String(json);
  if (typeof json === 'boolean') return json ? 'true' : 'false';
  if (typeof json === 'string') return json; // symbol, keyword (:x), item-ref (@x)
  if (typeof json === 'object' && !Array.isArray(json)) {
    if ('s' in json) return ppStr(json.s);
    if ('v' in json) return ppVec(json.v, indent);
    if ('m' in json) return ppMap(json.m, indent);
    if ('ci' in json) {
      const flat = '{' + json.ci.map(e => prettyPrint(e, 0)).join(' ') + '}';
      if (flat.length <= 80) return flat;
      const ind = '  '.repeat(indent + 1);
      const out = [prettyPrint(json.ci[0], indent + 1)];
      for (let i = 1; i < json.ci.length - 1; i += 2)
        out.push('\n' + ind + prettyPrint(json.ci[i], 0) + ' ' + prettyPrint(json.ci[i + 1], indent + 1));
      return '{' + out.join('') + '\n' + '  '.repeat(indent) + '}';
    }
  }
  if (Array.isArray(json)) return ppList(json, indent);
  return String(json);
}

function ppList(list, indent) {
  if (list.length === 0) return '()';
  // Try flat
  const flat = '(' + list.map(e => prettyPrint(e, 0)).join(' ') + ')';
  if (flat.length + indent <= 80) return flat;

  const head = typeof list[0] === 'string' ? list[0] : null;
  const bi = indent + 2; // body indent

  // Binding forms: (let [name val ...]\n  body...)
  if (head && BINDING_FORMS.has(head) && list.length >= 3 && list[1]?.v) {
    const bracketCol = indent + 1 + head.length + 1; // position of '['
    const binds = ppBindings(list[1].v, bracketCol);
    const body = list.slice(2).map(b => ' '.repeat(bi) + prettyPrint(b, bi));
    return '(' + head + ' ' + binds + '\n' + body.join('\n') + ')';
  }

  // fn/defn: keep params on head line
  if (head === 'fn' && list.length >= 3 && list[1]?.v) {
    const params = ppVec(list[1].v, indent + 4);
    const body = list.slice(2).map(b => ' '.repeat(bi) + prettyPrint(b, bi));
    return '(fn ' + params + '\n' + body.join('\n') + ')';
  }
  if (head === 'defn' && list.length >= 4 && list[2]?.v) {
    const name = prettyPrint(list[1], 0);
    const params = ppVec(list[2].v, indent + 7 + name.length);
    const body = list.slice(3).map(b => ' '.repeat(bi) + prettyPrint(b, bi));
    return '(defn ' + name + ' ' + params + '\n' + body.join('\n') + ')';
  }

  // for/doseq: keep binding vec on head line
  if ((head === 'for' || head === 'doseq') && list.length >= 3 && list[1]?.v) {
    const binds = ppVec(list[1].v, indent + head.length + 2);
    const body = list.slice(2).map(b => ' '.repeat(bi) + prettyPrint(b, bi));
    return '(' + head + ' ' + binds + '\n' + body.join('\n') + ')';
  }

  // Body forms: (head arg1\n  arg2\n  arg3)
  if (head && BODY_FORMS.has(head)) {
    const rest = list.slice(1).map(e => ' '.repeat(bi) + prettyPrint(e, bi));
    return '(' + head + '\n' + rest.join('\n') + ')';
  }

  // Default: (head arg1\n  arg2\n  arg3)
  const parts = list.map(e => prettyPrint(e, bi));
  const rest = parts.slice(1).map(p => ' '.repeat(bi) + p);
  return '(' + parts[0] + '\n' + rest.join('\n') + ')';
}

function ppVec(elements, indent) {
  if (elements.length === 0) return '[]';
  // Try flat
  const flat = '[' + elements.map(e => prettyPrint(e, 0)).join(' ') + ']';
  if (flat.length + indent <= 80) return flat;

  const ci = indent + 2; // child indent

  // Hiccup vector: starts with keyword tag
  if (typeof elements[0] === 'string' && elements[0].startsWith(':')) {
    const tag = elements[0];
    let attrStr = '';
    let childStart = 1;
    // Check for attribute map as second element
    if (elements.length > 1 && elements[1]?.m !== undefined) {
      attrStr = ' ' + ppMap(elements[1].m, indent + tag.length + 2);
      childStart = 2;
    }
    const headLine = '[' + tag + attrStr;
    if (childStart >= elements.length) return headLine + ']';
    const children = elements.slice(childStart).map(c => ' '.repeat(ci) + prettyPrint(c, ci));
    return headLine + '\n' + children.join('\n') + ']';
  }

  // Regular vector
  const parts = elements.map(e => prettyPrint(e, ci));
  const rest = parts.slice(1).map(p => ' '.repeat(indent + 1) + p);
  return '[' + parts[0] + '\n' + rest.join('\n') + ']';
}

function ppMap(entries, indent) {
  if (entries.length === 0) return '{}';
  const flat = '{' + entries.map(([k, v]) => prettyPrint(k, 0) + ' ' + prettyPrint(v, 0)).join(' ') + '}';
  if (flat.length + indent <= 80) return flat;
  // One entry per line, closing } on last line
  const ci = indent + 1;
  const lines = entries.map(([k, v], i) => {
    const ks = prettyPrint(k, ci);
    const vs = prettyPrint(v, ci + ks.length + 1);
    const suffix = i === entries.length - 1 ? '}' : '';
    return ' '.repeat(ci) + ks + ' ' + vs + suffix;
  });
  return '{' + lines[0].trimStart() + '\n' + lines.slice(1).join('\n');
}

function ppBindings(elems, indent) {
  if (elems.length === 0) return '[]';
  // Try flat
  const flat = '[' + elems.map(e => prettyPrint(e, 0)).join(' ') + ']';
  if (flat.length + indent <= 80) return flat;
  // One name-value pair per line
  const ci = indent + 1;
  const pairs = [];
  for (let i = 0; i < elems.length; i += 2) {
    const name = prettyPrint(elems[i], ci);
    if (i + 1 < elems.length) {
