        // let: bindings vector is children[1], names at even indices
        if (head.value === 'let' && child.children.length >= 2) {
          const bindings = child.children[1];
          if (bindings?.type === 'vector' && bindings.children) {
            for (let i = 0; i < bindings.children.length; i += 2) {
              const nameNode = bindings.children[i];
              if (nameNode?.type === 'symbol' && nameNode.value === targetName) return nameNode.id;
            }
          }
        }
      }
    }

    // Recurse into all container nodes (list, vector, map, root)
    const found = findSymbolNode(child, targetName);
    if (found !== null) return found;
  }
  return null;
}

// --- System symbol index (module-level, shared across editor instances) ---
const _CODE_TYPE_ID  = '22222222-0000-0000-0000-000000000000';
const _HOB_DEF_FORMS = new Set(['defn', 'def', 'def-view', 'def-watch', 'defmacro']);
let _symbolIndex  = { byItem: new Map(), flat: [], libraries: new Map(), subscribed: false };
let _codeTypeIds  = null;  // Set of all type IDs that extend kernel:code; null until built

function _extractItemSymbols(item) {
  const source = item.name || item.id.slice(0, 8);
  const syms = [];
  if (Array.isArray(item.content?.hob)) {
    for (const form of item.content.hob) {
      if (!Array.isArray(form) || form.length < 2 || !_HOB_DEF_FORMS.has(form[0])) continue;
      const n = form[1];
      if (typeof n === 'string' && !n.startsWith(':') && !n.startsWith('@'))
        syms.push({ name: n, detail: source, acType: 'system' });
    }
  }
  if (item.content?._symbols) {
    for (const key of Object.keys(item.content._symbols))
      if (!key.includes('.')) syms.push({ name: key, detail: source, acType: 'system' });
  }
  return syms;
}

function _rebuildFlatIndex() {
  const all = [];
  for (const syms of _symbolIndex.byItem.values()) all.push(...syms);
  _symbolIndex.flat = all;
}

async function _buildSymbolIndex(api) {
  try {
    const allItems = await api.query({});
    // Resolve unique type IDs against the code type chain using the kernel's built-in
    const uniqueTypes = [...new Set(allItems.map(i => i.type).filter(Boolean))];
    const results = await Promise.all(uniqueTypes.map(t => api.typeChainIncludes(t, _CODE_TYPE_ID)));
    _codeTypeIds = new Set(uniqueTypes.filter((_, i) => results[i]));
    for (const item of allItems) {
      if (!_codeTypeIds.has(item.type)) continue;
      if (item.name) _symbolIndex.libraries.set(item.id, item.name);
      const syms = _extractItemSymbols(item);
      if (syms.length) _symbolIndex.byItem.set(item.id, syms);
    }
    _rebuildFlatIndex();
  } catch {}
}

function _patchSymbolIndex(item) {
  if (!_codeTypeIds?.has(item.type)) return;
  if (item.name) _symbolIndex.libraries.set(item.id, item.name);
  else _symbolIndex.libraries.delete(item.id);
  const syms = _extractItemSymbols(item);
  if (syms.length) _symbolIndex.byItem.set(item.id, syms);
  else _symbolIndex.byItem.delete(item.id);
  _rebuildFlatIndex();
}

// --- Inflater: compact JSON AST → editor AST ---

function inflateAll(compactForms) {
  let nextId = 1;
  const nodeMap = new Map();
  const parentMap = new Map();

  function inflate(compact) {
    let node;
    if (compact === null) {
      node = { id: nextId++, type: 'nil' };
    } else if (typeof compact === 'number') {
      node = { id: nextId++, type: 'number', value: compact };
    } else if (typeof compact === 'boolean') {
      node = { id: nextId++, type: 'boolean', value: compact };
    } else if (typeof compact === 'string') {
      if (compact.startsWith(':')) {
        node = { id: nextId++, type: 'keyword', value: compact.slice(1) };
      } else if (compact.startsWith('@')) {
        node = { id: nextId++, type: 'item-ref', value: compact.slice(1) };
      } else {
        node = { id: nextId++, type: 'symbol', value: compact };
      }
    } else if (Array.isArray(compact) && compact[0] === ':doc') {
      // Doc node — opaque, stores entire Active Text AST as value
      node = { id: nextId++, type: 'doc', value: compact };
      nodeMap.set(node.id, node);
      return node;
    } else if (Array.isArray(compact)) {
      node = { id: nextId++, type: 'list', children: [] };
      nodeMap.set(node.id, node);
      node.children = compact.map(child => {
        const cNode = inflate(child);
        parentMap.set(cNode.id, node);
        return cNode;
      });
      return node;
    } else if (compact.s !== undefined) {
      node = { id: nextId++, type: 'string', value: compact.s };
    } else if (compact.v) {
      node = { id: nextId++, type: 'vector', children: [] };
      nodeMap.set(node.id, node);
      node.children = compact.v.map(child => {
        const cNode = inflate(child);
        parentMap.set(cNode.id, node);
        return cNode;
      });
      return node;
    } else if (compact.m) {
      node = { id: nextId++, type: 'map', children: [] };
      nodeMap.set(node.id, node);
      node.children = compact.m.flatMap(([k, v]) => {
        const kNode = inflate(k);
        const vNode = inflate(v);
        parentMap.set(kNode.id, node);
        parentMap.set(vNode.id, node);
        return [kNode, vNode];
      });
      return node;
    } else if (compact.ci) {
      node = { id: nextId++, type: 'list', _curlyInfix: true, children: [] };
      nodeMap.set(node.id, node);
      node.children = compact.ci.map(child => {
        const cNode = inflate(child);
        parentMap.set(cNode.id, node);
        return cNode;
      });
      return node;
    } else {
      node = { id: nextId++, type: 'nil' }; // fallback
    }
    nodeMap.set(node.id, node);
    return node;
  }

  const root = { id: 0, type: 'root', children: [] };
  nodeMap.set(0, root);
  root.children = compactForms.map(form => {
    const child = inflate(form);
    parentMap.set(child.id, root);
    return child;
  });

  _nextId = Math.max(_nextId, nextId);  // never decrease — prevents ID collisions across editor instances
  return { root, nodeMap, parentMap };
}

// --- Deflater: editor AST → compact JSON AST (inverse of inflate) ---

function deflate(node) {
  switch (node.type) {
    case 'nil': return null;
    case 'number': return node.value;
    case 'boolean': return node.value;
    case 'symbol': return node.value;
    case 'keyword': return ':' + node.value;
    case 'item-ref': return '@' + node.value;
    case 'string': return { s: node.value };
    case 'hole': return null;
    case 'doc': return node.value;
    case 'list': {
      const kids = node.children.filter(c => c.type !== 'hole');
      if (node._curlyInfix || node._curlyList) {
        const isUnary = kids.length === 2 && kids[0].type === 'symbol' && INFIX_OPS.has(kids[0].value);
        const isBinary = kids.length >= 3 && kids[1] && kids[1].type === 'symbol' && INFIX_OPS.has(kids[1].value);
        if (isUnary || isBinary) return { ci: kids.map(deflate) };
      }
      return kids.map(deflate);
    }
    case 'vector': return { v: node.children.filter(c => c.type !== 'hole').map(deflate) };
    case 'map': {
      const pairs = [];
      const kids = node.children.filter(c => c.type !== 'hole');
      for (let i = 0; i < kids.length; i += 2) {
        pairs.push([deflate(kids[i]), deflate(kids[i + 1] || { type: 'nil' })]);
      }
      return { m: pairs };
    }
    default: return null;
  }
}

function deflateAll(root) {
  return root.children.filter(c => c.type !== 'hole').map(deflate);
}

// --- S-expression serializer (for system clipboard text) ---

function nodeToSexp(node) {
  switch (node.type) {
    case 'nil':      return 'nil';
    case 'number':   return String(node.value);
    case 'boolean':  return String(node.value);
    case 'symbol':   return node.value;
    case 'keyword':  return ':' + node.value;
    case 'item-ref': return '@' + node.value;
    case 'string':   return '"' + node.value.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
    case 'hole':     return '·';
    case 'doc':      return nodeToSexp_doc(node.value);
    case 'list':     return '(' + node.children.map(nodeToSexp).join(' ') + ')';
    case 'vector':   return '[' + node.children.map(nodeToSexp).join(' ') + ']';
    case 'map':      return '{' + node.children.map(nodeToSexp).join(' ') + '}';
    default:         return '';
  }
}

function nodeToSexp_doc(ast) {
  // Serialize a compact Active Text node to s-expression form
  if (ast === null) return 'nil';
  if (typeof ast === 'number') return String(ast);
  if (typeof ast === 'boolean') return String(ast);
  if (typeof ast === 'string') return ast; // keywords, symbols
  if (ast && typeof ast === 'object' && 's' in ast) {
    return '"' + ast.s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
  }
  if (ast && typeof ast === 'object' && 'v' in ast) {
    return '[' + ast.v.map(nodeToSexp_doc).join(' ') + ']';
  }
  if (ast && typeof ast === 'object' && 'm' in ast) {
    return '{' + ast.m.map(([k, v]) => nodeToSexp_doc(k) + ' ' + nodeToSexp_doc(v)).join(' ') + '}';
  }
  if (Array.isArray(ast)) {
    return '(' + ast.map(nodeToSexp_doc).join(' ') + ')';
  }
  return '';
}

// --- S-expression parser (for system clipboard paste fallback) ---

function parseSexp(text) {
  let pos = 0;

  function skipWS() {
    while (pos < text.length && /[\s,]/.test(text[pos])) pos++;
  }

  function parseOne() {
    skipWS();
    if (pos >= text.length) return undefined;
    const ch = text[pos];

    if (ch === '(') {
      pos++;
      const items = [];
      skipWS();
      while (pos < text.length && text[pos] !== ')') {
        const item = parseOne();
        if (item !== undefined) items.push(item);
        skipWS();
      }
      if (pos < text.length) pos++; // skip )
      return items;
    }

    if (ch === '[') {
      pos++;
      const items = [];
      skipWS();
      while (pos < text.length && text[pos] !== ']') {
        const item = parseOne();
        if (item !== undefined) items.push(item);
        skipWS();
      }
      if (pos < text.length) pos++; // skip ]
      return { v: items };
    }

    if (ch === '{') {
      pos++;
      const items = [];
      skipWS();
      while (pos < text.length && text[pos] !== '}') {
        const item = parseOne();
        if (item !== undefined) items.push(item);
        skipWS();
      }
      if (pos < text.length) pos++; // skip }
      if (items.length === 1) return items[0];
      const isInfix =
        (items.length >= 3 && typeof items[1] === 'string' && !items[1].startsWith(':') && !items[1].startsWith('@') && INFIX_OPS.has(items[1])) ||
        (items.length === 2 && typeof items[0] === 'string' && !items[0].startsWith(':') && !items[0].startsWith('@') && INFIX_OPS.has(items[0]));
      if (isInfix) {
        if (items.length === 2) return [items[0], items[1]];
        const op = items[1];
        return [op, ...items.filter((_, i) => i % 2 === 0)];
      }
      const pairs = [];
      for (let i = 0; i < items.length; i += 2) {
        pairs.push([items[i], i + 1 < items.length ? items[i + 1] : null]);
      }
      return { m: pairs };
    }

    if (ch === '"') {
      pos++;
      let str = '';
      while (pos < text.length && text[pos] !== '"') {
        if (text[pos] === '\\' && pos + 1 < text.length) {
          pos++;
          if (text[pos] === 'n') str += '\n';
          else if (text[pos] === 't') str += '\t';
          else str += text[pos];
        } else {
          str += text[pos];
        }
        pos++;
      }
      if (pos < text.length) pos++; // skip closing "
      return { s: str };
    }

    // Atom: read until delimiter
    let atom = '';
    while (pos < text.length && !/[\s,\(\)\[\]\{\}"]/.test(text[pos])) {
      atom += text[pos];
      pos++;
    }

    if (!atom) { pos++; return undefined; }  // skip unrecognized delimiter
    if (atom === '·') return undefined;
    if (atom === 'nil') return null;
    if (atom === 'true') return true;
    if (atom === 'false') return false;
    if (/^-?\d+(\.\d+)?$/.test(atom)) return parseFloat(atom);
    return atom; // symbol, keyword (:foo), or item-ref (@guid)
  }

  return parseOne();
}

// --- Flat width calculation ---

function leafText(node) {
  switch (node.type) {
    case 'nil': return 'nil';
    case 'number': return String(node.value);
    case 'boolean': return String(node.value);
    case 'symbol': return node.value;
    case 'keyword': return ':' + node.value;
    case 'string': return '"' + node.value.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
    case 'item-ref': return '@' + node.value.slice(0, 8);
    case 'hole': return '·';
    case 'doc': return ';; doc';
    default: return '';
  }
}

function flatWidth(node) {
  if (node._fw !== undefined) return node._fw;
  if (node.type === 'doc') { node._fw = Infinity; return node._fw; }
  if (node.children) {
    if (node.type === 'list') {
      const inner = node.children.reduce((s, c) => s + flatWidth(c), 0);
      node._fw = 2 + inner + Math.max(0, node.children.length - 1); // parens + spaces
    } else if (node.type === 'vector') {
      const inner = node.children.reduce((s, c) => s + flatWidth(c), 0);
      node._fw = 2 + inner + Math.max(0, node.children.length - 1);
    } else if (node.type === 'map') {
      const inner = node.children.reduce((s, c) => s + flatWidth(c), 0);
      // pairs: key val key val — spaces between all, plus braces
      node._fw = 2 + inner + Math.max(0, node.children.length - 1);
    } else {
      node._fw = 0;
    }
  } else {
    node._fw = leafText(node).length;
  }
  return node._fw;
}

// --- DOM Renderer ---

const MAX_LINE = 60;

function renderNode(node, state, itemNames, api, indent) {
  if (node.type === 'doc') return renderDocNode(node, state, api, indent);
  if (!node.children) {
    return renderLeaf(node, state, itemNames, api);
  }
  if (node.type === 'list') return renderList(node, state, itemNames, api, indent);
  if (node.type === 'vector') return renderCollection(node, '[', ']', 'hob-vector', state, itemNames, api, indent);
  if (node.type === 'map') return renderMap(node, state, itemNames, api, indent);
  return renderLeaf(node, state, itemNames, api); // fallback
}

function renderLeaf(node, state, itemNames, api) {
  const span = document.createElement('span');
  span.setAttribute('data-node-id', node.id);
  state.domMap.set(node.id, span);

  switch (node.type) {
    case 'nil':
      span.className = 'hob-nil';
      span.textContent = 'nil';
      break;
    case 'number':
      span.className = 'hob-number';
      span.textContent = String(node.value);
      break;
    case 'boolean':
      span.className = 'hob-boolean';
      span.textContent = String(node.value);
      break;
    case 'symbol':
      span.className = SPECIAL_FORMS.has(node.value) ? 'hob-symbol hob-special' : 'hob-symbol';
      span.textContent = node.value;
      break;
    case 'keyword':
      span.className = 'hob-keyword';
      span.textContent = ':' + node.value;
      break;
    case 'string':
      span.className = 'hob-string';
      span.textContent = '"' + node.value.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n') + '"';
      break;
    case 'item-ref': {
      span.className = 'hob-item-ref';
      if (node.value === 'self') {
        span.textContent = '@self';
        span.title = '@self — resolves to this item';
      } else {
        const name = itemNames.get(node.value) || node.value.slice(0, 8);
        span.textContent = name;
        span.title = node.value;
        if (!state.onChange) {
          span.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            api.openItem(e, node.value);
          });
        }
      }
      break;
    }
    case 'hole':
      if (state.mode !== 'nav' && state.inputHoleId === node.id) {
        span.className = 'hob-hole hob-hole-active' + (state.mode === 'string' ? ' hob-string' : '');
        const inp = document.createElement('input');
        inp.type = 'text';
        inp.className = 'hob-hole-input';
        inp.value = state.inputBuffer;
        inp.style.width = state.inputBuffer.length + 'ch';
        if (state.mode === 'string') inp.setAttribute('data-string-mode', '1');
        span.appendChild(inp);
        // Tapping the span (including ::before/::after quote pseudo-elements) focuses the input
        span.addEventListener('click', (e) => { e.stopPropagation(); inp.focus(); });
      } else {
        span.className = 'hob-hole';
        span.textContent = '·';
      }
      break;
    default:
      span.textContent = '?';
  }

  return span;
}

function ws(insertAfterId) {
  const s = document.createElement('span');
  s.className = 'hob-ws';
  s.textContent = ' ';
  if (insertAfterId != null) s.setAttribute('data-insert-after', insertAfterId);
  return s;
}

function newline(indentLevel, insertAfterId) {
  const nl = document.createElement('span');
  nl.className = 'hob-newline';
  nl.textContent = '\n';
  const frag = document.createDocumentFragment();
  frag.appendChild(nl);
  if (indentLevel > 0) {
    const numGuides = Math.floor(indentLevel / 2);
    const remainder = indentLevel % 2;
    for (let i = 0; i < numGuides; i++) {
      const guide = document.createElement('span');
      // First 2-space block is plain indent (no guide at col 0); subsequent blocks show guide lines
      guide.className = i === 0 ? 'hob-indent' : 'hob-guide';
      guide.textContent = '  ';
      const isLast = (i === numGuides - 1) && remainder === 0;
      if (isLast && insertAfterId != null) guide.setAttribute('data-insert-after', insertAfterId);
      frag.appendChild(guide);
    }
    if (remainder > 0) {
      const rem = document.createElement('span');
      rem.className = 'hob-indent';
      rem.textContent = ' ';
      if (insertAfterId != null) rem.setAttribute('data-insert-after', insertAfterId);
      frag.appendChild(rem);
    }
  }
  return frag;
}

function delim(text) {
  const s = document.createElement('span');
  s.className = 'hob-delim';
  s.textContent = text;
  return s;
}

function collapsedSummary(node) {
  if (!node.children || node.children.length === 0) return '(…)';
  const head = node.children[0];
  const headText = head.type === 'symbol' ? head.value :
                   head.type === 'keyword' ? (':' + head.value) : '…';
  if (headText === 'fn' && node.children.length >= 2) {
    const params = node.children[1];
    if (params && params.type === 'vector') {
      const paramText = params.children.map(p => p.type === 'symbol' ? p.value : '…').join(' ');
      return '(fn [' + paramText + '] …)';
    }
  }
  if (headText === 'defn' && node.children.length >= 3) {
    const name = node.children[1];
    const params = node.children[2];
    if (name && name.type === 'symbol' && params && params.type === 'vector') {
      const paramText = params.children.map(p => p.type === 'symbol' ? p.value : '…').join(' ');
      return '(defn ' + name.value + ' [' + paramText + '] …)';
    }
  }
  return '(' + headText + ' …)';
}

function isInfixList(node) {
  return node.type === 'list'
    && node.children.length >= 2
    && node.children[0].type === 'symbol'
    && INFIX_OPS.has(node.children[0].value);
}

// Unary (- x) produced by mixed +/- normalization — rendered as subtraction within (+ ...)
function isUnaryMinus(node) {
  return node.type === 'list' && !node._curlyList
    && node.children.length === 2
    && node.children[0].type === 'symbol' && node.children[0].value === '-'
    && node.children[1].type !== 'hole';
}

function infixDelim(text) {
  const s = document.createElement('span');
  s.className = 'hob-infix-delim';
  s.textContent = text;
  return s;
}

function renderInfixList(node, state, itemNames, api, indent) {
  const span = document.createElement('span');
  span.className = 'hob-list';
  span.setAttribute('data-node-id', node.id);
  state.domMap.set(node.id, span);

  // Loaded from {ci:[...]}: children in natural order [operand, op, operand, op, ...]
  if (node._curlyInfix) {
    span.appendChild(infixDelim('{'));
    if (flatWidth(node) <= MAX_LINE) {
      for (let i = 0; i < node.children.length; i++) {
        if (i > 0) span.appendChild(ws(node.children[i - 1].id));
        span.appendChild(renderNode(node.children[i], state, itemNames, api, indent + 1));
      }
    } else {
      span.appendChild(renderNode(node.children[0], state, itemNames, api, indent + 1));
      for (let i = 1; i < node.children.length - 1; i += 2) {
        span.appendChild(newline(indent + 1, node.children[i - 1].id));
        span.appendChild(renderNode(node.children[i], state, itemNames, api, indent + 1));
        span.appendChild(ws(node.children[i].id));
        span.appendChild(renderNode(node.children[i + 1], state, itemNames, api, indent + 1));
      }
      span.appendChild(newline(indent, node.children[node.children.length - 1].id));
    }
    span.appendChild(infixDelim('}'));
    return span;
  }

  // Not yet a proper infix list (empty or op not yet committed) — show {} with children as-is
  if (!isInfixList(node)) {
    span.appendChild(infixDelim('{'));
    for (let i = 0; i < node.children.length; i++) {
      if (i > 0) span.appendChild(ws(node.children[i - 1].id));
      span.appendChild(renderNode(node.children[i], state, itemNames, api, indent + 1));
    }
    span.appendChild(infixDelim('}'));
    return span;
  }

  const op = node.children[0];
  const operands = node.children.slice(1);

  const fw = flatWidth(node);

  if (fw <= MAX_LINE) {
    span.appendChild(infixDelim('{'));
    if (operands.length === 1) {
      // Unary: { - x }
      span.appendChild(renderNode(op, state, itemNames, api, indent + 1));
      span.appendChild(ws(op.id));
      span.appendChild(renderNode(operands[0], state, itemNames, api, indent + 1));
    } else {
      // Binary / n-ary: { a op b op c }
      for (let i = 0; i < operands.length; i++) {
        if (i > 0) {
          const neg = op.value === '+' && isUnaryMinus(operands[i]);
          const s = document.createElement('span');
          s.className = 'hob-symbol hob-infix-sep';
          s.textContent = ' ' + (neg ? '-' : op.value) + ' ';
          if (i === 1) { state.domMap.set(op.id, s); }
          if (neg) {
            s.setAttribute('data-node-id', operands[i].id);
            state.domMap.set(operands[i].id, s);
          } else {
            s.setAttribute('data-node-id', op.id);
          }
          span.appendChild(s);
          if (neg) {
            span.appendChild(renderNode(operands[i].children[1], state, itemNames, api, indent + 1));
            continue;
          }
        }
        span.appendChild(renderNode(operands[i], state, itemNames, api, indent + 1));
      }
    }
    span.appendChild(infixDelim('}'));
  } else {
    // Multi-line: { operand1\n  op operand2\n  op operand3 }
    const childIndent = indent + 1;
    span.appendChild(infixDelim('{'));
    if (operands.length === 1) {
      span.appendChild(renderNode(op, state, itemNames, api, childIndent));
      span.appendChild(ws(op.id));
      span.appendChild(renderNode(operands[0], state, itemNames, api, childIndent));
    } else {
      span.appendChild(renderNode(operands[0], state, itemNames, api, childIndent));
      for (let i = 1; i < operands.length; i++) {
        const neg = op.value === '+' && isUnaryMinus(operands[i]);
        span.appendChild(newline(childIndent, operands[i - 1].id));
        const s = document.createElement('span');
        s.className = 'hob-symbol hob-infix-sep';
        s.textContent = (neg ? '-' : op.value) + ' ';
        if (i === 1) { state.domMap.set(op.id, s); }
        if (neg) {
          s.setAttribute('data-node-id', operands[i].id);
          state.domMap.set(operands[i].id, s);
        } else {
          s.setAttribute('data-node-id', op.id);
        }
        span.appendChild(s);
        span.appendChild(renderNode(neg ? operands[i].children[1] : operands[i], state, itemNames, api, childIndent));
      }
    }
    const lastOperand = operands[operands.length - 1];
    span.appendChild(newline(indent, lastOperand.id));
    span.appendChild(infixDelim('}'));
  }

  return span;
}

function renderList(node, state, itemNames, api, indent) {
  if (isInfixList(node) || node._curlyList || node._curlyInfix) return renderInfixList(node, state, itemNames, api, indent);

  const span = document.createElement('span');
  span.className = 'hob-list';
  span.setAttribute('data-node-id', node.id);
  state.domMap.set(node.id, span);

  if (node.children.length === 0) {
    span.appendChild(delim('('));
    span.appendChild(delim(')'));
    return span;
  }

  const fw = flatWidth(node);

  // Check if the head is a special form
  const head = node.children[0];
  const headName = (head.type === 'symbol') ? head.value : null;
  const isSpecial = headName && SPECIAL_FORMS.has(headName);
  const isBinding = headName && BINDING_FORMS.has(headName);

  // Try flat rendering
  if (fw <= MAX_LINE) {
    span.appendChild(delim('('));
    for (let i = 0; i < node.children.length; i++) {
      if (i > 0) span.appendChild(ws(node.children[i - 1].id));
      span.appendChild(renderNode(node.children[i], state, itemNames, api, indent + 2));
    }
    span.appendChild(delim(')'));
    return span;
  }

  // Multi-line rendering
  const isCollapsed = state.collapsedIds && state.collapsedIds.has(node.id);
  const toggleSpan = document.createElement('span');
  toggleSpan.className = 'hob-fold-toggle';
  toggleSpan.textContent = isCollapsed ? '▸' : '▾';
  toggleSpan.addEventListener('click', (e) => {
    e.stopPropagation();
    if (!state.collapsedIds) state.collapsedIds = new Set();
    if (state.collapsedIds.has(node.id)) {
      state.collapsedIds.delete(node.id);
    } else {
      state.collapsedIds.add(node.id);
    }
    state.selectedId = node.id;
    const ctx = state._ctx;
    if (ctx) rerender(state, ctx.itemNames, ctx.api, ctx.statusBar);
  });
  span.appendChild(toggleSpan);

  if (isCollapsed) {
    const summary = document.createElement('span');
    summary.className = 'hob-collapsed-summary';
    summary.textContent = collapsedSummary(node);
    span.appendChild(summary);
    return span;
  }

  span.appendChild(delim('('));

  if (isSpecial) {
    // Render head
    span.appendChild(renderNode(head, state, itemNames, api, indent + 2));
    const bodyIndent = indent + 2;

    if (isBinding && node.children.length >= 2) {
      // binding form: (let [bindings...] body...)
      // Head + space + bindings on first line, then body indented
      span.appendChild(ws(head.id));
      const bindingsNode = node.children[1];
      if (bindingsNode.type === 'vector') {
        span.appendChild(renderBindingVector(bindingsNode, state, itemNames, api, bodyIndent));
      } else {
        span.appendChild(renderNode(bindingsNode, state, itemNames, api, bodyIndent));
      }
      for (let i = 2; i < node.children.length; i++) {
        span.appendChild(newline(bodyIndent, node.children[i - 1].id));
        span.appendChild(renderNode(node.children[i], state, itemNames, api, bodyIndent));
      }
    } else {
      // Non-binding special: (defn name args\n  body...)
      // Put first 1-2 args on same line as head, rest indented
      const argsOnLine = (headName === 'defn' || headName === 'defmacro') ? 2 : 1;
      for (let i = 1; i < node.children.length; i++) {
        if (i <= argsOnLine) {
          span.appendChild(ws(node.children[i - 1].id));
        } else {
          span.appendChild(newline(bodyIndent, node.children[i - 1].id));
        }
        span.appendChild(renderNode(node.children[i], state, itemNames, api, bodyIndent));
      }
    }
  } else {
    // Normal list: first child, then all remaining indented
    span.appendChild(renderNode(head, state, itemNames, api, indent + 2));
    const restIndent = indent + 2;
    for (let i = 1; i < node.children.length; i++) {
      span.appendChild(newline(restIndent, node.children[i - 1].id));
      span.appendChild(renderNode(node.children[i], state, itemNames, api, restIndent));
    }
  }

  // Trailing gap before closing delimiter (clickable insert-after last child)
  const lastChild = node.children[node.children.length - 1];
  span.appendChild(newline(indent, lastChild.id));
  span.appendChild(delim(')'));
  return span;
}

function renderBindingVector(node, state, itemNames, api, indent) {
  const span = document.createElement('span');
  span.className = 'hob-vector';
  span.setAttribute('data-node-id', node.id);
  state.domMap.set(node.id, span);

  const kids = node.children;

  if (kids.length === 0) {
    span.appendChild(delim('['));
    span.appendChild(delim(']'));
    return span;
  }

  // Try flat rendering first
  const fw = flatWidth(node);
  if (fw <= MAX_LINE) {
    span.appendChild(delim('['));
    for (let i = 0; i < kids.length; i++) {
      if (i > 0) span.appendChild(ws(kids[i - 1].id));
      span.appendChild(renderNode(kids[i], state, itemNames, api, indent + 1));
    }
    span.appendChild(delim(']'));
    return span;
  }

  // Multi-line: render as pairs (name value)
  const childIndent = indent + 1;
  span.appendChild(delim('['));

  for (let i = 0; i < kids.length; i += 2) {
    const name = kids[i];
    const value = kids[i + 1];

    // Newline before each pair (outside the pair wrapper)
    span.appendChild(newline(childIndent, i > 0 ? kids[i - 1].id : null));

    // Wrap pair in a span; highlight _ (side-effect) bindings
    const isEffect = name.type === 'symbol' && name.value === '_';
    const pairSpan = document.createElement('span');
    pairSpan.className = isEffect ? 'hob-binding-pair hob-binding-effect' : 'hob-binding-pair';

    // Render name
    pairSpan.appendChild(renderNode(name, state, itemNames, api, childIndent));

    if (value) {
      // Check if name + value fit on the rest of the line
      const pairWidth = flatWidth(name) + 1 + flatWidth(value);
      if (childIndent + pairWidth <= MAX_LINE) {
        pairSpan.appendChild(ws(name.id));
        pairSpan.appendChild(renderNode(value, state, itemNames, api, childIndent));
      } else {
        // Value on next line with extra indent
        pairSpan.appendChild(newline(childIndent + 2, name.id));
        pairSpan.appendChild(renderNode(value, state, itemNames, api, childIndent + 2));
      }
    }

    span.appendChild(pairSpan);
  }

  // Trailing gap before closing delimiter
  const lastKid = kids[kids.length - 1];
  span.appendChild(newline(indent, lastKid.id));
  span.appendChild(delim(']'));
  return span;
}

function renderCollection(node, open, close, className, state, itemNames, api, indent) {
  const span = document.createElement('span');
  span.className = className;
  span.setAttribute('data-node-id', node.id);
  state.domMap.set(node.id, span);

  if (node.children.length === 0) {
    span.appendChild(delim(open));
    span.appendChild(delim(close));
    return span;
  }

  const fw = flatWidth(node);

  if (fw <= MAX_LINE) {
    span.appendChild(delim(open));
    for (let i = 0; i < node.children.length; i++) {
      if (i > 0) span.appendChild(ws(node.children[i - 1].id));
      span.appendChild(renderNode(node.children[i], state, itemNames, api, indent + 1));
    }
    span.appendChild(delim(close));
  } else {
    const childIndent = indent + 1;
    span.appendChild(delim(open));
    span.appendChild(renderNode(node.children[0], state, itemNames, api, childIndent));
    for (let i = 1; i < node.children.length; i++) {
      span.appendChild(newline(childIndent, node.children[i - 1].id));
      span.appendChild(renderNode(node.children[i], state, itemNames, api, childIndent));
    }
    // Trailing gap before closing delimiter
    const lastChild = node.children[node.children.length - 1];
    span.appendChild(newline(indent, lastChild.id));
    span.appendChild(delim(close));
  }

  return span;
}

function renderMap(node, state, itemNames, api, indent) {
  const span = document.createElement('span');
  span.className = 'hob-map';
  span.setAttribute('data-node-id', node.id);
  state.domMap.set(node.id, span);

  if (node.children.length === 0) {
    span.appendChild(delim('{'));
    span.appendChild(delim('}'));
    return span;
  }

  const fw = flatWidth(node);

  if (fw <= MAX_LINE) {
    span.appendChild(delim('{'));
    for (let i = 0; i < node.children.length; i++) {
      if (i > 0) span.appendChild(ws(node.children[i - 1].id));
      span.appendChild(renderNode(node.children[i], state, itemNames, api, indent + 1));
    }
    span.appendChild(delim('}'));
  } else {
    const childIndent = indent + 1;
    span.appendChild(delim('{'));
    // Render as key-value pairs, one pair per line
    for (let i = 0; i < node.children.length; i += 2) {
      if (i > 0) span.appendChild(newline(childIndent, node.children[i - 1].id));
      span.appendChild(renderNode(node.children[i], state, itemNames, api, childIndent));
      if (i + 1 < node.children.length) {
        span.appendChild(ws(node.children[i].id));
        span.appendChild(renderNode(node.children[i + 1], state, itemNames, api, childIndent));
      }
    }
    // Trailing gap before closing delimiter
    const lastChild = node.children[node.children.length - 1];
    span.appendChild(newline(indent, lastChild.id));
    span.appendChild(delim('}'));
  }

  return span;
}

function renderDocNode(node, state, api, indent) {
  const container = document.createElement('div');
  container.setAttribute('data-node-id', node.id);
  container.className = 'hob-doc-node';
  if (indent > 0) container.style.marginLeft = indent + 'ch';
  state.domMap.set(node.id, container);

  // Render doc content (starts read-only; Enter activates editing)
  container._docNodeId = node.id;
  container._docRenderContent = async (editable) => {
    container.textContent = '';
    try {
      if (editable && state.onChange) {
        const docEditor = await api.require('field-view-doc-editable');
        const el = await docEditor.render(JSON.parse(JSON.stringify(node.value)), {
          mode: 'editable',
          onChange: (newAst) => {
            node.value = newAst;
            if (state.onChange) state.onChange(deflateAll(state.nodeMap.get(0)));
          }
        }, api);
        container.appendChild(el);
      } else {
        const docRenderer = await api.require('field-view-doc-readonly');
        const el = await docRenderer.render(node.value, {}, api);
        container.appendChild(el);
      }
    } catch (err) {
      container.textContent = ';; (doc render error)';
    }
  };
  // Initial read-only render
  container._docRenderContent(false);

  return container;
}

function renderAST(root, state, itemNames, api) {
  const el = document.createElement('div');
  el.className = 'hob-editor';
  el.setAttribute('tabindex', '0');

  for (let i = 0; i < root.children.length; i++) {
    if (i > 0) {
      // Blank line between top-level forms
      el.appendChild(document.createTextNode('\n\n'));
    }
    el.appendChild(renderNode(root.children[i], state, itemNames, api, 0));
  }

  return el;
}

// --- Rerender ---

function clearFlatWidth(node) {
  delete node._fw;
  if (node.children) node.children.forEach(clearFlatWidth);
}

function rerender(state, itemNames, api, statusBar) {
  // Clear cached flat widths (stale after mutations)
  clearFlatWidth(state.nodeMap.get(0));

  // Clear domMap
  state.domMap = new Map();

  // Rebuild DOM children (reuse same editorEl to preserve event listeners).
  // Before clearing, move focus from any child input to editorEl itself — some browsers
  // scroll the page to (0,0) when a focused element is removed from the DOM.
  const _active = document.activeElement;
  if (_active && _active !== state.editorEl && state.editorEl.contains(_active)) {
    state.editorEl.focus({ preventScroll: true });
  }
  state.editorEl.textContent = '';
  const root = state.nodeMap.get(0);
  for (let i = 0; i < root.children.length; i++) {
    if (i > 0) state.editorEl.appendChild(document.createTextNode('\n\n'));
    state.editorEl.appendChild(renderNode(root.children[i], state, itemNames, api, 0));
  }

  // Validate selection still exists
  if (state.selectedId != null && !state.nodeMap.has(state.selectedId)) {
    state.selectedId = root.children[0]?.id || null;
  }
  state.selectionAnchorId = null;
  state.expansionStack = [];

  updateSelectionVisual(state);
  updateStatusBar(state, statusBar);
  postRender(state);
}

function postRender(state) {
  if (state.mode === 'input' || state.mode === 'string') {
    const holeEl = state.domMap.get(state.inputHoleId);
    if (!holeEl) return;
    const inp = holeEl.querySelector('.hob-hole-input');
    if (!inp) return;
    inp.value = state.inputBuffer;
    inp.style.width = state.inputBuffer.length + 'ch';
    inp.addEventListener('input', () => {
      const raw = inp.value;
      // On mobile, special characters arrive via `input` (keydown fires Unidentified so
      // e.preventDefault was never called). Mirror the keydown handling here.
      if (state.mode === 'input') {
        const { itemNames, api, statusBar } = state._ctx;
        // Space: commit token and open new hole
        if (raw.endsWith(' ') && raw.trim()) {
          state.inputBuffer = raw.trimEnd();
          const newNode = commitToken(state, itemNames, api, statusBar);
          if (newNode) {
            const nextHole = makeNode(state, 'hole', {});
            pushUndo(state);
            insertAfter(state, newNode.id, nextHole);
            notifyChange(state);
            state.replaceOriginal = null;
            enterInputMode(state, nextHole.id);
          }
          rerender(state, itemNames, api, statusBar);
          return;
        }
        // `"`: enter string mode (with or without prior token)
        if (raw.endsWith('"')) {
          const bufBefore = raw.slice(0, -1);
          if (bufBefore) {
            state.inputBuffer = bufBefore;
            const newNode = commitToken(state, itemNames, api, statusBar);
            const nextHole = makeNode(state, 'hole', {});
            pushUndo(state);
            insertAfter(state, newNode.id, nextHole);
            notifyChange(state);
            state.replaceOriginal = null;
            state.mode = 'string';
            state.inputHoleId = nextHole.id;
            state.inputBuffer = '';
            state.selectedId = nextHole.id;
            state.expansionStack = [];
          } else {
            state.mode = 'string';
            state.inputBuffer = '';
          }
          rerender(state, itemNames, api, statusBar);
          updateStringAutocomplete(state, state._ctx);
          return;
        }
      }
      state.inputBuffer = raw;
      state.inputCursor = inp.selectionStart ?? raw.length;
      state.inputSelectAll = false;
      inp.style.width = raw.length + 'ch';
      if (state.mode === 'string') {
        updateStringAutocomplete(state, state._ctx);
      } else {
        updateAutocomplete(state, state._ctx);
      }
    });
    if (state.inputSelectAll) {
      inp.select();
    } else {
      try { inp.setSelectionRange(state.inputCursor, state.inputCursor); } catch (_) {}
    }
    inp.focus();
  } else if (state.mode === 'nav') {
    if (!document.activeElement || document.activeElement === document.body) {
      state.editorEl?.focus({ preventScroll: true });
    }
  }
}

// --- Undo/Redo (snapshot approach) ---

function getNodePath(nodeId, state) {
  const path = [];
  let current = state.nodeMap.get(nodeId);
  if (!current) return null;
  let parent = state.parentMap.get(nodeId);
  while (parent) {
    const idx = parent.children.indexOf(current);
    if (idx === -1) return null;
    path.unshift(idx);
    current = parent;
    parent = state.parentMap.get(current.id);
  }
  return path;
}

function resolveNodePath(path, root) {
  let node = root;
  for (const idx of path) {
    if (!node.children || idx >= node.children.length) return null;
    node = node.children[idx];
  }
  return node;
}

function pushUndo(state) {
  const root = state.nodeMap.get(0);
  const compact = JSON.stringify(deflateAll(root));
  const selectionPath = state.selectedId != null ? getNodePath(state.selectedId, state) : null;
  state.undoStack.push({ compact, selectionPath });
  if (state.undoStack.length > 100) state.undoStack.shift();
  state.redoStack = [];
}

function restoreFromCompact(state, compactForms, selectionPath) {
  const { root, nodeMap, parentMap } = inflateAll(compactForms);
  // Replace maps in place so all references stay valid
  state.nodeMap.clear();
  for (const [k, v] of nodeMap) state.nodeMap.set(k, v);
  state.parentMap.clear();
  for (const [k, v] of parentMap) state.parentMap.set(k, v);
  // Restore selection
  if (selectionPath) {
    const node = resolveNodePath(selectionPath, root);
    state.selectedId = node ? node.id : (root.children[0]?.id || null);
  } else {
    state.selectedId = root.children[0]?.id || null;
  }
}

function notifyChange(state) {
  if (state.onChange) {
    const root = state.nodeMap.get(0);
    state.onChange(deflateAll(root));
  }
}

function undo(state, itemNames, api, statusBar) {
  if (state.undoStack.length === 0) return;
  // Push current state to redo
  const root = state.nodeMap.get(0);
  const currentCompact = JSON.stringify(deflateAll(root));
  const currentPath = state.selectedId != null ? getNodePath(state.selectedId, state) : null;
  state.redoStack.push({ compact: currentCompact, selectionPath: currentPath });
  // Pop undo
  const snapshot = state.undoStack.pop();
  restoreFromCompact(state, JSON.parse(snapshot.compact), snapshot.selectionPath);
  rerender(state, itemNames, api, statusBar);
  notifyChange(state);
}

function redo(state, itemNames, api, statusBar) {
  if (state.redoStack.length === 0) return;
  // Push current state to undo
  const root = state.nodeMap.get(0);
  const currentCompact = JSON.stringify(deflateAll(root));
  const currentPath = state.selectedId != null ? getNodePath(state.selectedId, state) : null;
  state.undoStack.push({ compact: currentCompact, selectionPath: currentPath });
  // Pop redo
  const snapshot = state.redoStack.pop();
  restoreFromCompact(state, JSON.parse(snapshot.compact), snapshot.selectionPath);
  rerender(state, itemNames, api, statusBar);
  notifyChange(state);
}

// --- Mutation wrapper ---

function applyMutation(state, itemNames, api, statusBar, mutationFn) {
  pushUndo(state);
  mutationFn();
  rerender(state, itemNames, api, statusBar);
  notifyChange(state);
}

// --- Delete operation ---

function removeFromMaps(node, state) {
  state.nodeMap.delete(node.id);
  state.parentMap.delete(node.id);
  if (node.children) node.children.forEach(child => removeFromMaps(child, state));
}

function deleteSelected(state) {
  const node = state.nodeMap.get(state.selectedId);
  if (!node) return;
  const parent = state.parentMap.get(state.selectedId);
  if (!parent || !parent.children) return;

  // Sole top-level form: replace with (·) and enter input mode immediately
  if (parent.type === 'root' && parent.children.length <= 1) {
    const hole = makeNode(state, 'hole', {});
    const list = makeNode(state, 'list', { children: [hole] });
    removeFromMaps(node, state);
    parent.children[0] = list;
    state.parentMap.set(list.id, parent);
    state.parentMap.set(hole.id, list);
    enterInputMode(state, hole.id);
    return;
  }

  const idx = parent.children.indexOf(node);
  if (idx === -1) return;

  if (parent.type === 'map' && node.type !== 'hole') {
    // Map special case: delete the entire key-value pair
    // (holes are single insertions that break pairing — use normal removal)
    const pairStart = idx % 2 === 0 ? idx : idx - 1;
    const removed = parent.children.splice(pairStart, 2);
    removed.forEach(n => removeFromMaps(n, state));
    // Selection: next pair, or previous pair, or parent
    if (parent.children.length === 0) {
      state.selectedId = parent.id;
    } else if (pairStart < parent.children.length) {
      state.selectedId = parent.children[pairStart].id;
    } else {
      state.selectedId = parent.children[parent.children.length - 2].id; // key of last pair
    }
  } else {
    // Normal case: remove single child
    parent.children.splice(idx, 1);
    removeFromMaps(node, state);
    // Selection: next sibling → previous sibling → parent
    if (parent.children.length === 0) {
      if (parent.type === 'list' || parent.type === 'vector') {
        // Empty collection: insert a hole and enter input mode immediately
        const hole = makeNode(state, 'hole', {});
        parent.children.push(hole);
        state.parentMap.set(hole.id, parent);
        enterInputMode(state, hole.id);
      } else {
        state.selectedId = parent.id;
      }
    } else if (idx < parent.children.length) {
      state.selectedId = parent.children[idx].id;
    } else {
      state.selectedId = parent.children[idx - 1].id;
    }
  }
}

// --- Range selection helpers (top-level forms only) ---

function getSelectedRange(state) {
  const root = state.nodeMap.get(0);
  const focusIdx = root.children.findIndex(c => c.id === state.selectedId);
  if (focusIdx === -1) return null;
  if (state.selectionAnchorId == null) return { lo: focusIdx, hi: focusIdx };
  const anchorIdx = root.children.findIndex(c => c.id === state.selectionAnchorId);
  if (anchorIdx === -1) return { lo: focusIdx, hi: focusIdx };
  return { lo: Math.min(anchorIdx, focusIdx), hi: Math.max(anchorIdx, focusIdx) };
}

function deleteRange(state) {
  const root = state.nodeMap.get(0);
  const range = getSelectedRange(state);
  if (!range) return;
  // Prevent deleting all top-level forms
  if (range.hi - range.lo + 1 >= root.children.length) return;
  const removed = root.children.splice(range.lo, range.hi - range.lo + 1);
  removed.forEach(n => removeFromMaps(n, state));
  state.selectionAnchorId = null;
  const newIdx = Math.min(range.lo, root.children.length - 1);
  state.selectedId = root.children[newIdx].id;
}

// --- AST manipulation helpers ---

let _nextId = 1;  // will be set from inflateAll result

function makeNode(state, type, props) {
  const node = { id: _nextId++, type, ...props };
  state.nodeMap.set(node.id, node);
  return node;
}

function insertAfter(state, refId, node) {
  const parent = state.parentMap.get(refId);
  if (!parent || !parent.children) return;
  const idx = parent.children.findIndex(c => c.id === refId);
  if (idx === -1) return;
  parent.children.splice(idx + 1, 0, node);
  state.parentMap.set(node.id, parent);
}

function insertBefore(state, refId, node) {
  const parent = state.parentMap.get(refId);
  if (!parent || !parent.children) return;
  const idx = parent.children.findIndex(c => c.id === refId);
  if (idx === -1) return;
  parent.children.splice(idx, 0, node);
  state.parentMap.set(node.id, parent);
}

function appendChild(state, parentId, node) {
  const parent = state.nodeMap.get(parentId);
  if (!parent || !parent.children) return;
  parent.children.push(node);
  state.parentMap.set(node.id, parent);
}

function replaceNode(state, targetId, node) {
  const parent = state.parentMap.get(targetId);
  if (!parent || !parent.children) return;
  const idx = parent.children.findIndex(c => c.id === targetId);
  if (idx === -1) return;
  // Remove old node from maps
  removeFromMaps(parent.children[idx], state);
  parent.children[idx] = node;
  state.nodeMap.set(node.id, node);
  state.parentMap.set(node.id, parent);
  // If new node has children, register them too
  if (node.children) {
    const registerChildren = (n) => {
      if (n.children) n.children.forEach(c => {
        state.nodeMap.set(c.id, c);
        state.parentMap.set(c.id, n);
        registerChildren(c);
      });
    };
    registerChildren(node);
  }
}

function inflateSubtree(compact, state) {
  if (compact === null) return makeNode(state, 'nil', {});
  if (typeof compact === 'number') return makeNode(state, 'number', { value: compact });
  if (typeof compact === 'boolean') return makeNode(state, 'boolean', { value: compact });
  if (typeof compact === 'string') {
    if (compact.startsWith(':')) return makeNode(state, 'keyword', { value: compact.slice(1) });
    if (compact.startsWith('@')) return makeNode(state, 'item-ref', { value: compact.slice(1) });
    return makeNode(state, 'symbol', { value: compact });
  }
  if (Array.isArray(compact) && compact[0] === ':doc') {
    return makeNode(state, 'doc', { value: compact });
  }
  if (Array.isArray(compact)) {
    const node = makeNode(state, 'list', { children: [] });
    node.children = compact.map(c => {
      const child = inflateSubtree(c, state);
      state.parentMap.set(child.id, node);
      return child;
    });
    return node;
  }
  if (compact.s !== undefined) return makeNode(state, 'string', { value: compact.s });
  if (compact.v) {
    const node = makeNode(state, 'vector', { children: [] });
    node.children = compact.v.map(c => {
      const child = inflateSubtree(c, state);
      state.parentMap.set(child.id, node);
      return child;
    });
    return node;
  }
  if (compact.m) {
    const node = makeNode(state, 'map', { children: [] });
    node.children = compact.m.flatMap(([k, v]) => {
      const kc = inflateSubtree(k, state);
      const vc = inflateSubtree(v, state);
      state.parentMap.set(kc.id, node);
      state.parentMap.set(vc.id, node);
      return [kc, vc];
    });
    return node;
  }
  return makeNode(state, 'nil', {});
}

// --- Token resolution ---

function resolveToken(buffer) {
  if (/^-?\d+(\.\d+)?$/.test(buffer)) return { type: 'number', value: parseFloat(buffer) };
  if (buffer === 'true') return { type: 'boolean', value: true };
  if (buffer === 'false') return { type: 'boolean', value: false };
  if (buffer === 'nil') return { type: 'nil' };
  if (buffer.startsWith(':')) return { type: 'keyword', value: buffer.slice(1) };
  if (buffer.startsWith('@') && buffer.length > 1) return { type: 'item-ref', value: buffer.slice(1) };
  return { type: 'symbol', value: buffer };
}

// --- Selection System ---

function updateSelectionVisual(state) {
  // Remove previous selection (may be multiple elements in range mode)
  state.editorEl?.querySelectorAll('.hob-selected').forEach(el => el.classList.remove('hob-selected'));
  state.editorEl?.querySelectorAll('.hob-ancestor').forEach(el => el.classList.remove('hob-ancestor'));

  if (state.selectedId == null) return;

  if (state.selectionAnchorId != null) {
    // Range selection: highlight all root-level nodes in the range
    const root = state.nodeMap.get(0);
    const range = getSelectedRange(state);
    if (!range) return;
    for (let i = range.lo; i <= range.hi; i++) {
      const el = state.domMap.get(root.children[i].id);
      if (el) el.classList.add('hob-selected');
    }
    // Scroll focus end into view
    const focusEl = state.domMap.get(state.selectedId);
    if (focusEl) focusEl.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    return;
  }

  // Single selection
  const el = state.domMap.get(state.selectedId);
  if (!el) return;
  el.classList.add('hob-selected');

  // Walk parent chain for ancestor highlighting
  let parentNode = state.parentMap.get(state.selectedId);
  while (parentNode && parentNode.type !== 'root') {
    const parentEl = state.domMap.get(parentNode.id);
    if (parentEl) parentEl.classList.add('hob-ancestor');
    parentNode = state.parentMap.get(parentNode.id);
  }

  // Scroll selected element into view
  el.scrollIntoView({ block: 'nearest', inline: 'nearest' });
}

function nodeLabel(node) {
  if (!node) return '?';
  if (node.type === 'root') return 'root';
  if (node.type === 'doc') return ';; doc';
  if (node.type === 'list' && node.children.length > 0 && node.children[0].type === 'symbol') {
    return '(' + node.children[0].value + ')';
  }
  if (node.type === 'list') return (node._curlyList || node._curlyInfix || isInfixList(node)) ? '{}' : '()';
  if (node.type === 'vector') return '[]';
  if (node.type === 'map') return '{}';
  return leafText(node);
}

function updateStatusBar(state, statusBar) {
  const breadcrumbsEl = statusBar.querySelector('.hob-breadcrumbs');
  const nodeInfoEl = statusBar.querySelector('.hob-node-info');
  const modeEl = statusBar.querySelector('.hob-mode');

  if (state.selectedId == null) {
    breadcrumbsEl.textContent = '';
    nodeInfoEl.textContent = '';
    return;
  }

  const node = state.nodeMap.get(state.selectedId);
  if (!node) return;

  // Update mode indicator
  if (state.onChange) {
    const modeText = state.mode === 'nav' ? 'NAV' : state.mode === 'doc' ? 'DOC' : state.mode === 'input' ? 'INPUT' : 'STRING';
    modeEl.textContent = modeText;
    modeEl.className = 'hob-mode ' + (state.mode === 'nav' ? 'hob-mode-nav' : 'hob-mode-input');
  } else {
    modeEl.textContent = 'VIEW';
    modeEl.className = 'hob-mode hob-mode-view';
  }

  // Range selection: show count instead of breadcrumbs
  if (state.selectionAnchorId != null) {
    const range = getSelectedRange(state);
    const count = range ? range.hi - range.lo + 1 : 1;
    breadcrumbsEl.textContent = count + ' forms selected';
    nodeInfoEl.textContent = '';
    return;
  }

  // Build breadcrumb chain
  const chain = [];
  let current = node;
  while (current) {
    chain.unshift(current);
    current = state.parentMap.get(current.id);
  }

  // Render breadcrumbs
  breadcrumbsEl.textContent = '';
  for (let i = 0; i < chain.length; i++) {
    if (i > 0) {
      const sep = document.createElement('span');
      sep.className = 'hob-breadcrumb-sep';
      sep.textContent = ' \u203a ';
      breadcrumbsEl.appendChild(sep);
    }
    const crumb = document.createElement('span');
    crumb.textContent = nodeLabel(chain[i]);
    const crumbNodeId = chain[i].id;
    crumb.addEventListener('click', (e) => {
      e.stopPropagation();
      state.selectedId = crumbNodeId;
      state.selectionAnchorId = null;
      state.expansionStack = [];
      updateSelectionVisual(state);
      updateStatusBar(state, statusBar);
    });
    breadcrumbsEl.appendChild(crumb);
  }

  // Node info
  if (node.children) {
    nodeInfoEl.textContent = node.type + ' (' + node.children.length + ')';
  } else {
    nodeInfoEl.textContent = node.type + ': ' + leafText(node);
  }
}

// --- Hole utilities ---

function buildCursorContent(el, before, after) {
  el.textContent = '';
  if (before) el.appendChild(document.createTextNode(before));
  const cur = document.createElement('span');
  cur.className = 'hob-cursor';
  cur.textContent = '\u200B'; // zero-width space for height
  el.appendChild(cur);
  if (after) el.appendChild(document.createTextNode(after));
}

function updateHoleDisplay(state) {
  const holeEl = state.domMap.get(state.inputHoleId);
  if (!holeEl) return;
  const inp = holeEl.querySelector('.hob-hole-input');
  if (!inp) return;
  inp.value = state.inputBuffer;
  inp.style.width = state.inputBuffer.length + 'ch';
  if (state.inputSelectAll) {
    inp.select();
  } else {
    try { inp.setSelectionRange(state.inputCursor, state.inputCursor); } catch (_) {}
  }
}

function findHoles(state) {
  // Collect all hole node IDs in document order (depth-first)
  const holes = [];
  function walk(node) {
    if (node.type === 'hole') { holes.push(node.id); return; }
    if (node.children) node.children.forEach(walk);
  }
  walk(state.nodeMap.get(0));
  return holes;
}

function enterDocEditing(state, docNodeId, itemNames, api, statusBar) {
  const docEl = state.domMap.get(docNodeId);
  if (!docEl || !docEl._docRenderContent) return;
  state.mode = 'doc';
  docEl._docRenderContent(true).then(() => {
    const firstEditable = docEl.querySelector('[contenteditable="true"]');
    if (firstEditable) firstEditable.focus();
    const escHandler = (evt) => {
      if (evt.key === 'Escape') {
        evt.preventDefault();
        evt.stopPropagation();
        docEl.removeEventListener('keydown', escHandler, true);
        state.mode = 'nav';
        docEl._docRenderContent(false).then(() => {
          state.editorEl.focus();
          updateSelectionVisual(state);
          updateStatusBar(state, statusBar);
        });
      }
    };
    docEl.addEventListener('keydown', escHandler, true);
    updateStatusBar(state, statusBar);
  });
}

function enterInputMode(state, holeId) {
  hideAutocomplete(state);
  state.mode = 'input';
  state.inputHoleId = holeId;
  state.inputBuffer = '';
  state.inputCursor = 0;
  state.inputSelectAll = false;
  state.selectedId = holeId;
  state.expansionStack = [];
}

function exitToNav(state, selectId) {
  hideAutocomplete(state);
  state.mode = 'nav';
  state.inputBuffer = '';
  state.inputCursor = 0;
  state.inputHoleId = null;
  state.inputSelectAll = false;
  state.replaceOriginal = null;
  if (selectId != null) {
    state.selectedId = selectId;
    state.expansionStack = [];
  }
}

function commitToken(state, itemNames, api, statusBar) {
  if (!state.inputBuffer) return null;
  const resolved = resolveToken(state.inputBuffer);
  const newNode = makeNode(state, resolved.type, resolved);
  pushUndo(state);
  replaceNode(state, state.inputHoleId, newNode);
  // If this is the first child of a {}-created list and it's a keyword, convert to map
  const parent = state.parentMap.get(newNode.id);
  if (parent && parent._curlyList && newNode.type === 'keyword'
      && parent.children[0] === newNode) {
    parent.type = 'map';
    delete parent._curlyList;
  }
  notifyChange(state);
  return newNode;
}

// --- Autocomplete ---

function collectSymbols(state) {
  const syms = new Set(SPECIAL_FORMS);
  for (const node of state.nodeMap.values()) {
    if (node.type === 'symbol') syms.add(node.value);
  }
  return [...syms].sort();
}

function collectScopeSymbols(state, holeId) {
  const scopeSymbols = [];
  const seen = new Set();

  function addSym(name, detail) {
    if (!seen.has(name)) {
      seen.add(name);
      scopeSymbols.push({ name, detail });
    }
  }

  // Walk up from hole through parent chain
  let currentId = holeId;
  while (state.parentMap.has(currentId)) {
    const parent = state.parentMap.get(currentId);
    if (parent.type === 'list' && parent.children.length > 0 && parent.children[0].type === 'symbol') {
      const headName = parent.children[0].value;

      if (BINDING_FORMS.has(headName)) {
        // (let [a 1 b 2] body) — bindings vector is children[1]
        if (parent.children.length >= 2 && parent.children[1].type === 'vector') {
          const bindings = parent.children[1].children;
          for (let i = 0; i < bindings.length; i += 2) {
            if (bindings[i].type === 'symbol') addSym(bindings[i].value, 'local');
          }
        }
      }

      if (headName === 'fn') {
        // (fn [x y & rest] body)
        if (parent.children.length >= 2 && parent.children[1].type === 'vector') {
          for (const param of parent.children[1].children) {
            if (param.type === 'symbol' && param.value !== '&') addSym(param.value, 'param');
          }
        }
      }

      if (headName === 'defn' || headName === 'defmacro') {
        // (defn name [x y] body)
        if (parent.children.length >= 3 && parent.children[2].type === 'vector') {
          for (const param of parent.children[2].children) {
            if (param.type === 'symbol' && param.value !== '&') addSym(param.value, 'param');
          }
        }
      }
    }
    currentId = parent.id;
  }

  // Top-level defs
  const root = state.nodeMap.get(0);
  if (root && root.children) {
    for (const form of root.children) {
      if (form.type === 'list' && form.children.length >= 2 && form.children[0].type === 'symbol') {
        const head = form.children[0].value;
        if (head === 'def' && form.children[1].type === 'symbol') {
          addSym(form.children[1].value, 'def');
        }
        if ((head === 'defn' || head === 'defmacro') && form.children[1].type === 'symbol') {
          addSym(form.children[1].value, 'defn');
        }
      }
    }
  }

  return scopeSymbols;
}

function hideAutocomplete(state) {
  state.acVisible = false;
  state.acItems = [];
  state.acIndex = 0;
  state.acMode = null;
  if (state._acTimer) {
    clearTimeout(state._acTimer);
    state._acTimer = null;
  }
  if (state.acEl && state.acEl.parentNode) {
    state.acEl.parentNode.removeChild(state.acEl);
  }
}

function renderAutocomplete(state) {
  if (!state.acVisible) {
    if (state.acEl && state.acEl.parentNode) {
      state.acEl.parentNode.removeChild(state.acEl);
    }
    return;
  }

  if (!state.acEl) {
    state.acEl = document.createElement('div');
    state.acEl.className = 'hob-autocomplete';
  }

  const holeEl = state.domMap.get(state.inputHoleId);
  if (holeEl) {
    const rect = holeEl.getBoundingClientRect();
    const spaceBelow = window.innerHeight - rect.bottom - 4;
    const spaceAbove = rect.top - 4;
    state.acEl.style.position = 'fixed';
    state.acEl.style.left = rect.left + 'px';
    if (spaceBelow >= 120 || spaceBelow >= spaceAbove) {
      state.acEl.style.top = (rect.bottom + 2) + 'px';
      state.acEl.style.bottom = '';
      state.acEl.style.maxHeight = Math.max(80, spaceBelow) + 'px';
    } else {
      state.acEl.style.top = '';
      state.acEl.style.bottom = (window.innerHeight - rect.top + 2) + 'px';
      state.acEl.style.maxHeight = Math.max(80, spaceAbove) + 'px';
    }
  }

  state.acEl.textContent = '';
  state.acItems.forEach((item, i) => {
    const row = document.createElement('div');
    row.className = 'hob-ac-item' + (i === state.acIndex ? ' hob-ac-selected' : '') + (item.acType === 'system' ? ' hob-ac-system' : '');

    const label = document.createElement('span');
    label.textContent = item.label;
    row.appendChild(label);

    if (item.detail) {
      const detail = document.createElement('span');
      detail.className = 'hob-ac-detail';
      detail.textContent = item.detail;
      row.appendChild(detail);
    }

    row.addEventListener('mousedown', (e) => {
      e.preventDefault();
      selectAutocomplete(state, i, state._ctx);
    });

    state.acEl.appendChild(row);
  });

  if (!state.acEl.parentNode) {
    document.body.appendChild(state.acEl);
  }
}

function isInRequireContext(state, holeId) {
  const parent = state.parentMap.get(holeId);
  if (!parent || parent.type !== 'list') return false;
  const head = parent.children?.[0];
  return head?.type === 'symbol' && head.value === 'require';
}

function updateStringAutocomplete(state, ctx) {
  if (!isInRequireContext(state, state.inputHoleId)) { hideAutocomplete(state); return; }
  const buf = state.inputBuffer;
  const items = [];
  for (const name of _symbolIndex.libraries.values()) {
    if (!buf || name.includes(buf))
      items.push({ label: name, detail: 'library', value: name, acType: 'require' });
  }
  items.sort((a, b) => a.label.localeCompare(b.label));
  state.acMode = 'require';
  state.acItems = items.slice(0, 50);
  state.acIndex = 0;
  state.acVisible = state.acItems.length > 0;
  if (state.acVisible) renderAutocomplete(state); else hideAutocomplete(state);
}

function updateAutocomplete(state, ctx) {
  const { itemNames, api } = ctx;
  const buf = state.inputBuffer;

  if (state._acTimer) {
    clearTimeout(state._acTimer);
    state._acTimer = null;
  }

  state._acGeneration = (state._acGeneration || 0) + 1;
  const gen = state._acGeneration;

  if (buf.startsWith('@')) {
    state.acMode = 'item';
    const query = buf.slice(1);

    const doSearch = async () => {
      try {
        let results;
        if (!query && state._itemSearchLib) {
          results = await state._itemSearchLib.getStarredItems(api);
        } else {
          // Name-only search — don't match against code/description/IDs
          const all = await api.getAll();
          const q = query.toLowerCase();
          results = all
            .filter(it => it.name && (!q || it.name.toLowerCase().includes(q)))
            .sort((a, b) => (a.name || '').localeCompare(b.name || ''));
        }
        if (gen !== state._acGeneration) return;
        state.acItems = results.slice(0, 12).map(item => ({
          label: item.name || item.id.slice(0, 8),
          detail: '',
          value: item.id,
          acType: 'item-ref'
        }));
        state.acIndex = 0;
        state.acVisible = state.acItems.length > 0;
        renderAutocomplete(state);
      } catch {
        if (gen !== state._acGeneration) return;
        hideAutocomplete(state);
      }
    };

    if (!query) {
      doSearch();
    } else {
      state._acTimer = setTimeout(doSearch, 150);
    }
  } else {
    state.acMode = 'symbol';
    const scopeSyms = collectScopeSymbols(state, state.inputHoleId);
    const seen = new Set();
    const allItems = [];

    // 1. Scope symbols
    for (const s of scopeSyms) {
      if (!buf || (s.name.startsWith(buf) && s.name !== buf)) {
        if (!seen.has(s.name)) {
          seen.add(s.name);
          allItems.push({ label: s.name, detail: s.detail, value: s.name, acType: 'symbol' });
        }
      }
    }

    // 2. AST symbols from current item (only when filtering)
    if (buf) {
      for (const sym of collectSymbols(state)) {
        if (sym.startsWith(buf) && sym !== buf && !seen.has(sym)) {
          seen.add(sym);
          allItems.push({ label: sym, detail: '', value: sym, acType: 'symbol' });
        }
      }
    }

    // 3. STDLIB (always shown on empty hole; filtered by prefix when typing)
    for (const s of STDLIB) {
      if (!buf || (s.n.startsWith(buf) && s.n !== buf)) {
        if (!seen.has(s.n)) {
          seen.add(s.n);
          allItems.push({ label: s.n, detail: s.d, value: s.n, acType: 'symbol' });
        }
      }
    }

    // 4. System index (cross-item symbols, shown last)
    for (const s of _symbolIndex.flat) {
      if (!buf || (s.name.startsWith(buf) && s.name !== buf)) {
        if (!seen.has(s.name)) {
          seen.add(s.name);
          allItems.push({ label: s.name, detail: s.detail, value: s.name, acType: 'system' });
        }
      }
    }

    state.acItems = allItems.slice(0, 50);
    state.acIndex = 0;
    state.acVisible = state.acItems.length > 0;
    if (state.acVisible) renderAutocomplete(state); else hideAutocomplete(state);
  }
}

function selectAutocomplete(state, index, ctx) {
  const { statusBar, itemNames, api } = ctx;
  const item = state.acItems[index];
  if (!item) return;

  hideAutocomplete(state);

  if (item.acType === 'symbol') {
    state.inputBuffer = item.value;
    state.inputCursor = item.value.length;
    state.inputSelectAll = false;
    const newNode = commitToken(state, itemNames, api, statusBar);
    exitToNav(state, newNode.id);
    rerender(state, itemNames, api, statusBar);
  } else if (item.acType === 'item-ref') {
    pushUndo(state);
    const newNode = makeNode(state, 'item-ref', { value: item.value });
    replaceNode(state, state.inputHoleId, newNode);
    itemNames.set(item.value, item.label);
    notifyChange(state);
    exitToNav(state, newNode.id);
    rerender(state, itemNames, api, statusBar);
  }
}

// --- Navigation ---

function handleNavKey(e, ctx) {
  const { state, statusBar, itemNames, api } = ctx;
  const node = state.nodeMap.get(state.selectedId);
  if (!node) return;
  const parent = state.parentMap.get(state.selectedId);

  let handled = true;

  if (e.key === 'ArrowLeft' && !e.shiftKey && !e.ctrlKey && !e.metaKey && !e.altKey) {
    // Go to parent (shallower)
    if (parent && parent.type !== 'root') {
      state.selectedId = parent.id;
      state.selectionAnchorId = null;
      state.expansionStack = [];
    }
  } else if (e.key === 'ArrowRight' && !e.shiftKey && !e.ctrlKey && !e.metaKey && !e.altKey) {
    // Enter container (deeper)
    if (node.children && node.children.length > 0) {
      state.selectedId = node.children[0].id;
      state.selectionAnchorId = null;
      state.expansionStack = [];
    }
  } else if (e.key === 'ArrowUp' && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
    // Previous sibling, or parent if at first child
    if (parent && parent.children) {
      const idx = parent.children.indexOf(node);
      if (idx > 0) {
        state.selectedId = parent.children[idx - 1].id;
        state.selectionAnchorId = null;
        state.expansionStack = [];
      } else if (parent.type !== 'root') {
        state.selectedId = parent.id;
        state.selectionAnchorId = null;
        state.expansionStack = [];
      }
    }
  } else if (e.key === 'ArrowDown' && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
    // Next sibling, or walk up to find ancestor's next sibling
    let cur = node;
    let curParent = parent;
    while (curParent && curParent.type !== 'root') {
      const idx = curParent.children.indexOf(cur);
      if (idx < curParent.children.length - 1) {
        state.selectedId = curParent.children[idx + 1].id;
        state.selectionAnchorId = null;
        state.expansionStack = [];
        break;
      }
      cur = curParent;
      curParent = state.parentMap.get(curParent.id);
    }
  } else if (e.key === 'Home' && !e.ctrlKey && !e.metaKey) {
    // First sibling
    if (parent && parent.children && parent.children.length > 0) {
      state.selectedId = parent.children[0].id;
      state.selectionAnchorId = null;
      state.expansionStack = [];
    }
  } else if (e.key === 'End' && !e.ctrlKey && !e.metaKey) {
    // Last sibling
    if (parent && parent.children && parent.children.length > 0) {
      state.selectedId = parent.children[parent.children.length - 1].id;
      state.selectionAnchorId = null;
      state.expansionStack = [];
    }
  } else if (e.key === 'ArrowUp' && (e.ctrlKey || e.metaKey) && !e.shiftKey) {
    // Select top-level: walk up to root's child
    let cur = node;
    let curParent = parent;
    while (curParent && curParent.type !== 'root') {
      cur = curParent;
      curParent = state.parentMap.get(curParent.id);
    }
    if (cur.id !== node.id) {
      state.selectedId = cur.id;
      state.selectionAnchorId = null;
      state.expansionStack = [];
    }
  } else if (e.key === 'ArrowLeft' && (e.ctrlKey || e.metaKey)) {
    // Previous top-level form
    const root = state.nodeMap.get(0);
    let cur = node;
    let curParent = parent;
    while (curParent && curParent.type !== 'root') {
      cur = curParent;
      curParent = state.parentMap.get(curParent.id);
    }
    const idx = root.children.indexOf(cur);
    if (idx > 0) {
      state.selectedId = root.children[idx - 1].id;
      state.selectionAnchorId = null;
      state.expansionStack = [];
    }
