  } else if (e.key === 'Tab' && e.shiftKey && state.onChange) {
    // Jump to previous hole
    const holes = findHoles(state);
    if (holes.length > 0) {
      const curIdx = holes.indexOf(state.selectedId);
      const prevIdx = curIdx <= 0 ? holes.length - 1 : curIdx - 1;
