    if (state.selectionAnchorId != null) {
      const root = state.nodeMap.get(0);
      const range = getSelectedRange(state);
      const nodes = root.children.slice(range.lo, range.hi + 1);
      _clipboard = nodes.map(deflate);
      navigator.clipboard?.writeText(nodes.map(nodeToSexp).join('\n\n'));
