    if (node.type === 'hole') {
      enterInputMode(state, node.id);
      if (e.key === '"') { state.mode = 'string'; }
      else { state.inputBuffer = e.key; state.inputCursor = 1; }
    } else if (node.type === 'string' && e.key === '"') {
      const hole = makeNode(state, 'hole', {});
      state.replaceOriginal = { nodeSnapshot: JSON.parse(JSON.stringify(node)), parentId: state.parentMap.get(node.id)?.id };
      pushUndo(state);
      replaceNode(state, node.id, hole);
      notifyChange(state);
      enterInputMode(state, hole.id);
      state.mode = 'string';
      state.inputBuffer = node.value;
      state.inputCursor = node.value.length;
    } else {
      const hole = makeNode(state, 'hole', {});
      state.replaceOriginal = { nodeSnapshot: JSON.parse(JSON.stringify(node)), parentId: state.parentMap.get(node.id)?.id };
      pushUndo(state);
      replaceNode(state, node.id, hole);
      notifyChange(state);
      if (e.key === '"') { enterInputMode(state, hole.id); state.mode = 'string'; }
      else { enterInputMode(state, hole.id); state.inputBuffer = e.key; state.inputCursor = 1; }
    }
    rerender(state, itemNames, api, statusBar);
  } else {
    handled = false;
  }

  return handled;
}

function handleInputKey(e, ctx) {
  const { state, statusBar, itemNames, api } = ctx;
  let handled = true;

  // Autocomplete intercept — when dropdown is visible, capture nav keys
  if (state.acVisible) {
    if (e.key === 'ArrowDown') {
      state.acIndex = (state.acIndex + 1) % state.acItems.length;
      renderAutocomplete(state);
      return true;
    }
    if (e.key === 'ArrowUp') {
      state.acIndex = (state.acIndex - 1 + state.acItems.length) % state.acItems.length;
      renderAutocomplete(state);
      return true;
    }
    if (e.key === 'Enter' || e.key === 'Tab') {
      selectAutocomplete(state, state.acIndex, ctx);
      return true;
    }
    if (e.key === 'Escape') {
      hideAutocomplete(state);
      return true;
    }
  }

  if (e.key === 'Escape') {
    // Cancel: restore or remove hole
    if (state.replaceOriginal) {
      // Restore original node
      const orig = state.replaceOriginal.nodeSnapshot;
      const restored = makeNode(state, orig.type, orig);
      pushUndo(state);
      replaceNode(state, state.inputHoleId, restored);
      notifyChange(state);
      exitToNav(state, restored.id);
    } else {
      // Remove the hole
      const holeId = state.inputHoleId;
      state.selectedId = holeId;
      pushUndo(state);
      deleteSelected(state);
      notifyChange(state);
      exitToNav(state, state.selectedId);
    }
    rerender(state, itemNames, api, statusBar);
  } else if (e.key === 'Enter') {
    if (state.inputBuffer) {
      const newNode = commitToken(state, itemNames, api, statusBar);
      exitToNav(state, newNode.id);
    } else {
      // Empty buffer: remove hole and exit
      const holeId = state.inputHoleId;
      state.selectedId = holeId;
      pushUndo(state);
      deleteSelected(state);
      notifyChange(state);
      exitToNav(state, state.selectedId);
    }
    rerender(state, itemNames, api, statusBar);
  } else if (e.key === ' ') {
    if (state.inputBuffer) {
      // Commit token, create new hole after it
      const newNode = commitToken(state, itemNames, api, statusBar);
      const nextHole = makeNode(state, 'hole', {});
      pushUndo(state);
      insertAfter(state, newNode.id, nextHole);
      notifyChange(state);
      state.replaceOriginal = null;
      enterInputMode(state, nextHole.id);
      rerender(state, itemNames, api, statusBar);
    }
    // If empty buffer, no-op
  } else if (e.key === 'Backspace') {
    if (!state.inputBuffer) {
      // Empty buffer: remove hole, exit to nav
      const holeId = state.inputHoleId;
      state.selectedId = holeId;
      if (state.replaceOriginal) {
        const orig = state.replaceOriginal.nodeSnapshot;
        const restored = makeNode(state, orig.type, orig);
        pushUndo(state);
        replaceNode(state, holeId, restored);
        notifyChange(state);
        exitToNav(state, restored.id);
      } else {
        pushUndo(state);
        deleteSelected(state);
        notifyChange(state);
        exitToNav(state, state.selectedId);
      }
      rerender(state, itemNames, api, statusBar);
    } else {
      handled = false; // non-empty: native input handles deletion
    }
  } else if (e.key === '(' || e.key === '[' || e.key === '{') {
    // Commit buffer if non-empty, then create container with inner hole
    let afterId = state.inputHoleId;
    if (state.inputBuffer) {
      const newNode = commitToken(state, itemNames, api, statusBar);
      afterId = newNode.id;
    }
    const containerType = e.key === '[' ? 'vector' : 'list';
    const innerHole = makeNode(state, 'hole', {});
    const container = makeNode(state, containerType, { children: [innerHole] });
    if (e.key === '{') container._curlyList = true;
    state.parentMap.set(innerHole.id, container);
    // If we committed, insert container as sibling after committed node
    // If buffer was empty, replace the hole with the container
    if (afterId !== state.inputHoleId) {
      // Buffer was committed; the old hole is gone. Insert container after committed node.
      pushUndo(state);
      insertAfter(state, afterId, container);
      notifyChange(state);
    } else {
      // Buffer was empty, replace hole with container
      pushUndo(state);
      replaceNode(state, state.inputHoleId, container);
      notifyChange(state);
    }
    enterInputMode(state, innerHole.id);
    rerender(state, itemNames, api, statusBar);
  } else if (e.key === ')' || e.key === ']' || e.key === '}') {
    // Commit buffer if non-empty, then select matching ancestor container
    if (state.inputBuffer) {
      const newNode = commitToken(state, itemNames, api, statusBar);
      state.selectedId = newNode.id;
    } else {
      // Remove empty hole
      const holeId = state.inputHoleId;
      state.selectedId = holeId;
      pushUndo(state);
      deleteSelected(state);
      notifyChange(state);
    }
    // Walk up to find matching container
    const targetType = e.key === ')' ? 'list' : e.key === ']' ? 'vector' : 'map';
    const targetCurly = e.key === '}';
    let cur = state.nodeMap.get(state.selectedId);
    let found = null;
    while (cur) {
      cur = state.parentMap.get(cur.id);
      if (cur && cur.type === targetType) { found = cur; break; }
      if (targetCurly && cur && (cur._curlyList || cur._curlyInfix || isInfixList(cur))) { found = cur; break; }
      if (cur && cur.type === 'root') break;
    }
    exitToNav(state, found ? found.id : state.selectedId);
    rerender(state, itemNames, api, statusBar);
  } else if (e.key === '"') {
    if (!state.inputBuffer) {
      // Enter string mode — rerender so span gets hob-string class for quote pseudo-elements
      state.mode = 'string';
      state.inputBuffer = '';
      rerender(state, itemNames, api, statusBar);
      updateStringAutocomplete(state, ctx);
    } else {
      // Commit current, then create new hole in string mode
      const newNode = commitToken(state, itemNames, api, statusBar);
      const nextHole = makeNode(state, 'hole', {});
      pushUndo(state);
      insertAfter(state, newNode.id, nextHole);
      notifyChange(state);
      state.replaceOriginal = null;
      state.mode = 'string';
      state.inputHoleId = nextHole.id;
      state.inputBuffer = '';
      state.selectedId = nextHole.id;
      state.expansionStack = [];
      rerender(state, itemNames, api, statusBar);
      updateStringAutocomplete(state, ctx);
    }
  } else if (e.key === 'Tab' && !e.shiftKey) {
    // Jump to next hole
    if (state.inputBuffer) {
      commitToken(state, itemNames, api, statusBar);
    }
    const holes = findHoles(state);
    if (holes.length > 0) {
      const curIdx = holes.indexOf(state.inputHoleId);
      const nextIdx = curIdx < 0 ? 0 : (curIdx + 1) % holes.length;
      enterInputMode(state, holes[nextIdx]);
    } else {
      exitToNav(state, state.selectedId);
    }
    rerender(state, itemNames, api, statusBar);
  } else if (e.key === 'Tab' && e.shiftKey) {
    // Jump to previous hole
    if (state.inputBuffer) {
      commitToken(state, itemNames, api, statusBar);
    }
    const holes = findHoles(state);
    if (holes.length > 0) {
      const curIdx = holes.indexOf(state.inputHoleId);
      const prevIdx = curIdx <= 0 ? holes.length - 1 : curIdx - 1;
      enterInputMode(state, holes[prevIdx]);
    } else {
      exitToNav(state, state.selectedId);
    }
    rerender(state, itemNames, api, statusBar);
  } else if (e.key === 'v' && (e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && _clipboard !== null) {
    // Structural paste from internal clipboard
    const holeId = state.inputHoleId;
    let afterId = holeId;
    if (state.inputBuffer) {
      const newNode = commitToken(state, itemNames, api, statusBar);
      afterId = newNode.id;
    }
    const pasted = inflateSubtree(_clipboard[0], state);
    exitToNav(state, pasted.id);
    applyMutation(state, itemNames, api, statusBar, () => {
      if (afterId !== holeId) {
        insertAfter(state, afterId, pasted);
      } else {
        replaceNode(state, holeId, pasted);
      }
    });
  } else {
    handled = false;
  }

  return handled;
}

function handleStringKey(e, ctx) {
  const { state, statusBar, itemNames, api } = ctx;
  let handled = true;

  // Autocomplete intercept (require-context string completion)
  if (state.acVisible) {
    if (e.key === 'ArrowDown') {
      state.acIndex = (state.acIndex + 1) % state.acItems.length;
      renderAutocomplete(state); return true;
    }
    if (e.key === 'ArrowUp') {
      state.acIndex = (state.acIndex - 1 + state.acItems.length) % state.acItems.length;
      renderAutocomplete(state); return true;
    }
    if (e.key === 'Tab' || (e.key === 'Enter' && !e.shiftKey)) {
      const sel = state.acItems[state.acIndex];
      if (sel) { state.inputBuffer = sel.value; state.inputCursor = sel.value.length; updateHoleDisplay(state); }
      hideAutocomplete(state); return true;
    }
    if (e.key === 'Escape') { hideAutocomplete(state); return true; }
  }

  if (e.key === 'Escape') {
    // Cancel string
    if (state.replaceOriginal) {
      const orig = state.replaceOriginal.nodeSnapshot;
      const restored = makeNode(state, orig.type, orig);
      pushUndo(state);
      replaceNode(state, state.inputHoleId, restored);
      notifyChange(state);
      exitToNav(state, restored.id);
    } else {
      const holeId = state.inputHoleId;
      state.selectedId = holeId;
      pushUndo(state);
      deleteSelected(state);
      notifyChange(state);
      exitToNav(state, state.selectedId);
    }
    rerender(state, itemNames, api, statusBar);
  } else if (e.key === 'Backspace' && !state.inputBuffer) {
    // Buffer already empty — delete the hole/node (mirrors handleInputKey Backspace behaviour).
    const holeId = state.inputHoleId;
    state.selectedId = holeId;
    pushUndo(state);
    deleteSelected(state);
    notifyChange(state);
    state.replaceOriginal = null;
    exitToNav(state, state.selectedId);
    rerender(state, itemNames, api, statusBar);
  } else if (e.key === 'Backspace') {
    handled = false; // non-empty buffer: native <input> handles character deletion
  } else if (e.key === '"' && !e.shiftKey) {
    // Commit string
    const strNode = makeNode(state, 'string', { value: state.inputBuffer });
    pushUndo(state);
    replaceNode(state, state.inputHoleId, strNode);
    notifyChange(state);
    exitToNav(state, strNode.id);
    rerender(state, itemNames, api, statusBar);
  } else if (e.key === 'Enter') {
    // Commit string and exit to nav (<input> is single-line, so Shift+Enter also commits)
    const strNode = makeNode(state, 'string', { value: state.inputBuffer });
    pushUndo(state);
    replaceNode(state, state.inputHoleId, strNode);
    notifyChange(state);
    state.replaceOriginal = null;
    exitToNav(state, strNode.id);
    rerender(state, itemNames, api, statusBar);
  } else {
    handled = false;
  }

  return handled;
}

function handleKey(e, ctx) {
  const { state, statusBar, itemNames, api } = ctx;

  // Help overlay is modal — swallow all keys; Ctrl+/ and Escape dismiss it
  if (state.helpVisible) {
    if ((e.key === '/' && (e.ctrlKey || e.metaKey)) || e.key === 'Escape') hideHelp(state);
    e.preventDefault();
    e.stopPropagation();
    return;
  }

  // In doc mode, let the prose editor handle all keys (Escape handled by doc's own listener)
  if (state.mode === 'doc') return;

  // Ctrl/Cmd+Enter — commit any in-progress edit then submit, from any mode
  if (e.key === 'Enter' && (e.ctrlKey || e.metaKey) && !e.shiftKey && state.onSubmit) {
    if (state.mode === 'input') {
      if (state.inputBuffer) {
        commitToken(state, itemNames, api, statusBar);
      } else {
        state.selectedId = state.inputHoleId;
        pushUndo(state);
        deleteSelected(state);
        notifyChange(state);
      }
      exitToNav(state, state.selectedId);
      rerender(state, itemNames, api, statusBar);
    } else if (state.mode === 'string') {
      const strNode = makeNode(state, 'string', { value: state.inputBuffer });
      pushUndo(state);
      replaceNode(state, state.inputHoleId, strNode);
      notifyChange(state);
      exitToNav(state, strNode.id);
      rerender(state, itemNames, api, statusBar);
    }
    const root = state.nodeMap.get(0);
    if (root) state.onSubmit(deflateAll(root));
    e.preventDefault();
    e.stopPropagation();
    return;
  }

  let handled;
  if (state.mode === 'string') {
    handled = handleStringKey(e, ctx);
  } else if (state.mode === 'input') {
    handled = handleInputKey(e, ctx);
  } else {
    handled = handleNavKey(e, ctx);
  }

  if (handled) {
    e.preventDefault();
    e.stopPropagation();
    updateSelectionVisual(state);
    updateStatusBar(state, statusBar);
    // Show starter suggestions when freshly entering a hole
    // (but not when user just dismissed autocomplete with Escape)
    if (state.mode === 'input' && !state.inputBuffer && !state.acVisible && e.key !== 'Escape') {
      updateAutocomplete(state, ctx);
    }
  }
}

function commitOrCancelInput(state, itemNames, api, statusBar) {
  hideAutocomplete(state);
  if (state.mode === 'nav') return;
  if (state.inputBuffer && state.mode === 'input') {
    const newNode = commitToken(state, itemNames, api, statusBar);
    exitToNav(state, newNode.id);
  } else if (state.inputBuffer && state.mode === 'string') {
    const strNode = makeNode(state, 'string', { value: state.inputBuffer });
    pushUndo(state);
    replaceNode(state, state.inputHoleId, strNode);
    notifyChange(state);
    exitToNav(state, strNode.id);
  } else {
    // Empty buffer: remove hole
    const holeId = state.inputHoleId;
    if (holeId && state.nodeMap.has(holeId)) {
      state.selectedId = holeId;
      pushUndo(state);
      deleteSelected(state);
      notifyChange(state);
    }
    exitToNav(state, null);
  }
  rerender(state, itemNames, api, statusBar);
}

function handleClick(e, ctx) {
  const { state, statusBar, itemNames, api } = ctx;

  // Check for insert-between-siblings click (editable mode only)
  if (state.onChange) {
    const insertTarget = e.target.closest('[data-insert-after]');
    if (insertTarget) {
      if (state.mode !== 'nav') commitOrCancelInput(state, itemNames, api, statusBar);
      const afterId = parseInt(insertTarget.getAttribute('data-insert-after'), 10);
      if (state.nodeMap.has(afterId)) {
        const hole = makeNode(state, 'hole', {});
        applyMutation(state, itemNames, api, statusBar, () => insertAfter(state, afterId, hole));
        enterInputMode(state, hole.id);
        rerender(state, itemNames, api, statusBar);
        updateSelectionVisual(state);
        updateStatusBar(state, statusBar);
        return;
      }
    }
  }

  const target = e.target.closest('[data-node-id]');
  if (!target) return;
  const id = parseInt(target.getAttribute('data-node-id'), 10);
  if (!state.nodeMap.has(id)) return;

  // If in doc mode, exit it first (unless clicking inside the same doc node)
  if (state.mode === 'doc') {
    const docNode = state.nodeMap.get(state.selectedId);
    if (docNode && docNode.type === 'doc' && id === docNode.id) return; // click inside doc — let prose editor handle
    const docEl = state.domMap.get(state.selectedId);
    if (docEl && docEl._docRenderContent) {
      state.mode = 'nav';
      docEl._docRenderContent(false);
    }
  }

  // If in input/string mode and the user tapped the active hole, just focus
  // the native <input> — this is a user gesture so the mobile keyboard appears.
  if (state.mode !== 'nav' && id === state.inputHoleId) {
    const inp = state.domMap.get(id)?.querySelector?.('.hob-hole-input');
    if (inp) { inp.focus(); return; }
  }
  // Otherwise commit or cancel before handling click
  if (state.mode !== 'nav') commitOrCancelInput(state, itemNames, api, statusBar);

  // Now handle the click target (re-check in case node was removed)
  if (!state.nodeMap.has(id)) return;

  // Second click/tap on already-selected node → enter edit mode.
  // Handles mobile tap-to-edit (tap once to select, tap again to edit)
  // and desktop slow double-click. The dblclick event that follows a fast
  // double-click is handled by handleDoubleClick, which bails if mode != nav.
  if (state.selectedId === id && state.mode === 'nav' && state.onChange) {
    handleDoubleClick(e, ctx);
    return;
  }

  state.selectedId = id;
  state.selectionAnchorId = null;
  state.expansionStack = [];
  updateSelectionVisual(state);
  updateStatusBar(state, statusBar);
}

function handleDoubleClick(e, ctx) {
  const { state, statusBar, itemNames, api } = ctx;
  if (!state.onChange) return;

  // If already in edit mode (e.g. entered via handleClick on second tap/click),
  // do nothing — avoids double-entry when dblclick fires after click(2).
  if (state.mode !== 'nav') return;

  const target = e.target.closest('[data-node-id]');
  if (!target) return;
  const id = parseInt(target.getAttribute('data-node-id'), 10);
  const node = state.nodeMap.get(id);
  if (!node) return;

  e.preventDefault();

  if (node.type === 'doc') {
    // Doc node → enter prose editing
    state.selectedId = node.id;
    state.selectionAnchorId = null;
    state.expansionStack = [];
    updateSelectionVisual(state);
    enterDocEditing(state, node.id, itemNames, api, statusBar);
    return;
  } else if (node.type === 'hole') {
    // Hole not in input mode → enter input mode
    if (state.mode === 'nav') {
      enterInputMode(state, node.id);
      rerender(state, itemNames, api, statusBar);
      updateSelectionVisual(state);
      updateStatusBar(state, statusBar);
    }
  } else if (node.children) {
    if (isUnaryMinus(node)) {
      // Subtracted term in infix expression — navigate to the argument rather than appending a hole
      state.selectedId = node.children[1].id;
      state.selectionAnchorId = null;
      state.expansionStack = [];
      updateSelectionVisual(state);
      updateStatusBar(state, statusBar);
    } else {
      // Container → append child hole, enter input mode
      const hole = makeNode(state, 'hole', {});
      applyMutation(state, itemNames, api, statusBar, () => appendChild(state, node.id, hole));
      enterInputMode(state, hole.id);
      rerender(state, itemNames, api, statusBar);
      updateSelectionVisual(state);
      updateStatusBar(state, statusBar);
    }
  } else {
    // Leaf → replace mode
    const hole = makeNode(state, 'hole', {});
    state.replaceOriginal = { nodeSnapshot: JSON.parse(JSON.stringify(node)), parentId: state.parentMap.get(node.id)?.id };
    applyMutation(state, itemNames, api, statusBar, () => replaceNode(state, node.id, hole));
    if (node.type === 'string') {
      // Strings → enter string mode with raw value (no quotes)
      enterInputMode(state, hole.id);
      state.mode = 'string';
      state.inputBuffer = node.value;
      state.inputCursor = node.value.length;
    } else {
      const prefill = leafText(node);
      enterInputMode(state, hole.id);
      state.inputBuffer = prefill;
      state.inputCursor = prefill.length;
      state.inputSelectAll = true;
    }
    rerender(state, itemNames, api, statusBar);
    updateSelectionVisual(state);
    updateStatusBar(state, statusBar);
  }
}

// --- Status Bar Builder ---

function buildStatusBar() {
  const bar = document.createElement('div');
  bar.className = 'hob-status-bar';

  const breadcrumbs = document.createElement('span');
  breadcrumbs.className = 'hob-breadcrumbs';

  const nodeInfo = document.createElement('span');
  nodeInfo.className = 'hob-node-info';

  const mode = document.createElement('span');
  mode.className = 'hob-mode';
  mode.textContent = 'NAV';

  bar.appendChild(breadcrumbs);
  bar.appendChild(nodeInfo);
  bar.appendChild(mode);

  return bar;
}

