const HELP_SECTIONS = [
  { title: 'Navigate', rows: [
    ['← / →',       'Go to parent / first child'],
    ['↑ / ↓',       'Prev / next sibling'],
    ['Home / End',   'First / last sibling'],
    ['Ctrl+↑',       'Select top-level form'],
    ['Ctrl+← / →',  'Prev / next top-level'],
    ['Tab / ⇧Tab',  'Next / prev hole'],
    ['⇧↑ / ⇧↓',    'Expand / contract selection'],
    ['Escape',       'Select parent'],
  ]},
  { title: 'Edit', rows: [
    ['Enter',        'Insert hole after'],
    ['⇧Enter',       'Insert hole before'],
    ['Backspace',    'Delete node'],
    ['r',            'Replace node'],
    ['d',            'Duplicate'],
    [';',            'Insert comment (doc)'],
  ]},
  { title: 'Structure', rows: [
    ['w (',          'Wrap in list'],
    ['W',            'Wrap in vector'],
    ['u',            'Unwrap / splice'],
    ['Alt+← / →',   'Move left / right'],
    ['>',            'Slurp right'],
    ['<',            'Barf right'],
    ['t',            'Change container type'],
  ]},
  { title: 'Copy & History', rows: [
    ['Ctrl+C',       'Copy'],
    ['Ctrl+X',       'Cut'],
    ['Ctrl+V',       'Paste'],
    ['Ctrl+Z',       'Undo'],
    ['Ctrl+⇧Z',      'Redo'],
  ]},
  { title: 'In a Hole', rows: [
    ['Space',        'Commit + new sibling'],
    ['Enter',        'Commit'],
    ['Escape',       'Cancel'],
    ['"',            'String mode'],
    ['@',            'Item reference mode'],
    ['( [ {',        'Create container'],
    ['↑ / ↓',        'Autocomplete'],
    ['Tab',          'Accept autocomplete'],
  ]},
];

function buildHelpOverlay() {
  const overlay = document.createElement('div');
  overlay.className = 'hob-help-overlay';

  const panel = document.createElement('div');
  panel.className = 'hob-help-panel';

  const header = document.createElement('div');
  header.className = 'hob-help-header';
  header.textContent = 'Keyboard Shortcuts';
  panel.appendChild(header);

  const grid = document.createElement('div');
  grid.className = 'hob-help-grid';

  for (const section of HELP_SECTIONS) {
    const sec = document.createElement('div');
    sec.className = 'hob-help-section';

    const title = document.createElement('div');
    title.className = 'hob-help-section-title';
    title.textContent = section.title;
    sec.appendChild(title);

    for (const [key, desc] of section.rows) {
      const keyEl = document.createElement('span');
      keyEl.className = 'hob-help-key';
      keyEl.textContent = key;
      const descEl = document.createElement('span');
      descEl.className = 'hob-help-desc';
      descEl.textContent = desc;
      sec.appendChild(keyEl);
      sec.appendChild(descEl);
    }
    grid.appendChild(sec);
  }
  panel.appendChild(grid);

  const footer = document.createElement('div');
  footer.className = 'hob-help-footer';
  footer.textContent = 'Ctrl+/ or Escape to close';
  panel.appendChild(footer);

  overlay.appendChild(panel);
  return overlay;
}

function showHelp(state, wrapper) {
  if (state.helpVisible) return;
  const overlay = buildHelpOverlay();
  overlay.addEventListener('click', (e) => { if (e.target === overlay) hideHelp(state); });
  wrapper.appendChild(overlay);
  state.helpEl = overlay;
  state.helpVisible = true;
}

function hideHelp(state) {
  if (!state.helpVisible) return;
  state.helpEl?.remove();
  state.helpEl = null;
  state.helpVisible = false;
}

// --- Main render entry point ---

export async function render(value, options, api) {
  // Load item search lib for autocomplete
  let itemSearchLib = null;
  try { itemSearchLib = await api.require('item-search-lib'); } catch {}

  // Handle empty/missing value
  if (!value || !Array.isArray(value) || value.length === 0) {
    if (!options.onChange) {
      const empty = api.createElement('div');
      empty.className = 'hob-empty';
      empty.textContent = 'No Hob code';
      empty.style.cssText = 'border: 1px solid var(--color-border); border-radius: var(--border-radius); padding: 24px; text-align: center; color: var(--color-text-tertiary); font-style: italic;';
      return empty;
    }
    value = [null]; // bootstrap with nil so the user can start editing
  }

  // Inflate AST
  const { root, nodeMap, parentMap } = inflateAll(value);

  // On touch devices pre-select the first string (or hole) leaf so one tap enters edit mode.
  // On desktop keep the top-level form selected (nav with keyboard is the norm there).
  const _isTouch = window.matchMedia?.('(pointer: coarse)').matches || ('ontouchstart' in window);
  let _initialSelectedId = root.children[0]?.id || null;
  if (_isTouch) {
    for (const n of nodeMap.values()) {
      if (n.type === 'string') { _initialSelectedId = n.id; break; }
    }
    if (_initialSelectedId === (root.children[0]?.id || null)) {
      for (const n of nodeMap.values()) {
        if (n.type === 'hole') { _initialSelectedId = n.id; break; }
      }
    }
  }

  // Build state
  const state = {
    selectedId: _initialSelectedId,
    selectionAnchorId: null,
    expansionStack: [],
    nodeMap,
    parentMap,
    domMap: new Map(),
    editorEl: null,
    onChange: options.onChange || null,
    onSubmit: options.onSubmit || null,
    compact: options.compact || false,
    mode: 'nav',
    inputBuffer: '',
    inputCursor: 0,
    inputHoleId: null,
    inputSelectAll: false,
    replaceOriginal: null,
    undoStack: [],
    redoStack: [],
    collapsedIds: new Set(),
    acVisible: false,
    acItems: [],
    acIndex: 0,
    acMode: null,
    acEl: null,
    _acTimer: null,
    _acGeneration: 0,
    _itemSearchLib: itemSearchLib,
    _ctx: null,
    helpVisible: false,
    helpEl: null
  };

  // Resolve item references (async, batch) — skip @self (reserved, not a real item)
  const itemRefs = [...nodeMap.values()].filter(n => n.type === 'item-ref' && n.value !== 'self');
  const itemNames = new Map();
  await Promise.all(itemRefs.map(async (ref) => {
    try {
      const it = await api.get(ref.value);
      itemNames.set(ref.value, it.name || ref.value.slice(0, 8));
    } catch {
      itemNames.set(ref.value, ref.value.slice(0, 8));
    }
  }));

  // Render AST to DOM
  const editorEl = renderAST(root, state, itemNames, api);
  state.editorEl = editorEl;
  if (state.onChange) editorEl.classList.add('hob-editable');

  // Status bar
  const statusBar = buildStatusBar();

  // Wrapper
  const wrapper = api.createElement('div');
  wrapper.style.cssText = options.compact
    ? 'display: flex; flex-direction: column; border: 1px solid var(--color-border); border-radius: var(--border-radius); position: relative;'
    : 'display: flex; flex-direction: column; border: 1px solid var(--color-border); border-radius: var(--border-radius); min-height: 200px; position: relative;';
  wrapper.appendChild(editorEl);
  if (!options.compact) wrapper.appendChild(statusBar);

  // Event context (shared by key and click handlers)
  const ctx = { state, statusBar, itemNames, api, wrapper };
  state._ctx = ctx;

  // Key handler
  editorEl.addEventListener('keydown', (e) => handleKey(e, ctx));

  // Paste handler for input/string modes
  editorEl.addEventListener('paste', (e) => {
    if ((state.mode === 'input' || state.mode === 'string') && state.onChange) {
      e.preventDefault();
      const text = e.clipboardData?.getData('text') || '';
      if (!text) return;
      if (state.inputSelectAll) {
        state.inputBuffer = text;
        state.inputCursor = text.length;
        state.inputSelectAll = false;
      } else {
        state.inputBuffer = state.inputBuffer.slice(0, state.inputCursor) + text + state.inputBuffer.slice(state.inputCursor);
        state.inputCursor += text.length;
      }
      updateHoleDisplay(state);
      if (state.mode === 'string') updateStringAutocomplete(state, ctx);
      else updateAutocomplete(state, ctx);
    } else if (state.mode === 'nav' && state.onChange && _clipboard === null) {
      // Fallback: parse s-expression text from system clipboard
      e.preventDefault();
      const text = e.clipboardData?.getData('text')?.trim();
      if (!text) return;
      const compact = parseSexp(text);
      if (compact === undefined) return;
      const node = state.nodeMap.get(state.selectedId);
      if (!node) return;
      const pasted = inflateSubtree(compact, state);
      applyMutation(state, itemNames, api, statusBar, () => {
        insertAfter(state, node.id, pasted);
        state.selectedId = pasted.id;
      });
    }
  });

  // Click and double-click handlers
  editorEl.addEventListener('click', (e) => handleClick(e, ctx));
  editorEl.addEventListener('dblclick', (e) => handleDoubleClick(e, ctx));

  // Navigate to symbol if requested — search defn/def/let bindings recursively
  if (options.scrollToSymbol) {
    const targetName = options.scrollToSymbol;
    const foundId = findSymbolNode(root, targetName);
    if (foundId !== null) state.selectedId = foundId;
  }

  // Initial selection
  updateSelectionVisual(state);
  updateStatusBar(state, statusBar);

  // Auto-focus: enter edit mode on first empty string or hole.
  // On touch devices, only select the node — the keyboard can only be shown
  // from a direct user gesture, so we wait for the user to tap it (which will
  // enter string mode via handleDoubleClick and focus within the gesture).
  if (options.autoFocus && state.onChange) {
    const isTouch = window.matchMedia?.('(pointer: coarse)').matches || ('ontouchstart' in window);
    let autoFocusNode = null;
    if (isTouch) {
      // On touch: any string (including non-empty from saved AST) or first hole
      for (const n of state.nodeMap.values()) {
        if (n.type === 'string') { autoFocusNode = n; break; }
        if (n.type === 'hole' && !autoFocusNode) autoFocusNode = n;
      }
    } else {
      // On desktop: only enter edit mode for empty strings or holes
      for (const n of state.nodeMap.values()) {
        if (n.type === 'string' && n.value === '') { autoFocusNode = n; break; }
        if (n.type === 'hole' && !autoFocusNode) autoFocusNode = n;
      }
    }
    if (autoFocusNode) {
      if (isTouch) {
        // Select the node so one tap enters edit mode (tap-to-edit-on-selected)
        state.selectedId = autoFocusNode.id;
        updateSelectionVisual(state);
        updateStatusBar(state, statusBar);
      } else {
        if (autoFocusNode.type === 'string') {
          const hole = makeNode(state, 'hole', {});
          state.replaceOriginal = { nodeSnapshot: JSON.parse(JSON.stringify(autoFocusNode)), parentId: state.parentMap.get(autoFocusNode.id)?.id };
          replaceNode(state, autoFocusNode.id, hole);
          enterInputMode(state, hole.id);
          state.mode = 'string';
          state.inputBuffer = autoFocusNode.value;
          state.inputCursor = autoFocusNode.value.length;
        } else {
          enterInputMode(state, autoFocusNode.id);
        }
        rerender(state, itemNames, api, statusBar);
        let _focusAttempts = 0;
        const tryFocus = () => {
          if (editorEl.isConnected) {
            const inp = editorEl.querySelector('.hob-hole-input');
            (inp || editorEl).focus();
          } else if (++_focusAttempts < 10) { requestAnimationFrame(tryFocus); }
        };
        requestAnimationFrame(tryFocus);
      }
    }
  }

  // Deferred scroll — element may not be in the DOM yet when render() returns.
  // When opened as a new canvas sibling, the window/scroll container may take
  // multiple frames to mount, so retry until the element is actually in the document.
  if (options.scrollToSymbol && state.selectedId != null) {
    const scrollTarget = state.domMap.get(state.selectedId);
    if (scrollTarget) {
      let attempts = 0;
      const tryScroll = () => {
        if (scrollTarget.isConnected) {
          scrollTarget.scrollIntoView({ block: 'center', inline: 'nearest' });
        } else if (++attempts < 10) {
          requestAnimationFrame(tryScroll);
        }
      };
      requestAnimationFrame(tryScroll);
    }
  }

  // Build system symbol index once per session, subscribe to updates
  if (!_symbolIndex.subscribed) {
    _symbolIndex.subscribed = true;
    _buildSymbolIndex(api);
    try {
      api.events.on('item:updated', (ev) => {
        const item = ev?.detail ?? ev;
        if (item?.id && item?.content) _patchSymbolIndex(item);
      });
    } catch {}
  }

  // Cleanup
  wrapper.setAttribute('data-hobson-cleanup', '');
  wrapper.__hobsonCleanup = () => { hideAutocomplete(state); hideHelp(state); };

  // Public submit: commit any in-progress edit then call onSubmit — mirrors Ctrl+Enter
  wrapper.hobSubmit = () => {
    if (state.mode === 'string') {
      const strNode = makeNode(state, 'string', { value: state.inputBuffer });
      pushUndo(state);
      replaceNode(state, state.inputHoleId, strNode);
      notifyChange(state);
      exitToNav(state, strNode.id);
      rerender(state, itemNames, api, statusBar);
    } else if (state.mode === 'input') {
      if (state.inputBuffer) {
        commitToken(state, itemNames, api, statusBar);
      } else {
        state.selectedId = state.inputHoleId;
        pushUndo(state);
        deleteSelected(state);
        notifyChange(state);
      }
      exitToNav(state, state.selectedId);
      rerender(state, itemNames, api, statusBar);
    }
    const root = state.nodeMap.get(0);
    if (root && state.onSubmit) state.onSubmit(deflateAll(root));
  };

  return wrapper;
}

// history-service — background service for time-series value recording.
// On boot, registers a listener for each unique trigger event found across all
// history items. On trigger, reads configured fields from each item's target
// and appends timestamped values to content.history (series-keyed by label).

const HISTORY_TYPE_ID = '3147ac83-79eb-4df6-a6bc-0a3847a8e1d8';

let _hob = null;
let _interp = null;
const _listeners = new Map(); // eventId -> listener fn

export async function onKernelBootComplete({ safeMode }, api) {
  if (safeMode) return;
  _hob = await api.require('hob-interpreter');
  _interp = _hob.createInterpreter(api);
  await _interp.macrosReady;
  await registerAllHistoryItems(api);
}

export async function onItemCreated({ item }, api) {
  if (!_interp || !item || item.type !== HISTORY_TYPE_ID) return;
  await registerAllHistoryItems(api);
}

export async function onItemUpdated({ item, previous }, api) {
  if (!_interp || !item || item.type !== HISTORY_TYPE_ID) return;
  // Only re-register if config changed — history data writes must not cause re-registration
  const configChanged =
    item.content?.trigger !== previous?.content?.trigger ||
    item.content?.target !== previous?.content?.target ||
    JSON.stringify(item.content?.fields) !== JSON.stringify(previous?.content?.fields);
  if (configChanged) await registerAllHistoryItems(api);
}

async function registerAllHistoryItems(api) {
  for (const [eventId, fn] of _listeners) {
    api.events.off(eventId, fn);
  }
  _listeners.clear();

  const historyItems = await api.query({ type: HISTORY_TYPE_ID });
  const triggerIds = new Set(historyItems.map(i => i.content?.trigger).filter(Boolean));

  for (const eventId of triggerIds) {
    const fn = async (event) => {
      const current = await api.query({ type: HISTORY_TYPE_ID });
      for (const item of current) {
        if (item.content?.trigger === eventId) {
          await recordSnapshot(item, event, api);
        }
      }
    };
    api.events.on(eventId, fn);
    _listeners.set(eventId, fn);
  }
}

async function recordSnapshot(historyItem, event, api) {
  const targetId = historyItem.content?.target;
  const fields = historyItem.content?.fields;
  if (!targetId || !fields?.length) return;

  const timestamp = event.content?.timestamp ?? Date.now();
  const history = JSON.parse(JSON.stringify(historyItem.content.history || {}));

  for (const { field, label } of fields) {
    if (!field || !label) continue;
    try {
      const value = await _interp.eval(`(get-field "${targetId}" ${field})`);
      if (value == null || value?._hobType === 'computed-field-error') continue;
      if (!history[label]) history[label] = [];
      const idx = history[label].findIndex(e => e.t === timestamp);
      if (idx >= 0) {
        history[label][idx] = { t: timestamp, v: value };
      } else {
        history[label].push({ t: timestamp, v: value });
      }
    } catch (e) {
      console.warn(`history-service: failed to read ${field} from ${targetId}:`, e);
    }
  }

  await api.set({ ...historyItem, content: { ...historyItem.content, history } });
}

