// Script code field view (readonly with run/copy buttons)
export async function render(value, options, api) {
  const { label, language = 'javascript' } = options;
  const code = value || '';

  const wrapper = api.createElement('div', { className: 'field-script-code' });
  wrapper.style.cssText = 'display: flex; flex-direction: column; gap: 12px;';

  if (label) {
    const labelEl = api.createElement('label');
    labelEl.textContent = label;
    labelEl.style.cssText = 'font-weight: 500; font-size: 0.875rem; color: var(--color-text);';
    wrapper.appendChild(labelEl);
  }

  // Load CodeMirror
  await api.require('codemirror');
  await api.require('codemirror-javascript');
  const CodeMirror = window.CodeMirror;

  // Editor container
  const editorContainer = api.createElement('div');
  editorContainer.style.cssText = 'border: 1px solid var(--color-border); border-radius: var(--border-radius); overflow: hidden;';
  wrapper.appendChild(editorContainer);

  // Create CodeMirror instance in readonly mode
  const cm = CodeMirror(editorContainer, {
    value: code,
    mode: language,
    lineNumbers: true,
    lineWrapping: true,
    theme: 'default',
    readOnly: true,
    cursorBlinkRate: -1,
    viewportMargin: 2000
  });

  cm.setSize('100%', '300px');

  // Refresh after layout
  requestAnimationFrame(() => cm.refresh());

  // Action buttons
  const buttons = api.createElement('div');
  buttons.style.cssText = 'display: flex; gap: 10px;';

  // Run Script button
  const runBtn = api.createElement('button');
  runBtn.textContent = 'Run Script';
  runBtn.style.cssText = 'padding: 10px 20px; cursor: pointer; background: var(--color-primary); color: white; border: none; border-radius: var(--border-radius); font-weight: 500;';
  runBtn.onclick = async () => {
    runBtn.disabled = true;
    runBtn.textContent = 'Running...';

    try {
      // Get the REPL API which has the helper functions
      const replApi = api.createREPLContext();

      // Execute the script code with REPL API
      const asyncFn = new Function('api', `
        return (async () => {
          ${code}
        })();
      `);

      const result = await asyncFn(replApi);
      alert('Script executed!\n\nResult: ' + (
        result !== undefined
          ? JSON.stringify(result, null, 2)
          : 'No return value'
      ));
    } catch (error) {
      alert('Error executing script:\n\n' + error.message);
    } finally {
      runBtn.disabled = false;
      runBtn.textContent = 'Run Script';
    }
  };
  buttons.appendChild(runBtn);

  // Copy Code button
  const copyBtn = api.createElement('button');
  copyBtn.textContent = 'Copy Code';
  copyBtn.style.cssText = 'padding: 10px 20px; cursor: pointer; border: 1px solid var(--color-border); border-radius: var(--border-radius); background: var(--color-bg-surface);';
  copyBtn.onclick = () => {
    navigator.clipboard.writeText(code);
    copyBtn.textContent = 'Copied!';
    setTimeout(() => { copyBtn.textContent = 'Copy Code'; }, 1000);
  };
  buttons.appendChild(copyBtn);

  wrapper.appendChild(buttons);

  return wrapper;
}

export function render(value, options, api) {
  const { mode, onChange, label, options: choices = [] } = options;
  const wrapper = api.createElement('div', { className: 'field-dropdown' });
  wrapper.style.cssText = 'display: flex; flex-direction: column; gap: 4px;';

  if (label) {
    const labelEl = api.createElement('label');
    labelEl.textContent = label;
    labelEl.style.cssText = 'font-weight: 500; font-size: 0.875rem; color: var(--color-text);';
    wrapper.appendChild(labelEl);
  }

  const normalized = choices.map(opt =>
    typeof opt === 'string' ? { value: opt, label: opt } : opt
  );

  if (mode === 'editable' && onChange) {
    const select = api.createElement('select');
    select.style.cssText = 'padding: 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); font-size: 0.875rem; background: var(--color-bg-body); color: var(--color-text); cursor: pointer;';

    if (!value) {
      const blank = api.createElement('option');
      blank.value = '';
      blank.textContent = '(none)';
      select.appendChild(blank);
    }

    for (const opt of normalized) {
      const optEl = api.createElement('option');
      optEl.value = opt.value;
      optEl.textContent = opt.label;
      if (opt.value === value) optEl.selected = true;
      select.appendChild(optEl);
    }

    select.onchange = (e) => onChange(e.target.value);
    wrapper.appendChild(select);
  } else {
    const match = normalized.find(o => o.value === value);
    let displayText, extraStyle;
    if (match) {
      displayText = match.label;
      extraStyle = '';
    } else if (value) {
      displayText = value + ' (?)';
      extraStyle = ' color: var(--color-text-secondary);';
    } else {
      displayText = '(none)';
      extraStyle = ' color: var(--color-text-tertiary); font-style: italic;';
    }
    const span = api.createElement('span');
    span.textContent = displayText;
    span.style.cssText = 'padding: 8px; background: var(--color-bg-surface-alt); border-radius: var(--border-radius); font-size: 0.875rem;' + extraStyle;
    wrapper.appendChild(span);
  }

  return wrapper;
}

const DEFAULT_TIMEOUT = 5000;

export function createSuite(name) {
  const results = [];

  function test(testName, fn) {
    const fullName = name ? `${name} > ${testName}` : testName;
    const symbol = fn.name || null;
    try {
      fn();
      results.push({ name: fullName, passed: true, symbol });
    } catch (e) {
      results.push({ name: fullName, passed: false, error: e.message, symbol });
    }
  }

  async function testAsync(testName, fn, timeout = DEFAULT_TIMEOUT) {
    const fullName = name ? `${name} > ${testName}` : testName;
    const symbol = fn.name || null;
    try {
      await Promise.race([
        fn(),
        new Promise((_, reject) =>
          setTimeout(() => reject(new Error(`Timed out after ${timeout}ms`)), timeout)
        )
      ]);
      results.push({ name: fullName, passed: true, symbol });
    } catch (e) {
      results.push({ name: fullName, passed: false, error: e.message, symbol });
    }
  }

  function getResults() {
    return [...results];
  }

  return { test, testAsync, getResults };
}

export function assert(condition, message) {
  if (!condition) throw new Error(message || 'Assertion failed');
}

export function assertEquals(actual, expected, message) {
  if (actual !== expected) {
    throw new Error(message || `Expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

export function assertDeepEquals(actual, expected, message) {
  if (!deepEqual(actual, expected)) {
    throw new Error(message || `Expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function deepEqual(a, b) {
  if (a === b) return true;
  if (a == null || b == null) return false;
  if (typeof a !== typeof b) return false;
  if (typeof a !== 'object') return false;

  const isArrayA = Array.isArray(a), isArrayB = Array.isArray(b);
  if (isArrayA !== isArrayB) return false;
  if (isArrayA) {
    if (a.length !== b.length) return false;
    return a.every((v, i) => deepEqual(v, b[i]));
  }

  const keysA = Object.keys(a), keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  return keysA.every(k => Object.hasOwn(b, k) && deepEqual(a[k], b[k]));
}

/** Poll for a condition. Useful for waiting on rendering. */
export async function waitFor(fn, { timeout = 2000, interval = 50 } = {}) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    const result = fn();
    if (result) return result;
    await new Promise(r => setTimeout(r, interval));
  }
  throw new Error(`waitFor timed out after ${timeout}ms`);
}

const TEST_TAG_ID = 'c0c0c0c0-0070-0000-0000-000000000000';
const INSTANCE_BOOT_TIMEOUT = 30000;
const TEST_RUN_TIMEOUT = 120000;

export async function render(item, api) {
  const instanceLib = await api.require('hobson-instance-lib');

  const container = api.createElement('div');
  container.style.cssText = 'display:flex; flex-direction:column; height:100%; font-family:var(--font-sans, system-ui, sans-serif); font-size: 0.875rem;';

  // Header
  const header = api.createElement('div');
  header.style.cssText = 'display:flex; align-items:center; justify-content:space-between; padding:12px 16px; border-bottom:1px solid var(--border-color, #e5e7eb);';

  const title = api.createElement('h2');
  title.textContent = 'Test Suite';
  title.style.cssText = 'margin:0; font-size: 1.125rem; font-weight:600;';
  header.appendChild(title);

  const runAllBtn = api.createElement('button');
  runAllBtn.textContent = 'Run All';
  runAllBtn.style.cssText = 'padding:6px 16px; background:#22c55e; color:#fff; border:none; border-radius:6px; cursor:pointer; font-size: 0.875rem; font-weight:500;';
  runAllBtn.onmouseenter = () => runAllBtn.style.background = '#16a34a';
  runAllBtn.onmouseleave = () => runAllBtn.style.background = '#22c55e';
  header.appendChild(runAllBtn);
  container.appendChild(header);

  // Summary bar
  const summaryBar = api.createElement('div');
  summaryBar.style.cssText = 'padding:8px 16px; font-size: 0.8125rem; color:var(--text-secondary, #6b7280); border-bottom:1px solid var(--border-color, #e5e7eb);';
  summaryBar.textContent = 'Discovering tests...';
  container.appendChild(summaryBar);

  // Results area
  const resultsArea = api.createElement('div');
  resultsArea.style.cssText = 'flex:1; overflow-y:auto; padding:8px 0;';
  container.appendChild(resultsArea);

  // Discover test items (in parent, for building the UI rows)
  const allItems = await api.getAll();
  const testItems = allItems.filter(i =>
    i.content?.tags?.includes(TEST_TAG_ID) && i.name && i.content?.code
  );
  summaryBar.textContent = `${testItems.length} test${testItems.length === 1 ? '' : 's'} found`;

  // Build test item rows
  const rows = [];
  for (const testItem of testItems) {
    const row = createTestRow(testItem, api);
    rows.push(row);
    resultsArea.appendChild(row.el);
  }

  // Helper to update summary bar from totals
  function updateSummary(totalPassed, totalFailed, timestamp) {
    const total = totalPassed + totalFailed;
    const ago = timestamp ? ' \u00b7 ' + formatTimeAgo(timestamp) : '';
    if (totalFailed === 0) {
      summaryBar.textContent = `All ${total} passed${ago}`;
      summaryBar.style.color = '#22c55e';
    } else {
      summaryBar.textContent = `${totalPassed}/${total} passed, ${totalFailed} failed${ago}`;
      summaryBar.style.color = '#ef4444';
    }
  }

  // Restore last run results if available
  const lastRun = item.content?.lastRun;
  if (lastRun && lastRun.suites) {
    const byId = new Map(lastRun.suites.map(s => [s.testItemId, s]));
    for (const row of rows) {
      const saved = byId.get(row.testItem.id);
      if (saved) {
        row.setResults(saved.results, saved.passed, saved.failed);
      }
    }
    updateSummary(lastRun.totalPassed, lastRun.totalFailed, lastRun.timestamp);
  }

  // Run all handler — creates a nested instance, runs tests there
  let instance = null;
  runAllBtn.addEventListener('click', async () => {
    runAllBtn.disabled = true;
    runAllBtn.style.opacity = '0.6';
    runAllBtn.style.cursor = 'default';

    for (const row of rows) row.reset();
    summaryBar.style.color = 'var(--text-secondary, #6b7280)';

    try {
      summaryBar.textContent = 'Booting test instance...';
      instance = await instanceLib.create(api, { name: 'Test Run' });

      await instance.waitForMessage('test-instance-ready', INSTANCE_BOOT_TIMEOUT);
      summaryBar.textContent = 'Running tests...';
      for (const row of rows) row.setStatus('running');

      const suiteMap = new Map(rows.map(r => [r.testItem.id, r]));

      const removeProgress = instance.onMessage('test-progress', msg => {
        const row = suiteMap.get(msg.suite?.testItemId);
        if (row) {
          row.setResults(msg.suite.results, msg.suite.passed, msg.suite.failed);
        }
      });

      const resultLastRun = await new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          removeComplete();
          removeError();
          reject(new Error('Test run timed out'));
        }, TEST_RUN_TIMEOUT);

        const removeComplete = instance.onMessage('test-complete', msg => {
          clearTimeout(timer);
          removeComplete();
          removeError();
          resolve(msg.lastRun);
        });

        const removeError = instance.onMessage('test-error', msg => {
          clearTimeout(timer);
          removeComplete();
          removeError();
          reject(new Error(msg.error));
        });
      });

      removeProgress();

      // Update summary and persist
      updateSummary(resultLastRun.totalPassed, resultLastRun.totalFailed, resultLastRun.timestamp);
      const updated = await api.get(item.id);
      updated.content = updated.content || {};
      updated.content.lastRun = resultLastRun;
      await api.set(updated, { silent: true });

    } catch (err) {
      summaryBar.textContent = `Error: ${err.message}`;
      summaryBar.style.color = '#ef4444';
    }

    // Show clean up button (instance stays alive for inspection)
    runAllBtn.style.display = 'none';
    const cleanupBtn = api.createElement('button');
    cleanupBtn.textContent = 'Clean Up Instance';
    cleanupBtn.style.cssText = 'padding:6px 16px; background:#6b7280; color:#fff; border:none; border-radius:6px; cursor:pointer; font-size: 0.875rem; font-weight:500;';
    cleanupBtn.onmouseenter = () => cleanupBtn.style.background = '#4b5563';
    cleanupBtn.onmouseleave = () => cleanupBtn.style.background = '#6b7280';
    cleanupBtn.addEventListener('click', async () => {
      cleanupBtn.disabled = true;
      cleanupBtn.textContent = 'Cleaning up...';
      try { if (instance) await instance.destroy(); } catch {}
      instance = null;
      cleanupBtn.remove();
      runAllBtn.style.display = '';
      runAllBtn.disabled = false;
      runAllBtn.style.opacity = '1';
      runAllBtn.style.cursor = 'pointer';
    });
    header.appendChild(cleanupBtn);
  });

  return container;
}

function createTestRow(testItem, api) {
  const el = api.createElement('div');
  el.style.cssText = 'padding:6px 16px;';

  const headerRow = api.createElement('div');
  headerRow.style.cssText = 'display:flex; align-items:center; gap:8px; cursor:default;';

  const indicator = api.createElement('span');
  indicator.style.cssText = 'width:20px; text-align:center; flex-shrink:0;';
  indicator.textContent = '\u25CB'; // circle
  indicator.style.color = '#9ca3af';

  const nameSpan = api.createElement('span');
  nameSpan.textContent = testItem.name || testItem.id;
  nameSpan.style.cssText = 'font-weight:500;';

  const countSpan = api.createElement('span');
  countSpan.style.cssText = 'margin-left:auto; font-size: 0.75rem; color:var(--text-secondary, #6b7280);';

  headerRow.appendChild(indicator);
  headerRow.appendChild(nameSpan);
  headerRow.appendChild(countSpan);
  el.appendChild(headerRow);

  const detailsContainer = api.createElement('div');
  detailsContainer.style.cssText = 'margin-left:28px; margin-top:4px;';
  el.appendChild(detailsContainer);

  return {
    el,
    testItem,
    reset() {
      indicator.textContent = '\u25CB';
      indicator.style.color = '#9ca3af';
      countSpan.textContent = '';
      detailsContainer.innerHTML = '';
    },
    setStatus(status) {
      if (status === 'running') {
        indicator.textContent = '\u25CF';
        indicator.style.color = '#f59e0b';
        countSpan.textContent = 'running...';
        countSpan.style.color = '#f59e0b';
      }
    },
    setResults(results, passed, failed) {
      const total = passed + failed;
      if (failed === 0) {
        indicator.textContent = '\u2713';
        indicator.style.color = '#22c55e';
        countSpan.textContent = `${passed}/${total} passed`;
        countSpan.style.color = '#22c55e';
      } else {
        indicator.textContent = '\u2717';
        indicator.style.color = '#ef4444';
        countSpan.textContent = `${passed}/${total} passed`;
        countSpan.style.color = '#ef4444';
      }

      // Show every individual test result
      detailsContainer.innerHTML = '';

      // Auto-expand if there are failures, collapse if all passed
      let expanded = failed > 0;

      const toggle = api.createElement('div');
      toggle.style.cssText = 'font-size: 0.6875rem; color:var(--text-secondary, #6b7280); cursor:pointer; user-select:none; padding:2px 0;';
      const updateToggle = () => {
        toggle.textContent = expanded ? '\u25BE hide details' : '\u25B8 show details';
      };
      updateToggle();
      toggle.addEventListener('click', () => {
        expanded = !expanded;
        updateToggle();
        listEl.style.display = expanded ? 'block' : 'none';
      });
      detailsContainer.appendChild(toggle);

      const listEl = api.createElement('div');
      listEl.style.display = expanded ? 'block' : 'none';

      for (const r of results) {
        const line = api.createElement('div');
        line.style.cssText = 'padding:2px 0; font-size: 0.75rem;';

        const icon = r.passed ? '\u2713 ' : '\u2717 ';
        const color = r.passed ? '#22c55e' : '#ef4444';

        const nameEl = api.createElement('a');
        nameEl.style.cssText = `color:${color}; cursor:pointer; text-decoration:none; border-bottom:1px solid transparent;`;
        nameEl.onmouseenter = () => nameEl.style.borderBottomColor = color;
        nameEl.onmouseleave = () => nameEl.style.borderBottomColor = 'transparent';
        nameEl.textContent = icon + r.name;
        nameEl.title = r.symbol ? `${testItem.name} \u2192 ${r.symbol}` : testItem.name;

        nameEl.onclick = (e) => {
          e.preventDefault();
          const params = { field: 'code' };
          if (r.symbol) params.symbol = r.symbol;
          api.openItem(e, { id: testItem.id, view: { navigateTo: params } });
        };

        line.appendChild(nameEl);

        if (!r.passed && r.error) {
          const errMsg = api.createElement('div');
          errMsg.style.cssText = 'color:#9ca3af; padding-left:16px; font-family:var(--font-mono, monospace); font-size: 0.6875rem; white-space:pre-wrap; word-break:break-all;';
          errMsg.textContent = r.error;
          line.appendChild(errMsg);
        }

        listEl.appendChild(line);
      }

      detailsContainer.appendChild(listEl);
    }
  };
}

function formatTimeAgo(timestamp) {
  const seconds = Math.floor((Date.now() - timestamp) / 1000);
  if (seconds < 60) return 'just now';
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

const NOTE_TYPE = '871ae771-b9b1-4f40-8c7f-d9038bfb69c3';

export async function run(api) {
  const { createSuite, assert, assertEquals } = await api.require('test-lib');
  const { testAsync, getResults } = createSuite('Storage');
  const created = [];

  async function createsAnItem() {
    const id = crypto.randomUUID();
    const item = await api.set({
      id,
      type: NOTE_TYPE,
      content: { description: 'Test note for storage-tests' }
    });
    created.push(id);
    assert(item, 'set() should return the item');
    assertEquals(item.id, id, 'Returned item should have correct id');
    assert(item.created, 'Returned item should have created timestamp');
    assert(item.modified, 'Returned item should have modified timestamp');
  }

  async function retrievesAnItem() {
    const id = created[0];
    assert(id, 'Need a previously created item');
    const item = await api.get(id);
    assert(item, 'get() should return the item');
    assertEquals(item.id, id);
    assertEquals(item.type, NOTE_TYPE);
    assertEquals(item.content.description, 'Test note for storage-tests');
  }

  async function updatesAnItem() {
    const id = created[0];
    const before = await api.get(id);
    await new Promise(r => setTimeout(r, 10));
    const updated = await api.set({
      ...before,
      content: { ...before.content, description: 'Updated description' }
    });
    assert(updated.modified >= before.modified, 'modified should be >= original');
    assertEquals(updated.content.description, 'Updated description');
  }

  async function queriesByType() {
    const results = await api.query({ type: NOTE_TYPE });
    assert(Array.isArray(results), 'query() should return an array');
    const found = results.find(i => i.id === created[0]);
    assert(found, 'Query results should include the created item');
  }

  async function overwritesAnItem() {
    const id = created[0];
    const replaced = await api.set({
      id,
      type: NOTE_TYPE,
      content: { description: 'Completely replaced' }
    });
    assertEquals(replaced.id, id, 'Should keep the same id');
    assertEquals(replaced.content.description, 'Completely replaced');
  }

  await testAsync('creates an item via set()', createsAnItem);
  await testAsync('retrieves an item via get()', retrievesAnItem);
  await testAsync('updates an item', updatesAnItem);
  await testAsync('queries items by type', queriesByType);
  await testAsync('overwrites an item via set()', overwritesAnItem);

