export async function run(api) {
  const { createSuite, assert, assertEquals } = await api.require('test-lib');
  const { testAsync, getResults } = createSuite('Module System');

  async function requiresByName() {
    const mod = await api.require('test-lib');
    assert(mod, 'require should return a module');
    assert(typeof mod.createSuite === 'function', 'Module should export createSuite');
    assert(typeof mod.assert === 'function', 'Module should export assert');
    assert(typeof mod.waitFor === 'function', 'Module should export waitFor');
  }

  async function requiresById() {
    const mod = await api.require('7e570001-0000-4000-8000-000000000000');
    assert(mod, 'require by ID should return a module');
    assert(typeof mod.createSuite === 'function', 'Module should export createSuite');
  }

  async function returnsCachedModule() {
    const mod1 = await api.require('test-lib');
    const mod2 = await api.require('test-lib');
    assert(mod1 === mod2, 'Repeated require should return cached module');
  }

  async function throwsOnMissing() {
    let threw = false;
    try {
      await api.require('definitely-does-not-exist-' + Date.now());
    } catch (e) {
      threw = true;
      assert(e.message.includes('not found'), 'Error should mention "not found"');
    }
    assert(threw, 'require of non-existent module should throw');
  }

  async function libraryExtendsCode() {
    const result = await api.typeChainIncludes(LIBRARY_TYPE, CODE_TYPE);
    assert(result, 'Library type chain should include code type');
  }

  async function codeExtendsItem() {
    const result = await api.typeChainIncludes(CODE_TYPE, ITEM_TYPE);
    assert(result, 'Code type chain should include item type');
  }

  async function noteDoesNotExtendCode() {
    const result = await api.typeChainIncludes(NOTE_TYPE, CODE_TYPE);
    assert(!result, 'Note type chain should not include code type');
  }

  await testAsync('requires a library by name', requiresByName);
  await testAsync('requires a library by ID', requiresById);
  await testAsync('returns same module on repeated require', returnsCachedModule);
  await testAsync('throws on non-existent module', throwsOnMissing);
  await testAsync('typeChainIncludes: library extends code', libraryExtendsCode);
  await testAsync('typeChainIncludes: code extends item', codeExtendsItem);
  await testAsync('typeChainIncludes: note does not extend code', noteDoesNotExtendCode);

  return getResults();
}

const NOTE_TYPE = '871ae771-b9b1-4f40-8c7f-d9038bfb69c3';
const STARRED_TAG = 'c0c0c0c0-0060-0000-0000-000000000000';

export async function run(api) {
  const { createSuite, assert, assertEquals } = await api.require('test-lib');
  const { testAsync, getResults } = createSuite('Tags & Attachments');

  async function storesAndRetrievesTags() {
    const id = crypto.randomUUID();
    await api.set({
      id,
      type: NOTE_TYPE,
      content: { description: 'Tagged item', tags: [STARRED_TAG] }
    });
    const item = await api.get(id);
    assert(Array.isArray(item.content.tags), 'Tags should be an array');
    assertEquals(item.content.tags.length, 1);
    assertEquals(item.content.tags[0], STARRED_TAG);
  }

  async function findsTaggedViaGetAll() {
    const id = crypto.randomUUID();
    await api.set({
      id,
      type: NOTE_TYPE,
      content: { description: 'Findable by tag', tags: [STARRED_TAG] }
    });
    const all = await api.getAll();
    const tagged = all.filter(i => i.content?.tags?.includes(STARRED_TAG));
    const found = tagged.find(i => i.id === id);
    assert(found, 'Should find the tagged item via getAll + filter');
  }

  async function untaggedItemHasNoTags() {
    const id = crypto.randomUUID();
    await api.set({
      id,
      type: NOTE_TYPE,
      content: { description: 'No tags here' }
    });
    const item = await api.get(id);
    const tags = item.content?.tags;
    assert(!tags || tags.length === 0, 'Untagged item should have no tags');
  }

  async function attachesChild() {
    const parentId = crypto.randomUUID();
    const childId = crypto.randomUUID();
    await api.set({ id: parentId, type: NOTE_TYPE, content: { description: 'Parent' }, attachments: [] });
    await api.set({ id: childId, type: NOTE_TYPE, content: { description: 'Child' } });

    await api.attach(parentId, childId);

    const parent = await api.get(parentId);
    assert(Array.isArray(parent.attachments), 'Parent should have attachments array');
    const found = parent.attachments.find(a => a.id === childId);
    assert(found, 'Parent attachments should include the child');
  }

  async function detachesChild() {
    const parentId = crypto.randomUUID();
    const childId = crypto.randomUUID();
    await api.set({ id: parentId, type: NOTE_TYPE, content: { description: 'Parent' }, attachments: [] });
    await api.set({ id: childId, type: NOTE_TYPE, content: { description: 'Child' } });

    await api.attach(parentId, childId);
    await api.detach(parentId, childId);

    const parent = await api.get(parentId);
    const found = parent.attachments.find(a => a.id === childId);
    assert(!found, 'Child should be removed from parent attachments after detach');
  }

  async function attachIsIdempotent() {
    const parentId = crypto.randomUUID();
    const childId = crypto.randomUUID();
    await api.set({ id: parentId, type: NOTE_TYPE, content: { description: 'Parent' }, attachments: [] });
    await api.set({ id: childId, type: NOTE_TYPE, content: { description: 'Child' } });

    await api.attach(parentId, childId);
    await api.attach(parentId, childId);

    const parent = await api.get(parentId);
    const count = parent.attachments.filter(a => a.id === childId).length;
    assertEquals(count, 1, 'Child should appear exactly once even after double attach');
  }

  async function findContainerOfFindsParent() {
    const parentId = crypto.randomUUID();
    const childId = crypto.randomUUID();
    await api.set({ id: parentId, type: NOTE_TYPE, content: { description: 'Parent' }, attachments: [] });
    await api.set({ id: childId, type: NOTE_TYPE, content: { description: 'Child' } });

    await api.attach(parentId, childId);

    const container = await api.findContainerOf(childId);
    assert(container, 'findContainerOf should return the parent');
    assertEquals(container.id, parentId);
  }

  await testAsync('stores and retrieves tags', storesAndRetrievesTags);
  await testAsync('finds tagged items via getAll + filter', findsTaggedViaGetAll);
  await testAsync('item with no tags has empty/missing tags', untaggedItemHasNoTags);
  await testAsync('attaches a child to a parent', attachesChild);
  await testAsync('detaches a child from a parent', detachesChild);
  await testAsync('attach is idempotent', attachIsIdempotent);
  await testAsync('findContainerOf finds parent', findContainerOfFindsParent);

  return getResults();
}

export async function run(api) {
  const { createSuite, assert, assertEquals } = await api.require('test-lib');
  const { testAsync, getResults } = createSuite('Events');

  const ITEM_UPDATED = 'e0e00000-0001-0002-0000-000000000000';

  async function onReceivesEmitted() {
    let received = null;
    const unsub = api.events.on(ITEM_UPDATED, (event) => {
      if (event.content?._testMarker === 'events-test-1') received = event;
    });
    try {
      api.events.emit({
        type: ITEM_UPDATED,
        content: { _testMarker: 'events-test-1', value: 42 }
      });
      assert(received, 'Handler should have been called');
      assertEquals(received.content.value, 42);
      assert(received.timestamp, 'Event should have a timestamp');
    } finally {
      unsub();
    }
  }

  async function offUnsubscribes() {
    let callCount = 0;
    const handler = () => { callCount++; };
    api.events.on(ITEM_UPDATED, handler);

    api.events.emit({ type: ITEM_UPDATED, content: { _testMarker: 'events-test-2' } });
    assertEquals(callCount, 1, 'Handler should be called once');

    api.events.off(ITEM_UPDATED, handler);
    api.events.emit({ type: ITEM_UPDATED, content: { _testMarker: 'events-test-3' } });
    assertEquals(callCount, 1, 'Handler should not be called after off()');
  }

  async function returnedUnsubscribeWorks() {
    let callCount = 0;
    const unsub = api.events.on(ITEM_UPDATED, () => { callCount++; });

    api.events.emit({ type: ITEM_UPDATED, content: { _testMarker: 'events-test-4' } });
    assertEquals(callCount, 1);

    unsub();
    api.events.emit({ type: ITEM_UPDATED, content: { _testMarker: 'events-test-5' } });
    assertEquals(callCount, 1, 'Handler should not fire after unsubscribe');
  }

  async function typeHierarchyDispatch() {
    const PARENT_TYPE = 'e0e00000-0001-0000-0000-000000000000'; // item-event
    let received = false;
    const unsub = api.events.on(PARENT_TYPE, (event) => {
      if (event.content?._testMarker === 'events-test-hierarchy') received = true;
    });
    try {
      api.events.emit({
        type: ITEM_UPDATED,
        content: { _testMarker: 'events-test-hierarchy' }
      });
      assert(received, 'Parent event listener should receive child event');
    } finally {
      unsub();
    }
  }

  await testAsync('on() receives emitted events', onReceivesEmitted);
  await testAsync('off() unsubscribes handler', offUnsubscribes);
  await testAsync('on() returns unsubscribe function', returnedUnsubscribeWorks);
  await testAsync('event type hierarchy dispatch', typeHierarchyDispatch);

  return getResults();
}

const TEST_TAG_ID = 'c0c0c0c0-0070-0000-0000-000000000000';

export async function onViewportReady(event, api) {
  // Only activate in nested instances
  const instanceId = api.getInstanceId();
  if (!instanceId) return;

  // Auto-run tests immediately on boot
  try {
    window.parent.postMessage({ type: 'test-instance-ready', instanceId }, '*');
    await runAllTests(api, instanceId);
  } catch (err) {
    window.parent.postMessage({ type: 'test-error', error: err.message, instanceId }, '*');
  }
}

async function runAllTests(api, instanceId) {
  const vpMgr = await api.require('viewport-manager');
  const rendering = vpMgr.getRendering();

  const allItems = await api.getAll();
  const testItems = allItems.filter(i =>
    i.content?.tags?.includes(TEST_TAG_ID) && i.name && i.content?.code
  );

  // Hidden area for test viewports
  const testArea = document.createElement('div');
  testArea.style.cssText = 'position:absolute; left:-9999px; top:-9999px; width:800px; height:600px; overflow:hidden;';
  document.body.appendChild(testArea);

  let totalPassed = 0;
  let totalFailed = 0;
  const suites = [];

  for (const testItem of testItems) {
    let suite;
    try {
      const results = await runTestItem(testItem, api, testArea, rendering);
      const passed = results.filter(r => r.passed).length;
      const failed = results.filter(r => !r.passed).length;
      totalPassed += passed;
      totalFailed += failed;
      suite = { testItemId: testItem.id, testItemName: testItem.name, passed, failed, results };
    } catch (e) {
      totalFailed += 1;
      const results = [{ name: testItem.name, passed: false, error: e.message }];
      suite = { testItemId: testItem.id, testItemName: testItem.name, passed: 0, failed: 1, results };
    }
    suites.push(suite);
    window.parent.postMessage({ type: 'test-progress', suite, instanceId }, '*');
  }

  const lastRun = { timestamp: Date.now(), totalPassed, totalFailed, suites };
  window.parent.postMessage({ type: 'test-complete', lastRun, instanceId }, '*');

  testArea.remove();
}

async function runTestItem(testItem, api, testArea, rendering) {
  const testApi = {
    set: async (item) => {
      const id = await api.set(item, { silent: true });
      return api.get(id);
    },
    get: async (id) => {
      try { return await api.get(id); }
      catch { return null; }
    },
    query: (filter) => api.query(filter),
    getAll: () => api.getAll(),
    delete: async (id) => {
      try { await api.delete(id); } catch { /* item may not exist */ }
    },
    require: (name) => api.require(name),
    typeChainIncludes: (typeId, targetId) => api.typeChainIncludes(typeId, targetId),
    attach: (parentId, itemId) => api.attach(parentId, itemId),
    detach: (parentId, itemId) => api.detach(parentId, itemId),
    findContainerOf: (itemId) => api.findContainerOf(itemId),
    events: api.events,

    openViewport: async (itemId, viewId) => {
      const viewport = document.createElement('div');
      viewport.className = 'test-viewport';
      viewport.style.cssText = 'width:800px; height:600px;';
      testArea.appendChild(viewport);
      const dom = await rendering.renderItem(itemId, viewId || null);
      if (dom) viewport.appendChild(dom);
      return viewport;
    },

    closeViewport: (el) => {
      if (el && el.parentNode) el.remove();
    }
  };

  const mod = await api.require(testItem.name);
  if (!mod || typeof mod.run !== 'function') {
    throw new Error(`Test item "${testItem.name}" does not export a run() function`);
  }

  const ITEM_TIMEOUT = 30000;
  const results = await Promise.race([
    mod.run(testApi),
    new Promise((_, reject) =>
      setTimeout(() => reject(new Error(`Test item "${testItem.name}" timed out after ${ITEM_TIMEOUT / 1000}s`)), ITEM_TIMEOUT)
    )
  ]);

  if (!Array.isArray(results)) {
    throw new Error(`Test item "${testItem.name}" run() must return an array of results`);
  }

  return results;
}

// Hob Reader Tests

export async function run(api) {
  const { createSuite, assert, assertEquals, assertDeepEquals } = await api.require('test-lib');
  const { test, testAsync, getResults } = createSuite('Hob Reader');
  const hob = await api.require('hob-interpreter');

  // --- Primitives ---

  function readsInteger() {
    const ast = hob.read('42');
    assertEquals(typeof ast, 'number');
    assertEquals(ast, 42);
  }

  function readsNegativeNumber() {
    const ast = hob.read('-7');
    assertEquals(typeof ast, 'number');
    assertEquals(ast, -7);
  }

  function readsFloat() {
    const ast = hob.read('3.14');
    assertEquals(typeof ast, 'number');
    assertEquals(ast, 3.14);
  }

  function readsString() {
    const ast = hob.read('"hello world"');
    assertEquals(typeof ast, 'object');
    assertEquals(ast.s, 'hello world');
  }

  function readsStringEscapes() {
    const ast = hob.read('"line1\\nline2\\ttab\\\\back\\"quote"');
    assertEquals(ast.s, 'line1\nline2\ttab\\back"quote');
  }

  function readsTrue() {
    const ast = hob.read('true');
    assertEquals(ast, true);
  }

  function readsFalse() {
    const ast = hob.read('false');
    assertEquals(ast, false);
  }

  function readsNil() {
    const ast = hob.read('nil');
    assertEquals(ast, null);
  }

  function readsKeyword() {
    const ast = hob.read(':title');
    assertEquals(typeof ast, 'string');
    assertEquals(ast, ':title');
  }

  function readsSymbol() {
    const ast = hob.read('foo-bar');
    assertEquals(typeof ast, 'string');
    assertEquals(ast, 'foo-bar');
  }

  function readsItemRefName() {
    const ast = hob.read('@my-note');
    assertEquals(typeof ast, 'string');
    assertEquals(ast, '@my-note');
  }

  function readsItemRefUUID() {
    const ast = hob.read('@a1b2c3d4-e5f6-7890-abcd-ef1234567890');
    assertEquals(ast, '@a1b2c3d4-e5f6-7890-abcd-ef1234567890');
  }

  // --- Collections ---

  function readsList() {
    const ast = hob.read('(+ 1 2)');
    assert(Array.isArray(ast), 'Should be an array (list)');
    assertEquals(ast.length, 3);
    assertEquals(ast[0], '+');
    assertEquals(ast[1], 1);
    assertEquals(ast[2], 2);
  }

  function readsEmptyList() {
    const ast = hob.read('()');
    assert(Array.isArray(ast), 'Should be an array');
    assertEquals(ast.length, 0);
  }

  function readsVector() {
    const ast = hob.read('[1 2 3]');
    assert(ast.v !== undefined, 'Should have .v property (vector)');
    assertEquals(ast.v.length, 3);
    assertEquals(ast.v[0], 1);
  }

  function readsMap() {
    const ast = hob.read('{:a 1 :b 2}');
    assert(ast.m !== undefined, 'Should have .m property (map)');
    assertEquals(ast.m.length, 2);
    assertEquals(ast.m[0][0], ':a');
    assertEquals(ast.m[0][1], 1);
  }

  function readsNestedCollections() {
    const ast = hob.read('(def m {:names ["alice" "bob"]})');
    assert(Array.isArray(ast), 'Should be an array (list)');
    assertEquals(ast.length, 3);
    assert(ast[2].m !== undefined, 'Third element should be a map');
    assert(ast[2].m[0][1].v !== undefined, 'Map value should be a vector');
  }

  // --- Whitespace and comments ---

  function commasAsWhitespace() {
    const ast = hob.read('[1, 2, 3]');
    assert(ast.v !== undefined, 'Should be a vector');
    assertEquals(ast.v.length, 3);
  }

  function commentsIgnored() {
    const ast = hob.read('(+ 1 ; this is a comment\n2)');
    assert(Array.isArray(ast), 'Should be a list');
    assertEquals(ast.length, 3);
    assertEquals(ast[2], 2);
  }

  // --- Quote ---

  function quoteShorthand() {
    const ast = hob.read("'(1 2 3)");
    assert(Array.isArray(ast), 'Should be a list');
    assertEquals(ast.length, 2);
    assertEquals(ast[0], 'quote');
    assert(Array.isArray(ast[1]), 'Second element should be a list');
  }

  // --- Source locations ---
  // Compact JSON format does not carry source locations — test removed

  // --- Error cases ---

  function errorOnUnterminatedString() {
    let caught = false;
    try { hob.read('"unterminated'); } catch (e) { caught = true; assert(e.message.includes('Unterminated'), 'Should mention unterminated'); }
    assert(caught, 'Should throw on unterminated string');
  }

  function errorOnUnterminatedList() {
    let caught = false;
    try { hob.read('(+ 1 2'); } catch (e) { caught = true; assert(e.message.includes('Unterminated'), 'Should mention unterminated'); }
    assert(caught, 'Should throw on unterminated list');
  }

  function errorOnSetLiteral() {
    let caught = false;
    try { hob.read('#{1 2 3}'); } catch (e) { caught = true; assert(e.message.includes('not yet supported'), 'Should mention sets not supported'); }
    assert(caught, 'Should throw on set literal');
  }

  function errorOnOddMapForms() {
    let caught = false;
    try { hob.read('{:a 1 :b}'); } catch (e) { caught = true; assert(e.message.includes('even number'), 'Should mention even number'); }
    assert(caught, 'Should throw on odd map forms');
  }

  function errorOnEmptyInput() {
    let caught = false;
    try { hob.read(''); } catch (e) { caught = true; }
    assert(caught, 'Should throw on empty input');
  }

  // --- Curly-infix ---

  function readsInfixBinary() {
    const ast = hob.read('{a + b}');
    assert(ast && ast.ci !== undefined, 'Should have .ci property');
    assertEquals(ast.ci[0], 'a');
    assertEquals(ast.ci[1], '+');
    assertEquals(ast.ci[2], 'b');
  }

  function readsInfixChained() {
    const ast = hob.read('{a + b + c}');
    assert(ast && ast.ci !== undefined, 'Should have .ci property');
    assertEquals(ast.ci.length, 5);
    assertEquals(ast.ci[4], 'c');
  }

  function readsInfixNested() {
    const ast = hob.read('{{a + b} * c}');
    assert(ast && ast.ci !== undefined, 'Should have .ci property');
    assertEquals(ast.ci[1], '*');
    assert(ast.ci[0] && ast.ci[0].ci !== undefined, 'First operand should be a ci node');
    assertEquals(ast.ci[0].ci[1], '+');
    assertEquals(ast.ci[2], 'c');
  }

  function readsInfixUnary() {
    const ast = hob.read('{- x}');
    assert(ast && ast.ci !== undefined, 'Should have .ci property');
    assertEquals(ast.ci[0], '-');
    assertEquals(ast.ci[1], 'x');
  }

  function readsInfixSingleton() {
    const ast = hob.read('{x}');
    assertEquals(ast, 'x');
  }

  function readsMixedInfixOps() {
    const ast = hob.read('{a + b - c}');
    assert(ast && ast.ci !== undefined, 'Should have .ci property');
    assertEquals(ast.ci[0], 'a');
    assertEquals(ast.ci[1], '+');
    assertEquals(ast.ci[2], 'b');
    assertEquals(ast.ci[3], '-');
    assertEquals(ast.ci[4], 'c');
  }

  // --- Run all tests ---

  test('reads integer', readsInteger);
  test('reads negative number', readsNegativeNumber);
  test('reads float', readsFloat);
