// Hob Integration Tests
// Tests item operations and REPL integration using a mock API

export async function run(api) {
  const { createSuite, assert, assertEquals, assertDeepEquals } = await api.require('test-lib');
  const { testAsync, getResults } = createSuite('Hob Integration');
  const hob = await api.require('hob-interpreter');

  // Mock item store
  function createMockApi() {
    const store = new Map();

    // Pre-populate with a test item
    store.set('test-note-id', {
      id: 'test-note-id',
      name: 'Test Note',
      type: '871ae771-b9b1-4f40-8c7f-d9038bfb69c3',
      content: { description: 'Hello from test' },
      attachments: []
    });

    return {
      get: async (id) => {
        const item = store.get(id);
        if (!item) throw new Error(`Item not found: ${id}`);
        return JSON.parse(JSON.stringify(item));
      },
      set: async (item) => {
        store.set(item.id, JSON.parse(JSON.stringify(item)));
        return item.id;
      },
      delete: async (id) => {
        store.delete(id);
      },
      getAll: async () => {
        return [...store.values()].map(i => JSON.parse(JSON.stringify(i)));
      },
      query: async (filter) => {
        const all = [...store.values()];
        if (filter.name) {
          return all.filter(i => i.name === filter.name).map(i => JSON.parse(JSON.stringify(i)));
        }
        return all.map(i => JSON.parse(JSON.stringify(i)));
      },
      _store: store
    };
  }

  // --- Item Operations ---

  async function getItem() {
    const mockApi = createMockApi();
    const interp = hob.createInterpreter(mockApi);
    const result = await interp.eval('(get-item "test-note-id")');
    assert(result !== null, 'Should return an item');
    assertEquals(result.name, 'Test Note');
    assertEquals(result.id, 'test-note-id');
  }

  async function setItem() {
    const mockApi = createMockApi();
    const interp = hob.createInterpreter(mockApi);
    // Use string keys (not keywords) so the JS object has "id", "name" etc.
    const result = await interp.eval('(set-item! {"id" "new-item" "name" "New Item" "type" "871ae771-b9b1-4f40-8c7f-d9038bfb69c3" "content" {"description" "Created from Hob"} "attachments" []})');
    assert(result !== null, 'Should return the item');
    // Verify it was stored
    const stored = await mockApi.get('new-item');
    assert(stored !== null, 'Item should be in store');
  }

  async function deleteItem() {
    const mockApi = createMockApi();
    const interp = hob.createInterpreter(mockApi);
    await interp.eval('(delete-item! "test-note-id")');
    let caught = false;
    try { await mockApi.get('test-note-id'); } catch { caught = true; }
    assert(caught, 'Item should be deleted');
  }

  async function getAll() {
    const mockApi = createMockApi();
    const interp = hob.createInterpreter(mockApi);
    const result = await interp.eval('(get-all)');
    assert(Array.isArray(result), 'Should return array');
    assert(result.length >= 1, 'Should have at least one item');
  }

  async function findItems() {
    const mockApi = createMockApi();
    const interp = hob.createInterpreter(mockApi);
    const result = await interp.eval('(find-items {:name "Test Note"})');
    assert(Array.isArray(result), 'Should return array');
    assertEquals(result.length, 1);
    assertEquals(result[0].name, 'Test Note');
  }

  // --- Item Reference Resolution ---

  async function itemRefByName() {
    const mockApi = createMockApi();
    const interp = hob.createInterpreter(mockApi);
    // @Test Note should be resolved by name query... but item refs use symbol-like names
    // Let's add an item with a simple name
    await mockApi.set({ id: 'simple-id', name: 'simple-item', type: 'test', content: {}, attachments: [] });
    const result = await interp.eval('@simple-item');
    assert(result !== null, 'Should resolve item ref');
    assertEquals(result.name, 'simple-item');
  }

  async function itemRefByUUID() {
    const mockApi = createMockApi();
    const interp = hob.createInterpreter(mockApi);
    // Add an item with a UUID-format id and resolve it by UUID
    await mockApi.set({ id: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890', name: 'UUID Item', type: 'test', content: {}, attachments: [] });
    const result = await interp.eval('@a1b2c3d4-e5f6-7890-abcd-ef1234567890');
    assert(result !== null, 'Should resolve UUID item ref');
    assertEquals(result.name, 'UUID Item');
  }

  async function itemRefUnresolvable() {
    const mockApi = createMockApi();
    const interp = hob.createInterpreter(mockApi);
    let caught = false;
    try { await interp.eval('@nonexistent-item'); } catch (e) { caught = true; assert(e.message.includes('resolve'), 'Should mention resolve'); }
    assert(caught, 'Should throw on unresolvable item ref');
  }

  // --- Printer round-trip ---

  async function printerRoundTrip() {
    assertEquals(hob.prStr(42), '42');
    assertEquals(hob.prStr('hello'), '"hello"');
    assertEquals(hob.prStr(null), 'nil');
    assertEquals(hob.prStr(true), 'true');
    assertEquals(hob.prStr([1, 2, 3]), '[1 2 3]');
    assertEquals(hob.prStr(hob.keyword('foo')), ':foo');
  }

  // --- REPL eval entry point ---

  async function replEvalEntryPoint() {
    const mockApi = createMockApi();
    const interp = hob.createInterpreter(mockApi);
    // Test the main eval entry point that REPL uses
    const result = await interp.eval('(+ 1 2)');
    assertEquals(result, 3);
  }

  async function replEvalMultipleExpressions() {
    const mockApi = createMockApi();
    const interp = hob.createInterpreter(mockApi);
    // Multiple expressions — returns last
    const result = await interp.eval('(def x 10) (def y 20) (+ x y)');
    assertEquals(result, 30);
  }

  // --- Run all tests ---

  await testAsync('get-item', getItem);
  await testAsync('set-item!', setItem);
  await testAsync('delete-item!', deleteItem);
  await testAsync('get-all', getAll);
  await testAsync('find-items', findItems);
  await testAsync('item ref by name', itemRefByName);
  await testAsync('item ref by UUID', itemRefByUUID);
  await testAsync('unresolvable item ref', itemRefUnresolvable);
  await testAsync('printer round-trip', printerRoundTrip);
  await testAsync('REPL eval entry point', replEvalEntryPoint);
  await testAsync('REPL eval multiple expressions', replEvalMultipleExpressions);

  return getResults();
}

// Hob Macro Tests

export async function run(api) {
  const { createSuite, assert, assertEquals, assertDeepEquals } = await api.require('test-lib');
  const { test, testAsync, getResults } = createSuite('Hob Macros');
  const hob = await api.require('hob-interpreter');
  const interp = hob.createInterpreter(api);
  await interp.macrosReady;

  // --- Reader: quasiquote, unquote, unquote-splicing ---

  function readsQuasiquote() {
    const ast = hob.read('`(a b c)');
    assert(Array.isArray(ast), 'Should be an array (list)');
    assertEquals(ast[0], 'quasiquote');
    assert(Array.isArray(ast[1]), 'Second element should be a list');
  }

  function readsUnquote() {
    const ast = hob.read('`(a ~b c)');
    const inner = ast[1]; // (a ~b c)
    assert(Array.isArray(inner[1]), 'Unquote should be a list');
    assertEquals(inner[1][0], 'unquote');
    assertEquals(inner[1][1], 'b');
  }

  function readsUnquoteSplicing() {
    const ast = hob.read('`(a ~@xs c)');
    const inner = ast[1];
    assert(Array.isArray(inner[1]), 'Unquote-splicing should be a list');
    assertEquals(inner[1][0], 'unquote-splicing');
    assertEquals(inner[1][1], 'xs');
  }

  // --- Quasiquote evaluation ---

  async function quasiquoteEval() {
    const result = await interp.eval('(let [x 1] `(a ~x c))');
    // Returns a list (array) with symbol a, number 1, symbol c
    assert(Array.isArray(result), 'Should be an array');
    assertEquals(result.length, 3);
    assertEquals(result[0]._hobType, 'symbol');
    assertEquals(result[0].value, 'a');
    assertEquals(result[1], 1);
    assertEquals(result[2]._hobType, 'symbol');
    assertEquals(result[2].value, 'c');
  }

  async function quasiquoteSpliceEval() {
    const result = await interp.eval('(let [xs [1 2]] `(a ~@xs c))');
    assert(Array.isArray(result), 'Should be an array');
    assertEquals(result.length, 4);
    assertEquals(result[1], 1);
    assertEquals(result[2], 2);
  }

  // --- defmacro ---

  async function defmacroBasic() {
    const result = await interp.eval('(do (defmacro my-nil [] nil) (my-nil))');
    assertEquals(result, null);
  }

  async function defmacroReceivesUnevaluated() {
    const result = await interp.eval(`
      (do
        (defmacro quote-first [x & rest] \`'~x)
        (quote-first hello world))
    `);
    assertEquals(result._hobType, 'symbol');
    assertEquals(result.value, 'hello');
  }

  // --- Standard macros: when ---

  async function whenTrue() {
    const result = await interp.eval('(when true 1 2 3)');
    assertEquals(result, 3);
  }

  async function whenFalse() {
    const result = await interp.eval('(when false 1 2 3)');
    assertEquals(result, null);
  }

  // --- when-let ---

  async function whenLetTruthy() {
    const result = await interp.eval('(when-let [x 42] (inc x))');
    assertEquals(result, 43);
  }

  async function whenLetNil() {
    const result = await interp.eval('(when-let [x nil] (inc x))');
    assertEquals(result, null);
  }

  // --- cond ---

  async function condMatches() {
    const result = await interp.eval('(cond (= 1 2) "a" (= 1 1) "b" :else "c")');
    assertEquals(result, 'b');
  }

  async function condNoMatch() {
    const result = await interp.eval('(cond (= 1 2) "a" (= 1 3) "b")');
    assertEquals(result, null);
  }

  async function condElse() {
    const result = await interp.eval('(cond (= 1 2) "a" :else "fallback")');
    assertEquals(result, 'fallback');
  }

  // --- defn ---

  async function defnBasic() {
    const result = await interp.eval('(do (defn f [x] (+ x 1)) (f 5))');
    assertEquals(result, 6);
  }

  async function defnMultiArity() {
    const result = await interp.eval(`
      (do
        (defn f
          ([x] (f x 10))
          ([x y] (+ x y)))
        [(f 5) (f 5 20)])
    `);
    assertDeepEquals(result, [15, 25]);
  }

  // --- Threading macros ---

  async function threadFirst() {
    const result = await interp.eval('(-> 1 inc inc)');
    assertEquals(result, 3);
  }

  async function threadFirstWithArgs() {
    const result = await interp.eval('(-> "hello" str/upper-case (subs 0 3))');
    assertEquals(result, 'HEL');
  }

  async function threadLast() {
    const result = await interp.eval('(->> [1 2 3] (map inc) (filter (fn [x] (> x 2))))');
    assertDeepEquals(result, [3, 4]);
  }

  // --- for ---

  async function forBasic() {
    const result = await interp.eval('(for [x [1 2 3]] (* x x))');
    assertDeepEquals(result, [1, 4, 9]);
  }

  // --- and/or as macros ---

  async function andMacro() {
    const r1 = await interp.eval('(and 1 2 3)');
    assertEquals(r1, 3);
    const r2 = await interp.eval('(and 1 nil 3)');
    assertEquals(r2, null);
    const r3 = await interp.eval('(and)');
    assertEquals(r3, true);
  }

  async function orMacro() {
    const r1 = await interp.eval('(or nil false 3)');
    assertEquals(r1, 3);
    const r2 = await interp.eval('(or nil false)');
    assertEquals(r2, false);
    const r3 = await interp.eval('(or)');
    assertEquals(r3, null);
  }

  // --- Macro expansion is recursive ---

  async function macroRecursiveExpansion() {
    const result = await interp.eval(`
      (do
        (defmacro double-when [test & body]
          \`(when ~test (when ~test ~@body)))
        (double-when true 42))
    `);
    assertEquals(result, 42);
  }

  // --- gensym ---

  async function gensymProducesUnique() {
    const result = await interp.eval('(let [a (gensym "x") b (gensym "x")] (not= a b))');
    assertEquals(result, true);
  }

  // --- Anonymous fn shorthand ---

  function readsAnonFn() {
    const ast = hob.read('#(+ %1 %2)');
    assert(Array.isArray(ast), 'Should be a list');
    assertEquals(ast[0], 'fn');
    assert(ast[1].v !== undefined, 'Second element should be a vector');
    assertEquals(ast[1].v.length, 2);
    assertEquals(ast[1].v[0], '%1');
    assertEquals(ast[1].v[1], '%2');
  }

  async function anonFnEval() {
    const result = await interp.eval('(map #(+ % 10) [1 2 3])');
    assertDeepEquals(result, [11, 12, 13]);
  }

  async function anonFnMultiArg() {
    const result = await interp.eval('(#(+ %1 %2 %3) 1 2 3)');
    assertEquals(result, 6);
  }

  // --- unless (user-defined macro) ---

  async function unlessMacro() {
    const result = await interp.eval(`
      (do
        (defmacro unless [test & body]
          \`(if ~test nil (do ~@body)))
        (unless false 42))
    `);
    assertEquals(result, 42);
  }

  // --- Run all tests ---

  test('reads quasiquote', readsQuasiquote);
  test('reads unquote', readsUnquote);
  test('reads unquote-splicing', readsUnquoteSplicing);
  await testAsync('quasiquote eval', quasiquoteEval);
  await testAsync('quasiquote splice eval', quasiquoteSpliceEval);
  await testAsync('defmacro basic', defmacroBasic);
  await testAsync('defmacro receives unevaluated forms', defmacroReceivesUnevaluated);
  await testAsync('when true', whenTrue);
  await testAsync('when false', whenFalse);
  await testAsync('when-let truthy', whenLetTruthy);
  await testAsync('when-let nil', whenLetNil);
  await testAsync('cond matches', condMatches);
  await testAsync('cond no match', condNoMatch);
  await testAsync('cond else', condElse);
  await testAsync('defn basic', defnBasic);
  await testAsync('defn multi-arity', defnMultiArity);
  await testAsync('-> thread-first', threadFirst);
  await testAsync('-> thread-first with args', threadFirstWithArgs);
  await testAsync('->> thread-last', threadLast);
  await testAsync('for', forBasic);
  await testAsync('and macro', andMacro);
  await testAsync('or macro', orMacro);
  await testAsync('macro recursive expansion', macroRecursiveExpansion);
  await testAsync('gensym produces unique', gensymProducesUnique);
  test('reads anonymous fn', readsAnonFn);
  await testAsync('anonymous fn eval', anonFnEval);
  await testAsync('anonymous fn multi-arg', anonFnMultiArg);
  await testAsync('unless user-defined macro', unlessMacro);

  return getResults();
}

// Hob Destructuring Tests

export async function run(api) {
  const { createSuite, assert, assertEquals, assertDeepEquals } = await api.require('test-lib');
  const { test, testAsync, getResults } = createSuite('Hob Destructuring');
  const hob = await api.require('hob-interpreter');
  const interp = hob.createInterpreter(api);
  await interp.macrosReady;

  // --- Vector destructuring in let ---

  async function vecDestrBasic() {
    const result = await interp.eval('(let [[a b c] [1 2 3]] (+ a b c))');
    assertEquals(result, 6);
  }

  async function vecDestrFewer() {
    const result = await interp.eval('(let [[a b] [1 2 3]] b)');
    assertEquals(result, 2);
  }

  async function vecDestrMore() {
    const result = await interp.eval('(let [[a b c] [1 2]] c)');
    assertEquals(result, null);
  }

  async function vecDestrRest() {
    const result = await interp.eval('(let [[a & rest] [1 2 3 4]] rest)');
    assertDeepEquals(result, [2, 3, 4]);
  }

  async function vecDestrUnderscore() {
    const result = await interp.eval('(let [[_ b _] [1 2 3]] b)');
    assertEquals(result, 2);
  }

  async function vecDestrNested() {
    const result = await interp.eval('(let [[[a b] c] [[1 2] 3]] (+ a b c))');
    assertEquals(result, 6);
  }

  // --- Map destructuring in let ---

  async function mapDestrDirect() {
    const result = await interp.eval('(let [{a :a b :b} {:a 1 :b 2}] (+ a b))');
    assertEquals(result, 3);
  }

  async function mapDestrKeys() {
    const result = await interp.eval('(let [{:keys [a b]} {:a 1 :b 2}] (+ a b))');
    assertEquals(result, 3);
  }

  async function mapDestrKeysMissing() {
    const result = await interp.eval('(let [{:keys [a b c]} {:a 1 :b 2}] c)');
    assertEquals(result, null);
  }

  async function mapDestrOr() {
    const result = await interp.eval('(let [{:keys [a b] :or {b 10}} {:a 1}] (+ a b))');
    assertEquals(result, 11);
  }

  async function mapDestrAs() {
    const result = await interp.eval('(let [{:keys [a] :as m} {:a 1 :b 2}] (count m))');
    assertEquals(result, 2);
  }

  async function mapDestrStrs() {
    const result = await interp.eval('(let [{:strs [name]} {"name" "Alice"}] name)');
    assertEquals(result, 'Alice');
  }

  // --- Destructuring in fn params ---

  async function fnVecDestr() {
    const result = await interp.eval('((fn [[a b]] (+ a b)) [1 2])');
    assertEquals(result, 3);
  }

  async function fnMapDestr() {
    const result = await interp.eval('((fn [{:keys [x y]}] (+ x y)) {:x 3 :y 4})');
    assertEquals(result, 7);
  }

  // --- Destructuring in loop ---

  async function loopVecDestr() {
    const result = await interp.eval(`
      (loop [[x & xs] [1 2 3] acc 0]
        (if (nil? x) acc (recur xs (+ acc x))))
    `);
    assertEquals(result, 6);
  }

  async function loopMapDestr() {
    const result = await interp.eval(`
      (loop [{:keys [n acc]} {:n 5 :acc 1}]
        (if (<= n 1) acc (recur {:n (dec n) :acc (* acc n)})))
    `);
    assertEquals(result, 120);
  }

  // --- Edge cases ---

  async function emptyVecDestr() {
    const result = await interp.eval('(let [[] []] nil)');
    assertEquals(result, null);
  }

  async function emptyMapDestr() {
    const result = await interp.eval('(let [{} {}] nil)');
    assertEquals(result, null);
  }

  async function nilVecDestr() {
    const result = await interp.eval('(let [[a b] nil] [a b])');
    assertDeepEquals(result, [null, null]);
  }

  async function nilMapDestr() {
    const result = await interp.eval('(let [{:keys [a]} nil] a)');
    assertEquals(result, null);
  }

  // --- defn with destructured params ---

  async function defnDestr() {
    const result = await interp.eval(`
      (do
        (defn point-str [{:keys [x y]}] (str x "," y))
        (point-str {:x 1 :y 2}))
    `);
    assertEquals(result, '1,2');
  }

  // --- Error on bad vector destructuring ---

  async function errorVecDestrNonSeq() {
    let caught = false;
    try {
      await interp.eval('(let [[a] 42] a)');
    } catch (e) {
      caught = true;
      assert(e.message.includes('destructure') || e.message.includes('non-sequential') || e.message.includes('vector'), 'Should mention destructuring error');
    }
    assert(caught, 'Should throw on destructuring non-sequential');
  }

  // --- Deeply nested ---

  async function deeplyNested() {
    const result = await interp.eval(`
      (let [{:keys [a] [{:keys [x]}] :items} {:a 1 :items [{:x 42}]}]
        [a x])
    `);
    assertDeepEquals(result, [1, 42]);
  }

  // --- Run all tests ---

  await testAsync('vector destructuring basic', vecDestrBasic);
  await testAsync('vector destructuring fewer elements', vecDestrFewer);
  await testAsync('vector destructuring more elements', vecDestrMore);
  await testAsync('vector destructuring rest', vecDestrRest);
  await testAsync('vector destructuring underscore', vecDestrUnderscore);
  await testAsync('nested vector destructuring', vecDestrNested);
  await testAsync('map destructuring direct', mapDestrDirect);
  await testAsync('map :keys shorthand', mapDestrKeys);
  await testAsync('map :keys missing key', mapDestrKeysMissing);
  await testAsync('map :or defaults', mapDestrOr);
  await testAsync('map :as whole', mapDestrAs);
  await testAsync('map :strs shorthand', mapDestrStrs);
  await testAsync('fn vector destructuring', fnVecDestr);
  await testAsync('fn map destructuring', fnMapDestr);
  await testAsync('loop vector destructuring', loopVecDestr);
  await testAsync('loop map destructuring', loopMapDestr);
  await testAsync('empty vector destructuring', emptyVecDestr);
  await testAsync('empty map destructuring', emptyMapDestr);
  await testAsync('nil vector destructuring', nilVecDestr);
  await testAsync('nil map destructuring', nilMapDestr);
  await testAsync('defn with destructured params', defnDestr);
  await testAsync('error on non-sequential vector destructuring', errorVecDestrNonSeq);
  await testAsync('deeply nested destructuring', deeplyNested);

  return getResults();
}

// Hob Concurrency Tests

export async function run(api) {
  const { createSuite, assert, assertEquals, assertDeepEquals } = await api.require('test-lib');
  const { test, testAsync, getResults } = createSuite('Hob Concurrency');
  const hob = await api.require('hob-interpreter');
  const interp = hob.createInterpreter(api);
  await interp.macrosReady;

  // --- Auto-parallel let: correctness ---

  async function autoParallelBasic() {
    const result = await interp.eval('(let [a 1 b 2] (+ a b))');
    assertEquals(result, 3);
  }

  async function autoParallelDependent() {
    const result = await interp.eval('(let [a 1 b (+ a 1)] b)');
    assertEquals(result, 2);
  }

  async function autoParallelMixed() {
    const result = await interp.eval('(let [a 1 b 2 c (+ a b)] c)');
    assertEquals(result, 3);
  }

  async function autoParallelThreeIndependent() {
    const result = await interp.eval(`
      (let [a (do 1) b (do 2) c (do 3)]
        (+ a b c))
    `);
    assertEquals(result, 6);
  }

  async function autoParallelOuterScope() {
    // a and b reference outer x, not each other — they're independent
    const result = await interp.eval('(do (def x 1) (let [a x b x] (+ a b)))');
    assertEquals(result, 2);
  }

  async function autoParallelTransitiveDep() {
    const result = await interp.eval('(let [a 1 b (+ a 1) c (+ b 1)] c)');
    assertEquals(result, 3);
  }

  // --- plet ---

  async function pletBasic() {
    const result = await interp.eval('(plet [a 1 b 2 c 3] (+ a b c))');
    assertEquals(result, 6);
  }

  async function pletError() {
    let caught = false;
    try {
      await interp.eval('(plet [a (throw "fail")] a)');
    } catch (e) {
      caught = true;
    }
    assert(caught, 'plet should propagate errors');
  }

  // --- pmap ---

  async function pmapBasic() {
    const result = await interp.eval('(pmap inc [1 2 3])');
    assertDeepEquals(result, [2, 3, 4]);
  }

  async function pmapEmpty() {
    const result = await interp.eval('(pmap inc [])');
    assertDeepEquals(result, []);
  }

  async function pmapPreservesOrder() {
    const result = await interp.eval('(pmap identity [3 1 2])');
    assertDeepEquals(result, [3, 1, 2]);
  }

  async function pmapError() {
    let caught = false;
    try {
      await interp.eval('(pmap (fn [x] (if (= x 2) (throw "bad") x)) [1 2 3])');
    } catch (e) {
      caught = true;
    }
    assert(caught, 'pmap should propagate errors');
  }

  // --- Parallel let with closures ---

  async function parallelLetClosures() {
    const result = await interp.eval('(let [f (fn [x] x) a (f 1) b (f 2)] [a b])');
    assertDeepEquals(result, [1, 2]);
  }

  // --- Sequential correctness under parallel ---

  async function sequentialSideEffects() {
    const result = await interp.eval(`
      (let [a (atom 0)
            b (do (swap! a inc) 1)
            c (do (swap! a inc) 2)]
        (deref a))
    `);
    assertEquals(result, 2);
  }

  // --- Auto-parallel with destructuring ---

  async function autoParallelDestructuring() {
    const result = await interp.eval(`
      (let [[a b] [1 2]
            [c d] [3 4]]
        (+ a b c d))
    `);
    assertEquals(result, 10);
  }

  // --- plet with destructuring ---

  async function pletDestructuring() {
    const result = await interp.eval(`
      (plet [[a b] [1 2] {:keys [x]} {:x 3}]
        (+ a b x))
    `);
    assertEquals(result, 6);
  }

  // --- freeSymbols handles quote correctly ---

  async function freeSymbolsQuote() {
    // Bindings that reference only quoted symbols should be independent
    const result = await interp.eval(`
      (let [a (quote hello)
            b (quote world)]
        [a b])
    `);
    assert(Array.isArray(result), 'Should return array');
    assertEquals(result.length, 2);
  }

  // --- Run all tests ---

  await testAsync('auto-parallel let basic', autoParallelBasic);
  await testAsync('auto-parallel dependent bindings', autoParallelDependent);
  await testAsync('auto-parallel mixed', autoParallelMixed);
  await testAsync('auto-parallel three independent', autoParallelThreeIndependent);
  await testAsync('auto-parallel outer scope', autoParallelOuterScope);
  await testAsync('auto-parallel transitive dependency', autoParallelTransitiveDep);
  await testAsync('plet basic', pletBasic);
  await testAsync('plet error propagation', pletError);
  await testAsync('pmap basic', pmapBasic);
  await testAsync('pmap empty', pmapEmpty);
  await testAsync('pmap preserves order', pmapPreservesOrder);
  await testAsync('pmap error propagation', pmapError);
  await testAsync('parallel let with closures', parallelLetClosures);
  await testAsync('sequential side effects', sequentialSideEffects);
  await testAsync('auto-parallel with destructuring', autoParallelDestructuring);
  await testAsync('plet with destructuring', pletDestructuring);
  await testAsync('freeSymbols handles quote', freeSymbolsQuote);

  return getResults();
}

// Hob Atom Tests

export async function run(api) {
  const { createSuite, assert, assertEquals, assertDeepEquals } = await api.require('test-lib');
  const { test, testAsync, getResults } = createSuite('Hob Atoms');
  const hob = await api.require('hob-interpreter');
  const interp = hob.createInterpreter(api);
  await interp.macrosReady;

  // --- atom creation ---

  async function atomCreates() {
    const result = await interp.eval('(type-of (atom 0))');
    assertEquals(result, 'atom');
  }

  // --- deref ---

  async function derefReads() {
    const result = await interp.eval('(do (def a (atom 42)) (deref a))');
    assertEquals(result, 42);
  }

  // --- swap! ---

  async function swapApplies() {
    const result = await interp.eval('(do (def a (atom 0)) (swap! a inc) (deref a))');
    assertEquals(result, 1);
  }

  async function swapExtraArgs() {
    const result = await interp.eval('(do (def a (atom 0)) (swap! a + 5) (deref a))');
    assertEquals(result, 5);
  }

  async function swapReturns() {
    const result = await interp.eval('(do (def a (atom 0)) (swap! a inc))');
    assertEquals(result, 1);
  }

  // --- reset! ---

  async function resetSets() {
    const result = await interp.eval('(do (def a (atom 0)) (reset! a 42) (deref a))');
    assertEquals(result, 42);
  }

  async function resetReturns() {
    const result = await interp.eval('(do (def a (atom 0)) (reset! a 42))');
    assertEquals(result, 42);
  }

  // --- Multiple swaps ---

  async function multipleSwaps() {
    const result = await interp.eval('(do (def a (atom 0)) (swap! a inc) (swap! a inc) (swap! a inc) (deref a))');
    assertEquals(result, 3);
  }

  // --- Complex value ---

  async function atomComplexValue() {
    const result = await interp.eval(`
      (do
        (def a (atom {:count 0}))
        (swap! a (fn [m] (assoc m :count (inc (:count m)))))
        (deref a))
    `);
    assertEquals(result['\u029ecount'], 1);
  }

  // --- Atom in closure ---

  async function atomInClosure() {
    const result = await interp.eval(`
      (do
        (def a (atom 0))
        (def inc-a (fn [] (swap! a inc)))
        (inc-a)
        (inc-a)
        (deref a))
    `);
    assertEquals(result, 2);
  }

  // --- atom? predicate ---

  async function atomPredicate() {
    const r1 = await interp.eval('(atom? (atom 0))');
    assertEquals(r1, true);
    const r2 = await interp.eval('(atom? 42)');
    assertEquals(r2, false);
  }

  // --- Atom with nil ---

  async function atomNil() {
    const r1 = await interp.eval('(do (def a (atom nil)) (deref a))');
    assertEquals(r1, null);
    const r2 = await interp.eval('(do (def a (atom nil)) (nil? (deref a)))');
    assertEquals(r2, true);
  }

  // --- Atom in let ---

  async function atomInLet() {
    const result = await interp.eval('(let [a (atom 0)] (swap! a inc) (deref a))');
    assertEquals(result, 1);
  }

  // --- Atom identity ---

  async function atomIdentity() {
    const result = await interp.eval('(do (def a (atom 0)) (= a a))');
    assertEquals(result, true);
  }

  // --- Run all tests ---

  await testAsync('atom creates', atomCreates);
  await testAsync('deref reads value', derefReads);
  await testAsync('swap! applies function', swapApplies);
  await testAsync('swap! with extra args', swapExtraArgs);
  await testAsync('swap! returns new value', swapReturns);
  await testAsync('reset! sets value', resetSets);
  await testAsync('reset! returns value', resetReturns);
  await testAsync('multiple swaps accumulate', multipleSwaps);
  await testAsync('atom with complex value', atomComplexValue);
  await testAsync('atom in closure', atomInClosure);
  await testAsync('atom? predicate', atomPredicate);
  await testAsync('atom with nil', atomNil);
  await testAsync('atom in let', atomInLet);
  await testAsync('atom identity', atomIdentity);

  return getResults();
}

// Hob Error Handling Tests

export async function run(api) {
  const { createSuite, assert, assertEquals, assertDeepEquals } = await api.require('test-lib');
  const { test, testAsync, getResults } = createSuite('Hob Error Handling');
  const hob = await api.require('hob-interpreter');
  const interp = hob.createInterpreter(api);
  await interp.macrosReady;

  // --- throw/catch basics ---

  async function throwCatchBasic() {
    const result = await interp.eval('(try (throw "oops") (catch e e))');
    assertEquals(result, 'oops');
  }

  async function throwMapValue() {
    const result = await interp.eval('(try (throw {:message "bad" :code 42}) (catch e (:code e)))');
    assertEquals(result, 42);
  }

  // --- No error passes through ---

  async function tryNoError() {
    const result = await interp.eval('(try (+ 1 2) (catch e "caught"))');
    assertEquals(result, 3);
  }

  // --- Catch undefined symbol ---

  async function catchUndefined() {
    const result = await interp.eval('(try undefined-var (catch e (str e)))');
    assert(typeof result === 'string', 'Should return string');
    assert(result.includes('Undefined') || result.includes('undefined'), 'Should mention undefined');
  }

  // --- Nested try/catch ---

  async function nestedTryCatch() {
    const result = await interp.eval(`
      (try
        (try (throw "inner") (catch e (str "inner: " e)))
        (catch e (str "outer: " e)))
    `);
    assertEquals(result, 'inner: inner');
  }

  // --- Rethrow ---

  async function rethrow() {
    const result = await interp.eval(`
      (try
        (try (throw "err") (catch e (throw (str "re-" e))))
        (catch e e))
    `);
    assertEquals(result, 're-err');
  }

  // --- finally clause ---

  async function finallyClause() {
    const result = await interp.eval(`
      (do
        (def a (atom 0))
        (try
          (throw "err")
          (catch e nil)
          (finally (swap! a inc)))
        (deref a))
    `);
    assertEquals(result, 1);
  }

  async function finallyWithoutError() {
    const result = await interp.eval(`
      (do
        (def a (atom 0))
        (try
          42
          (finally (swap! a inc)))
        (deref a))
    `);
    assertEquals(result, 1);
  }

  // --- Error in function call ---

  async function errorInFnCall() {
    const result = await interp.eval('(try ((fn [] (throw "fn-err"))) (catch e e))');
    assertEquals(result, 'fn-err');
  }

  // --- Catch in loop ---

  async function catchInLoop() {
    const result = await interp.eval(`
      (loop [i 0 acc []]
        (if (>= i 3) acc
          (recur (inc i)
            (conj acc (try (if (= i 1) (throw "skip") i) (catch e nil))))))
    `);
    assertDeepEquals(result, [0, null, 2]);
  }

  // --- Catch preserves environment ---

  async function catchPreservesEnv() {
    const result = await interp.eval('(let [x 42] (try (throw "err") (catch e x)))');
    assertEquals(result, 42);
  }

  // --- Uncaught error propagates ---

  async function uncaughtPropagates() {
    let caught = false;
    try {
      await interp.eval('(throw "uncaught")');
    } catch (e) {
      caught = true;
      assert(e.message.includes('uncaught') || (e.hobValue === 'uncaught'), 'Should contain error value');
    }
    assert(caught, 'Uncaught error should propagate');
  }

  // --- Error from try body, no catch ---

  async function tryWithoutCatch() {
    const result = await interp.eval(`
      (do
        (def a (atom 0))
        (try
          (do (swap! a inc) 42)
          (finally (swap! a inc)))
        (deref a))
    `);
    assertEquals(result, 2);
  }

  // --- Catch type error ---

  async function catchTypeError() {
    const result = await interp.eval('(try (+ 1 "a") (catch e "caught"))');
    // + with string concatenation may not error, so test with explicit throw
    assert(result === 'caught' || result === '1a' || typeof result === 'string', 'Should catch or concatenate');
  }

  // --- Run all tests ---

  await testAsync('throw/catch basic', throwCatchBasic);
  await testAsync('throw map value', throwMapValue);
  await testAsync('try no error', tryNoError);
  await testAsync('catch undefined symbol', catchUndefined);
  await testAsync('nested try/catch', nestedTryCatch);
  await testAsync('rethrow', rethrow);
  await testAsync('finally clause', finallyClause);
  await testAsync('finally without error', finallyWithoutError);
  await testAsync('error in function call', errorInFnCall);
  await testAsync('catch in loop', catchInLoop);
  await testAsync('catch preserves environment', catchPreservesEnv);
  await testAsync('uncaught error propagates', uncaughtPropagates);
  await testAsync('try without catch (finally only)', tryWithoutCatch);
  await testAsync('catch type error', catchTypeError);

  return getResults();
}

// Hob DOM Tests — parseTag and hiccupToDOM

export async function run(api) {
  const { createSuite, assert, assertEquals, assertDeepEquals } = await api.require('test-lib');
  const { test, testAsync, getResults } = createSuite('Hob DOM');
  const hob = await api.require('hob-interpreter');
  const interp = hob.createInterpreter(api);
  await interp.macrosReady;

  // ============================================================
  // parseTag tests
  // ============================================================

  test('parseTag basic', () => {
    const r = hob.parseTag('div');
    assertEquals(r.tag, 'div');
    assertEquals(r.id, null);
    assertDeepEquals(r.classes, []);
  });

  test('parseTag with class', () => {
    const r = hob.parseTag('div.foo');
    assertEquals(r.tag, 'div');
    assertDeepEquals(r.classes, ['foo']);
  });

  test('parseTag with multiple classes', () => {
    const r = hob.parseTag('div.foo.bar');
    assertEquals(r.tag, 'div');
    assertDeepEquals(r.classes, ['foo', 'bar']);
  });

  test('parseTag with id', () => {
    const r = hob.parseTag('div#main');
    assertEquals(r.tag, 'div');
    assertEquals(r.id, 'main');
  });

  test('parseTag with id and classes', () => {
    const r = hob.parseTag('div#main.foo.bar');
    assertEquals(r.tag, 'div');
    assertEquals(r.id, 'main');
    assertDeepEquals(r.classes, ['foo', 'bar']);
  });

  test('parseTag default tag', () => {
    const r = hob.parseTag('.wrapper');
    assertEquals(r.tag, 'div');
    assertDeepEquals(r.classes, ['wrapper']);
  });

  test('parseTag id only', () => {
    const r = hob.parseTag('#app');
    assertEquals(r.tag, 'div');
    assertEquals(r.id, 'app');
  });

  // ============================================================
  // hiccupToDOM tests
  // ============================================================

  test('hiccup text node', () => {
    const node = hob.hiccupToDOM('hello');
    assert(node.nodeType === 3, 'Should be text node');
    assertEquals(node.textContent, 'hello');
  });

  test('hiccup number node', () => {
    const node = hob.hiccupToDOM(42);
    assert(node.nodeType === 3, 'Should be text node');
    assertEquals(node.textContent, '42');
  });

  test('hiccup null returns null', () => {
    assertEquals(hob.hiccupToDOM(null), null);
    assertEquals(hob.hiccupToDOM(undefined), null);
  });

  test('hiccup simple element', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div')]);
    assert(el.nodeType === 1, 'Should be element');
    assertEquals(el.tagName, 'DIV');
  });

  test('hiccup element with text', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div'), 'hello']);
    assertEquals(el.tagName, 'DIV');
    assertEquals(el.textContent, 'hello');
  });

  test('hiccup element with attrs', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div'), { [kw('id')]: 'foo' }]);
    assertEquals(el.id, 'foo');
  });

  test('hiccup element with class attr', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div'), { [kw('class')]: 'foo bar' }]);
    assert(el.classList.contains('foo'), 'Should have class foo');
    assert(el.classList.contains('bar'), 'Should have class bar');
  });

  test('hiccup element with style object', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div'), { [kw('style')]: { color: 'red', fontSize: '14px' } }]);
    assertEquals(el.style.color, 'red');
    assertEquals(el.style.fontSize, '14px');
  });

  test('hiccup tag classes merge with attr class', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div.a'), { [kw('class')]: 'b' }]);
    assert(el.classList.contains('a'), 'Should have tag class a');
    assert(el.classList.contains('b'), 'Should have attr class b');
  });

  test('hiccup nested elements', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div'), [kw('span'), 'hi']]);
    assertEquals(el.children.length, 1);
    assertEquals(el.children[0].tagName, 'SPAN');
    assertEquals(el.children[0].textContent, 'hi');
  });

  test('hiccup multiple children', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div'), 'a', 'b', 'c']);
    assertEquals(el.childNodes.length, 3);
    assertEquals(el.textContent, 'abc');
  });

  test('hiccup boolean true attr', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('input'), { [kw('disabled')]: true }]);
    assert(el.hasAttribute('disabled'), 'Should have disabled attr');
  });

  test('hiccup boolean false attr skipped', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('input'), { [kw('disabled')]: false }]);
    assert(!el.hasAttribute('disabled'), 'Should not have disabled attr');
  });

  test('hiccup event handler', () => {
    const kw = hob.keyword;
    let clicked = false;
    const handler = () => { clicked = true; };
    const el = hob.hiccupToDOM([kw('button'), { [kw('on-click')]: handler }, 'Click']);
    el.click();
    assert(clicked, 'Click handler should have fired');
  });

  test('hiccup mixed children', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div'), 'text', [kw('span'), 'child'], 42]);
    assertEquals(el.childNodes.length, 3);
    assertEquals(el.childNodes[0].textContent, 'text');
    assertEquals(el.childNodes[1].tagName, 'SPAN');
    assertEquals(el.childNodes[2].textContent, '42');
  });

  test('hiccup deeply nested', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM(
      [kw('div'), [kw('section'), [kw('p'), [kw('strong'), 'deep']]]]
    );
    assertEquals(el.querySelector('strong').textContent, 'deep');
  });

  test('hiccup DOM passthrough', () => {
    const kw = hob.keyword;
    const existing = document.createElement('span');
    existing.textContent = 'existing';
    const el = hob.hiccupToDOM([kw('div'), existing]);
    assert(el.contains(existing), 'Should contain existing DOM node');
  });

  test('hiccup empty attrs object', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div'), {}, 'text']);
    assertEquals(el.textContent, 'text');
  });

  test('hiccup keyword to tag name', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('h1'), 'Title']);
    assertEquals(el.tagName, 'H1');
  });

  test('hiccup tag with id and class', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div#app.container.main')]);
    assertEquals(el.id, 'app');
    assert(el.classList.contains('container'), 'Should have class container');
    assert(el.classList.contains('main'), 'Should have class main');
  });

  test('hiccup style with keyword keys', () => {
    const kw = hob.keyword;
    const el = hob.hiccupToDOM([kw('div'), { [kw('style')]: { [kw('color')]: 'blue' } }]);
    assertEquals(el.style.color, 'blue');
  });

  test('hiccup flattens nested arrays from map', () => {
    const kw = hob.keyword;
    // Simulate what (map ...) produces: an array of hiccup elements
    const children = [[kw('li'), 'a'], [kw('li'), 'b'], [kw('li'), 'c']];
    const el = hob.hiccupToDOM([kw('ul'), children]);
    assertEquals(el.children.length, 3);
    assertEquals(el.children[0].tagName, 'LI');
    assertEquals(el.children[2].textContent, 'c');
  });

  // ============================================================
  // hiccupToDOM via Hob eval
  // ============================================================

  await testAsync('hiccup from Hob eval', async () => {
    const result = await interp.eval('(hiccup->dom [:div "hello"])');
    assert(result.nodeType === 1, 'Should be element');
    assertEquals(result.tagName, 'DIV');
    assertEquals(result.textContent, 'hello');
  });

  await testAsync('hiccup with Hob-computed attrs', async () => {
    const result = await interp.eval('(hiccup->dom [:div {:class (str "a" "-" "b")} "x"])');
    assert(result.classList.contains('a-b'), 'Should have computed class');
  });

  await testAsync('hiccup with Hob-generated children', async () => {
    const result = await interp.eval('(hiccup->dom [:ul (map (fn [x] [:li x]) ["a" "b" "c"])])');
    assertEquals(result.children.length, 3);
    assertEquals(result.children[0].textContent, 'a');
    assertEquals(result.children[2].textContent, 'c');
  });

  await testAsync('prStr DOM node', async () => {
    const result = await interp.eval('(str (hiccup->dom [:div "hi"]))');
    assertEquals(result, '#<dom div>');
  });

  return getResults();
}

// Hob View Tests — def-view macro, view ops, and integration

export async function run(api) {
  const { createSuite, assert, assertEquals, assertDeepEquals } = await api.require('test-lib');
  const { test, testAsync, getResults } = createSuite('Hob Views');
  const hob = await api.require('hob-interpreter');

  // ============================================================
  // def-view macro tests
  // ============================================================

  await testAsync('def-view produces map', async () => {
    const interp = hob.createInterpreter(api);
    await interp.macrosReady;
    const result = await interp.eval(`
      (def-view my-view "some-type-id" [item api]
        [:div (:name item)])
    `);
    assert(result != null, 'Should return a map');
    assertEquals(result[hob.keyword('for-type')], 'some-type-id');
    assert(typeof result[hob.keyword('render')] === 'function', ':render should be a function');
  });

  await testAsync('def-view render is callable', async () => {
    const interp = hob.createInterpreter(api);
    await interp.macrosReady;
    await interp.eval(`
      (def-view test-view "type-id" [item api]
        [:div "rendered"])
    `);
    const result = await interp.eval('((:render test-view) {:name "Test"} nil)');
    assert(Array.isArray(result), 'render should return hiccup vector');
    assertEquals(result[1], 'rendered');
  });

  await testAsync('def-view render accesses item', async () => {
    const interp = hob.createInterpreter(api);
    await interp.macrosReady;
    await interp.eval(`
      (def-view name-view "type-id" [item api]
        [:h2 (:name item)])
    `);
    const result = await interp.eval('((:render name-view) {:name "Hello World"} nil)');
    assert(Array.isArray(result), 'Should be vector');
    assertEquals(result[1], 'Hello World');
  });

  // ============================================================
  // View ops tests (using registerViewOps directly)
  // ============================================================

  await testAsync('hiccup->dom in view context', async () => {
    const mockViewApi = {
      renderItem: async () => document.createElement('div'),
      navigate: () => {},
      rerenderItem: () => {},
    };
    const interp = hob.createInterpreter(api, mockViewApi);
    await interp.macrosReady;
    const result = await interp.eval('(hiccup->dom [:div "view"])');
    assert(result.nodeType === 1, 'Should be element');
    assertEquals(result.tagName, 'DIV');
    assertEquals(result.textContent, 'view');
  });

  await testAsync('navigate! is callable', async () => {
    let navigatedTo = null;
    const mockViewApi = {
      renderItem: async () => null,
      navigate: (id) => { navigatedTo = id; },
      rerenderItem: () => {},
    };
    const interp = hob.createInterpreter(api, mockViewApi);
    await interp.macrosReady;
    const result = await interp.eval('(navigate! "some-item-id")');
    assertEquals(result, null);
    assertEquals(navigatedTo, 'some-item-id');
  });

  await testAsync('rerender! is callable', async () => {
    let rerendered = false;
    const mockViewApi = {
      renderItem: async () => null,
      navigate: () => {},
      rerenderItem: () => { rerendered = true; },
    };
    const interp = hob.createInterpreter(api, mockViewApi);
    await interp.macrosReady;
    const result = await interp.eval('(rerender!)');
    assertEquals(result, null);
    assert(rerendered, 'rerenderItem should have been called');
  });

  await testAsync('render-item returns DOM', async () => {
    const mockDiv = document.createElement('div');
    mockDiv.textContent = 'rendered';
    const mockViewApi = {
      renderItem: async () => mockDiv,
      navigate: () => {},
      rerenderItem: () => {},
    };
    const interp = hob.createInterpreter(api, mockViewApi);
    await interp.macrosReady;
    const result = await interp.eval('(render-item "test-id")');
    assert(result.nodeType === 1, 'Should be DOM element');
    assertEquals(result.textContent, 'rendered');
  });

  // ============================================================
  // View rendering integration tests
  // ============================================================

  await testAsync('view renders item name', async () => {
    const interp = hob.createInterpreter(api);
    await interp.macrosReady;
    await interp.eval(`
      (def-view nv "type" [item api]
        [:div (:name item)])
    `);
    const hiccup = await interp.eval('((:render nv) {:name "My Item"} nil)');
    const dom = hob.hiccupToDOM(hiccup);
    assertEquals(dom.textContent, 'My Item');
  });

  await testAsync('view renders item content', async () => {
    const interp = hob.createInterpreter(api);
    await interp.macrosReady;
    await interp.eval(`
      (def-view cv "type" [item api]
        [:p (:description (:content item))])
    `);
    const hiccup = await interp.eval(`
      ((:render cv) {:name "Test" :content {:description "Hello desc"}} nil)
    `);
    const dom = hob.hiccupToDOM(hiccup);
    assertEquals(dom.tagName, 'P');
    assertEquals(dom.textContent, 'Hello desc');
  });

  await testAsync('view with conditional rendering', async () => {
    const interp = hob.createInterpreter(api);
    await interp.macrosReady;
    await interp.eval(`
      (def-view cond-view "type" [item api]
        (if (:active item) [:div "active"] [:div "inactive"]))
    `);
    const active = await interp.eval('((:render cond-view) {:active true} nil)');
    const inactive = await interp.eval('((:render cond-view) {:active false} nil)');
    assertEquals(hob.hiccupToDOM(active).textContent, 'active');
    assertEquals(hob.hiccupToDOM(inactive).textContent, 'inactive');
  });

  await testAsync('view with list rendering', async () => {
    const interp = hob.createInterpreter(api);
    await interp.macrosReady;
    await interp.eval(`
      (def-view list-view "type" [item api]
        [:ul (for [t (:tags item)] [:li t])])
    `);
    const hiccup = await interp.eval('((:render list-view) {:tags ["x" "y" "z"]} nil)');
    const dom = hob.hiccupToDOM(hiccup);
    assertEquals(dom.tagName, 'UL');
    assertEquals(dom.children.length, 3);
    assertEquals(dom.children[0].textContent, 'x');
    assertEquals(dom.children[2].textContent, 'z');
  });

  await testAsync('view event handler fires', async () => {
    const mockViewApi = {
      renderItem: async () => null,
      navigate: () => {},
      rerenderItem: () => {},
    };
    const interp = hob.createInterpreter(api, mockViewApi);
    await interp.macrosReady;
    const dom = await interp.eval(`
      (do
        (def clicks (atom 0))
        (hiccup->dom [:button {:on-click (fn [] (swap! clicks inc))} "Click"]))
    `);
    assertEquals(dom.tagName, 'BUTTON');
    dom.click();
    dom.click();
    // swap! is async — yield to microtask queue so both swaps complete
    await new Promise(r => setTimeout(r, 0));
    const count = await interp.eval('(deref clicks)');
    assertEquals(count, 2);
  });

  return getResults();
}

// Hob Watch Tests — def-watch macro, emit!, event ops, JS interop fix

