// Hob Reactivity Tests — selector-based reactivity, cycle detection

export async function run(api) {
  const { createSuite, assert, assertEquals } = await api.require('test-lib');
  const { test, testAsync, getResults } = createSuite('Hob Reactivity');
  const hob = await api.require('hob-interpreter');

  // ============================================================
  // get-item basics
  // ============================================================

  await testAsync('get-item returns an item', async () => {
    const interp = hob.createInterpreter(api);
    await interp.macrosReady;

    const result = await interp.eval('(get-item "00000000-0000-0000-0000-000000000000")');
    assert(result != null, 'Should return the item');
    assertEquals(result.id, '00000000-0000-0000-0000-000000000000');
  });

  // ============================================================
  // Selector registration via get-item :select
  // ============================================================

  await testAsync('get-item :select registers selectorInfo', async () => {
    const targetId = '00000000-0000-0000-0000-000000000000';
    // Simulate render context: set _renderItemId so get-item recognises "own item"
    const testApi = Object.create(api);
    testApi._renderItemId = targetId;
    testApi._selectorInfo = null;

    const interp = hob.createInterpreter(testApi);
    await interp.macrosReady;

    await interp.eval(`(get-item "${targetId}" :select (fn [item] (:name item)))`);
    assert(testApi._selectorInfo != null, 'selectorInfo should be set');
    assert(typeof testApi._selectorInfo.selector === 'function', 'Should have a selector function');
    assert('lastValue' in testApi._selectorInfo, 'Should have a lastValue');
  });

  await testAsync('get-item :select pins to first call', async () => {
    const targetId = '00000000-0000-0000-0000-000000000000';
    const testApi = Object.create(api);
    testApi._renderItemId = targetId;
    testApi._selectorInfo = null;

    const interp = hob.createInterpreter(testApi);
    await interp.macrosReady;

    // First call sets selectorInfo
    await interp.eval(`(get-item "${targetId}" :select (fn [item] (:name item)))`);
    const first = testApi._selectorInfo;
    assert(first != null, 'First call should set selectorInfo');

    // Second call should NOT overwrite
    await interp.eval(`(get-item "${targetId}" :select (fn [item] (:type item)))`);
    assert(testApi._selectorInfo === first, 'Second call should not overwrite first');
  });

  await testAsync('get-item without :select leaves selectorInfo null', async () => {
    const targetId = '00000000-0000-0000-0000-000000000000';
    const testApi = Object.create(api);
    testApi._renderItemId = targetId;
    testApi._selectorInfo = null;

    const interp = hob.createInterpreter(testApi);
    await interp.macrosReady;

    await interp.eval(`(get-item "${targetId}")`);
    assertEquals(testApi._selectorInfo, null, 'Should remain null without :select');
  });

  await testAsync('get-item :select ignores non-matching item', async () => {
    const targetId = '00000000-0000-0000-0000-000000000000';
    const otherId = '11111111-0000-0000-0000-000000000000';
    const testApi = Object.create(api);
    testApi._renderItemId = targetId;
    testApi._selectorInfo = null;

    const interp = hob.createInterpreter(testApi);
    await interp.macrosReady;

    // Request a different item with :select — should not register
    await interp.eval(`(get-item "${otherId}" :select (fn [item] (:name item)))`);
    assertEquals(testApi._selectorInfo, null, 'Should not register for non-matching item');
  });

  await testAsync('get-item :select computes lastValue', async () => {
    const targetId = '00000000-0000-0000-0000-000000000000';
    const testApi = Object.create(api);
    testApi._renderItemId = targetId;
    testApi._selectorInfo = null;

    const interp = hob.createInterpreter(testApi);
    await interp.macrosReady;

    // The atom type item's name is known
    const item = await api.get(targetId);
    await interp.eval(`(get-item "${targetId}" :select (fn [item] (:name item)))`);
    assertEquals(testApi._selectorInfo.lastValue, item.name, 'lastValue should be the selector result');
  });

  // ============================================================
  // Cycle detection (unit-level)
  // ============================================================

  test('re-render depth tracked per instance', () => {
    const depthMap = new Map();
    const MAX = 3;
    depthMap.set(1, 0);
    depthMap.set(1, (depthMap.get(1) || 0) + 1);
    assertEquals(depthMap.get(1), 1, 'Depth should increment');
    depthMap.set(1, (depthMap.get(1) || 0) + 1);
    assertEquals(depthMap.get(1), 2);
    depthMap.set(1, (depthMap.get(1) || 0) + 1);
    assertEquals(depthMap.get(1), 3);
    assert(depthMap.get(1) >= MAX, 'Should hit max');
  });

  test('exceeding max depth blocks re-render', () => {
    const MAX = 3;
    const depthMap = new Map();
    let blocked = false;
    for (let i = 0; i < 4; i++) {
      const depth = depthMap.get(1) || 0;
      if (depth >= MAX) {
        blocked = true;
        break;
      }
      depthMap.set(1, depth + 1);
    }
    assert(blocked, 'Should have been blocked after 3 increments');
  });

  test('depth counter resets after flush', () => {
    const depthMap = new Map();
    depthMap.set(1, 3);
    depthMap.set(2, 1);
    depthMap.clear();
    assertEquals(depthMap.get(1) || 0, 0, 'Depth should be 0 after clear');
    assertEquals(depthMap.get(2) || 0, 0, 'Depth should be 0 after clear');
  });

  return getResults();
}

// test-auto-runner — watches code changes, runs tests in headless nested instance

const TEST_RUN_COMPLETE_EVENT = 'e0e00000-0002-0003-0000-000000000000';
const TEST_RUN_RESULT_LIST_TYPE = '7e5700a1-0000-4000-8000-000000000000';
const SELF_ID = '7e5700b0-0000-4000-8000-000000000000';
const DEBOUNCE_MS = 2500;

export async function onViewportReady(event, api) {
  // Don't run in nested instances (test-runner-service handles that)
  if (api.getInstanceId()) return;

  scheduleTestRun(null, api);
}

export async function onItemUpdated({ item }, api) {
  // Don't run in nested instances
  if (api.getInstanceId()) return;

  scheduleTestRun({ id: item.id, name: item.name }, api);
}

async function scheduleTestRun(trigger, api) {
  // Write a unique token to the item — only the latest token wins
  const token = crypto.randomUUID();
  const self = await api.get(SELF_ID);
  self.content._pendingRunToken = token;
  self.content._pendingTrigger = trigger;
  await api.set(self, { silent: true });

  setTimeout(async () => {
    try {
      const current = await api.get(SELF_ID);
      if (current.content._pendingRunToken !== token) return; // stale
      if (!(await isEnabled(api))) return;
      await runTests(current.content._pendingTrigger, api);
    } catch (err) {
      console.warn('test-auto-runner: run failed', err);
    }
  }, DEBOUNCE_MS);
}

async function isEnabled(api) {
  // Check if any test-run-result-list item has autoRunEnabled set to false
  // Default: enabled (true) if no list item exists or flag is not set
  const allItems = await api.getAll();
  const listItem = allItems.find(i => i.type === TEST_RUN_RESULT_LIST_TYPE);
  if (!listItem) return true;
  return listItem.content?.autoRunEnabled !== false;
}

async function runTests(trigger, api) {
  const instanceId = crypto.randomUUID();
  const { populate } = await api.require('hobson-instance-lib');

  // Populate the nested instance with all current items
  const allItems = await api.getAll();
  await populate(instanceId, allItems);

  // Create hidden iframe
  const path = window.location.pathname;
  const src = path + '?instance=' + encodeURIComponent(instanceId);

  const iframe = document.createElement('iframe');
  iframe.style.cssText = 'position:absolute;left:-9999px;top:-9999px;width:1px;height:1px;opacity:0;pointer-events:none;';
  iframe.src = src;
  document.body.appendChild(iframe);

  try {
    // Wait for test-complete message from nested instance
    const result = await new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        window.removeEventListener('message', listener);
        reject(new Error('Test run timed out after 60s'));
      }, 60000);

      function listener(e) {
        if (e.data?.instanceId !== instanceId) return;
        if (e.data.type === 'test-complete') {
          clearTimeout(timeout);
          window.removeEventListener('message', listener);
          resolve(e.data.lastRun);
        } else if (e.data.type === 'test-error') {
          clearTimeout(timeout);
          window.removeEventListener('message', listener);
          reject(new Error(e.data.error || 'Test instance error'));
        }
      }
      window.addEventListener('message', listener);
    });

    // Emit test:run-complete event with results
    api.events.emit({
      type: TEST_RUN_COMPLETE_EVENT,
      content: {
        timestamp: result.timestamp,
        totalPassed: result.totalPassed,
        totalFailed: result.totalFailed,
        suites: result.suites,
        trigger: trigger
      }
    });

  } finally {
    // Clean up iframe
    if (iframe.parentNode) iframe.remove();

    // Clean up instance data from IndexedDB
    try {
      await api.deleteByPrefix(instanceId + ':');
    } catch (cleanupErr) {
      console.warn('test-auto-runner: cleanup failed', cleanupErr);
    }
  }
}

// test-result-handler — creates result items and shows toast on test completion

const TEST_RUN_RESULT_TYPE = '7e5700a0-0000-4000-8000-000000000000';
const TEST_RUN_RESULT_LIST_TYPE = '7e5700a1-0000-4000-8000-000000000000';

export async function onTestRunComplete({ timestamp, totalPassed, totalFailed, suites, trigger }, api) {
  try {
    const resultId = crypto.randomUUID();
    const triggerLabel = trigger ? `[${trigger.name || trigger.id.slice(0, 8)}] ` : '';
    const status = totalFailed === 0 ? 'PASS' : 'FAIL';

    await api.set({
      id: resultId,
      type: TEST_RUN_RESULT_TYPE,
      name: `Test Run: ${triggerLabel}${status} (${totalPassed}/${totalPassed + totalFailed})`,
      created: Date.now(),
      modified: Date.now(),
      attachments: [],
      content: {
        timestamp,
        totalPassed,
        totalFailed,
        suites,
        trigger
      }
    });

    // Re-render any visible test-run-result-list views
    try {
      const vpMgr = await api.require('viewport-manager');
      await vpMgr.getRendering().rerenderByType(TEST_RUN_RESULT_LIST_TYPE);
    } catch (e) {
      // viewport-manager may not be loaded yet on first boot
    }

    showTestToast(totalPassed, totalFailed, trigger, resultId, api);
  } catch (err) {
    console.error('test-result-handler failed:', err);
  }
}

function showTestToast(passed, failed, trigger, resultId, api) {
  const existing = document.querySelector('.test-toast');
  if (existing) existing.remove();

  const allPassed = failed === 0;
  const total = passed + failed;
  const triggerLabel = trigger ? (trigger.name || trigger.id.slice(0, 8)) : 'boot';

  const toast = api.createElement('div', {}, []);
  toast.className = 'test-toast';
  toast.style.cssText = `
    position: fixed;
    bottom: 20px;
    right: 20px;
    background: ${allPassed ? 'var(--color-success, #22c55e)' : 'var(--color-danger, #ef4444)'};
    color: white;
    padding: 16px;
    border-radius: var(--border-radius);
    box-shadow: var(--shadow-md);
    max-width: 400px;
    z-index: 2147483647;
    cursor: pointer;
    font-family: system-ui, sans-serif;
  `;

  const icon = allPassed ? '&#10003;' : '&#10007;';
  const title = allPassed ? 'All Tests Passed' : `${failed} Test${failed !== 1 ? 's' : ''} Failed`;

  toast.innerHTML = `
    <div style="display: flex; gap: 12px; align-items: start;">
      <span style="font-size: 1.5rem;">${icon}</span>
      <div style="flex: 1;">
        <strong>${title}</strong>
        <p style="margin: 4px 0 0 0; font-size: 0.875rem;">${passed}/${total} passed</p>
        <p style="margin: 4px 0 0 0; font-size: 0.75rem; opacity: 0.8;">Triggered by: ${triggerLabel}</p>
      </div>
    </div>
  `;

  toast.onclick = async () => {
    toast.remove();
    try {
      const vpMgr = await api.require('viewport-manager');
      const currentRoot = vpMgr.getRoot();
      if (currentRoot) {
        await api.attach(currentRoot, resultId);
        await vpMgr.getRendering().renderViewport();
      } else {
        await vpMgr.navigate(resultId);
      }
    } catch (e) {
      console.warn('test-result-handler: navigate failed', e);
    }
  };

  document.body.appendChild(toast);

  // Auto-dismiss: 5s for pass, 10s for fail
  const dismissTime = allPassed ? 5000 : 10000;
  setTimeout(() => {
    if (toast.parentNode) toast.remove();
  }, dismissTime);
}

// test-run-result-view — renders a single test run result

export async function render(item, api) {
  const content = item.content || {};
  const totalPassed = content.totalPassed || 0;
  const totalFailed = content.totalFailed || 0;
  const total = totalPassed + totalFailed;
  const suites = content.suites || [];
  const trigger = content.trigger;
  const allPassed = totalFailed === 0;

  const container = api.createElement('div');
  container.style.cssText = 'font-family: system-ui, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px;';

  // Header with pass/fail indicator
  const header = api.createElement('div');
  const borderColor = allPassed ? 'var(--color-success, #22c55e)' : 'var(--color-danger, #ef4444)';
  const bgColor = allPassed ? 'var(--color-success-light, #e8f5e9)' : 'var(--color-danger-light, #fef2f2)';
  header.style.cssText = `padding: 16px; margin-bottom: 16px; border-left: 4px solid ${borderColor}; background: ${bgColor};`;

  const headerRow = api.createElement('div');
  headerRow.style.cssText = 'display: flex; align-items: start; gap: 12px;';

  const icon = api.createElement('span');
  icon.style.cssText = 'font-size: 2rem;';
  icon.textContent = allPassed ? '\u2713' : '\u2717';
  headerRow.appendChild(icon);

  const info = api.createElement('div');
  info.style.cssText = 'flex: 1;';

  const summary = api.createElement('div');
  summary.style.cssText = 'font-size: 1.125rem; font-weight: 600; margin-bottom: 4px;';
  summary.textContent = `${totalPassed}/${total} tests passed`;
  info.appendChild(summary);

  const date = api.createElement('div');
  date.style.cssText = 'font-size: 0.75rem; color: var(--color-text-secondary);';
  date.textContent = item.created ? new Date(item.created).toLocaleString() : '';
  info.appendChild(date);

  if (trigger) {
    const triggerEl = api.createElement('div');
    triggerEl.style.cssText = 'font-size: 0.75rem; color: var(--color-text-secondary); margin-top: 2px;';
    const triggerName = trigger.name || trigger.id;
    triggerEl.textContent = `Triggered by: ${triggerName}`;
    if (trigger.id) {
      triggerEl.style.cursor = 'pointer';
      triggerEl.style.color = 'var(--color-primary)';
      triggerEl.onclick = (e) => api.openItem(e, trigger.id);
    }
    info.appendChild(triggerEl);
  }

  headerRow.appendChild(info);
  header.appendChild(headerRow);
  container.appendChild(header);

  // Per-suite breakdown
  if (suites.length > 0) {
    const suitesHeader = api.createElement('h4');
    suitesHeader.style.cssText = 'margin: 0 0 8px 0;';
    suitesHeader.textContent = 'Suites';
    container.appendChild(suitesHeader);

    for (const suite of suites) {
      const suiteEl = api.createElement('div');
      const suiteFailed = (suite.failed || 0) > 0;
      const suiteBg = suiteFailed ? 'var(--color-danger-light, #fef2f2)' : 'var(--color-bg-hover)';
      suiteEl.style.cssText = `padding: 8px 12px; margin-bottom: 4px; border-radius: var(--border-radius); background: ${suiteBg};`;

      const suiteHeader = api.createElement('div');
      suiteHeader.style.cssText = 'display: flex; justify-content: space-between; align-items: center; cursor: pointer;';

      const suiteName = api.createElement('span');
      suiteName.style.cssText = 'font-weight: 500;';
      suiteName.textContent = suite.testItemName || 'Unknown';
      if (suite.testItemId) {
        suiteName.style.cursor = 'pointer';
        suiteName.style.color = 'var(--color-primary)';
        suiteName.onclick = (e) => api.openItem(e, suite.testItemId);
      }
      suiteHeader.appendChild(suiteName);

      const suiteCount = api.createElement('span');
      suiteCount.style.cssText = 'font-size: 0.875rem;';
      suiteCount.style.color = suiteFailed ? 'var(--color-danger, #ef4444)' : 'var(--color-success, #22c55e)';
      suiteCount.textContent = `${suite.passed || 0}/${(suite.passed || 0) + (suite.failed || 0)}`;
      suiteHeader.appendChild(suiteCount);

      suiteEl.appendChild(suiteHeader);

      // Individual test results (collapsed for passing, expanded for failing)
      const results = suite.results || [];
      if (results.length > 0) {
        const details = api.createElement('div');
        details.style.cssText = 'margin-top: 4px; font-size: 0.75rem;';
        details.style.display = suiteFailed ? 'block' : 'none';

        suiteHeader.onclick = (e) => {
          if (e.target === suiteName && suite.testItemId) return;
          details.style.display = details.style.display === 'none' ? 'block' : 'none';
        };

        for (const r of results) {
          const line = api.createElement('div');
          line.style.cssText = 'padding: 2px 0;';
          const rIcon = r.passed ? '\u2713 ' : '\u2717 ';
          const rColor = r.passed ? 'var(--color-success, #22c55e)' : 'var(--color-danger, #ef4444)';
          line.style.color = rColor;
          line.textContent = rIcon + r.name;

          if (!r.passed && r.error) {
            const errMsg = api.createElement('div');
            errMsg.style.cssText = 'color: var(--color-text-secondary); padding-left: 16px; font-family: var(--font-mono, monospace); font-size: 0.6875rem; white-space: pre-wrap; word-break: break-all;';
            errMsg.textContent = r.error;
            line.appendChild(errMsg);
          }

          details.appendChild(line);
        }

        suiteEl.appendChild(details);
      }

      container.appendChild(suiteEl);
    }
  }

  // Actions
  const actions = api.createElement('div');
  actions.style.cssText = 'display: flex; gap: 8px; margin-top: 16px;';

  const deleteBtn = api.createElement('button');
  deleteBtn.style.cssText = 'padding: 8px 16px; cursor: pointer; color: var(--color-danger);';
  deleteBtn.textContent = 'Delete';
  deleteBtn.onclick = async () => {
    const modalLib = await api.require('modal-lib');
    if (await modalLib.confirm({
      message: 'Delete this test result?',
      title: 'Delete Test Result',
      confirmText: 'Delete',
      confirmStyle: 'danger',
      api
    })) {
      await api.delete(item.id);
    }
  };
  actions.appendChild(deleteBtn);

  container.appendChild(actions);
  return container;
}

