// web-clipper — handles Android share intents (ACTION_SEND / text/plain)
//
// Two paths to receiving a URL:
//   Already running: Kotlin injects window.__pendingShareUrl via evaluateJavascript and
//                    dispatches 'hobson-check-share'. No file read needed.
//   Cold launch: Kotlin wrote pending_share.txt to cacheDir before Hobson started;
//                consume_pending_share() reads and deletes it on boot.

let api = null;

export async function onViewportReady(_payload, _api) {
  api = _api;

  if (!window.__TAURI__) return;

  await checkPendingShare();
  window.addEventListener('hobson-check-share', onCheckShare);
}

async function onCheckShare() {
  const url = window.__pendingShareUrl;
  if (url) {
    delete window.__pendingShareUrl;
    await showShareDialog(url);
    return;
  }
  await checkPendingShare();
}

async function checkPendingShare() {
  try {
    const url = await window.__TAURI__.core.invoke('consume_pending_share');
    if (url) await showShareDialog(url);
  } catch (e) {
    console.error('[web-clipper] consume_pending_share failed:', e);
  }
}

async function showShareDialog(url) {
  const modalLib = await api.require('modal-lib');
  const searchLib = await api.require('item-search-lib');

  const container = document.createElement('div');

  const urlDisplay = document.createElement('div');
  urlDisplay.style.cssText = 'padding: 8px 12px; margin-bottom: 12px; background: var(--color-bg-surface); border: 1px solid var(--color-border-light); border-radius: var(--border-radius); font-size: 0.8125rem; color: var(--color-text-secondary); word-break: break-all;';
  urlDisplay.textContent = url;
  container.appendChild(urlDisplay);

  const searchArea = document.createElement('div');
  container.appendChild(searchArea);

  const { close } = modalLib.showModal({
    title: 'Save URL to...',
    width: '600px',
    maxHeight: '80vh',
    api,
    content: container
  });

  searchLib.createSearchUI(
    searchArea,
    async (selectedItem) => {
      close();
      await appendUrlToItem(selectedItem.id, url);
    },
    api,
    { placeholder: 'Search for an item...', autoFocus: true }
  );
}

async function appendUrlToItem(itemId, url) {
  const item = await api.get(itemId);
  if (!item.content) item.content = {};

  const linkParagraph = [':p', [':link', { s: url }, { s: url }]];

  if (Array.isArray(item.content.description) && item.content.description[0] === ':doc') {
    item.content.description = [...item.content.description, linkParagraph];
  } else {
    item.content.description = [':doc', [':p', { s: '' }], linkParagraph];
  }

  item.modified = Date.now();
  await api.set(item);
}

export function cleanup() {
  window.removeEventListener('hobson-check-share', onCheckShare);
}

export async function render(item, api) {
  const history = item.content?.history ?? {};
  const labels = Object.keys(history);

  const container = api.createElement('div');
  container.style.cssText = 'padding: 16px;';

  const heading = api.createElement('h2');
  heading.textContent = item.name;
  heading.style.cssText = 'margin: 0 0 16px 0;';
  container.appendChild(heading);

  if (labels.length === 0) {
    const empty = api.createElement('p');
    empty.textContent = 'No history recorded yet.';
    empty.style.cssText = 'color: var(--color-text-secondary);';
    container.appendChild(empty);
    return container;
  }

  // Collect all unique timestamps across all series, sorted descending
  const tsSet = new Set();
  for (const label of labels) {
    for (const { t } of history[label]) tsSet.add(t);
  }
  const timestamps = [...tsSet].sort((a, b) => b - a);

  // Build index: label -> Map(t -> v) for O(1) lookup
  const index = {};
  for (const label of labels) {
    index[label] = new Map(history[label].map(({ t, v }) => [t, v]));
  }

  const formatDate = (t) => new Date(t).toISOString(); //.slice(0, 10);

  const formatValue = (v) => {
    if (v == null) return '\u2014';
    if (typeof v === 'number') return v.toLocaleString('en-GB', { maximumFractionDigits: 2 });
    if (typeof v === 'object') return JSON.stringify(v);
    return String(v);
  };

  const s = {
    table: 'width: 100%; border-collapse: collapse; font-size: 0.875rem;',
    th: 'padding: 8px 12px; text-align: right; border-bottom: 2px solid var(--color-border); font-weight: 600; white-space: nowrap;',
    thDate: 'padding: 8px 12px; text-align: left; border-bottom: 2px solid var(--color-border); font-weight: 600;',
    td: 'padding: 6px 12px; text-align: right; border-bottom: 1px solid var(--color-border); font-variant-numeric: tabular-nums;',
    tdDate: 'padding: 6px 12px; text-align: left; border-bottom: 1px solid var(--color-border); color: var(--color-text-secondary);',
  };

  const table = api.createElement('table');
  table.style.cssText = s.table;

  const thead = api.createElement('thead');
  const headerRow = api.createElement('tr');
  const dateTh = api.createElement('th');
  dateTh.textContent = 'Date';
  dateTh.style.cssText = s.thDate;
  headerRow.appendChild(dateTh);
  for (const label of labels) {
    const th = api.createElement('th');
    th.textContent = label;
    th.style.cssText = s.th;
    headerRow.appendChild(th);
  }
  thead.appendChild(headerRow);
  table.appendChild(thead);

  const tbody = api.createElement('tbody');
  for (const t of timestamps) {
    const row = api.createElement('tr');
    const dateTd = api.createElement('td');
    dateTd.textContent = formatDate(t);
    dateTd.style.cssText = s.tdDate;
    row.appendChild(dateTd);
    for (const label of labels) {
      const td = api.createElement('td');
      const v = index[label].get(t);
      td.textContent = v !== undefined ? formatValue(v) : '\u2014';
      td.style.cssText = s.td;
      row.appendChild(td);
    }
    tbody.appendChild(row);
  }
  table.appendChild(tbody);
  container.appendChild(table);

  return container;
}

