    if (scrollToSymbol && !lineRange) {
      const currentItem = api.getCurrentItem();
      const symbols = currentItem?.content?._symbols || {};
      // Try exact match first, then unqualified match
      let symbolInfo = symbols[scrollToSymbol];
      if (!symbolInfo) {
        for (const [key, info] of Object.entries(symbols)) {
          if (info.name === scrollToSymbol) {
            symbolInfo = info;
            break;
          }
        }
      }
      if (symbolInfo) {
        lineRange = { start: symbolInfo.line, end: symbolInfo.endLine };
      }
    }

    // Fallback to URL params for backward compatibility
    if (!lineRange) {
      const urlParams = new URLSearchParams(window.location.search);
      const urlLines = urlParams.get('lines');
      if (urlLines) {
        lineRange = parseLines(urlLines);
      }
    }

    if (lineRange) {
      // CodeMirror uses 0-based line numbers
      const startLine = lineRange.start - 1;
      const endLine = lineRange.end - 1;

      // Scroll first line into view
      cm.scrollIntoView({ line: startLine, ch: 0 }, 100);

      // Add CSS for highlight if not present
      if (!document.getElementById('line-highlight-css')) {
        const style = document.createElement('style');
        style.id = 'line-highlight-css';
        style.textContent = '.line-highlight { background: var(--color-warning-light) !important; }';
        document.head.appendChild(style);
      }

      // Highlight all lines in range
      for (let i = startLine; i <= endLine; i++) {
        cm.addLineClass(i, 'background', 'line-highlight');
      }
    }
  };

  // Use IntersectionObserver to refresh CodeMirror when visible
  const observer = new IntersectionObserver((entries) => {
    for (const entry of entries) {
      if (entry.isIntersecting) {
        cm.refresh();
        processCommentLinks();
        navigateToTarget();
        observer.disconnect();
        break;
      }
    }
  }, { threshold: 0.1 });
  observer.observe(editorContainer);

  // Also refresh on first click as fallback
  const clickHandler = () => {
    cm.refresh();
    processCommentLinks();
    navigateToTarget();
    editorContainer.removeEventListener('click', clickHandler);
  };
  editorContainer.addEventListener('click', clickHandler);

  // Register cleanup handler for DOM removal (prevents CodeMirror memory leaks)
  wrapper.setAttribute('data-hobson-cleanup', '');
  wrapper.__hobsonCleanup = () => {
    observer.disconnect();
  };

  // Re-process links when viewport changes (scroll/resize)
  cm.on('viewportChange', () => {
    requestAnimationFrame(processCommentLinks);
  });

  return wrapper;
}
// [END:render]

export function render(value, onChange, api, options = {}) {
  const input = api.createElement('input', {}, []);
  input.type = 'text';
  input.value = value || '';
  input.placeholder = options.placeholder || '';
  input.style.cssText = 'width: 100%; padding: 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); font-size: 0.875rem;';

  if (options.readonly) {
    input.readOnly = true;
    input.style.background = 'var(--color-bg-body)';
  }

  input.addEventListener('input', (e) => {
    onChange(e.target.value);
  });

  return input;
}

// Tag Tree Builder Library
// Shared logic for building hierarchical tag trees

/**
 * Builds a hierarchical tree structure from a flat list of tag items
 * @param {Array} tags - Flat array of tag items
 * @returns {Array} Root nodes of the tree, each with a children array
 */
export function buildTagTree(tags) {
  // Create map of tags by ID for quick lookup
  const tagMap = new Map();
  tags.forEach(tag => tagMap.set(tag.id, { ...tag, children: [] }));

  // Separate root and child tags
  const roots = [];
  tags.forEach(tag => {
    const parent = tag.content.parent;
    if (!parent) {
      // Root tag (no parent)
      roots.push(tagMap.get(tag.id));
    } else {
      // Child tag - add to parent's children array
      const parentNode = tagMap.get(parent);
      if (parentNode) {
        parentNode.children.push(tagMap.get(tag.id));
      } else {
        // Parent not found - treat as root
        roots.push(tagMap.get(tag.id));
      }
    }
  });

  // Sort all nodes by name (case-insensitive)
  const sortByName = (a, b) => {
    const nameA = (a.content.name || a.name || a.id).toLowerCase();
    const nameB = (b.content.name || b.name || b.id).toLowerCase();
    return nameA.localeCompare(nameB);
  };

  roots.sort(sortByName);
  tagMap.forEach(node => node.children.sort(sortByName));

  return roots;
}

/**
 * Gets display name for a tag node
 * @param {Object} tagNode - Tag node from tree
 * @returns {string} Display name
 */
export function getTagName(tagNode) {
  return tagNode.content.name || tagNode.name || tagNode.id;
}

/**
 * Gets fully-qualified tag name by walking up the parent chain
 * @param {string} tagId - Tag item ID
 * @param {Object} api - Hobson API (needs api.get)
 * @param {string} [stopAtId] - Optional ancestor ID to stop before (for relative paths)
 * @returns {Promise<string>} Fully-qualified name like "Root / Child / Grandchild"
 */
export async function getFullyQualifiedName(tagId, api, stopAtId) {
  const parts = [];
  let currentId = tagId;
  const seen = new Set();
  while (currentId) {
    if (currentId === stopAtId) break;
    if (seen.has(currentId)) break;
    seen.add(currentId);
    let item;
    try { item = await api.get(currentId); } catch (e) { break; }
    if (!item) break;
    parts.unshift(item.content?.name || item.name || currentId.substring(0, 8));
    currentId = item.content?.parent;
  }
  return parts.join(' / ');
}

/**
 * Gets color for a tag node
 * @param {Object} tagNode - Tag node from tree
 * @returns {string} Hex color code
 */
export function getTagColor(tagNode) {
  return tagNode.content.color || '#3b82f6';
}

const HOBSON_INSTANCE_TYPE = '99999999-0000-0000-0000-000000000000';

/**
 * Create a nested Hobson instance, populate it, open it, and return a handle.
 *
 * Item selection (pick one, checked in this order):
 *   options.items  — explicit array of items
 *   options.filter — predicate (item) => boolean applied to api.getAll()
 *   (default)      — all items from api.getAll()
 *
 * Other options:
 *   options.name    — instance item name (default: 'Hobson Instance')
 *   options.timeout — boot timeout in ms (default: 30000)
 */
export async function create(api, options = {}) {
  const id = crypto.randomUUID();
  const name = options.name || 'Hobson Instance';
  const timeout = options.timeout || 30000;

  // Resolve items to populate
  let items;
  if (options.items) {
    items = options.items;
  } else if (options.filter) {
    const all = await api.getAll();
    items = all.filter(options.filter);
  } else {
    items = await api.getAll();
  }

  // Populate IndexedDB namespace
  await populate(id, items);

  // Create the instance item and open it
  await api.set({
    id,
    name,
    type: HOBSON_INSTANCE_TYPE,
    content: {},
    attachments: []
  }, { silent: true });

  const parentId = api.getParentId();
  if (parentId) {
    await api.attach(parentId, id);
  } else {
    api.navigate(id);
  }

  // Build and return the handle
  return {
    id,

    onMessage(type, handler) {
      function listener(e) {
        if (e.data?.type === type && e.data?.instanceId === id) {
          handler(e.data);
        }
      }
      window.addEventListener('message', listener);
      return () => window.removeEventListener('message', listener);
    },

    waitForMessage(type, msgTimeout) {
      const t = msgTimeout || timeout;
      return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          window.removeEventListener('message', listener);
          reject(new Error(`Timed out waiting for ${type}`));
        }, t);

        function listener(e) {
          if (e.data?.type === type && e.data?.instanceId === id) {
            clearTimeout(timer);
            window.removeEventListener('message', listener);
            resolve(e.data);
          }
        }

        window.addEventListener('message', listener);
      });
    },

    async destroy() {
      await api.delete(id);
    }
  };
}

/**
 * Low-level: write items into a nested instance's IndexedDB namespace.
 * Bypasses the kernel to avoid side effects.
 */
export async function populate(instanceId, items) {
  const db = await new Promise((resolve, reject) => {
    const req = indexedDB.open('hobson');
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });

  const prefix = `${instanceId}:`;

  // Copy items
  const itemTx = db.transaction('items', 'readwrite');
  const itemStore = itemTx.objectStore('items');
  for (const item of items) {
    itemStore.put({ ...item, id: prefix + item.id });
  }
  await new Promise((resolve, reject) => {
    itemTx.oncomplete = resolve;
    itemTx.onerror = () => reject(itemTx.error);
  });

  // Copy blobs for these items (blob ID mirrors item ID)
  const itemIds = new Set(items.map(item => item.id));
  const allBlobs = await new Promise((resolve, reject) => {
    const tx = db.transaction('blobs', 'readonly');
    const req = tx.objectStore('blobs').getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  const blobsToCopy = allBlobs.filter(entry => itemIds.has(entry.id));

  if (blobsToCopy.length > 0) {
    const blobTx = db.transaction('blobs', 'readwrite');
    const blobStore = blobTx.objectStore('blobs');
    for (const entry of blobsToCopy) {
      blobStore.put({ id: prefix + entry.id, blob: entry.blob });
    }
    await new Promise((resolve, reject) => {
      blobTx.oncomplete = resolve;
      blobTx.onerror = () => reject(blobTx.error);
    });
  }

  db.close();
}

// iframe-nav-tracker — synchronous pushState patching for iframe navigation depth tracking
//
// Hob functions are always async, but browsers reject async calls to
// History.pushState as insecure. This library provides a synchronous JS
// wrapper that patches pushState inside an iframe's contentWindow.
//
// Uses replaceState + renderViewport() instead of history.back() because
// the viewport-manager's popstate handler doesn't handle back-to-no-root.

/**
 * Patch pushState on an iframe to track navigation depth.
 * Call this from the iframe's onload handler.
 *
 * Returns an object with:
 *   - depth()  — current navigation depth (0 = at initial page)
 *   - back()   — go back if depth > 0; returns true if navigated
 *   - reset()  — reset depth to 0 (call on iframe reload)
 *
 * Returns null if the iframe's contentWindow is inaccessible (cross-origin).
 */
export function patch(iframe) {
  // Stack of URLs before each pushState — used for back navigation
  const urlStack = [];

  try {
    const iframeHistory = iframe.contentWindow.history;
    const origPushState = iframeHistory.pushState.bind(iframeHistory);
    iframeHistory.pushState = function(...args) {
      // Capture current URL before the push so we can go back to it
      urlStack.push(iframe.contentWindow.location.href);
      return origPushState(...args);
    };
  } catch (e) {
    return null;
  }

  return {
    depth() { return urlStack.length; },
    back() {
      if (urlStack.length > 0) {
        const prevUrl = urlStack.pop();
        // Replace current URL with the previous one (no new history entry)
        iframe.contentWindow.history.replaceState(null, '', prevUrl);
        // Tell the nested kernel to re-render from the updated URL
        iframe.contentWindow.kernel.renderViewport();
        return true;
      }
      return false;
    },
    reset() { urlStack.length = 0; }
  };
}

// Script View - Renders script items
// See [Views & Rendering](item://a0a0a0a0-d0c0-4000-8000-000000000004)

// [BEGIN:render]
export async function render(item, api) {
  const container = api.createElement('div', { style: 'padding: 15px;' }, []);

  // Header
  const header = api.createElement('h3', { style: 'margin-top: 0;' }, [
    item.name || 'Untitled Script'
  ]);
  container.appendChild(header);

  // Description
  if (item.content.description) {
    const desc = api.createElement('p', { style: 'color: var(--color-text-secondary); font-style: italic;' }, [
      item.content.description
    ]);
    container.appendChild(desc);
  }

  // Code display
  const code = api.createElement('pre', {
    style: `
      background: var(--color-bg-surface-alt);
      padding: 15px;
      border-radius: var(--border-radius);
      border: 1px solid var(--color-border-light);
      overflow-x: auto;
      font-family: 'SF Mono', Monaco, monospace;
      font-size: 0.8125rem;
      line-height: 1.5;
    `
  }, [item.content.code || '// No code']);
  container.appendChild(code);

  // Buttons
  const buttons = api.createElement('div', { 
    style: 'margin-top: 15px; display: flex; gap: 10px;' 
  }, []);

  const runBtn = api.createElement('button', {
    style: 'padding: 10px 20px; cursor: pointer; background: var(--color-primary); color: white; border: none; border-radius: var(--border-radius); font-weight: 500;',
    onclick: async () => {
      runBtn.disabled = true;
      runBtn.textContent = 'Running...';

      try {
        // Get the REPL API which has the helper functions
        const replApi = api.createREPLContext();

        // Execute the script code with REPL API
        const asyncFn = new Function('api', `
          return (async () => {
            ${item.content.code}
          })();
        `);

        const result = await asyncFn(replApi);
        alert('Script executed!\n\nResult: ' + (
          result !== undefined 
            ? JSON.stringify(result, null, 2) 
            : 'No return value'
        ));
      } catch (error) {
        alert('Error executing script:\n\n' + error.message);
      } finally {
        runBtn.disabled = false;
        runBtn.textContent = 'Run Script';
      }
    }
  }, ['Run Script']);
  buttons.appendChild(runBtn);

  const editBtn = api.createElement('button', {
    style: 'padding: 10px 20px; cursor: pointer;',
    onclick: () => {
      // Navigate to raw editor for this item
      api.editRaw(item.id);
    }
  }, ['Edit']);
  buttons.appendChild(editBtn);

  const copyBtn = api.createElement('button', {
    style: 'padding: 10px 20px; cursor: pointer;',
    onclick: () => {
      navigator.clipboard.writeText(item.content.code);
      copyBtn.textContent = 'Copied!';
      setTimeout(() => copyBtn.textContent = 'Copy Code', 1000);
    }
  }, ['Copy Code']);
  buttons.appendChild(copyBtn);

  container.appendChild(buttons);

  return container;
}
// [END:render]

