// Kernel Export Library
// Exports starter packs based on starter-pack/* tags

const TAG_IDS = {
  BARE: 'aaaa0001-0001-0000-0000-000000000000',
  BASIC: 'aaaa0001-0002-0000-0000-000000000000',
  ALL: 'aaaa0001-0003-0000-0000-000000000000'
};

const TIER_TAGS = {
  bare: [TAG_IDS.BARE],
  basic: [TAG_IDS.BARE, TAG_IDS.BASIC],
  all: [TAG_IDS.BARE, TAG_IDS.BASIC, TAG_IDS.ALL]
};

const FILENAMES = {
  bare: 'initial-kernel.json',
  basic: 'starter-basic.json',
  all: 'starter-all.json'
};

/**
 * Collect items for a given tier
 * @param {'bare'|'basic'|'all'} tier - The tier to collect
 * @param {object} api - The Hobson API object
 * @returns {Promise<Array>} Array of items to export
 */
export async function collect(tier, api) {
  if (!api) {
    // Allow calling from REPL where api is global
    api = window.kernel?.createAPI();
  }

  if (!TIER_TAGS[tier]) {
    throw new Error(`Unknown tier: ${tier}. Use 'bare', 'basic', or 'all'.`);
  }

  const tagIds = TIER_TAGS[tier];
  const allItems = await api.getAll();

  // Filter items that have any of the tier's tags
  const items = allItems.filter(item => {
    const itemTags = item.tags || [];
    return tagIds.some(tagId => itemTags.includes(tagId));
  });

  // Always include the starter-pack tags themselves so importing works
  const tagTypeId = 'd1da8525-b0dc-4a79-8bef-0cbed1ed003d';
  const starterPackParentId = 'aaaa0001-0000-0000-0000-000000000000';

  // Add parent tag and tier tags if not already included
  const idsToInclude = new Set(items.map(i => i.id));
  idsToInclude.add(starterPackParentId);
  tagIds.forEach(id => idsToInclude.add(id));

  // Also include the tag type definition itself
  idsToInclude.add(tagTypeId);

  // Re-filter to get the complete set
  const result = allItems.filter(item => idsToInclude.has(item.id));

  // Sort by type chain order (types before instances) for clean import
  return sortForExport(result);
}

/**
 * Sort items so types come before their instances
 */
function sortForExport(items) {
  const itemMap = new Map(items.map(i => [i.id, i]));
  const itemIds = new Set(items.map(i => i.id));

  // Build dependency graph
  const dependsOn = new Map();

  for (const item of items) {
    const deps = [];

    // Type dependency
    if (item.type && itemIds.has(item.type) && item.type !== item.id) {
      deps.push(item.type);
    }

    // Extends dependency
    if (item.extends && itemIds.has(item.extends) && item.extends !== item.id) {
      deps.push(item.extends);
    }

    dependsOn.set(item.id, deps);
  }

  // Topological sort (Kahn's algorithm)
  const mustComeBefore = new Map();
  const inDegree = new Map();

  for (const item of items) {
    inDegree.set(item.id, dependsOn.get(item.id).length);

    for (const dep of dependsOn.get(item.id)) {
      if (!mustComeBefore.has(dep)) mustComeBefore.set(dep, []);
      mustComeBefore.get(dep).push(item.id);
    }
  }

  const queue = [];
  for (const [id, degree] of inDegree) {
    if (degree === 0) queue.push(id);
  }

  const result = [];
  while (queue.length > 0) {
    const id = queue.shift();
    result.push(itemMap.get(id));

    for (const dependent of (mustComeBefore.get(id) || [])) {
      const newDegree = inDegree.get(dependent) - 1;
      inDegree.set(dependent, newDegree);
      if (newDegree === 0) {
        queue.push(dependent);
      }
    }
  }

  // Handle cycles: append remaining
  if (result.length < items.length) {
    const resultIds = new Set(result.map(i => i.id));
    for (const item of items) {
      if (!resultIds.has(item.id)) {
        result.push(item);
      }
    }
  }

  return result;
}

/**
 * Download a starter pack as a JSON file
 * @param {'bare'|'basic'|'all'} tier - The tier to export
 * @param {object} api - The Hobson API object
 */
export async function download(tier, api) {
  if (!api) {
    api = window.kernel?.createAPI();
  }

  const items = await collect(tier, api);
  const filename = FILENAMES[tier];

  const json = JSON.stringify(items, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);

  console.log(`Downloaded ${filename} with ${items.length} items`);
  return { filename, count: items.length };
}

/**
 * List items in each tier with counts
 * @param {object} api - The Hobson API object
 */
export async function summary(api) {
  if (!api) {
    api = window.kernel?.createAPI();
  }

  const result = {};

  for (const tier of ['bare', 'basic', 'all']) {
    const items = await collect(tier, api);
    result[tier] = {
      count: items.length,
      items: items.map(i => i.name || i.id)
    };
  }

  return result;
}

/**
 * Check which tier(s) an item is tagged for
 * @param {string} itemId - The item ID to check
 * @param {object} api - The Hobson API object
 */
export async function tierOf(itemId, api) {
  if (!api) {
    api = window.kernel?.createAPI();
  }

  const item = await api.get(itemId);
  const itemTags = item.tags || [];

  const tiers = [];
  if (itemTags.includes(TAG_IDS.BARE)) tiers.push('bare');
  if (itemTags.includes(TAG_IDS.BASIC)) tiers.push('basic');
  if (itemTags.includes(TAG_IDS.ALL)) tiers.push('all');

  return tiers;
}

// Default View - Fallback JSON display
// See [Views & Rendering](item://a0a0a0a0-d0c0-4000-8000-000000000004)

// [BEGIN:render]
export async function render(item, api) {
  const container = api.createElement('div', { className: 'default-view' });

  const header = api.createElement('div', { style: 'margin-bottom: 15px; padding-bottom: 10px; border-bottom: 1px solid var(--color-border-light);' });
  const title = api.createElement('h3', { style: 'margin: 0 0 5px 0;' });
  title.textContent = item.name || item.id.slice(0, 8) + '...';
  header.appendChild(title);
  const meta = api.createElement('div', { style: 'font-size: 0.75rem; color: var(--color-text-secondary);' });
  meta.textContent = 'Type: ' + item.type.slice(0, 8) + '...';
  header.appendChild(meta);
  container.appendChild(header);

  const textarea = api.createElement('textarea', {
    style: 'width: 100%; min-height: 300px; font-family: monospace; font-size: 0.8125rem; padding: 10px; border: 1px solid var(--color-border); border-radius: var(--border-radius);'
  });
  textarea.value = JSON.stringify(item, null, 2);
  container.appendChild(textarea);

  const actions = api.createElement('div', { style: 'margin-top: 10px; display: flex; gap: 10px;' });

  const saveBtn = api.createElement('button', { style: 'padding: 8px 16px; cursor: pointer;' });
  saveBtn.textContent = 'Save';
  saveBtn.onclick = async () => {
    try {
      const updated = JSON.parse(textarea.value);
      await api.set(updated);
      await api.rerenderItem(updated.id);
    } catch (e) {
      alert('Error: ' + e.message);
    }
  };
  actions.appendChild(saveBtn);

  const copyBtn = api.createElement('button', { style: 'padding: 8px 16px; cursor: pointer;' });
  copyBtn.textContent = 'Copy JSON';
  copyBtn.onclick = () => {
    navigator.clipboard.writeText(textarea.value);
    copyBtn.textContent = 'Copied!';
    setTimeout(() => copyBtn.textContent = 'Copy JSON', 1500);
  };
  actions.appendChild(copyBtn);

  container.appendChild(actions);
  return container;
}
// [END:render]

export async function render(value, options, api) {
  const { mode, onChange, label, itemSpec = {}, defaultItem } = options;
  const isEditable = mode === 'editable' && onChange;

  // Internal mutable state — always authoritative. getCurrent() was insufficient
  // because generic-view buffers edits without re-rendering, so add/delete/reorder
  // must use this local copy rather than trying to read back from the parent.
  let currentArr = Array.isArray(value) ? [...value] : [];

  const wrapper = api.createElement('div', { className: 'field-array' });
  wrapper.style.cssText = 'display: flex; flex-direction: column; gap: 4px;';

  if (label) {
    const labelEl = api.createElement('div');
    labelEl.textContent = label;
    labelEl.style.cssText = 'font-weight: 500; font-size: 0.875rem; color: var(--color-text); margin-bottom: 4px;';
    wrapper.appendChild(labelEl);
  }

  const fieldViewName = 'field-view-' + (itemSpec.field_view || inferFieldView(currentArr));
  let fieldView;
  try {
    fieldView = await api.require(fieldViewName);
  } catch (e) {
    fieldView = await api.require('field-view-json');
  }

  const itemsContainer = api.createElement('div');
  itemsContainer.style.cssText = 'display: flex; flex-direction: column; gap: 8px;';

  const btnStyle = 'padding: 3px 7px; font-size: 0.75rem; cursor: pointer; background: var(--color-bg-hover); border: 1px solid var(--color-border-light); border-radius: var(--border-radius); line-height: 1.4;';

  // Value mutation: update state only — no DOM re-render, so focus is preserved
  // while typing in text/number sub-fields.
  const mutateValue = (newArr) => {
    currentArr = newArr;
    onChange(newArr);
  };

  // Structural mutation: update state AND re-render the items DOM.
  const mutateStructure = async (newArr) => {
    currentArr = newArr;
    onChange(newArr);
    await renderItems();
  };

  const renderItems = async () => {
    while (itemsContainer.firstChild) itemsContainer.removeChild(itemsContainer.firstChild);

    if (currentArr.length === 0 && !isEditable) {
      const emptyEl = api.createElement('div');
      emptyEl.textContent = '(empty)';
      emptyEl.style.cssText = 'color: var(--color-text-tertiary); font-style: italic; font-size: 0.8125rem; padding: 8px;';
      itemsContainer.appendChild(emptyEl);
      return;
    }

    for (let i = 0; i < currentArr.length; i++) {
      const itemWrapper = api.createElement('div');
      itemWrapper.style.cssText = 'display: flex; gap: 8px; align-items: flex-start;';

      const fieldEl = await fieldView.render(currentArr[i], {
        ...itemSpec,
        mode,
        onChange: isEditable ? (newVal) => {
          const newArr = [...currentArr];
          newArr[i] = newVal;
          mutateValue(newArr);
        } : null,
        getCurrentValue: isEditable ? () => currentArr[i] : undefined,
        label: null,
      }, api);

      fieldEl.style.flex = '1';
      itemWrapper.appendChild(fieldEl);

      if (isEditable) {
        const controls = api.createElement('div');
        controls.style.cssText = 'display: flex; flex-direction: column; gap: 2px; flex-shrink: 0; padding-top: 2px;';

        const upBtn = api.createElement('button');
        upBtn.textContent = '↑';
        upBtn.title = 'Move up';
        upBtn.style.cssText = btnStyle + (i === 0 ? ' opacity: 0.3;' : '');
        upBtn.disabled = i === 0;
        upBtn.onclick = () => {
          const newArr = [...currentArr];
          [newArr[i - 1], newArr[i]] = [newArr[i], newArr[i - 1]];
          mutateStructure(newArr);
        };

        const downBtn = api.createElement('button');
        downBtn.textContent = '↓';
        downBtn.title = 'Move down';
        downBtn.style.cssText = btnStyle + (i === currentArr.length - 1 ? ' opacity: 0.3;' : '');
        downBtn.disabled = i === currentArr.length - 1;
        downBtn.onclick = () => {
          const newArr = [...currentArr];
          [newArr[i], newArr[i + 1]] = [newArr[i + 1], newArr[i]];
          mutateStructure(newArr);
        };

        const delBtn = api.createElement('button');
        delBtn.textContent = '×';
        delBtn.title = 'Remove';
        delBtn.style.cssText = btnStyle + ' color: var(--color-text-secondary);';
        delBtn.onclick = () => {
          mutateStructure(currentArr.filter((_, j) => j !== i));
        };

        controls.appendChild(upBtn);
        controls.appendChild(downBtn);
        controls.appendChild(delBtn);
        itemWrapper.appendChild(controls);
      }

      itemsContainer.appendChild(itemWrapper);
    }
  };

  await renderItems();
  wrapper.appendChild(itemsContainer);

  if (isEditable) {
    const addBtn = api.createElement('button');
    addBtn.textContent = '+ Add Item';
    addBtn.style.cssText = 'margin-top: 4px; padding: 4px 12px; font-size: 0.75rem; cursor: pointer; background: var(--color-bg-surface-alt); border: 1px solid var(--color-border-light); border-radius: var(--border-radius); color: var(--color-text-secondary);';
    addBtn.onclick = () => {
      const base = defaultItem !== undefined ? defaultItem : getDefaultForSpec(itemSpec);
      // Deep-copy objects so each new item gets its own reference
      const newItem = (base !== null && typeof base === 'object')
        ? JSON.parse(JSON.stringify(base))
        : base;
      mutateStructure([...currentArr, newItem]);
    };
    wrapper.appendChild(addBtn);
  }

  return wrapper;
}

function inferFieldView(arr) {
  if (arr.length === 0) return 'text';
  const guidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const types = arr.map(v => {
    if (v === null || v === undefined) return 'null';
    if (typeof v === 'boolean') return 'boolean';
    if (typeof v === 'number') return 'number';
    if (Array.isArray(v)) return 'array';
    if (typeof v === 'object') return 'object';
    if (guidPattern.test(v)) return 'guid';
    return 'string';
  });
  if (new Set(types).size !== 1) return 'text';
  switch (types[0]) {
    case 'guid':    return 'item-ref';
    case 'number':  return 'number';
    case 'boolean': return 'checkbox';
    case 'array':   return 'array';
    case 'object':  return 'object';
    default:        return 'text';
  }
}

function getDefaultForSpec(spec) {
  switch (spec.field_view) {
    case 'number': return 0;
    case 'checkbox': return false;
    case 'object': return {};
    case 'array': return [];
    default: return '';
  }
}

