// symbol-extractor-lib
// Extracts symbol definitions from JavaScript code (using Acorn) and Hob code (AST walk)

export async function extractSymbols(code, api) {
  await api.require('acorn');
  const acorn = await api.require('acorn-wrapper');

  const comments = [];
  let ast;
  try {
    ast = acorn.parse(code, {
      ecmaVersion: 'latest',
      sourceType: 'module',
      locations: true,
      allowReturnOutsideFunction: true,
      onComment: comments,
    });
  } catch (e) {
    console.warn('Symbol extraction parse error:', e.message);
    return {};
  }

  const symbols = {};
  walkNode(ast, null, symbols);
  attachJSDoc(comments, symbols);
  return symbols;
}

// --- Hob symbol extraction (compact JSON AST) ---

const HOB_DEF_FORMS = new Set(['defn', 'def', 'def-view', 'def-watch', 'defmacro']);

export function extractHobSymbols(hobAst) {
  if (!Array.isArray(hobAst)) return {};
  const symbols = {};
  for (const form of hobAst) walkHobForm(form, null, symbols);
  return symbols;
}

function walkHobForm(form, scope, symbols) {
  if (!Array.isArray(form) || form.length < 2) return;
  const head = form[0];
  if (typeof head !== 'string') return;

  if (HOB_DEF_FORMS.has(head)) {
    const name = form[1];
    if (typeof name !== 'string' || name.startsWith(':') || name.startsWith('@')) return;
    const info = { name, kind: null, scope: scope || null };

    switch (head) {
      case 'defn': {
        info.kind = 'function';
        info.signature = hobParamSignature(form[2]);
        break;
      }
      case 'def': {
        const value = form[2];
        if (Array.isArray(value) && value[0] === 'fn') {
          info.kind = 'function';
          info.signature = hobParamSignature(value[1]);
        } else {
          info.kind = 'variable';
        }
        break;
      }
      case 'def-view': {
        info.kind = 'view';
        info.signature = hobParamSignature(form[3]);
        break;
      }
      case 'def-watch': {
        info.kind = 'watch';
        info.signature = hobParamSignature(form[3]);
        break;
      }
      case 'defmacro': {
        info.kind = 'macro';
        info.signature = hobParamSignature(form[2]);
        break;
      }
    }
    if (info.kind) {
      const key = scope ? `${scope}.${name}` : name;
      symbols[key] = info;
    }
  } else if (head === 'let' && form[1]?.v) {
    // (let [name1 val1 name2 val2 ...] body...)
    const bindings = form[1].v;
    for (let i = 0; i < bindings.length; i += 2) {
      const name = bindings[i];
      if (typeof name !== 'string' || name.startsWith(':') || name.startsWith('@')) continue;
      const value = bindings[i + 1];
      const isFn = Array.isArray(value) && value[0] === 'fn';
      const key = scope ? `${scope}.${name}` : name;
      symbols[key] = {
        name,
        kind: isFn ? 'function' : 'binding',
        scope: scope || null,
        ...(isFn ? { signature: hobParamSignature(value[1]) } : {})
      };
      // Recurse into the value expression
      if (Array.isArray(value)) walkHobForm(value, scope, symbols);
    }
    // Recurse into body forms
    for (let i = 2; i < form.length; i++) {
      if (Array.isArray(form[i])) walkHobForm(form[i], scope, symbols);
    }
  } else {
    // Recurse into sub-forms (fn bodies, etc.)
    for (let i = 1; i < form.length; i++) {
      if (Array.isArray(form[i])) walkHobForm(form[i], scope, symbols);
    }
  }
}

function hobParamSignature(params) {
  // Params are a vector: {v: ["a", "b", "c"]} or multi-arity: array of ([params] body) lists
  if (params && params.v && Array.isArray(params.v)) {
    const names = params.v.map(p => {
      if (typeof p === 'string') {
        if (p === '&') return '&';
        return p;
      }
      return '?';
    });
    return '(' + names.join(' ') + ')';
  }
  // Multi-arity: first form is a list whose first element is the param vector
  if (Array.isArray(params) && Array.isArray(params[0])) {
    const arities = params.map(arity => {
      if (Array.isArray(arity) && arity[0]?.v) {
        return '(' + arity[0].v.join(' ') + ')';
      }
      return '(?)';
    });
    return arities.join(' | ');
  }
  return null;
}

// --- JavaScript symbol extraction (Acorn) ---

// Helper: Extract function signature from params
function extractSignature(params) {
  if (!params || params.length === 0) return '()';
  const parts = params.map(p => {
    switch (p.type) {
      case 'Identifier': return p.name;
      case 'AssignmentPattern':
        // foo = default
        const name = p.left.type === 'Identifier' ? p.left.name : '?';
        return name + ' = ...';
      case 'RestElement':
        // ...args
        const restName = p.argument.type === 'Identifier' ? p.argument.name : 'args';
        return '...' + restName;
      case 'ObjectPattern': return '{ ... }';
      case 'ArrayPattern': return '[ ... ]';
      default: return '?';
    }
  });
  return '(' + parts.join(', ') + ')';
}

// Helper: Get params from a function node (works for FunctionDeclaration, FunctionExpression, ArrowFunctionExpression)
function getFunctionParams(node) {
  if (!node) return null;
  if (node.params) return node.params;
  if (node.value?.params) return node.value.params;  // MethodDefinition
  return null;
}

function walkNode(node, scope, symbols) {
  if (!node || typeof node !== 'object') return;

  switch (node.type) {
    case 'FunctionDeclaration':
      if (node.id?.name) {
        const sig = extractSignature(node.params);
        addSymbol(symbols, node.id.name, node.loc, 'function', scope, sig);
        walkNode(node.body, node.id.name, symbols);
      }
      break;

    case 'VariableDeclaration':
      for (const decl of node.declarations) {
        if (decl.id?.name) {
          const isFunc = decl.init?.type === 'ArrowFunctionExpression' ||
                         decl.init?.type === 'FunctionExpression';
          const kind = isFunc ? 'function' : 'variable';
          const sig = isFunc ? extractSignature(decl.init.params) : null;
          addSymbol(symbols, decl.id.name, decl.loc, kind, scope, sig);

          if (decl.init) {
            const initScope = decl.id.name;
            if (decl.init.body) {
              walkNode(decl.init.body, initScope, symbols);
            } else if (decl.init.type === 'ObjectExpression') {
              walkNode(decl.init, initScope, symbols);
            }
          }
        }
      }
      break;

    case 'ClassDeclaration':
      if (node.id?.name) {
        addSymbol(symbols, node.id.name, node.loc, 'class', scope);
        walkNode(node.body, node.id.name, symbols);
      }
      break;

    case 'MethodDefinition':
      if (node.key?.name) {
        const sig = extractSignature(node.value?.params);
        addSymbol(symbols, node.key.name, node.loc, 'method', scope, sig);
        walkNode(node.value?.body, `${scope}.${node.key.name}`, symbols);
      }
      break;

    case 'PropertyDefinition':
      if (node.key?.name) {
        const isFunc = node.value?.type === 'FunctionExpression' ||
                       node.value?.type === 'ArrowFunctionExpression';
        const kind = isFunc ? 'field-function' : 'field';
        const sig = isFunc ? extractSignature(node.value.params) : null;
        addSymbol(symbols, node.key.name, node.loc, kind, scope, sig);

        if (node.value?.body) {
          const newScope = scope ? `${scope}.${node.key.name}` : node.key.name;
          walkNode(node.value.body, newScope, symbols);
        }
      }
      break;

    case 'Property':
      if (node.key?.name) {
        const isFunc = node.value?.type === 'FunctionExpression' ||
                       node.value?.type === 'ArrowFunctionExpression' ||
                       node.method;
        const kind = isFunc ? 'property-function' : 'property';
        const sig = isFunc ? extractSignature(node.value?.params) : null;
        addSymbol(symbols, node.key.name, node.loc, kind, scope, sig);

        const newScope = scope ? `${scope}.${node.key.name}` : node.key.name;

        if (node.value?.body) {
          walkNode(node.value.body, newScope, symbols);
        } else if (node.value?.type === 'ObjectExpression') {
          walkNode(node.value, newScope, symbols);
        }
      }
      break;

    case 'ExportNamedDeclaration':
      if (node.declaration) {
        walkNode(node.declaration, scope, symbols);
      }
      break;

    case 'ExportDefaultDeclaration':
      if (node.declaration) {
        walkNode(node.declaration, scope, symbols);
      }
      break;

    case 'ExpressionStatement':
      // Detect env.define('name', fn) or env.define('name', Object.assign(fn, ...))
      if (node.expression?.type === 'CallExpression') {
        const call = node.expression;
        const callee = call.callee;
        if (callee?.type === 'MemberExpression' &&
            callee.property?.name === 'define' &&
            call.arguments?.length >= 2 &&
            call.arguments[0].type === 'Literal' &&
            typeof call.arguments[0].value === 'string') {
          const symName = call.arguments[0].value;
          let valuNode = call.arguments[1];
          // Unwrap Object.assign(fn, {_hobName: ...})
          if (valuNode.type === 'CallExpression' &&
              valuNode.callee?.type === 'MemberExpression' &&
              valuNode.callee.object?.name === 'Object' &&
              valuNode.callee.property?.name === 'assign' &&
              valuNode.arguments?.length >= 1) {
            valuNode = valuNode.arguments[0];
          }
          const isFunc = valuNode.type === 'ArrowFunctionExpression' ||
                         valuNode.type === 'FunctionExpression';
          const sig = isFunc ? extractSignature(valuNode.params) : null;
          addSymbol(symbols, symName, node.loc, isFunc ? 'function' : 'variable', scope, sig);
        }
      }
      walkNode(node.expression, scope, symbols);
      break;

    default:
      for (const key of Object.keys(node)) {
        if (key === 'loc' || key === 'range') continue;
        const child = node[key];
        if (Array.isArray(child)) {
          for (const c of child) {
            walkNode(c, scope, symbols);
          }
        } else if (child && typeof child === 'object' && child.type) {
          walkNode(child, scope, symbols);
        }
      }
  }
}

function addSymbol(symbols, name, loc, kind, scope, signature = null) {
  const key = scope ? `${scope}.${name}` : name;
  const info = {
    name,
    line: loc.start.line,
    col: loc.start.column,
    endLine: loc.end.line,
    endCol: loc.end.column,
    kind,
    scope: scope || null
  };
  if (signature) info.signature = signature;
  symbols[key] = info;
}

// Parse a JSDoc comment value (the text between /** and */)
function parseJSDoc(value) {
  const lines = value.split('\n').map(l => l.replace(/^\s*\*\s?/, '').trimEnd());
  // Drop empty first/last lines (from /** and */)
  if (lines.length && lines[0].trim() === '') lines.shift();
  if (lines.length && lines[lines.length - 1].trim() === '') lines.pop();

  let description = '';
  const params = [];
  let returns = null;

  for (const line of lines) {
    const paramMatch = line.match(/^@param\s+(?:\{([^}]*)\}\s+)?(\[?\w+\]?)\s*(?:-\s*)?(.*)$/);
    if (paramMatch) {
      const p = { name: paramMatch[2].replace(/^\[|\]$/g, '') };
      if (paramMatch[1]) p.type = paramMatch[1];
      if (paramMatch[3]) p.description = paramMatch[3];
      params.push(p);
      continue;
    }

    const returnMatch = line.match(/^@returns?\s+(?:\{([^}]*)\}\s*)?(.*)$/);
    if (returnMatch) {
      returns = {};
      if (returnMatch[1]) returns.type = returnMatch[1];
      if (returnMatch[2]) returns.description = returnMatch[2];
      continue;
    }

    // Skip other @ tags
    if (/^@\w/.test(line)) continue;

    // Accumulate description (lines before any @tag)
    if (params.length === 0 && !returns) {
      description += (description ? '\n' : '') + line;
    }
  }

  const result = {};
  description = description.trim();
  if (description) result.description = description;
  if (params.length) result.params = params;
  if (returns) result.returns = returns;
  return result;
}

// Attach JSDoc comments to the nearest symbol that follows them
function attachJSDoc(comments, symbols) {
  // Filter to JSDoc block comments (start with *)
  const jsdocs = comments.filter(c => c.type === 'Block' && c.value.startsWith('*'));
  if (!jsdocs.length) return;

  // Build array of symbols sorted by line
  const symEntries = Object.values(symbols);
  if (!symEntries.length) return;

  for (const comment of jsdocs) {
    const commentEndLine = comment.loc.end.line;
    // Find the symbol whose start line is closest after the comment end (within 1-line gap)
    let best = null;
    for (const sym of symEntries) {
      const gap = sym.line - commentEndLine;
      if (gap >= 0 && gap <= 1) {
        if (!best || sym.line < best.line) best = sym;
      }
    }
    if (!best) continue;

    const parsed = parseJSDoc(comment.value);
    if (parsed.description) best.description = parsed.description;
    if (parsed.params) best.params = parsed.params;
    if (parsed.returns) best.returns = parsed.returns;
  }
}

// Symbol indexer - extracts and stores symbol definitions from code items

export async function onItemCreated({ item }, api) {
  await indexSymbols(item, api);
}

export async function onItemUpdated({ item }, api) {
  await indexSymbols(item, api);
}

async function indexSymbols(item, api) {
  const hasCode = item.content?.code && typeof item.content.code === 'string';
  const hasHob = Array.isArray(item.content?.hob);
  if (!hasCode && !hasHob) return;

  const extractor = await api.require('symbol-extractor-lib');
  const symbols = hasHob
    ? extractor.extractHobSymbols(item.content.hob)
    : await extractor.extractSymbols(item.content.code, api);

  // Check if symbols changed (avoid unnecessary saves)
  const existingSymbols = item.content._symbols || {};
  if (JSON.stringify(symbols) === JSON.stringify(existingSymbols)) {
    return;
  }

  // Update item with new symbols (silent to avoid re-triggering watchers)
  item.content._symbols = symbols;
  await api.set(item, { silent: true });

  console.log(`Indexed ${Object.keys(symbols).length} symbols in ${item.name || item.id}`);
}

// REPL introspection — dir(), help(), symbols(), symbolSearch()

let _api = null;

export async function onKernelBootComplete(payload, api) {
  _api = api;
  window.dir = dir;
  window.help = help;
  window.symbols = symbols;
  window.symbolSearch = symbolSearch;
}

// --- dir(obj) — synchronous ---
// Enumerates keys, groups into Functions / Namespaces / Values
function dir(obj) {
  if (obj == null) return 'dir() requires an argument';
  if (typeof obj !== 'object' && typeof obj !== 'function') {
    return `(${typeof obj}) ${String(obj)}`;
  }

  const keys = Object.keys(obj).sort();
  if (keys.length === 0) return '(no enumerable properties)';

  const fns = [], ns = [], vals = [];
  for (const k of keys) {
    try {
      const v = obj[k];
      if (typeof v === 'function') fns.push(k);
      else if (v && typeof v === 'object' && Object.keys(v).length > 0) ns.push(k);
      else vals.push(k);
    } catch { vals.push(k); }
  }

  const lines = [];
  if (fns.length)  lines.push('Functions:  ' + fns.join(', '));
  if (ns.length)   lines.push('Namespaces: ' + ns.join(', '));
  if (vals.length) lines.push('Values:     ' + vals.join(', '));
  return lines.join('\n');
}

// --- help(obj, methodName?) — async ---
// Resolves source item via kernel API detection, sub-namespace matching, or WeakMap provenance.
// Shows symbols from _symbols index.
async function help(obj, methodName) {
  if (!_api) return 'help() not ready \u2014 wait for boot';
  if (obj == null) return 'Usage: help(obj) or help(obj, "methodName")';
  if (typeof obj === 'string') return await symbols(obj);
  if (typeof obj !== 'object' && typeof obj !== 'function') {
    return `(${typeof obj}) \u2014 pass an object or module to help()`;
  }

  const source = resolveSource(obj);
  if (!source) {
    if (methodName) return 'Could not determine source item. Try: await symbols("item-name")';
    return 'Could not determine source item.\n\n' + dir(obj);
  }

  const item = await _api.get(source.itemId);
  const syms = item?.content?._symbols;
  if (!syms) return `Source: ${source.itemName}\nNo _symbols indexed for this item.`;

  return methodName
    ? formatMethodHelp(syms, source, methodName)
    : formatScopeHelp(syms, source);
}

// Resolve an object to { itemId, itemName, scope }
function resolveSource(obj) {
  // Strategy 1: Kernel API — IDS is a shared module-level const across all createAPI() calls
  if (obj.IDS && obj.IDS === window.kernel?.IDS) {
    return { itemId: _api.IDS.KERNEL_CORE, itemName: 'kernel:core', scope: 'api' };
  }

  // Strategy 2: API sub-namespaces — match keys against our boot api's sub-namespace objects
  const nsMap = { events: 'api.events', viewport: 'api.viewport', instances: 'api.instances', helpers: 'api.helpers' };
  for (const [ns, scope] of Object.entries(nsMap)) {
    if (_api[ns] && keysMatch(obj, _api[ns])) {
      return { itemId: _api.IDS.KERNEL_CORE, itemName: 'kernel:core', scope };
    }
  }

  // Strategy 3: WeakMap provenance (loaded libraries)
  const info = window.kernel?.moduleSystem?.getModuleInfo(obj);
  if (info) return { itemId: info.itemId, itemName: info.itemName, scope: null };

  return null;
}

function keysMatch(a, b) {
  const ak = Object.keys(a).sort().join('\0');
  const bk = Object.keys(b).sort().join('\0');
  return ak === bk && ak.length > 0;
}

// Format help for a single method/symbol
function formatMethodHelp(syms, source, methodName) {
  const prefix = source.scope ? source.scope + '.' : '';
  let sym = syms[prefix + methodName];

  // Fallback: search by name within scope
  if (!sym) {
    for (const s of Object.values(syms)) {
      if (s.name === methodName && (!source.scope || s.scope === source.scope)) {
        sym = s;
        break;
      }
    }
  }

  if (!sym) {
    const hint = source.scope ? ` (scope: ${source.scope})` : '';
    return `No symbol "${methodName}" found in ${source.itemName}${hint}`;
  }

  const lines = [
    `${sym.name}${sym.signature || ''}`,
  ];
  if (sym.description) lines.push(`  ${sym.description}`);
  lines.push(`  Kind: ${sym.kind}  |  Line: ${sym.line}`);
  if (sym.params) {
    for (const p of sym.params) {
      const type = p.type ? ` (${p.type})` : '';
      const desc = p.description ? ` - ${p.description}` : '';
      lines.push(`  Param: ${p.name}${type}${desc}`);
    }
  }
  if (sym.returns) {
    const type = sym.returns.type || '';
    const desc = sym.returns.description ? ` - ${sym.returns.description}` : '';
    lines.push(`  Returns: ${type}${desc}`);
  }
  lines.push(`  Source: ${source.itemName}`);
  lines.push(`  Navigate: api.navigate('${source.itemId}', { symbol: '${sym.name}' })`);
  return lines.join('\n');
}

// Format help for an entire scope (all symbols at that level)
function formatScopeHelp(syms, source) {
  const entries = Object.values(syms);
  let relevant;

  if (source.scope) {
    // Scoped (kernel API / sub-namespace): show symbols AT this scope
    relevant = entries.filter(s => s.scope === source.scope);
  } else {
    // Unscoped (library): show top-level symbols + class methods
    const topLevel = entries.filter(s => s.scope === null);
    const classNames = new Set(topLevel.filter(s => s.kind === 'class').map(s => s.name));
    const classMethods = classNames.size > 0
      ? entries.filter(s => s.scope && classNames.has(s.scope))
      : [];
    relevant = [...topLevel, ...classMethods];
  }

  if (relevant.length === 0) {
    const hint = source.scope ? ` in scope "${source.scope}"` : '';
    return `Source: ${source.itemName}\nNo symbols found${hint}.`;
  }

  const labelOf = (kind) => ({
    'class': 'Classes', 'method': 'Methods', 'function': 'Functions',
    'property-function': 'Functions', 'field-function': 'Functions',
    'property': 'Properties', 'field': 'Fields', 'variable': 'Variables'
  })[kind] || kind;

  const groups = {};
  for (const s of relevant) {
    const label = labelOf(s.kind);
    (groups[label] ??= []).push(s);
  }

  const lines = [`Source: ${source.itemName} (${source.itemId})`];
  if (source.scope) lines.push(`Scope: ${source.scope}`);
  lines.push('');

  const labelOrder = ['Classes', 'Methods', 'Functions', 'Properties', 'Fields', 'Variables'];
  for (const label of labelOrder) {
    if (!groups[label]) continue;
    lines.push(`${label}:`);
    for (const s of groups[label].sort((a, b) => a.name.localeCompare(b.name))) {
      const scope = s.scope && s.scope !== source.scope ? ` [${s.scope}]` : '';
      lines.push(`  ${s.name}${s.signature || ''}${scope}  (line ${s.line})`);
      if (s.description) lines.push(`    ${s.description.split('\n')[0]}`);
    }
    delete groups[label];
  }

  // Any remaining kind labels not in labelOrder
  for (const [label, arr] of Object.entries(groups)) {
    lines.push(`${label}:`);
    for (const s of arr.sort((a, b) => a.name.localeCompare(b.name))) {
      lines.push(`  ${s.name}${s.signature || ''}  (line ${s.line})`);
      if (s.description) lines.push(`    ${s.description.split('\n')[0]}`);
    }
  }

  return lines.join('\n');
}

// --- symbols(nameOrId) — async ---
// Full dump of all _symbols for an item, grouped by kind.
async function symbols(nameOrId) {
  if (!_api) return 'symbols() not ready \u2014 wait for boot';
  if (!nameOrId) return 'Usage: await symbols("item-name") or await symbols("guid")';

  let item;
  if (nameOrId.includes('-') && nameOrId.length >= 36) {
    try { item = await _api.get(nameOrId); } catch (e) { /* not found by id */ }
  }
  if (!item) {
    item = await _api.helpers.findByName(nameOrId);
  }
  if (!item) return `Item not found: ${nameOrId}`;

  const syms = item.content?._symbols;
  if (!syms) return `${item.name || item.id} has no indexed symbols.`;

  const entries = Object.values(syms);
  const groups = {};
  for (const s of entries) {
    (groups[s.kind] ??= []).push(s);
  }

  const lines = [`Symbols for: ${item.name || item.id} (${item.id})`];
  lines.push(`Total: ${entries.length} symbols`);
  lines.push('');

  const kindOrder = ['class', 'method', 'function', 'property-function', 'field-function', 'property', 'field', 'variable'];
  const kindLabels = {
    'class': 'Classes', 'method': 'Methods', 'function': 'Functions',
    'property-function': 'Property Functions', 'field-function': 'Field Functions',
    'property': 'Properties', 'field': 'Fields', 'variable': 'Variables'
  };

  for (const kind of kindOrder) {
    if (!groups[kind]) continue;
    lines.push(`${kindLabels[kind]}:`);
    for (const s of groups[kind].sort((a, b) => a.line - b.line)) {
      const scope = s.scope ? ` [${s.scope}]` : '';
      lines.push(`  ${s.name}${s.signature || ''}  (line ${s.line})${scope}`);
    }
    delete groups[kind];
  }

  // Any remaining kinds
  for (const [kind, arr] of Object.entries(groups)) {
    lines.push(`${kind}:`);
    for (const s of arr.sort((a, b) => a.line - b.line)) {
      lines.push(`  ${s.name}${s.signature || ''}  (line ${s.line})${s.scope ? ` [${s.scope}]` : ''}`);
    }
  }

  return lines.join('\n');
}

// --- symbolSearch(pattern, options?) — async ---
// Cross-item symbol search. Scans _symbols across all code items.
// pattern: string (case-insensitive substring) or RegExp
// options: { kind?, scope?, limit? }
async function symbolSearch(pattern, options = {}) {
  if (!_api) return 'symbolSearch() not ready \u2014 wait for boot';
  if (!pattern) return 'Usage: await symbolSearch("name") or await symbolSearch(/pattern/, { kind: "function" })';

  const isRegex = pattern instanceof RegExp;
  const test = isRegex
    ? (name) => pattern.test(name)
    : (name) => name.toLowerCase().includes(pattern.toLowerCase());

  const { kind, scope, limit = 50 } = options;

  const allItems = await _api.getAll();
  const matches = []; // { itemName, itemId, sym }

  for (const item of allItems) {
    const syms = item.content?._symbols;
    if (!syms) continue;

    for (const sym of Object.values(syms)) {
      if (!test(sym.name)) continue;
      if (kind && sym.kind !== kind) continue;
      if (scope !== undefined && sym.scope !== scope) continue;
      matches.push({ itemName: item.name || item.id, itemId: item.id, sym });
    }
  }

  if (matches.length === 0) {
    return `No symbols matching "${pattern}" found.`;
  }

  // Group by item
  const byItem = new Map();
  for (const m of matches) {
    (byItem.get(m.itemId) ?? (() => { const a = []; byItem.set(m.itemId, a); return a; })()).push(m);
  }

  const truncated = matches.length > limit;
  const lines = [`Symbol search: ${isRegex ? pattern : `"${pattern}"`} (${matches.length} match${matches.length === 1 ? '' : 'es'} across ${byItem.size} item${byItem.size === 1 ? '' : 's'})${truncated ? ` \u2014 showing first ${limit}` : ''}`];
  lines.push('');

  let shown = 0;
  for (const [itemId, itemMatches] of byItem) {
    if (shown >= limit) break;
    lines.push(`${itemMatches[0].itemName}:`);
    for (const m of itemMatches.sort((a, b) => a.sym.line - b.sym.line)) {
      if (shown >= limit) break;
      const s = m.sym;
      const scopeHint = s.scope ? ` [${s.scope}]` : '';
      lines.push(`  ${s.name}${s.signature || ''}  ${s.kind}  (line ${s.line})${scopeHint}`);
      shown++;
    }
  }

  return lines.join('\n');
}

export async function render(value, options, api) {
  const { mode, onChange, label, filterType } = options;
  const wrapper = api.createElement('div', { class: 'field-item-ref' });
  wrapper.style.cssText = 'display: flex; flex-direction: column; gap: 4px;';

  if (label) {
    const labelEl = api.createElement('label');
    labelEl.textContent = label;
    labelEl.style.cssText = 'font-weight: 500; font-size: 0.875rem; color: var(--color-text);';
    wrapper.appendChild(labelEl);
  }

  const itemId = value || '';
  const isEditable = mode === 'editable' && onChange;

  // Reference to name display element (set later, used by showItemPicker)
  let nameSpan = null;

  // Helper to navigate to item
  const navigateToItem = async (e, id) => {
    try {
      await api.openItem(e, id);
    } catch (err) {
      console.error('item_ref navigation error:', err);
    }
  };

  // Helper to show item picker modal
  const showItemPicker = async () => {
    const searchLib = await api.require('item-search-lib');
    const modalLib = await api.require('modal-lib');

    const { close } = modalLib.showModal({
      title: 'Select Item',
      width: '500px',
      maxHeight: '70vh',
      api,
      content: ({ close: closeModal }) => {
        const searchContainer = api.createElement('div');
        searchContainer.style.cssText = 'min-height: 200px;';

        // Create search UI
        searchLib.createSearchUI(
          searchContainer,
          (selectedItem) => {
            closeModal();
            onChange(selectedItem.id);
            // Update display immediately
            if (nameSpan) {
              nameSpan.textContent = selectedItem.name || selectedItem.id;
            }
          },
          api,
          { placeholder: 'Search for items...', autoFocus: true, savedQuery: filterType ? 'type:' + filterType : '' }
        );

        return searchContainer;
      }
    });
  };

  // Get current item name
  let currentName = itemId ? itemId.slice(0, 8) + '...' : '(none)';
  let itemExists = false;
  if (itemId) {
    try {
      const refItem = await api.get(itemId);
      currentName = refItem.name || refItem.id;
      itemExists = true;
    } catch (e) {
      currentName = itemId.slice(0, 8) + '... (not found)';
    }
  }

  if (isEditable) {
    // Editable: show picker button with current value
    const row = api.createElement('div');
    row.style.cssText = 'display: flex; gap: 8px; align-items: center;';

    const pickerBtn = api.createElement('button');
