// Item: window-zindex-lib
// ID: bc80bdc2-f6b3-49df-a72d-1cecf866ddcf
// Type: 66666666-0000-0000-0000-000000000000
//
// Z-index management for spatial-canvas-view. DB-authoritative — no DOM queries.

// Get max z-index from DB only
// children: fresh item.attachments array
// baseZ: base z-index offset (typically 1)
// isAnchoredFn: function to check if an anchor string means the window is anchored
export function getMaxZ(children, baseZ, isAnchoredFn) {
  const floating = children.filter(c => !isAnchoredFn(c.view?.anchor) && !c.view?.minimized);
  const maxStoredZ = Math.max(...floating.map(c => c.view?.z || 0), 0);
  return maxStoredZ + baseZ;
}

// Calculate new z-index for bringing window to front
// Returns null if already at front
// Pure calculation — caller handles persistence and DOM update
export function bringToFrontZ(childId, children, baseZ, isAnchoredFn) {
  const floating = children.filter(c => !isAnchoredFn(c.view?.anchor) && !c.view?.minimized);
  const maxStoredZ = Math.max(...floating.map(c => c.view?.z || 0), 0);

  const target = floating.find(c => c.id === childId);
  if (!target) return null; // Anchored or minimized

  const currentZ = (target.view?.z || 0) + baseZ;
  const maxZ = maxStoredZ + baseZ;

  if (currentZ >= maxZ) return null; // Already at front

  const newDomZ = maxZ + 1;
  const newStoredZ = newDomZ - baseZ;

  return { newZ: newDomZ, newStoredZ };
}

// Normalize all z-indices to sequential 0, 1, 2...
// Returns Map<childId, newZ> for caller to apply in one batch
export function normalizeZIndices(children, isAnchoredFn) {
  const floating = children
    .filter(c => !isAnchoredFn(c.view?.anchor) && !c.view?.minimized)
    .map(c => ({ id: c.id, z: c.view?.z || 0 }))
    .sort((a, b) => a.z - b.z);

  const result = new Map();
  floating.forEach((c, idx) => {
    result.set(c.id, idx);
  });
  return result;
}

export function render(value, onChange, api, options = {}) {
  const container = api.createElement('div');
  container.style.cssText = 'display: flex; gap: 8px; align-items: center;';

  // Display area for current selection
  const displayArea = api.createElement('div');
  displayArea.style.cssText = 'flex: 1; padding: 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); font-size: 0.875rem; background: var(--color-bg-surface-alt); min-height: 36px; display: flex; align-items: center;';

  const updateDisplay = async () => {
    if (!value || value === '') {
      displayArea.textContent = '(no item selected)';
      displayArea.style.color = 'var(--color-border-dark)';
      displayArea.style.fontStyle = 'italic';
    } else {
      displayArea.textContent = 'Loading...';
      displayArea.style.color = 'var(--color-text-secondary)';
      displayArea.style.fontStyle = 'italic';

      try {
        const item = await api.get(value);
        displayArea.textContent = item.name || item.content?.title || item.id.substring(0, 8) + '...';
        displayArea.style.color = 'var(--color-text)';
        displayArea.style.fontStyle = 'normal';
      } catch (e) {
        displayArea.textContent = '(invalid reference: ' + value.substring(0, 8) + '...)';
        displayArea.style.color = 'var(--color-danger)';
        displayArea.style.fontStyle = 'italic';
      }
    }
  };

  updateDisplay();
  container.appendChild(displayArea);

  if (!options.readonly) {
    // Select button
    const selectBtn = api.createElement('button');
    selectBtn.textContent = 'Select...';
    selectBtn.style.cssText = 'padding: 8px 16px; cursor: pointer; background: var(--color-primary); color: white; border: none; border-radius: var(--border-radius); font-size: 0.875rem;';
    selectBtn.onclick = () => openModal();
    container.appendChild(selectBtn);

    // Clear button (only show if there's a value)
    const clearBtn = api.createElement('button');
    clearBtn.textContent = '\u00d7';
    clearBtn.title = 'Clear selection';
    clearBtn.style.cssText = 'padding: 8px 12px; cursor: pointer; background: var(--color-danger); color: white; border: none; border-radius: var(--border-radius); font-size: 1rem; font-weight: bold;';
    clearBtn.onclick = () => {
      onChange('');
      value = '';
      updateDisplay();
    };
    if (value && value !== '') {
      container.appendChild(clearBtn);
    }

    // Modal using modal-lib
    const openModal = async () => {
      const modalLib = await api.require('modal-lib');

      const { close, contentContainer } = modalLib.showModal({
        title: options.modalTitle || 'Select Item',
        width: '600px',
        maxHeight: '80vh',
        api
      });

      // Load search library and create search UI
      const searchLib = await api.require('item-search-lib');
      searchLib.createSearchUI(
        contentContainer,
        (selectedItem) => {
          onChange(selectedItem.id);
          value = selectedItem.id;
          updateDisplay();
          close();
        },
        api,
        {
          placeholder: options.searchPlaceholder || 'Search for items...',
          targetContainer: options.targetContainer || null,
          autoFocus: true
        }
      );
    };
  }

  return container;
}

export function render(value, onChange, api, options = {}) {
  const props = {
    type: 'number',
    value: value ?? '',
    style: 'width: 100%; padding: 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); font-size: 0.875rem;' +
           (options.readonly ? ' background: var(--color-bg-body);' : ''),
    oninput: (e) => {
      const val = e.target.value === '' ? null : Number(e.target.value);
      onChange(val);
    }
  };

  if (options.min !== undefined) props.min = options.min;
  if (options.max !== undefined) props.max = options.max;
  if (options.step !== undefined) props.step = options.step;
  if (options.readonly) props.readonly = true;

  return api.createElement('input', props);
}

