// Type Workshop view — visual form for creating and editing Hobson types

export async function render(workshop, api) {
  const container = api.createElement('div', {
    style: 'width: 100%; max-width: 800px; margin: 0 auto; padding: 20px; box-sizing: border-box;'
  }, []);

  // Constants
  const TYPE_DEFINITION = '11111111-0000-0000-0000-000000000000';
  const ITEM_TYPE = '00000000-0000-0000-0000-000000000000';
  const VIEW_TYPE = 'aaaaaaaa-0000-0000-0000-000000000000';

  const DELEGATE_CODE = [
    'export async function render(item, api) {',
    "  const genericView = await api.require('generic-view');",
    '  return genericView.render(item, api);',
    '}'
  ].join('\n');

  const FIELD_VIEWS = [
    'heading', 'text', 'textarea', 'markdown', 'code',
    'checkbox', 'number', 'timestamp', 'tags', 'item-ref', 'json', 'object'
  ];

  const MODES = ['both', 'readonly', 'editable'];

  // Known hint properties that map to workshop field options
  const KNOWN_HINT_PROPS = new Set([
    'field_view', 'mode', 'label',
    'level', 'placeholder', 'rows', 'sizing', 'language',
    'min', 'max', 'step', 'format',
    'dividerAfter', 'collapsible', 'startCollapsed'
  ]);

  // State — initialize from persisted content or defaults
  const state = {
    typeName: workshop.content?.typeName || '',
    extendsType: workshop.content?.extendsType || ITEM_TYPE,
    typeDescription: workshop.content?.typeDescription || '',
    fields: (workshop.content?.fields || []).map(f => ({ ...f, options: { ...(f.options || {}) } })),
    editingSource: workshop.content?.editingSource || null,
    lastStatus: workshop.content?.lastStatus || null  // { msg, isError }
  };

  // Fetch all type-defs for the extends dropdown
  const allItems = await api.getAll();
  const typeDefs = allItems
    .filter(i => i.type === TYPE_DEFINITION)
    .sort((a, b) => (a.name || '').localeCompare(b.name || ''));

  // ==============================
  // Edit Existing: helpers
  // ==============================

  // Classify views for a type into generic-view delegates vs custom views
  async function classifyViews(viewIds) {
    const genericDelegates = { readonly: null, editable: null };
    const customViews = [];

    for (const viewId of viewIds) {
      const view = await api.get(viewId);
      if (!view) continue;

      const code = view.content?.code || '';
      const isDelegate = code.includes("require('generic-view')") &&
                         code.includes('genericView.render');
      const hasHints = !!view.content?.ui_hints;

      if (isDelegate && hasHints) {
        const hints = view.content.ui_hints;
        // Find first non-name hint to determine mode
        const firstHint = Object.entries(hints)
          .filter(([p]) => p !== 'name')
          .map(([, h]) => h)[0];
        if (firstHint?.mode === 'editable') {
          genericDelegates.editable = view;
        } else {
          genericDelegates.readonly = view;
        }
      } else {
        customViews.push(view);
      }
    }
    return { genericDelegates, customViews };
  }

  // Reverse-engineer workshop fields from ui_hints
  function uiHintsToFields(readonlyHints, editableHints) {
    const fields = [];
    const allPaths = new Set([
      ...Object.keys(readonlyHints || {}),
      ...Object.keys(editableHints || {})
    ]);
    allPaths.delete('name'); // auto-included heading

    for (const path of allPaths) {
      const rHint = readonlyHints?.[path];
      const eHint = editableHints?.[path];
      const hint = eHint || rHint;

      // Determine mode
      let mode = 'both';
      if (rHint && !eHint) mode = 'readonly';
      if (!rHint && eHint) mode = 'editable';

      // Normalize field_view: strip mode suffix
      let fieldView = hint.field_view;
      if (fieldView?.endsWith('-readonly') || fieldView?.endsWith('-editable')) {
        const base = fieldView.replace(/-readonly$/, '').replace(/-editable$/, '');
        if (base === 'markdown' || base === 'code') fieldView = base;
      }

      // Extract known options
      const options = {};
      if (hint.level) options.level = hint.level;
      if (hint.placeholder) options.placeholder = hint.placeholder;
      if (hint.rows) options.rows = hint.rows;
      if (hint.sizing) options.sizing = hint.sizing;
      if (hint.language) options.language = hint.language;
      if (hint.min != null) options.min = hint.min;
      if (hint.max != null) options.max = hint.max;
      if (hint.step != null) options.step = hint.step;
      if (hint.format) options.format = hint.format;
      if (hint.dividerAfter) options.dividerAfter = true;
      if (hint.collapsible) options.collapsible = true;
      if (hint.startCollapsed) options.startCollapsed = hint.startCollapsed;

      // Preserve unrecognized hint properties for round-trip fidelity
      const extraHintProps = {};
      for (const key of Object.keys(hint)) {
        if (!KNOWN_HINT_PROPS.has(key)) {
          extraHintProps[key] = hint[key];
        }
      }

      fields.push({
        id: crypto.randomUUID(),
        path,
        label: hint.label || '',
        fieldView: fieldView || 'text',
        mode,
        options,
        extraHintProps: Object.keys(extraHintProps).length > 0 ? extraHintProps : undefined
      });
    }
    return fields;
  }

  // Load an existing type into the workshop form
  async function loadType(typeDef) {
    const relLib = await api.require('related-items-lib');
    const viewIds = relLib.getViewsFor(typeDef.id);
    const { genericDelegates, customViews } = await classifyViews(viewIds);

    const readonlyView = genericDelegates.readonly;
    const editableView = genericDelegates.editable;
    const readonlyHints = readonlyView?.content?.ui_hints || {};
    const editableHints = editableView?.content?.ui_hints || {};

    state.typeName = typeDef.name || '';
    state.extendsType = typeDef.extends || ITEM_TYPE;
    state.typeDescription = typeDef.content?.description || '';
    state.fields = uiHintsToFields(readonlyHints, editableHints);
    state.editingSource = {
      typeDefId: typeDef.id,
      readonlyViewId: readonlyView?.id || null,
      editableViewId: editableView?.id || null,
      customViewIds: customViews.map(v => v.id),
      preferredViewId: typeDef.preferredView || null
    };

    // Set status message (showStatus will persistState + render)
    if (customViews.length > 0) {
      const names = customViews.map(v => v.name || v.id.substring(0, 8)).join(', ');
      showStatus('Loaded. Note: ' + customViews.length + ' custom view(s) not managed here: ' + names, 'warning');
    } else {
      showStatus('Loaded type: ' + state.typeName, 'success');
    }

    // Update form controls (these are local DOM updates, not affected by re-render
    // since the re-render from persistState will rebuild everything from state)
    nameInput.value = state.typeName;
    extendsSelect.value = state.extendsType;
    renderDescEditor();
    rebuildFields();
    renderSummary();
    updateEditModeUI();
  }

  // Reset to create-new mode
  function resetToNew() {
    state.typeName = '';
    state.extendsType = ITEM_TYPE;
    state.typeDescription = '';
    state.fields = [];
    state.editingSource = null;
    state.lastStatus = null;
    persistState();
    nameInput.value = '';
    extendsSelect.value = ITEM_TYPE;
    renderDescEditor();
    rebuildFields();
    renderSummary();
    updateEditModeUI();
    renderStatusArea();
  }

  // Show the type picker modal
  async function showTypePicker() {
    const modalLib = await api.require('modal-lib');

    modalLib.showModal({
      title: 'Load Existing Type',
      width: '480px',
      api,
      content: ({ close }) => {
        const wrapper = api.createElement('div', {
          style: 'display: flex; flex-direction: column; gap: 8px;'
        }, []);

        // Search input
        const searchInput = api.createElement('input', {
          type: 'text',
          placeholder: 'Filter types...',
          style: inputStyle + ' margin-bottom: 8px;'
        }, []);
        wrapper.appendChild(searchInput);

        // Type list
        const listEl = api.createElement('div', {
          style: 'max-height: 360px; overflow-y: auto; display: flex; flex-direction: column; gap: 4px;'
        }, []);

        function renderList(filter) {
          listEl.innerHTML = '';
          const filtered = typeDefs.filter(td => {
            if (!filter) return true;
            const f = filter.toLowerCase();
            return (td.name || '').toLowerCase().includes(f) ||
                   td.id.toLowerCase().includes(f);
          });
          if (filtered.length === 0) {
            listEl.appendChild(api.createElement('div', {
              style: 'padding: 12px; color: var(--color-text-secondary); text-align: center;'
            }, ['No matching types.']));
            return;
          }
          for (const td of filtered) {
            const row = api.createElement('div', {
              style: 'padding: 8px 12px; border-radius: var(--border-radius); cursor: pointer; display: flex; justify-content: space-between; align-items: center;'
            }, []);
            row.appendChild(api.createElement('span', {
              style: 'font-weight: 500;'
            }, [td.name || td.id.substring(0, 8)]));
            row.appendChild(api.createElement('span', {
              style: 'font-size: 0.75rem; color: var(--color-text-secondary);'
            }, [td.id.substring(0, 8)]));
            row.onmouseenter = () => { row.style.background = 'var(--color-bg-hover)'; };
            row.onmouseleave = () => { row.style.background = ''; };
            row.onclick = async () => {
              close();
              try {
                await loadType(td);
              } catch (e) {
                console.error('loadType failed:', e);
                showStatus('Load failed: ' + e.message, 'error');
              }
            };
            listEl.appendChild(row);
          }
        }

        searchInput.oninput = () => renderList(searchInput.value);
        renderList('');

        wrapper.appendChild(listEl);

        // Focus search after modal opens
        setTimeout(() => searchInput.focus(), 50);
        return wrapper;
      }
    });
  }

  // Persist state to workshop item (symbol-browser pattern)
  const persistState = () => {
    workshop.content = { ...workshop.content, ...state };
    workshop.modified = Date.now();
    api.set(workshop);
  };

