// viewport-mobile-view — Phone-optimized viewport with bottom action bar.
// Replaces viewport-desktop-view on touch devices (screens: { touch: true }).

export async function render(item, api) {
  // === URL root resolution (same logic as viewport-view) ===
  const params = new URLSearchParams(window.location.search);
  const urlRoot = params.get('root');
  const storedSpec = item.attachments?.[0];
  const storedRootId = typeof storedSpec === 'string' ? storedSpec : storedSpec?.id;

  let rootId = storedRootId;
  let rootSpec = storedSpec;

  if (urlRoot && urlRoot !== storedRootId) {
    try {
      await api.get(urlRoot);
      await api.set(
        { ...item, attachments: [{ id: urlRoot }], modified: Date.now() },
        { silent: true }
      );
      rootId = urlRoot;
      rootSpec = { id: urlRoot };
    } catch {
      // URL root not found, keep stored
    }
  }

  // Honor the user's explicit view choice if it matches this environment,
  // otherwise let resolveView pick an appropriate view.
  const storedViewId = rootSpec?.view?.type || rootSpec?.view || rootSpec?.renderer || null;
  let rootViewId = null;
  if (storedViewId) {
    try {
      const vpRendering = await api.require('viewport-rendering');
      const rs = vpRendering.getRendering();
      const storedView = await api.get(storedViewId);
      if (rs.viewMatchesEnv(storedView)) rootViewId = storedViewId;
    } catch { /* view not found, let resolveView handle it */ }
  }

  // === Set document title ===
  if (rootId) {
    try {
      const rootItem = await api.get(rootId);
      const name = rootItem.content?.title || rootItem.name || rootId.slice(0, 8);
      document.title = `${name} - Hobson`;
    } catch {
      document.title = 'Hobson';
    }
  } else {
    document.title = 'Hobson';
  }
  // Sync to Tauri window title
  if (window.__TAURI__?.window?.getCurrentWindow) {
    window.__TAURI__.window.getCurrentWindow().setTitle(document.title).catch(() => {});
  }

  // === Selection state ===
  let selectedItemId = null;
  let selectedElement = null;

  function findItemElement(target) {
    return target.closest('[data-parent-id][data-item-id]')
      || target.closest('[data-item-id]');
  }

  function updateSelectionVisual() {
    container.querySelectorAll('[data-item-id].item-selected').forEach(el =>
      el.classList.remove('item-selected')
    );
    if (selectedElement) selectedElement.classList.add('item-selected');
  }

  function selectItem(iid, el) {
    selectedItemId = iid;
    selectedElement = el;
    api.viewport.select(iid, el?.getAttribute('data-parent-id'));
    updateSelectionVisual();
  }

  function clearSelection() {
    selectedItemId = null;
    selectedElement = null;
    api.viewport.clearSelection();
    updateSelectionVisual();
  }

  // === Build DOM ===
  const container = api.createElement('div', {
    class: 'mobile-viewport',
    style: 'display:flex; flex-direction:column; height:100%; position:relative;'
  });

  // --- Content area ---
  const contentArea = api.createElement('div', {
    class: 'mobile-viewport-content',
    style: 'flex:1; overflow:auto; display:flex; flex-direction:column; min-height:0;'
  });

  if (rootId) {
    const decorator = (dom, itemId, theItem) => {
      dom.setAttribute('data-item-id', itemId);
      const iname = theItem?.name || theItem?.content?.title || itemId.slice(0, 8);
      let typeName;
      try {
        const ti = theItem?.type;
        typeName = ti ? ti.slice(0, 8) : '?';
      } catch { typeName = '?'; }
      dom.setAttribute('title', `${iname} (${typeName})`);
    };

    const rootDom = await api.renderItem(rootId, rootViewId, {
      decorator,
      onCycle: () => {
        const el = api.createElement('div', {
          style: 'padding:20px; color:var(--color-text-secondary); font-style:italic; text-align:center;'
        });
        el.textContent = rootId.slice(0, 8) + ' (cycle)';
        return el;
      }
    });
    if (rootDom) {
      rootDom.style.cssText = 'flex:1; min-height:0; display:flex; flex-direction:column;';
      contentArea.appendChild(rootDom);
    }
  } else {
    const empty = api.createElement('div', {
      style: 'padding:40px; text-align:center; color:var(--color-text-secondary); flex:1; display:flex; align-items:center; justify-content:center;'
    });
    empty.innerHTML = 'No item selected.<br><br>Tap Search to find items.';
    contentArea.appendChild(empty);
  }

  // Tap to select
  contentArea.addEventListener('click', (e) => {
    hideSheet();
    const el = findItemElement(e.target);
    if (el) {
      selectItem(el.getAttribute('data-item-id'), el);
      e.stopPropagation();
    } else {
      clearSelection();
    }
  });

  container.appendChild(contentArea);

  // --- Bottom sheet (context menu) ---
  const backdrop = api.createElement('div', {
    class: 'mobile-bottom-sheet-backdrop',
    style: 'display:none; position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.4); z-index:10000;'
  });

  const sheet = api.createElement('div', {
    class: 'mobile-bottom-sheet',
    style: 'position:fixed; bottom:0; left:0; right:0; max-height:60vh; background:var(--color-bg-surface); border-radius:12px 12px 0 0; overflow-y:auto; z-index:10001; padding-bottom:env(safe-area-inset-bottom);'
  });

  const handle = api.createElement('div', {
    style: 'width:36px; height:4px; background:var(--color-border); border-radius:2px; margin:8px auto 4px;'
  });
  sheet.appendChild(handle);

  const sheetBody = api.createElement('div', { class: 'mobile-sheet-body' });
  sheet.appendChild(sheetBody);
  backdrop.appendChild(sheet);

  function hideSheet() {
    backdrop.style.display = 'none';
    sheetBody.innerHTML = '';
  }

  backdrop.addEventListener('click', (e) => {
    if (e.target === backdrop) hideSheet();
  });

  async function showContextMenu(itemId) {
    sheetBody.innerHTML = '';
    const menuLib = await api.require('context-menu-lib');
    const dismiss = () => {
      hideSheet();
    };
    const menuEl = await menuLib.buildItemMenu(api, itemId, { onDismiss: dismiss, rootId });
    // Override desktop positioning for bottom sheet
    menuEl.style.cssText = 'position:static; display:block; box-shadow:none; max-width:none; border:none; min-width:0; padding:0;';
    sheetBody.appendChild(menuEl);
    backdrop.style.display = 'block';
  }

  container.appendChild(backdrop);

  // --- Overlay rendering (search palette, etc.) ---
  const overlaySpecs = (item.attachments || []).slice(1);
  for (const spec of overlaySpecs) {
    const oid = typeof spec === 'string' ? spec : spec.id;
    const wrapper = api.createElement('div', {
      style: 'position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.5); display:flex; align-items:flex-start; justify-content:center; padding-top:5vh; z-index:10000000;'
    });
    const modal = api.createElement('div', {
      style: 'background:var(--color-bg-surface); border-radius:8px; width:92vw; max-height:80vh; display:flex; flex-direction:column; box-shadow:0 4px 20px rgba(0,0,0,0.3); overflow:auto;'
    });

    const closeOverlay = async () => {
      await api.detach(item.id, oid);
      (await api.require('viewport-rendering')).getRendering()?.renderViewport();
    };
    wrapper.addEventListener('click', (e) => {
      if (e.target === wrapper) closeOverlay();
    });
    document.addEventListener('keydown', function escHandler(e) {
      if (e.key === 'Escape') {
        e.preventDefault();
        document.removeEventListener('keydown', escHandler);
        closeOverlay();
      }
    });

    const childDom = await api.renderItem(oid);
    if (childDom) modal.appendChild(childDom);

    wrapper.appendChild(modal);
    container.appendChild(wrapper);

    setTimeout(() => {
      const input = modal.querySelector('input');
      if (input) input.focus();
    }, 0);
  }

  // --- Bottom action bar ---
  const actionBar = api.createElement('div', {
    class: 'mobile-action-bar',
    style: [
      'display:flex', 'background:var(--color-bg-surface)',
      'border-top:1px solid var(--color-border)',
      'padding-bottom:env(safe-area-inset-bottom)',
      'flex-shrink:0'
    ].join(';')
  });

  function actionButton(label, icon, handler) {
    const btn = api.createElement('button', {
      style: [
        'flex:1', 'display:flex', 'flex-direction:column', 'align-items:center', 'justify-content:center',
        'background:none', 'border:none', 'color:var(--color-text-secondary)',
        'font-size:0.625rem', 'gap:2px', 'cursor:pointer', 'min-height:48px',
        'padding:4px 0', '-webkit-tap-highlight-color:transparent'
      ].join(';')
    });
    const iconEl = api.createElement('span', { style: 'font-size:1.25rem;' });
    iconEl.textContent = icon;
    btn.appendChild(iconEl);
    const labelEl = api.createElement('span');
    labelEl.textContent = label;
    btn.appendChild(labelEl);
    btn.addEventListener('click', handler);
    return btn;
  }

  actionBar.appendChild(actionButton('Search', '\u2315', async () => {
    await api.showItemList();
    (await api.require('viewport-rendering')).getRendering()?.renderViewport();
  }));
  actionBar.appendChild(actionButton('Edit', '\u270e', async () => {
    // Find the most specific displayed item (e.g. active tab in tabbed view),
    // falling back to the root item. Exclude items inside transclusion wrappers
    // (data-provenance-node) — those are embedded content, not navigation targets.
    const candidates = rootId ? [...document.querySelectorAll(`[data-parent-id="${rootId}"][data-item-id]`)] : [];
    const activeEl = candidates.find(el => !el.closest('[data-provenance-node]')) ?? null;
    const editId = activeEl?.getAttribute('data-item-id') || rootId;
    if (!editId) return;
    const ctxLib = await api.require('context-menu-lib');
    const editItem = await api.get(editId);
    const editView = await ctxLib.findEditableView(api, editItem.type);
    if (!editView) return;
    if (editId !== rootId && activeEl) {
      const parentId = activeEl.getAttribute('data-parent-id');
      await api.setAttachmentView(parentId, editId, editView.id);
      await api.rerenderItem(editId);
    } else {
      const vpMgr = window.kernel.moduleSystem.getCached('viewport-manager');
      await vpMgr.navigate(editId, { view: editView.id });
    }
  }));
  actionBar.appendChild(actionButton('More', '\u22ef', () => {
    const targetId = selectedItemId || rootId;
    if (targetId) showContextMenu(targetId);
  }));
  actionBar.appendChild(actionButton('REPL', '\u2328', async () => {
    // Toggle: if already open, close it
    const existing = container.querySelector('.mobile-repl-overlay');
    if (existing) { existing.remove(); return; }

    const overlay = api.createElement('div', {
      class: 'mobile-repl-overlay',
      style: 'position:fixed; top:0; left:0; right:0; bottom:0; background:var(--color-bg-surface); display:flex; flex-direction:column; z-index:10000;'
    });

    // Header with close button
    const hdr = api.createElement('div', {
      style: 'display:flex; align-items:center; justify-content:space-between; padding:8px 12px; border-bottom:1px solid var(--color-border); flex-shrink:0; background:var(--color-bg-surface);'
    });
    const titleEl = api.createElement('span', { style: 'font-weight:600; font-size:0.875rem;' });
    titleEl.textContent = 'REPL';
    hdr.appendChild(titleEl);
    const closeBtn = api.createElement('button', {
      style: 'background:none; border:none; color:var(--color-text-secondary); font-size:1.25rem; cursor:pointer; padding:4px 8px; -webkit-tap-highlight-color:transparent;'
    });
    closeBtn.textContent = '\u2715';
    closeBtn.addEventListener('click', () => overlay.remove());
    hdr.appendChild(closeBtn);
    overlay.appendChild(hdr);

    // Override REPL layout to stack vertically on mobile
    const mobileStyle = api.createElement('style');
    mobileStyle.textContent = '.mobile-repl-overlay .repl-panel-content{flex-direction:column!important;flex:1;min-height:0} .mobile-repl-overlay .repl-input-section{flex:1!important;min-height:0} .mobile-repl-overlay .repl-vertical-splitter{display:none!important} .mobile-repl-overlay .repl-output-section{flex:1!important;min-height:0}';
    overlay.appendChild(mobileStyle);

    // Render REPL view into overlay body
    const body = api.createElement('div', { style: 'flex:1; min-height:0; display:flex; flex-direction:column;' });
    try {
      const replItem = await api.get('f1111111-0003-0003-0000-000000000000');
      const replView = await api.require('f1111111-0003-0002-0000-000000000000');
      const replDom = await replView.render(replItem, api);
      replDom.style.cssText = 'flex:1; min-height:0; display:flex; flex-direction:column;';
      body.appendChild(replDom);
    } catch (e) {
      const err = api.createElement('div', { style: 'padding:16px; color:var(--color-danger);' });
      err.textContent = 'Failed to load REPL: ' + e.message;
      body.appendChild(err);
    }
    overlay.appendChild(body);

    // Escape to close
    const escHandler = (e) => {
      if (e.key === 'Escape') { overlay.remove(); document.removeEventListener('keydown', escHandler); }
    };
    document.addEventListener('keydown', escHandler);

    container.appendChild(overlay);
    setTimeout(() => { const ta = overlay.querySelector('textarea'); if (ta) ta.focus(); }, 0);
  }));

  const syncBtn = actionButton('Sync', '\u27f3', async () => {
    const labelEl = syncBtn.querySelector('span:last-child');
    const iconEl = syncBtn.querySelector('span:first-child');
    labelEl.textContent = 'Syncing\u2026';
    syncBtn.disabled = true;
    try {
      const client = await api.require('sync-client');
      const result = await client.sync();
      iconEl.textContent = '\u2713';
      labelEl.textContent = result.accepted > 0 ? `${result.accepted} new` : 'Done';
    } catch (e) {
      iconEl.textContent = '\u2717';
      labelEl.textContent = 'Failed';
      throw e;
    }
    syncBtn.disabled = false;
    setTimeout(() => { iconEl.textContent = '\u27f3'; labelEl.textContent = 'Sync'; }, 2000);
  });
  actionBar.appendChild(syncBtn);

  container.appendChild(actionBar);

  return container;
}

// image-view — Renders an image item
// Fetches the blob from the blob store by item ID, converts to data URL for display.

export async function render(item, api) {
  const el = api.createElement('div', { className: 'image-view' });
  el.style.cssText = 'display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 8px;';

  try {
    const blob = await api.getBlob(item.id);
    const dataUrl = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
    const img = api.createElement('img');
    img.src = dataUrl;
    img.alt = item.content?.alt || item.name || '';
    img.style.cssText = 'max-width: 100%; height: auto; border-radius: var(--border-radius);';
    img.draggable = false;
    el.appendChild(img);
  } catch {
    const placeholder = api.createElement('div');
    placeholder.style.cssText = 'padding: 2em; color: var(--color-text-secondary); text-align: center; border: 2px dashed var(--color-border); border-radius: var(--border-radius);';
    placeholder.textContent = 'No image data';
    el.appendChild(placeholder);
  }

  return el;
}

// image-editor-view — Editor for image items
// Stores image as a native Blob in the blob store (keyed by item ID).
// content.mimeType and content.alt are the only content fields.

export async function render(item, api) {
  const el = api.createElement('div', { className: 'image-editor-view' });
  el.style.cssText = 'display: flex; flex-direction: column; gap: 12px; padding: 8px;';

  // --- Name field ---
  const nameInput = api.createElement('input');
  nameInput.type = 'text';
  nameInput.value = item.name || '';
  nameInput.placeholder = 'Image name';
  nameInput.style.cssText = 'font-size: 1.25rem; font-weight: 600; padding: 4px 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); background: var(--color-bg-surface); color: var(--color-text); outline: none;';

  // --- Alt text field ---
  const altInput = api.createElement('input');
  altInput.type = 'text';
  altInput.value = item.content?.alt || '';
  altInput.placeholder = 'Alt text (accessibility)';
  altInput.style.cssText = 'font-size: 0.875rem; padding: 4px 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); background: var(--color-bg-surface); color: var(--color-text); outline: none;';

  // --- Preview area ---
  const preview = api.createElement('div');
  preview.style.cssText = 'display: flex; justify-content: center; align-items: center; min-height: 120px;';

  async function renderPreview() {
    preview.innerHTML = '';
    try {
      const blob = await api.getBlob(item.id);
      const dataUrl = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(blob);
      });
      const img = api.createElement('img');
      img.src = dataUrl;
      img.alt = item.content?.alt || item.name || '';
      img.style.cssText = 'max-width: 100%; max-height: 60vh; height: auto; border-radius: var(--border-radius);';
      img.draggable = false;
      preview.appendChild(img);
    } catch {
      // No blob yet — preview stays empty
    }
  }
  await renderPreview();

  // --- Drop zone ---
  const dropZone = api.createElement('div');
  dropZone.style.cssText = 'padding: 2em; text-align: center; border: 2px dashed var(--color-border); border-radius: var(--border-radius); color: var(--color-text-secondary); cursor: pointer; transition: border-color 0.15s, background 0.15s;';
  dropZone.textContent = item.content?.mimeType ? 'Drop image to replace, paste, or click to browse' : 'Drop image here, paste, or click to browse';

  // --- File loading helper ---
  async function loadFile(file) {
    if (!file || !file.type.startsWith('image/')) return;
    await api.setBlob(item.id, file);
    item.content = item.content || {};
    item.content.mimeType = file.type;
    if (!item.name || item.name === 'Untitled') item.name = file.name.replace(/\.[^.]+$/, '');
    nameInput.value = item.name;
    await renderPreview();
    dropZone.textContent = 'Drop image to replace, paste, or click to browse';
  }

  // --- Tauri file picker or browser fallback ---
  async function pickFile() {
    const tauri = window.__TAURI__;
    if (tauri) {
      try {
        const result = await tauri.dialog.open({
          multiple: false,
          filters: [{ name: 'Images', extensions: ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg', 'bmp', 'ico'] }]
        });
        if (result) {
          const bytes = await tauri.fs.readFile(result);
          const ext = result.split('.').pop().toLowerCase();
          const mimeMap = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp', svg: 'image/svg+xml', bmp: 'image/bmp', ico: 'image/x-icon' };
          const mimeType = mimeMap[ext] || 'image/png';
          const blob = new Blob([bytes], { type: mimeType });
          await api.setBlob(item.id, blob);
          item.content = item.content || {};
          item.content.mimeType = mimeType;
          const fileName = result.split('/').pop().split('\\').pop().replace(/\.[^.]+$/, '');
          if (!item.name || item.name === 'Untitled') item.name = fileName;
          nameInput.value = item.name;
          await renderPreview();
          dropZone.textContent = 'Drop image to replace, paste, or click to browse';
        }
      } catch (e) {
        console.error('[image-editor] Tauri file picker error:', e);
      }
    } else {
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = 'image/*';
      input.onchange = () => { if (input.files[0]) loadFile(input.files[0]); };
      input.click();
    }
  }

  dropZone.addEventListener('click', pickFile);

  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--color-primary)';
    dropZone.style.background = 'var(--color-primary-light)';
  });
  dropZone.addEventListener('dragleave', () => {
    dropZone.style.borderColor = 'var(--color-border)';
    dropZone.style.background = '';
  });
  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--color-border)';
    dropZone.style.background = '';
    const file = e.dataTransfer.files[0];
    if (file) loadFile(file);
  });

  el.addEventListener('paste', (e) => {
    const items = e.clipboardData?.items;
    if (!items) return;
    for (const clipItem of items) {
      if (clipItem.type.startsWith('image/')) {
        e.preventDefault();
        loadFile(clipItem.getAsFile());
        return;
      }
    }
  });
  el.tabIndex = 0;

  // --- Action buttons ---
  const actions = api.createElement('div');
  actions.style.cssText = 'display: flex; gap: 8px; justify-content: flex-end;';

  const cancelBtn = api.createElement('button');
  cancelBtn.textContent = 'Cancel';
  cancelBtn.style.cssText = 'padding: 6px 16px; background: var(--color-bg-surface-alt); color: var(--color-text); border: 1px solid var(--color-border); border-radius: var(--border-radius); cursor: pointer; font-size: 0.875rem;';
  cancelBtn.addEventListener('click', async () => {
    if (api.restorePreviousView) await api.restorePreviousView(item.id);
  });
  actions.appendChild(cancelBtn);

  const saveBtn = api.createElement('button');
  saveBtn.textContent = 'Save';
  saveBtn.style.cssText = 'padding: 6px 16px; background: var(--color-primary); color: white; border: none; border-radius: var(--border-radius); cursor: pointer; font-size: 0.875rem;';
  saveBtn.addEventListener('click', async () => {
    item.name = nameInput.value || item.name;
    item.content = item.content || {};
    if (altInput.value) item.content.alt = altInput.value;
    else delete item.content.alt;
    await api.update(item);
    if (api.restorePreviousView) await api.restorePreviousView(item.id);
  });
  actions.appendChild(saveBtn);

  el.appendChild(nameInput);
  el.appendChild(altInput);
  el.appendChild(preview);
  el.appendChild(dropZone);
  el.appendChild(actions);

  return el;
}

// image-import-lib — Creates image items from various sources
// Used by obsidian-import, paste handlers, and the image editor

const IMAGE_TYPE = 'd0d0d0d0-0010-0000-0000-000000000000';

/** Create an image item from a base64 data URL.
 * @param {Object} api - Hobson API
 * @param {string} dataUrl - Base64 data URL (data:image/png;base64,...)
 * @param {Object} [opts] - Options: name, alt
 * @returns {Promise<string>} The new image item's ID
 */
export async function fromDataUrl(api, dataUrl, opts = {}) {
  const mimeMatch = dataUrl.match(/^data:([^;]+);/);
  const mimeType = mimeMatch ? mimeMatch[1] : 'image/png';
  const base64 = dataUrl.split(',')[1];
  const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
  const blob = new Blob([bytes], { type: mimeType });
  return fromBlob(api, blob, opts);
}

/** Create an image item from a Blob or File.
 * @param {Object} api - Hobson API
 * @param {Blob|File} blob - Image blob
 * @param {Object} [opts] - Options: name, alt
 * @returns {Promise<string>} The new image item's ID
 */
export async function fromBlob(api, blob, opts = {}) {
  const id = crypto.randomUUID();
  const name = opts.name || (blob.name ? blob.name.replace(/\.[^.]+$/, '') : 'Image');
  const item = {
    id,
    name,
    type: IMAGE_TYPE,
    created: Date.now(),
    modified: Date.now(),
    content: {
      mimeType: blob.type || 'image/png',
      alt: opts.alt || undefined
    },
    attachments: []
  };
  await api.set(item);
  await api.setBlob(id, blob);
  return id;
}

/** Create an image item from a file path (Tauri only).
 * @param {Object} api - Hobson API
 * @param {string} filePath - Absolute file path
 * @param {Object} [opts] - Options: name, alt
 * @returns {Promise<string>} The new image item's ID
 */
export async function fromFile(api, filePath, opts = {}) {
  const tauri = window.__TAURI__;
  if (!tauri) throw new Error('fromFile requires Tauri (filesystem access)');

  const bytes = await tauri.fs.readFile(filePath);
  const ext = filePath.split('.').pop().toLowerCase();
  const mimeMap = {
    png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg',
    gif: 'image/gif', webp: 'image/webp', svg: 'image/svg+xml',
    bmp: 'image/bmp', ico: 'image/x-icon'
  };
  const mimeType = mimeMap[ext] || 'image/png';
  const blob = new Blob([bytes], { type: mimeType });
  const fileName = filePath.split('/').pop().split('\\').pop().replace(/\.[^.]+$/, '');
  const name = opts.name || fileName || 'Image';
  return fromBlob(api, blob, { ...opts, name });
}

// obsidian-import — Imports an Obsidian vault into Hobson
// Uses Tauri fs/dialog for filesystem access, markdown-to-active-text for conversion,
// image-import-lib for image files. REPL-invocable:
//   const imp = await api.require('obsidian-import');
//   await imp.importVault(api);

const NOTE_TYPE = '871ae771-b9b1-4f40-8c7f-d9038bfb69c3';
const IMAGE_TYPE = 'd0d0d0d0-0010-0000-0000-000000000000';
const OBSIDIAN_TAG = 'efd6b48b-59b9-4ce6-8b4b-96f41f58cb9c';
const IMAGE_EXTENSIONS = new Set(['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg', 'bmp', 'ico']);
const SKIP_EXTENSIONS = new Set(['base', 'canvas']); // Obsidian Bases and Canvas files

/**
 * Import an Obsidian vault into Hobson.
 * @param {Object} api - Hobson API
 * @param {Object} [opts]
 * @param {string} [opts.path] - Vault path (opens folder picker if omitted)
 * @param {Function} [opts.onProgress] - Callback: (message, current, total) => void
 * @returns {Promise<Object>} Import summary
 */
export async function importVault(api, opts = {}) {
  const tauri = window.__TAURI__;
  if (!tauri) throw new Error('Obsidian import requires Tauri (filesystem access)');
  try { return await _importVault(api, tauri, opts); }
  catch (e) { const msg = e?.message || e?.toString?.() || JSON.stringify(e); console.error('[obsidian-import]', e); throw new Error(msg); }
}

async function _importVault(api, tauri, opts) {

  const log = opts.onProgress || ((msg) => console.log('[obsidian-import] ' + msg));

  // --- Pick vault folder ---
  const vaultPath = opts.path || await tauri.dialog.open({
    directory: true,
    title: 'Select Obsidian Vault Folder'
  });
  if (!vaultPath) return { message: 'Cancelled' };
  log('Scanning vault: ' + vaultPath);

  // --- Clean up previous import ---
  // Also remove old flat tags from prior imports (they weren't tagged with OBSIDIAN_TAG,
  // but their description contains the importer signature string)
  if (opts.cleanUp && confirm("This will delete all existing items tagged 'obsidian'!")) {     
    const allItems = await api.getAll();
    const previousImport = allItems.filter(it =>
      it.content?.tags?.includes(OBSIDIAN_TAG) ||
      JSON.stringify(it.content?.description || '').includes('Imported from Obsidian tag')
    );
    if (previousImport.length > 0) {
      log(`Removing ${previousImport.length} items from previous import...`);
      for (const item of previousImport) {
        await api.delete(item.id);
      }
      log('Cleanup complete');
    }
  }

  // --- Phase 1: Scan all files ---
  const allFiles = await walkDir(tauri, vaultPath);
  log(`Scanned ${allFiles.length} files`);
  const mdFiles = [];
  const imageFiles = [];
  const otherFiles = [];

  for (const file of allFiles) {
    // Skip hidden files and .obsidian config
    if (file.relativePath.startsWith('.')) continue;
    if (file.relativePath.includes('/.')) continue;

    const ext = (file.name.split('.').pop() || '').toLowerCase();
    if (ext === 'md') {
      mdFiles.push(file);
    } else if (IMAGE_EXTENSIONS.has(ext)) {
      imageFiles.push(file);
    } else if (!SKIP_EXTENSIONS.has(ext)) {
      otherFiles.push(file);
    }
  }
  log(`Found ${mdFiles.length} notes, ${imageFiles.length} images, ${otherFiles.length} other files`);

  // --- Phase 2: Assign GUIDs and build name maps ---
  const noteNameToGuid = {};
  const noteGuidToFile = {};
  for (const file of mdFiles) {
    const guid = crypto.randomUUID();
    const noteName = file.name.replace(/\.md$/i, '');
    // Handle duplicate names: first one wins, warn on duplicates
    if (noteNameToGuid[noteName]) {
      log(`Warning: duplicate note name "${noteName}" — using first occurrence`);
      continue;
    }
    noteNameToGuid[noteName] = guid;
    noteGuidToFile[guid] = { ...file, noteName };
  }

  // --- Phase 3: Import images ---
  const imageImport = await api.require('image-import-lib');
  const imageNameToGuid = {};
  let imageCount = 0;
  for (const file of imageFiles) {
    try {
      const guid = await imageImport.fromFile(api, file.path, { name: file.name.replace(/\.[^.]+$/, '') });
      // Tag with obsidian tag
      const imgItem = await api.get(guid);
      imgItem.content.tags = [OBSIDIAN_TAG];
      await api.set(imgItem, { silent: true });
      imageNameToGuid[file.name] = guid;
      // Also map without path (Obsidian often references by filename only)
      const baseName = file.name;
      if (!imageNameToGuid[baseName]) imageNameToGuid[baseName] = guid;
      imageCount++;
      if (imageCount % 10 === 0) log(`Images: ${imageCount}/${imageFiles.length}`);
    } catch (e) {
      log(`Warning: failed to import image ${file.name}: ${e.message}`);
    }
  }
  log(`Imported ${imageCount} images`);

  // --- Phase 4: Import notes ---
  const converter = await api.require('markdown-to-active-text');
  let noteCount = 0;
  let errorCount = 0;
  const tagItemCache = {}; // obsidian tag → hobson tag GUID

  for (const [guid, file] of Object.entries(noteGuidToFile)) {
    try {
      const text = await tauri.fs.readTextFile(file.path);
      const { frontmatter, body } = parseFrontmatter(text);

      // Rewrite wikilinks and image embeds
      const rewritten = rewriteObsidianSyntax(body, noteNameToGuid, imageNameToGuid);

      // Convert markdown to Active Text
      const ast = converter.convert(rewritten);

      // Build content from frontmatter
      const content = { description: ast };

      // Handle Obsidian tags (from frontmatter and inline) + obsidian import tag
      const tagGuids = [OBSIDIAN_TAG];
      const obsidianTags = extractTags(frontmatter, body);
      for (const tagName of obsidianTags) {
        if (!tagItemCache[tagName]) {
          await findOrCreateTag(api, tagName, tagItemCache);
        }
        tagGuids.push(tagItemCache[tagName]);
      }
      content.tags = tagGuids;

      // Store frontmatter fields (excluding tags, which we handled above)
      for (const [key, value] of Object.entries(frontmatter)) {
        if (key === 'tags' || key === 'tag') continue;
        if (key === 'aliases' || key === 'cssclass') continue; // Obsidian-specific, skip
        content[key] = value;
      }

      const item = {
        id: guid,
        name: file.noteName,
        type: NOTE_TYPE,
        created: Date.now(),
        modified: Date.now(),
        content,
        attachments: []
      };

      await api.set(item);
      noteCount++;
      if (noteCount % 25 === 0) log(`Notes: ${noteCount}/${Object.keys(noteGuidToFile).length}`);
    } catch (e) {
      log(`Error importing "${file.noteName}": ${e?.message || e?.toString?.() || JSON.stringify(e)}`);
      console.error('[obsidian-import] Failed:', file.noteName, file.path, e);
      errorCount++;
    }
  }

  const summary = {
    message: `Import complete: ${noteCount} notes, ${imageCount} images` + (errorCount ? `, ${errorCount} errors` : ''),
    notes: noteCount,
    images: imageCount,
    errors: errorCount,
    tags: Object.keys(tagItemCache).length
  };
  log(summary.message);
  return summary;
}

// --- Filesystem helpers ---

async function walkDir(tauri, dirPath, basePath = null) {
  if (!basePath) basePath = dirPath;
  const entries = await tauri.fs.readDir(dirPath);
  const results = [];
  for (const entry of entries) {
    const name = entry.name ?? entry.path?.split('/').pop();
    if (!name) continue;
    const fullPath = dirPath + '/' + name;
    const relativePath = fullPath.substring(basePath.length + 1);
    // Tauri v2: entry.isDirectory is a boolean; some versions use entry.children !== undefined
    const isDir = entry.isDirectory === true || entry.isDirectory === undefined && entry.children != null;
    if (isDir) {
      try {
        const children = await walkDir(tauri, fullPath, basePath);
        results.push(...children);
      } catch (e) {
        console.warn('[obsidian-import] Could not read directory:', fullPath, e);
      }
    } else {
      results.push({ path: fullPath, name, relativePath });
    }
  }
  return results;
}

// --- Frontmatter parsing ---

function parseFrontmatter(text) {
  const frontmatter = {};
  let body = text;

  if (text.startsWith('---')) {
    const endIdx = text.indexOf('\n---', 3);
    if (endIdx !== -1) {
      const yamlBlock = text.substring(4, endIdx).trim();
      body = text.substring(endIdx + 4).trim();

      // Simple YAML parser (handles key: value, key: [array], key: list)
      let currentKey = null;
      let currentList = null;
      for (const line of yamlBlock.split('\n')) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#')) continue;

        // List continuation
        if (trimmed.startsWith('- ') && currentKey) {
          if (!currentList) currentList = [];
          currentList.push(trimmed.substring(2).trim().replace(/^["']|["']$/g, ''));
          frontmatter[currentKey] = currentList;
          continue;
        }

        // Flush previous list
        currentList = null;

        const colonIdx = trimmed.indexOf(':');
        if (colonIdx === -1) continue;

        currentKey = trimmed.substring(0, colonIdx).trim();
        let value = trimmed.substring(colonIdx + 1).trim();

        // Inline array: [a, b, c]
        if (value.startsWith('[') && value.endsWith(']')) {
          value = value.slice(1, -1).split(',').map(s => s.trim().replace(/^["']|["']$/g, ''));
          frontmatter[currentKey] = value;
          currentList = null;
          continue;
        }

        // Strip quotes
        if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        // Boolean/number coercion
        if (value === 'true') value = true;
        else if (value === 'false') value = false;
        else if (value !== '' && !isNaN(value)) value = Number(value);

        if (value !== '') {
          frontmatter[currentKey] = value;
        } else {
          // Key with no value — might be start of list
          currentList = [];
        }
      }
    }
  }

  return { frontmatter, body };
}

// --- Wikilink and image rewriting ---

function rewriteObsidianSyntax(markdown, noteNameToGuid, imageNameToGuid) {
  // ![[image.png]] → ![image](item://guid) (becomes transclusion)
  // ![[Note Name]] → ![Note Name](item://guid) (becomes transclusion)
  // [[Note Name|display]] → [display](item://guid)
  // [[Note Name#heading|display]] → [display](item://guid)
  // [[Note Name]] → [Note Name](item://guid)
  // [[Note Name#heading]] → [Note Name](item://guid)

  let result = markdown;

  // Image/file embeds: ![[filename]]
  result = result.replace(/!\[\[([^\]]+)\]\]/g, (match, ref) => {
    const name = ref.split('|')[0].split('#')[0].trim();
    // Check images first
    if (imageNameToGuid[name]) {
      return '![' + name + '](item://' + imageNameToGuid[name] + '?embed)';
    }
    // Then notes (transclusion)
    if (noteNameToGuid[name]) {
      return '![' + name + '](item://' + noteNameToGuid[name] + ')';
    }
    // Unresolved — leave as text
    return match;
  });

  // Wikilinks: [[Note Name]] or [[Note Name|display]] or [[Note Name#heading]]
  result = result.replace(/\[\[([^\]]+)\]\]/g, (match, ref) => {
    const parts = ref.split('|');
    const target = parts[0].split('#')[0].trim();
    const display = parts.length > 1 ? parts[1].trim() : target;
    const guid = noteNameToGuid[target];
    if (guid) {
      return '[' + display + '](item://' + guid + ')';
    }
    // Unresolved — render as plain text
    return display;
  });

  return result;
}

// --- Tag handling ---

function extractTags(frontmatter, body) {
  const tags = new Set();

  // From frontmatter
  const fmTags = frontmatter.tags || frontmatter.tag;
  if (Array.isArray(fmTags)) {
    for (const t of fmTags) tags.add(String(t).replace(/^#/, ''));
  } else if (typeof fmTags === 'string') {
    for (const t of fmTags.split(/[,\s]+/)) {
      const clean = t.trim().replace(/^#/, '');
      if (clean) tags.add(clean);
    }
  }

  // From inline #tags in body (but not inside code blocks or links)
  const tagPattern = /(?:^|\s)#([a-zA-Z][a-zA-Z0-9_/-]*)/g;
  let match;
  while ((match = tagPattern.exec(body)) !== null) {
    tags.add(match[1]);
  }

  return [...tags];
}

async function findOrCreateTag(api, tagName, tagItemCache) {
  // Handle hierarchical tags: "sailing/glossary" → create "sailing", then "glossary" under it
  const segments = tagName.split('/');
  let parentId = null;
  let pathSoFar = '';

  for (const segment of segments) {
    pathSoFar = pathSoFar ? pathSoFar + '/' + segment : segment;

    // Check cache first (covers intermediate segments from earlier tags)
    if (tagItemCache[pathSoFar]) {
      parentId = tagItemCache[pathSoFar];
      continue;
    }

    // Search for existing tag with matching name and parent
    const existing = await api.query({ name: segment });
    let found = null;
    for (const item of existing) {
      if (item.name === segment && (item.content?.parent || null) === parentId) {
        found = item;
        break;
      }
    }

    if (found) {
      tagItemCache[pathSoFar] = found.id;
      parentId = found.id;
    } else {
      const id = crypto.randomUUID();
      const content = {
        description: [':doc', [':p', { s: 'Imported from Obsidian tag #' + tagName }]],
        tags: [OBSIDIAN_TAG]
      };
      if (parentId) content.parent = parentId;

      await api.set({
        id,
        name: segment,
        type: NOTE_TYPE,
        created: Date.now(),
        modified: Date.now(),
        content,
        attachments: []
      });

      tagItemCache[pathSoFar] = id;
      parentId = id;
    }
  }

  return parentId; // leaf tag ID
}

// item-history-view — shows change history for any item.
// Select an item to see its timeline of changes with auto-generated descriptions.

export async function render(item, api) {
  const container = api.createElement('div');
  container.style.cssText = 'width:100%; max-width:800px; margin:0 auto; padding:20px; box-sizing:border-box;';

  // Header
  const h2 = api.createElement('h2');
  h2.textContent = item.name || 'History Viewer';
  h2.style.cssText = 'margin:0 0 20px; font-size:1.25rem;';
  container.appendChild(h2);

  // Item selector
  const selectRow = api.createElement('div');
  selectRow.style.cssText = 'display:flex; gap:8px; margin-bottom:20px;';

  const select = api.createElement('select');
  select.style.cssText = 'flex:1; padding:8px; font-size:0.9rem; border:1px solid var(--color-border,#ccc); border-radius:4px; background:var(--color-bg-surface,#fff); color:var(--color-text,#333);';

  const allItems = await api.getAll();
  allItems.sort((a, b) => (a.name || a.id).localeCompare(b.name || b.id));

  const defaultOpt = api.createElement('option');
  defaultOpt.value = '';
  defaultOpt.textContent = 'Select an item\u2026';
  select.appendChild(defaultOpt);

  const selectedId = item.content?.selectedItemId;
  for (const it of allItems) {
    const opt = api.createElement('option');
    opt.value = it.id;
    opt.textContent = it.name || it.id.substring(0, 12);
    if (selectedId === it.id) opt.selected = true;
    select.appendChild(opt);
  }
  selectRow.appendChild(select);
  container.appendChild(selectRow);

  // Timeline container
  const timeline = api.createElement('div');
  container.appendChild(timeline);

  // Show history for selected item
  if (selectedId) {
    await showHistory(selectedId, timeline, api);
  }

  // On selection change, persist choice and re-render
  select.onchange = async () => {
    await api.set({
      ...item,
      content: { ...item.content, selectedItemId: select.value },
      modified: Date.now()
    });
  };

  return container;
}

function formatTime(ts) {
  const now = Date.now();
  const diff = now - ts;
  if (diff < 60000) return 'just now';
  if (diff < 3600000) return Math.floor(diff / 60000) + 'm ago';
  if (diff < 86400000) return Math.floor(diff / 3600000) + 'h ago';
  if (diff < 604800000) return Math.floor(diff / 86400000) + 'd ago';
  return new Date(ts).toLocaleString();
}

function describeChange(prev, curr) {
  if (!prev) return 'created';
  const changed = [];
  for (const key of ['name', 'type', 'content', 'attachments']) {
    if (JSON.stringify(prev[key]) !== JSON.stringify(curr[key])) {
      changed.push(key);
    }
  }
  return changed.length > 0 ? changed.join(', ') + ' changed' : 'modified';
}

function snapshotSummary(snapshot, api) {
  const lines = [];
  for (const key of ['id', 'name', 'type', 'created', 'modified']) {
    if (key in snapshot) {
      let val = snapshot[key];
      if (key === 'created' || key === 'modified') val = new Date(val).toLocaleString();
      lines.push(key + ': ' + val);
    }
  }
  if (snapshot.content) {
    const contentKeys = Object.keys(snapshot.content);
    lines.push('content: {' + contentKeys.join(', ') + '}');
  }
  if (snapshot.attachments) {
    lines.push('attachments: [' + snapshot.attachments.length + ' items]');
  }
  const pre = api.createElement('pre');
  pre.style.cssText = 'margin:0; white-space:pre-wrap; font-family:monospace; line-height:1.5;';
  pre.textContent = lines.join('\n');
  return pre;
}

async function showHistory(itemId, container, api) {
  container.innerHTML = '';

  let entries;
  try {
    entries = await api.getHistory(itemId);
  } catch (e) {
    container.textContent = 'Error loading history: ' + e.message;
    return;
  }

  if (!entries || entries.length === 0) {
    container.textContent = 'No history yet. History is recorded from now on \u2014 future edits will appear here.';
    return;
  }

  // Load snapshots for diffing
  const snapshots = [];
  for (const entry of entries) {
    try {
      const full = await api.viewAt(itemId, entry.timestamp);
      snapshots.push(full);
    } catch {
      snapshots.push(null);
    }
  }

  // Get current item state for the header
  let targetName = itemId.substring(0, 12);
  try {
    const targetItem = await api.get(itemId);
    targetName = targetItem.name || targetItem.content?.title || targetName;
  } catch { /* item may have been deleted */ }

  const header = api.createElement('div');
  header.style.cssText = 'margin-bottom:15px; font-size:0.875rem; color:var(--color-text-secondary,#888);';
  header.textContent = entries.length + ' version' + (entries.length === 1 ? '' : 's') + ' of \u201c' + targetName + '\u201d';
  container.appendChild(header);

  // Reverse chronological order
  for (let i = entries.length - 1; i >= 0; i--) {
    const entry = entries[i];
    const snapshot = snapshots[i];
    const prevSnapshot = i > 0 ? snapshots[i - 1] : null;

    const isDeleted = entry.deleted;
    const borderColor = isDeleted ? 'var(--color-danger,#c00)' : 'var(--color-border,#ddd)';

    const row = api.createElement('div');
    row.style.cssText = 'padding:10px 12px; border-left:3px solid ' + borderColor + '; margin-bottom:2px; cursor:pointer; transition:background 0.1s;';
    row.onmouseenter = function() { this.style.background = 'var(--color-bg-hover,rgba(0,0,0,0.04))'; };
    row.onmouseleave = function() { this.style.background = ''; };

    const time = api.createElement('span');
    time.style.cssText = 'color:var(--color-text-secondary,#888); font-size:0.8rem; margin-right:10px; min-width:70px; display:inline-block;';
    time.textContent = formatTime(entry.timestamp);
    time.title = new Date(entry.timestamp).toLocaleString();
    row.appendChild(time);

    const msg = api.createElement('span');
    msg.style.cssText = 'font-size:0.875rem;';
    if (isDeleted) {
      msg.textContent = 'deleted';
      msg.style.color = 'var(--color-danger,#c00)';
    } else {
      msg.textContent = describeChange(prevSnapshot, snapshot);
    }
    row.appendChild(msg);

    // Click to toggle snapshot detail
    const idx = i;
    row.onclick = function() {
      const existing = row.nextElementSibling;
      if (existing && existing.dataset.historyDetail) {
        existing.remove();
        return;
      }
      if (!snapshots[idx]) return;

      const detail = api.createElement('div');
      detail.dataset.historyDetail = '1';
      detail.style.cssText = 'padding:10px 12px; margin-bottom:2px; background:var(--color-bg-secondary,#f5f5f5); border-radius:4px; font-size:0.8rem; overflow-x:auto;';
      detail.appendChild(snapshotSummary(snapshots[idx], api));
      row.after(detail);
    };

    container.appendChild(row);
  }
}

// diagram-lib — Auto-generated SVG diagrams from item metadata
// See: item://c0c0c0c0-005a-0000-0000-000000000000

// [BEGIN:eventFlow]
/** Render declarative event flow as an interactive SVG diagram.
 * Usage in markdown: ![](item://diagram-lib?call=eventFlow)
 * @param {Object} api - Hobson API
 * @param {Object} params - URL query params (unused)
 * @returns {Element} SVG element
 */
export async function eventFlow(api, params) {
  const allItems = await api.getAll();

  // Name lookup for resolving GUIDs to human names
  const nameOf = new Map();
  for (const it of allItems) nameOf.set(it.id, it.name || '');

  // Collect declarative watches → edges
  const edges = [];
  const eventSet = new Set();
  const subs = new Map(); // subscriber id → name

  for (const it of allItems) {
    const watches = it.watches || it.content?.watches;
    if (!watches?.length) continue;
    for (const w of watches) {
      if (!w.event) continue;
      eventSet.add(w.event);
      subs.set(it.id, it.name || it.id.slice(0, 12));
      const filters = [];
      if (w.type) filters.push('type=' + shortName(nameOf, w.type));
      if (w.typeExtends) filters.push('ext=' + shortName(nameOf, w.typeExtends));
      if (w.id) filters.push('id=' + shortName(nameOf, w.id));
      // Derive handler name: "item:deleted" → "onItemDeleted"
      const handlerName = eventToHandlerName(nameOf.get(w.event) || '');
      edges.push({ event: w.event, sub: it.id, filters, handlerName });
    }
  }

  if (!edges.length) return textEl('No declarative watches found.');

  // Sort events by GUID (encodes category-then-specificity)
  const events = [...eventSet].sort();

  // Sort subscribers: group by primary event, then alphabetically
  const primary = new Map();       // sub id → primary event id
  const primaryHandler = new Map(); // sub id → primary handler name
  for (const e of edges) {
    if (!primary.has(e.sub)) {
      primary.set(e.sub, e.event);
      primaryHandler.set(e.sub, e.handlerName);
    }
  }
  const subList = [...subs.keys()].sort((a, b) => {
    const d = events.indexOf(primary.get(a)) - events.indexOf(primary.get(b));
    return d || (subs.get(a) || '').localeCompare(subs.get(b) || '');
  });

  // --- Layout ---
  const P = 24;       // padding
  const BH = 28;      // box height
  const BR = 5;       // border radius
  const VG = 8;       // vertical gap
  const EW = 210;     // event box width
  const SW = 210;     // subscriber box width
  const MID = 200;    // gap between columns (for curves + filter labels)
  const HEADER = 20;  // space for column labels
  const RX = P + EW + MID;  // right column x
  const W = RX + SW + P;    // total width

  const nE = events.length;
  const nS = subList.length;
  const span = Math.max(nE, nS) * (BH + VG) - VG;
  const eStep = nE > 1 ? (span - BH) / (nE - 1) : 0;
  const sStep = nS > 1 ? (span - BH) / (nS - 1) : 0;
  const topY = P + HEADER;
  const ey = i => topY + i * eStep;
  const sy = i => topY + i * sStep;
  const H = topY + span + P;

  const evtY = new Map();
  events.forEach((id, i) => evtY.set(id, ey(i)));
  const subY = new Map();
  subList.forEach((id, i) => subY.set(id, sy(i)));

  // --- Colors: solid boxes with white text (works on any background) ---
  const cat = id => {
    if (id.startsWith('e0e00000-0001')) return { bg: '#3b82f6', ln: '#60a5fa' }; // item events – blue
    if (id.startsWith('e0e00000-0002')) return { bg: '#d97706', ln: '#fbbf24' }; // system events – amber
    if (id.startsWith('e0e00000-0003')) return { bg: '#059669', ln: '#34d399' }; // viewport events – green
    return { bg: '#6b7280', ln: '#9ca3af' };
  };

  // --- Build SVG ---
  const o = [];
  o.push(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" style="font-family:system-ui,sans-serif;font-size:11px;max-width:100%">`);
  o.push(`<style>g[data-id]:hover rect{filter:brightness(1.3)}g[data-id]{cursor:pointer}path[data-sub]{cursor:pointer}path[data-sub]:hover+path{opacity:0.9;stroke-width:2.5}</style>`);

  // Column labels
  o.push(`<text x="${P + EW / 2}" y="${P + 10}" text-anchor="middle" fill="#64748b" font-size="10" font-weight="600" letter-spacing="0.05em">EVENTS</text>`);
  o.push(`<text x="${RX + SW / 2}" y="${P + 10}" text-anchor="middle" fill="#64748b" font-size="10" font-weight="600" letter-spacing="0.05em">WATCHERS</text>`);

  // Edges (drawn first so boxes render on top)
  // Each edge is clickable: opens the subscriber scrolled to its handler
  for (const e of edges) {
    const y1 = evtY.get(e.event) + BH / 2;
    const y2 = subY.get(e.sub) + BH / 2;
    const x1 = P + EW;
    const x2 = RX;
    const c = cat(e.event);
    // Invisible wider hit area for the path
    o.push(`<path data-sub="${e.sub}" data-handler="${e.handlerName}" d="M${x1} ${y1} C${x1 + MID * 0.4} ${y1} ${x2 - MID * 0.4} ${y2} ${x2} ${y2}" fill="none" stroke="transparent" stroke-width="12" style="cursor:pointer"/>`);
    // Visible path
    o.push(`<path d="M${x1} ${y1} C${x1 + MID * 0.4} ${y1} ${x2 - MID * 0.4} ${y2} ${x2} ${y2}" fill="none" stroke="${c.ln}" stroke-width="1.5" opacity="0.4" pointer-events="none"/>`);

    // Filter annotation along the curve
    if (e.filters.length) {
      const mx = (x1 + x2) / 2;
      const my = (y1 + y2) / 2;
      o.push(`<text x="${mx}" y="${my - 4}" text-anchor="middle" font-size="9" fill="#94a3b8" pointer-events="none">${esc(e.filters.join(', '))}</text>`);
    }
  }

  // Event boxes (left column)
  events.forEach(id => {
    const y = evtY.get(id);
    const c = cat(id);
    const name = nameOf.get(id) || id.slice(0, 12);
    o.push(`<g data-id="${id}">`);
    o.push(`<rect x="${P}" y="${y}" width="${EW}" height="${BH}" rx="${BR}" fill="${c.bg}"/>`);
    o.push(`<text x="${P + EW / 2}" y="${y + BH / 2 + 4}" text-anchor="middle" fill="#fff" font-weight="600">${esc(name)}</text>`);
    o.push(`</g>`);
  });

  // Subscriber boxes (right column)
  subList.forEach(id => {
    const y = subY.get(id);
    const handler = primaryHandler.get(id) || '';
    o.push(`<g data-id="${id}" data-handler="${handler}">`);
    o.push(`<rect x="${RX}" y="${y}" width="${SW}" height="${BH}" rx="${BR}" fill="#475569"/>`);
    o.push(`<text x="${RX + SW / 2}" y="${y + BH / 2 + 4}" text-anchor="middle" fill="#fff">${esc(subs.get(id))}</text>`);
    o.push(`</g>`);
  });

  o.push('</svg>');

  // Parse to DOM and add interactivity
  const div = document.createElement('div');
  div.innerHTML = o.join('\n');
  const svgEl = div.firstElementChild;

  // Click boxes: open item scrolled to handler symbol
  for (const g of svgEl.querySelectorAll('g[data-id]')) {
    g.addEventListener('click', (e) => {
      const handler = g.dataset.handler;
      if (handler) {
        api.openItem(e, { id: g.dataset.id, view: { navigateTo: { symbol: handler } } });
      } else {
        api.openItem(e, g.dataset.id);
      }
    });
  }

  // Click edges: open subscriber scrolled to that specific handler
  for (const path of svgEl.querySelectorAll('path[data-sub]')) {
    path.addEventListener('click', (e) => {
      const handler = path.dataset.handler;
      if (handler) {
        api.openItem(e, { id: path.dataset.sub, view: { navigateTo: { symbol: handler } } });
      } else {
        api.openItem(e, path.dataset.sub);
      }
    });
  }

  return svgEl;
}
// [END:eventFlow]

// "item:deleted" → "onItemDeleted", "kernel:boot-complete" → "onKernelBootComplete"
function eventToHandlerName(eventName) {
  if (!eventName) return '';
  const parts = eventName.split(/[:-]/);
  return 'on' + parts.map(p => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase()).join('');
}

function shortName(nameOf, id) {
  return nameOf.get(id) || id.slice(0, 8);
}

function textEl(msg) {
  const p = document.createElement('p');
  p.textContent = msg;
  p.style.color = '#94a3b8';
  return p;
}

function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Minimal marked.js implementation - just what we need
// Full library: https://cdn.jsdelivr.net/npm/marked@11.1.1/marked.min.js

const marked = (() => {
  const block = {
    newline: /^\n+/,
    code: /^( {4}[^\n]+\n*)+/,
    heading: /^ {0,3}(#{1,6})(?=\s|$)(.*)(?:\n+|$)/,
    hr: /^ {0,3}((?:- *){3,}|(?:_ *){3,}|(?:\* *){3,})(?:\n+|$)/,
    blockquote: /^( {0,3}> ?(>| )?(.*(?:\n(?! {0,3}\[)[^\n]+)*)(?:\n+|$))+/,
    list: /^( {0,3})(bull) [\s\S]+?(?:hr|def|\n{2,}(?! )(?!\1bull )\n*|\s*$)/,
    paragraph: /^([^\n]+(?:\n(?!hr|heading|blockquote)[^\n]+)*)/,
    text: /^[^\n]+/
  };

  const inline = {
    escape: /^\\([!"#$%&'()*+,\-./:;<=>?@\[\\\]^_`{|}~])/,
    link: /^!?\[((?:\[[^\]]*\]|[^\[\]]|\](?=[^\[]*\]))*)\]\(\s*<?(.*?)>?(?:\s+['"](.*?)['"])?\s*\)/,
    strong: /^__(.*?)__(?!_)|^\*\*(.*?)\*\*(?!\*)/,
    em: /^\b_((?:__|[^_])+?)_\b|^\*((?:\*\*|[^\*])+?)\*(?!\*)/,
    code: /^`([^`]|[^`][\s\S]*?[^`])`/,
    br: /^ {2,}\n(?!\s*$)/,
    text: /^[\s\S]+?(?=[\\<!\[_*`]| {2,}\n|$)/
  };

  function escape(html) {
    return html
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function parseInline(src) {
    let out = '';
    let cap;

    while (src) {
      // escape
      if (cap = inline.escape.exec(src)) {
        src = src.substring(cap[0].length);
        out += escape(cap[1]);
        continue;
      }

      // link
      if (cap = inline.link.exec(src)) {
        src = src.substring(cap[0].length);
        const text = cap[1];
        const href = cap[2];
        out += '<a href="' + escape(href) + '">' + parseInline(text) + '</a>';
        continue;
      }

      // strong
      if (cap = inline.strong.exec(src)) {
        src = src.substring(cap[0].length);
        out += '<strong>' + parseInline(cap[2] || cap[1]) + '</strong>';
        continue;
      }

      // em
      if (cap = inline.em.exec(src)) {
        src = src.substring(cap[0].length);
        out += '<em>' + parseInline(cap[2] || cap[1]) + '</em>';
        continue;
      }

      // code
      if (cap = inline.code.exec(src)) {
        src = src.substring(cap[0].length);
        out += '<code>' + escape(cap[1].trim()) + '</code>';
        continue;
      }

      // br
      if (cap = inline.br.exec(src)) {
        src = src.substring(cap[0].length);
        out += '<br>';
        continue;
      }

      // text
      if (cap = inline.text.exec(src)) {
        src = src.substring(cap[0].length);
        out += escape(cap[0]);
        continue;
      }

      if (src) {
        throw new Error('Infinite loop on byte: ' + src.charCodeAt(0));
      }
    }

    return out;
  }

  function parse(src) {
    let out = '';
    let cap;

    src = src.replace(/\r\n|\r/g, '\n').replace(/\t/g, '    ');

    while (src) {
      // newline
      if (cap = block.newline.exec(src)) {
        src = src.substring(cap[0].length);
        continue;
      }

      // code block
      if (cap = block.code.exec(src)) {
        src = src.substring(cap[0].length);
        const code = cap[0].replace(/^ {4}/gm, '');
        out += '<pre><code>' + escape(code.trim()) + '</code></pre>\n';
        continue;
      }

      // heading
      if (cap = block.heading.exec(src)) {
        src = src.substring(cap[0].length);
        const level = cap[1].length;
        const text = cap[2].trim();
        out += '<h' + level + '>' + parseInline(text) + '</h' + level + '>\n';
        continue;
      }

      // hr
      if (cap = block.hr.exec(src)) {
        src = src.substring(cap[0].length);
        out += '<hr>\n';
        continue;
      }

      // blockquote
      if (cap = block.blockquote.exec(src)) {
        src = src.substring(cap[0].length);
        const quote = cap[0].replace(/^ *> ?/gm, '');
        out += '<blockquote>\n' + parse(quote) + '</blockquote>\n';
        continue;
      }

      // paragraph
      if (cap = block.paragraph.exec(src)) {
        src = src.substring(cap[0].length);
        const text = cap[1].trim();
        out += '<p>' + parseInline(text) + '</p>\n';
        continue;
      }

      // text (fallback)
      if (cap = block.text.exec(src)) {
        src = src.substring(cap[0].length);
        out += '<p>' + parseInline(cap[0]) + '</p>\n';
        continue;
      }

      if (src) {
        throw new Error('Infinite loop on byte: ' + src.charCodeAt(0));
      }
    }

    return out;
  }

  return { parse };
})();

export default marked;

