// Code Editable Field View - CodeMirror-based code editor
// See [field-view-code-editable documentation](item://e7b73a8e-2191-4ce5-ae9c-f721b5e30731)

// [BEGIN:findRegionStartLine]
// Helper: Find the line number where a region starts
function findRegionStartLine(text, regionName) {
  const lines = text.split('\n');
  const marker = '[BEGIN:' + regionName + ']';
  for (let i = 0; i < lines.length; i++) {
    const cleaned = lines[i].trim()
      .replace(/^\/\/\s*/, '')
      .replace(/^#\s*/, '')
      .replace(/^<!--\s*/, '')
      .replace(/\s*-->$/, '')
      .trim();
    if (cleaned === marker) return i + 2; // Line after marker (1-indexed)
  }
  return null;
}
// [END:findRegionStartLine]

// Helper: Parse lines param ("5" or "10-20") into { start, end }
const parseLines = (linesStr) => {
  if (!linesStr) return null;
  if (typeof linesStr === 'number') return { start: linesStr, end: linesStr };
  const str = String(linesStr);
  if (str.includes('-')) {
    const [start, end] = str.split('-').map(n => parseInt(n, 10));
    return { start, end };
  }
  const line = parseInt(str, 10);
  return { start: line, end: line };
};

// [BEGIN:render]
// Code editable field view
export async function render(value, options, api) {
  const { onChange, label, language = 'javascript', scrollToLines, scrollToLine, scrollToRegion, scrollToSymbol } = options;

  // JSON AST support: if value is a compact JSON AST array, pretty-print to s-expressions.
  // Uses the canonical pretty-printer from the Hob evaluator module.
  let code = value || '';
  let isJsonObject = false;
  if (Array.isArray(value)) {
    const hob = await api.require('40b00001-0000-4000-8000-000000000000');
    code = hob.prettyPrintAll(value);
  } else if (value !== null && typeof value === 'object') {
    code = JSON.stringify(value, null, 2);
    isJsonObject = true;
  }

  const wrapper = api.createElement('div', { className: 'field-code-editable' });
  wrapper.style.cssText = 'display: flex; flex-direction: column; gap: 8px;';

  if (label) {
    const labelEl = api.createElement('label');
    labelEl.textContent = label;
    labelEl.style.cssText = 'font-weight: 500; font-size: 0.875rem; color: var(--color-text);';
    wrapper.appendChild(labelEl);
  }

  // Load CodeMirror
  await api.require('codemirror');
  await api.require('codemirror-javascript');
  const CodeMirror = window.CodeMirror;

  // Editor container
  const editorContainer = api.createElement('div');
  editorContainer.style.cssText = 'border: 1px solid var(--color-border); border-radius: var(--border-radius); overflow: hidden; min-height: 300px;';
  wrapper.appendChild(editorContainer);

  // Create CodeMirror instance
  const cm = CodeMirror(editorContainer, {
    value: code,
    mode: language,
    lineNumbers: true,
    lineWrapping: true,
    theme: 'default',
    indentUnit: 2,
    tabSize: 2,
    indentWithTabs: false,
    viewportMargin: 2000,
    extraKeys: {
      'Tab': (editor) => {
        if (editor.somethingSelected()) {
          editor.indentSelection('add');
        } else {
          editor.replaceSelection('  ');
        }
      }
    }
  });

  cm.setSize('100%', '400px');

  // Function to handle line/region navigation
  const navigateToTarget = () => {
    // Parse scrollToLines ("5" or "10-20") - prefer plural, fall back to singular
    let lineRange = parseLines(scrollToLines) || parseLines(scrollToLine);

    // If scrollToRegion is specified but no lines, find the region
    if (scrollToRegion && !lineRange) {
      const regionStart = findRegionStartLine(code, scrollToRegion);
      if (regionStart) {
        lineRange = { start: regionStart, end: regionStart };
      }
    }

    // If scrollToSymbol is specified, look up in item's _symbols
    if (scrollToSymbol && !lineRange) {
      const currentItem = api.getCurrentItem ? api.getCurrentItem() : null;
      const symbols = currentItem?.content?._symbols || {};
      let symbolInfo = symbols[scrollToSymbol];
      if (!symbolInfo) {
        for (const [key, info] of Object.entries(symbols)) {
          if (info.name === scrollToSymbol) {
            symbolInfo = info;
            break;
          }
        }
      }
      if (symbolInfo) {
        lineRange = { start: symbolInfo.line, end: symbolInfo.endLine || symbolInfo.line };
      }
    }

    // Fallback to URL params for backward compatibility
    if (!lineRange) {
      const urlParams = new URLSearchParams(window.location.search);
      const urlLines = urlParams.get('lines');
      if (urlLines) {
        lineRange = parseLines(urlLines);
      } else {
        const urlLine = parseInt(urlParams.get('line'), 10);
        if (!isNaN(urlLine) && urlLine > 0) {
          lineRange = { start: urlLine, end: urlLine };
        }
      }
    }

    if (lineRange) {
      // CodeMirror uses 0-based line numbers
      const startLine = lineRange.start - 1;
      const endLine = lineRange.end - 1;

      // Scroll first line into view and set cursor
      cm.scrollIntoView({ line: startLine, ch: 0 }, 100);
      cm.setCursor({ line: startLine, ch: 0 });
      cm.focus();

      // Add CSS for highlight if not present
      if (!document.getElementById('line-highlight-css')) {
        const style = document.createElement('style');
        style.id = 'line-highlight-css';
        style.textContent = '.line-highlight { background: var(--color-warning-light) !important; }';
        document.head.appendChild(style);
      }

      // Highlight all lines in range
      for (let i = startLine; i <= endLine; i++) {
        cm.addLineClass(i, 'background', 'line-highlight');
      }
    }
  };

  // Use IntersectionObserver to refresh CodeMirror when visible
  const observer = new IntersectionObserver((entries) => {
    for (const entry of entries) {
      if (entry.isIntersecting) {
        cm.refresh();
        navigateToTarget();
        observer.disconnect();
        break;
      }
    }
  }, { threshold: 0.1 });
  observer.observe(editorContainer);

  // Also refresh on first focus as fallback
  const focusHandler = () => {
    cm.refresh();
    navigateToTarget();
    editorContainer.removeEventListener('click', focusHandler);
  };
  editorContainer.addEventListener('click', focusHandler);

  // Register cleanup handler for DOM removal (prevents CodeMirror memory leaks)
  wrapper.setAttribute('data-hobson-cleanup', '');
  wrapper.__hobsonCleanup = () => {
    if (cm.display?.blinker) clearInterval(cm.display.blinker);
    observer.disconnect();
  };

  // Call onChange on edits
  if (onChange) {
    cm.on('change', () => {
      if (isJsonObject) {
        try { onChange(JSON.parse(cm.getValue())); } catch (e) { /* invalid JSON */ }
      } else {
        onChange(cm.getValue());
      }
    });
  }

  // Keyboard shortcut hint
  const hint = api.createElement('div');
  hint.style.cssText = 'font-size: 0.75rem; color: var(--color-text-tertiary);';
  hint.textContent = 'Tip: Tab for indent, Shift+Tab to dedent';
  wrapper.appendChild(hint);

  return wrapper;
}
// [END:render]

export async function render(value, options, api) {
  const { mode, onChange, label } = options;
  const isEditable = mode === 'editable' && onChange;
  const computed = value || {};

  const wrapper = api.createElement('div', { className: 'field-computed-fields' });
  wrapper.style.cssText = 'display: flex; flex-direction: column; gap: 8px;';

  if (label) {
    const labelEl = api.createElement('label');
    labelEl.textContent = label;
    labelEl.style.cssText = 'font-weight: 500; font-size: 0.875rem; color: var(--color-text);';
    wrapper.appendChild(labelEl);
  }

  const hobStructural = await api.require('field-view-hob');

  const entries = Object.entries(computed);

  if (entries.length === 0 && !isEditable) {
    const empty = api.createElement('div');
    empty.textContent = 'No computed fields';
    empty.style.cssText = 'color: var(--color-text-muted); font-size: 0.8125rem; font-style: italic;';
    wrapper.appendChild(empty);
    return wrapper;
  }

  // Clone computed map for edits
  const edited = { ...computed };

  function emitChange() {
    if (onChange) onChange({ ...edited });
  }

  for (const [fieldName, formula] of entries) {
    const row = api.createElement('div', { className: 'computed-field-row' });
    row.style.cssText = 'display: flex; flex-direction: column; gap: 4px; padding: 8px; background: var(--color-bg-surface-alt); border-radius: var(--border-radius); border: 1px solid var(--color-border);';

    // Header row: field name + delete button
    const header = api.createElement('div');
    header.style.cssText = 'display: flex; align-items: center; gap: 8px;';

    if (isEditable) {
      const nameInput = api.createElement('input', {
        type: 'text',
        value: fieldName,
        placeholder: 'field name',
        style: 'flex: 1; padding: 4px 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); font-size: 0.8125rem; font-family: monospace; background: var(--color-bg-surface); color: var(--color-text);'
      });
      nameInput.addEventListener('change', (e) => {
        const newName = e.target.value.trim();
        if (newName && newName !== fieldName && !edited[newName]) {
          const val = edited[fieldName];
          delete edited[fieldName];
          edited[newName] = val;
          emitChange();
        }
      });
      header.appendChild(nameInput);

      const deleteBtn = api.createElement('button');
      deleteBtn.textContent = '×';
      deleteBtn.title = 'Remove computed field';
      deleteBtn.style.cssText = 'background: none; border: none; color: var(--color-danger); cursor: pointer; font-size: 1.25rem; padding: 0 4px; line-height: 1;';
      deleteBtn.addEventListener('click', () => {
        delete edited[fieldName];
        emitChange();
        row.remove();
      });
      header.appendChild(deleteBtn);
    } else {
      const nameLabel = api.createElement('code');
      nameLabel.textContent = fieldName;
      nameLabel.style.cssText = 'font-size: 0.8125rem; color: var(--color-text); font-weight: 500;';
      header.appendChild(nameLabel);
    }

    row.appendChild(header);

    // Formula editor using hob-structural (multi-form stored as { forms: [...] })
    const forms = formula && !Array.isArray(formula) && Array.isArray(formula.forms) ? formula.forms : [formula];
    const formulaEl = await hobStructural.render(forms, {
      mode: isEditable ? 'editable' : 'readonly',
      onChange: isEditable ? (newFormula) => {
        edited[fieldName] = newFormula.length === 1 ? newFormula[0] : { forms: newFormula };
        emitChange();
      } : null,
    }, api);
    row.appendChild(formulaEl);

    wrapper.appendChild(row);
  }

  // Add button
  if (isEditable) {
    const addBtn = api.createElement('button');
    addBtn.textContent = '+ Add computed field';
    addBtn.style.cssText = 'align-self: flex-start; padding: 4px 12px; background: var(--color-bg-surface-alt); border: 1px dashed var(--color-border); border-radius: var(--border-radius); color: var(--color-text-muted); cursor: pointer; font-size: 0.8125rem;';
    addBtn.addEventListener('click', async () => {
      // Find a unique name
      let i = 1;
      let name = 'field-' + i;
      while (edited[name]) { i++; name = 'field-' + i; }

      // Default to empty list — minimal editable form in structural editor
      edited[name] = [];
      emitChange();

      // Re-render the new entry inline
      const row = api.createElement('div', { className: 'computed-field-row' });
      row.style.cssText = 'display: flex; flex-direction: column; gap: 4px; padding: 8px; background: var(--color-bg-surface-alt); border-radius: var(--border-radius); border: 1px solid var(--color-border);';

      const header = api.createElement('div');
      header.style.cssText = 'display: flex; align-items: center; gap: 8px;';

      const nameInput = api.createElement('input', {
        type: 'text',
        value: name,
        placeholder: 'field name',
        style: 'flex: 1; padding: 4px 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); font-size: 0.8125rem; font-family: monospace; background: var(--color-bg-surface); color: var(--color-text);'
      });
      nameInput.addEventListener('change', (e) => {
        const newName = e.target.value.trim();
        if (newName && newName !== name && !edited[newName]) {
          const val = edited[name];
          delete edited[name];
          edited[newName] = val;
          name = newName;
          emitChange();
        }
      });
      header.appendChild(nameInput);

      const deleteBtn = api.createElement('button');
      deleteBtn.textContent = '×';
      deleteBtn.title = 'Remove computed field';
      deleteBtn.style.cssText = 'background: none; border: none; color: var(--color-danger); cursor: pointer; font-size: 1.25rem; padding: 0 4px; line-height: 1;';
      deleteBtn.addEventListener('click', () => {
        delete edited[name];
        emitChange();
        row.remove();
      });
      header.appendChild(deleteBtn);
      row.appendChild(header);

      const formulaEl = await hobStructural.render([[]], {
        mode: 'editable',
        onChange: (newFormula) => {
          edited[name] = newFormula[0];
          emitChange();
        },
      }, api);
      row.appendChild(formulaEl);

      wrapper.insertBefore(row, addBtn);
      nameInput.focus();
      nameInput.select();
    });
    wrapper.appendChild(addBtn);
  }

  return wrapper;
}

export async function render(value, options, api) {
  const { mode, onChange, label, exclude, getCurrentValue } = options;
  const isEditable = mode === 'editable' && onChange;
  const content = value || {};
  const excludeSet = new Set(exclude || []);
  const guidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

  // Extract static fields (everything not excluded)
  const staticFields = {};
  for (const [k, v] of Object.entries(content)) {
    if (!excludeSet.has(k)) staticFields[k] = v;
  }

  const wrapper = api.createElement('div', { className: 'field-static-fields' });
  wrapper.style.cssText = 'display: flex; flex-direction: column; gap: 8px;';

  if (label) {
    const labelEl = api.createElement('label');
    labelEl.textContent = label;
    labelEl.style.cssText = 'font-weight: 500; font-size: 0.875rem; color: var(--color-text);';
    wrapper.appendChild(labelEl);
  }

  const entries = Object.entries(staticFields);

  if (entries.length === 0 && !isEditable) {
    return wrapper; // nothing to show
  }

  const edited = { ...staticFields };

  function emitChange() {
    if (!onChange) return;
    // Use getCurrentValue() to read latest edited state (avoids stale closure)
    const base = (getCurrentValue ? getCurrentValue() : content) || {};
    const merged = { ...base };
    // Remove old static keys
    for (const k of Object.keys(merged)) {
      if (!excludeSet.has(k)) delete merged[k];
    }
    // Add current static fields
    Object.assign(merged, edited);
    onChange(merged);
  }

  async function createRow(fieldName, fieldValue) {
    const row = api.createElement('div', { className: 'static-field-row' });
    row.style.cssText = 'display: flex; align-items: center; gap: 8px;';

    const isGuid = typeof fieldValue === 'string' && guidPattern.test(fieldValue);

    if (isEditable) {
      const nameInput = api.createElement('input', {
        type: 'text',
        value: fieldName,
        placeholder: 'field name',
        style: 'width: 120px; padding: 4px 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); font-size: 0.8125rem; font-family: monospace; background: var(--color-bg-surface); color: var(--color-text);'
      });

      let currentName = fieldName;

      nameInput.addEventListener('change', (e) => {
        const newName = e.target.value.trim();
        if (newName && newName !== currentName && !edited[newName] && !excludeSet.has(newName)) {
          const val = edited[currentName];
          delete edited[currentName];
          edited[newName] = val;
          currentName = newName;
          emitChange();
        }
      });

      const deleteBtn = api.createElement('button');
      deleteBtn.textContent = '×';
      deleteBtn.title = 'Remove field';
      deleteBtn.style.cssText = 'background: none; border: none; color: var(--color-danger); cursor: pointer; font-size: 1.25rem; padding: 0 4px; line-height: 1;';
      deleteBtn.addEventListener('click', () => {
        delete edited[currentName];
        emitChange();
        row.remove();
      });

      if (isGuid) {
        const itemRefView = await api.require('field-view-item-ref');
        const itemRefEl = await itemRefView.render(fieldValue, {
          mode: 'editable',
          onChange: (v) => { edited[currentName] = v; emitChange(); },
        }, api);
        itemRefEl.style.flex = '1';
        row.appendChild(nameInput);
        row.appendChild(itemRefEl);
        row.appendChild(deleteBtn);
      } else if (Array.isArray(fieldValue)) {
        const arrayView = await api.require('field-view-array');
        const arrayEl = await arrayView.render(fieldValue, {
          mode: 'editable',
          onChange: (v) => { edited[currentName] = v; emitChange(); },
        }, api);
        arrayEl.style.flex = '1';
        row.style.alignItems = 'flex-start';
        row.appendChild(nameInput);
        row.appendChild(arrayEl);
        row.appendChild(deleteBtn);
      } else {
        // Auto-detect type from a string value
        const autoDetect = (raw) => {
          if (raw === 'true') return { value: true, type: 'bool' };
          if (raw === 'false') return { value: false, type: 'bool' };
          if (raw === 'null' || raw === 'nil') return { value: null, type: 'null' };
          if (raw !== '' && !isNaN(Number(raw))) return { value: Number(raw), type: '#' };
          if (/^\[/.test(raw) || /^\{/.test(raw)) {
            try { return { value: JSON.parse(raw), type: Array.isArray(JSON.parse(raw)) ? '[]' : '{}' }; }
            catch { return { value: raw, type: 'Aa' }; }
          }
          return { value: raw, type: 'Aa' };
        };

        const detectStoredType = (v) => {
          if (v === null || v === undefined) return 'null';
          if (typeof v === 'boolean') return 'bool';
          if (typeof v === 'number') return '#';
          if (Array.isArray(v)) return '[]';
          if (typeof v === 'object') return '{}';
          return 'Aa';
        };

        const valueWrapper = api.createElement('span');
        valueWrapper.style.cssText = 'flex: 1; display: flex; align-items: center; gap: 0;';

        const valueInput = api.createElement('input', {
          type: 'text',
          value: fieldValue != null ? (typeof fieldValue === 'object' ? JSON.stringify(fieldValue) : String(fieldValue)) : '',
          placeholder: 'value',
          style: 'flex: 1; padding: 4px 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius) 0 0 var(--border-radius); font-size: 0.8125rem; font-family: monospace; background: var(--color-bg-surface); color: var(--color-text);'
        });

        // Type indicator — shows auto-detected type
        let detectedType = detectStoredType(fieldValue);
        const typeIndicator = api.createElement('span');
        typeIndicator.textContent = detectedType;
        typeIndicator.title = 'Detected type';
        typeIndicator.style.cssText = 'border: 1px solid var(--color-border); border-left: none; border-radius: 0 var(--border-radius) var(--border-radius) 0; padding: 4px 6px; font-size: 0.7em; color: var(--color-text-muted); background: var(--color-bg-surface); user-select: none;';

        valueInput.addEventListener('input', (e) => {
          const { value: parsed, type } = autoDetect(e.target.value);
          detectedType = type;
          typeIndicator.textContent = type;
          edited[currentName] = parsed;
          emitChange();
        });

        valueWrapper.appendChild(valueInput);
        valueWrapper.appendChild(typeIndicator);
        row.appendChild(nameInput);
        row.appendChild(valueWrapper);
        row.appendChild(deleteBtn);
      }
    } else {
      // Readonly
      const nameEl = api.createElement('code');
      nameEl.textContent = fieldName;
      nameEl.style.cssText = 'font-size: 0.8125rem; color: var(--color-text); font-weight: 500; min-width: 120px;';
      row.appendChild(nameEl);

      if (isGuid) {
        const itemRefView = await api.require('field-view-item-ref');
        const itemRefEl = await itemRefView.render(fieldValue, { mode: 'readonly' }, api);
        row.appendChild(itemRefEl);
      } else {
        const valueEl = api.createElement('span');
        valueEl.textContent = fieldValue != null ? String(fieldValue) : '';
        valueEl.style.cssText = 'font-size: 0.8125rem; color: var(--color-text); font-family: monospace;';
        row.appendChild(valueEl);
      }
    }

    return row;
  }

  for (const [fieldName, fieldValue] of entries) {
    wrapper.appendChild(await createRow(fieldName, fieldValue));
  }

  if (isEditable) {
    const addBtn = api.createElement('button');
    addBtn.textContent = '+ Add field';
    addBtn.style.cssText = 'align-self: flex-start; padding: 4px 12px; background: var(--color-bg-surface-alt); border: 1px dashed var(--color-border); border-radius: var(--border-radius); color: var(--color-text-muted); cursor: pointer; font-size: 0.8125rem;';
    addBtn.addEventListener('click', async () => {
      let i = 1;
      let name = 'field-' + i;
      while (edited[name] || excludeSet.has(name)) { i++; name = 'field-' + i; }
      edited[name] = '';
      emitChange();
      const row = await createRow(name, '');
      wrapper.insertBefore(row, addBtn);
      row.querySelector('input').focus();
      row.querySelector('input').select();
    });
    wrapper.appendChild(addBtn);
  }

  return wrapper;
}

// Readonly field summary: shows static fields and computed fields with provenance
export async function render(value, options, api) {
  const { exclude, item } = options;
  const guidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

  // Load prStr for displaying non-primitive values
  let prStr = String;
  try {
    const hob = await api.require('hob-interpreter');
    const hobPrStr = (v) => hob.prStr(v, false);
    prStr = (v) => typeof v === 'object' && v !== null ? JSON.stringify(v) : hobPrStr(v);
  } catch {}
  const content = value || {};
  const excludeSet = new Set(exclude || []);

  // Separate static and computed fields
  const computed = content.computed || {};
  const staticFields = {};
  for (const [k, v] of Object.entries(content)) {
    if (!excludeSet.has(k)) staticFields[k] = v;
  }

  const staticKeys = Object.keys(staticFields);
  const computedKeys = Object.keys(computed);

  // Nothing to show — render invisible element
  if (staticKeys.length === 0 && computedKeys.length === 0) {
    const empty = api.createElement('div');
    empty.style.display = 'none';
    return empty;
  }

  const wrapper = api.createElement('div', { className: 'field-summary' });
  wrapper.style.cssText = 'font-size: 0.8125rem; line-height: 1.6;';

  // Static fields
  for (const k of staticKeys) {
    const row = api.createElement('div', { className: 'field-entry' });
    row.id = 'field-' + k;
    row.style.cssText = 'padding: 2px 0;';

    const nameEl = api.createElement('span');
    nameEl.textContent = k;
    nameEl.style.cssText = 'font-weight: 500; font-family: monospace;';
    row.appendChild(nameEl);

    const sep = api.createElement('span');
    sep.textContent = ':';
    sep.style.cssText = 'color: var(--color-text-muted); margin: 0 6px;';
    row.appendChild(sep);

    const v = staticFields[k];
    if (typeof v === 'string' && guidPattern.test(v)) {
      const itemRefView = await api.require('field-view-item-ref');
      const itemRefEl = await itemRefView.render(v, { mode: 'readonly' }, api);
      row.appendChild(itemRefEl);
    } else {
      const valEl = api.createElement('span');
      valEl.textContent = prStr(v);
      row.appendChild(valEl);
    }

    wrapper.appendChild(row);
  }

  // Computed fields — show formula + resolved value + provenance links
  if (computedKeys.length > 0) {
    let hobStructural;
    try {
      hobStructural = await api.require('field-view-hob-structural');
    } catch (e) { /* structural editor not available */ }

    for (const k of computedKeys) {
      const formula = computed[k];
      const row = api.createElement('div', { className: 'field-entry' });
      row.id = 'field-' + k;
      row.style.cssText = 'padding: 4px 0;';

      const nameEl = api.createElement('span');
      nameEl.textContent = k;
      nameEl.style.cssText = 'font-weight: 500; font-family: monospace; font-style: italic;';
      row.appendChild(nameEl);

      const sep = api.createElement('span');
      sep.textContent = ':';
      sep.style.cssText = 'color: var(--color-text-muted); margin: 0 6px;';
      row.appendChild(sep);

      // Formula display (multi-form stored as { forms: [...] })
      if (hobStructural) {
        const forms = formula && !Array.isArray(formula) && Array.isArray(formula.forms) ? formula.forms : [formula];
        const formulaEl = await hobStructural.render(forms, { mode: 'readonly' }, api);
        formulaEl.style.cssText = 'margin-left: 16px;';
        row.appendChild(formulaEl);
      }

      // Resolved value
      const resolvedRow = api.createElement('div');
      resolvedRow.style.cssText = 'margin-left: 16px; color: var(--color-text-muted);';
      let resolvedText = '';
      if (item) {
        try {
          const val = await api.getField(item.id, k);
          resolvedText = val != null ? prStr(val) : '';
        } catch (e) {
          console.error('field-summary: error resolving', k, e);
          resolvedText = '[error]';
        }
      }
      resolvedRow.textContent = '\u2192 ' + resolvedText;
      row.appendChild(resolvedRow);

      // Provenance links — extract @-refs from formula AST
      const refs = extractItemRefs(formula);
      if (refs.length > 0) {
        const linksRow = api.createElement('div');
        linksRow.style.cssText = 'margin-left: 16px; display: flex; gap: 8px; flex-wrap: wrap;';
        for (const refId of refs) {
          const link = api.createElement('a');
          link.style.cssText = 'font-size: 0.75rem; color: var(--color-primary); cursor: pointer; text-decoration: none;';
          link.href = '#';
          // Fetch item name
          try {
            const refItem = await api.get(refId);
            link.textContent = refItem?.name || refId.substring(0, 8) + '...';
            link.title = refItem?.name || refId;
          } catch (e) {
            link.textContent = refId.substring(0, 8) + '...';
            link.title = refId;
          }
          link.addEventListener('click', (e) => {
            e.preventDefault();
            api.openItem(e, refId);
          });
          linksRow.appendChild(link);
        }
        row.appendChild(linksRow);
      }

      wrapper.appendChild(row);
    }
  }

  return wrapper;
}

// Walk JSON AST to find @-prefixed item references
function extractItemRefs(ast) {
  const refs = [];
  const seen = new Set();
  function walk(node) {
    if (typeof node === 'string' && node.startsWith('@')) {
      const id = node.substring(1);
      if (!seen.has(id)) { seen.add(id); refs.push(id); }
    } else if (Array.isArray(node)) {
      for (const child of node) walk(child);
    } else if (node && typeof node === 'object') {
      if (node.v) for (const child of node.v) walk(child);
      if (node.m) for (const child of node.m) walk(child);
    }
  }
  walk(ast);
  return refs;
}

export function render(value, options, api) {
  const { mode, onChange, label, placeholder, rows = 5 } = options;
  const wrapper = api.createElement('div', { className: 'field-textarea' });
  wrapper.style.cssText = 'display: flex; flex-direction: column; gap: 4px;';

  if (label) {
    const labelEl = api.createElement('label');
    labelEl.textContent = label;
    labelEl.style.cssText = 'font-weight: 500; font-size: 0.875rem; color: var(--color-text);';
    wrapper.appendChild(labelEl);
  }

  if (mode === 'editable' && onChange) {
    const textarea = api.createElement('textarea', { style: 'padding: 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); font-size: 0.875rem; font-family: inherit; resize: vertical;', rows: rows });
    textarea.value = value || '';
    textarea.placeholder = placeholder || '';
    textarea.oninput = (e) => onChange(e.target.value);
    wrapper.appendChild(textarea);
  } else {
    const pre = api.createElement('pre');
    pre.textContent = value || '';
    pre.style.cssText = 'padding: 8px; background: var(--color-bg-body); border-radius: var(--border-radius); font-size: 0.875rem; white-space: pre-wrap; margin: 0; font-family: inherit;';
    wrapper.appendChild(pre);
  }
  return wrapper;
}

// Element Inspector Library
// Provides tools to inspect which view/item rendered any UI element

let inspectorState = null;

export function activate(api) {
  if (inspectorState) {
    console.warn('Element inspector already active');
    return inspectorState;
  }

  let active = false;

  function toggleInspectMode() {
    active = !active;
    document.body.classList.toggle('hobson-inspect-mode', active);
    if (!active) {
      // Remove all highlight classes
      document.querySelectorAll('.hobson-inspect-highlight').forEach(el => {
        el.classList.remove('hobson-inspect-highlight');
      });
    }
  }

  // Click handler when active — logs info to console for REPL use
  const clickHandler = async (e) => {
    if (!active) return;

    e.preventDefault();
    e.stopPropagation();

    const info = collectElementInfo(e.target);
    console.log('Element inspection:', info);
  };
  document.addEventListener('click', clickHandler, true);

  // Hover highlight when active
  const mouseoverHandler = (e) => {
    if (!active) return;
    e.target.classList.add('hobson-inspect-highlight');
  };
  document.addEventListener('mouseover', mouseoverHandler, true);

  const mouseoutHandler = (e) => {
    if (!active) return;
    e.target.classList.remove('hobson-inspect-highlight');
  };
  document.addEventListener('mouseout', mouseoutHandler, true);

  inspectorState = {
    toggle: toggleInspectMode,
    isActive: () => active,
    // Store handlers for proper cleanup
    _handlers: { clickHandler, mouseoverHandler, mouseoutHandler }
  };

  return inspectorState;
}

export function deactivate() {
  if (inspectorState) {
    // Remove all event listeners
    if (inspectorState._handlers) {
      document.removeEventListener('click', inspectorState._handlers.clickHandler, true);
      document.removeEventListener('mouseover', inspectorState._handlers.mouseoverHandler, true);
      document.removeEventListener('mouseout', inspectorState._handlers.mouseoutHandler, true);
    }

    // Exit inspect mode if active
    if (inspectorState.isActive()) {
      inspectorState.toggle();
    }

    // Remove any lingering highlights
    document.querySelectorAll('.hobson-inspect-highlight').forEach(el => {
      el.classList.remove('hobson-inspect-highlight');
    });
    document.body.classList.remove('hobson-inspect-mode');

    inspectorState = null;
  }
}

export function collectElementInfo(element) {
  const info = {
    element,
    chain: []
  };

  let el = element;
  while (el && el !== document.body) {
    const entry = {};

    // Collect any attribution present
    if (el.dataset.source) {
      entry.source = el.dataset.source;
      if (el.dataset.sourceLine) entry.sourceLine = el.dataset.sourceLine;
      if (el.dataset.sourceLang) entry.sourceLang = el.dataset.sourceLang;
      if (el.dataset.sourceBinding) entry.sourceBinding = el.dataset.sourceBinding;
    }
    if (el.dataset.viewId) {
      entry.viewId = el.dataset.viewId;
    }
    if (el.dataset.forItem) {
      entry.forItem = el.dataset.forItem;
    }
    if (el.dataset.itemId) {
      entry.itemId = el.dataset.itemId;
    }
    if (el.dataset.renderInstance) {
      entry.renderInstance = el.dataset.renderInstance;
    }

    if (Object.keys(entry).length > 0) {
      entry.tagName = el.tagName.toLowerCase();
      // Filter out inspector's own classes from display
      entry.className = el.className
        .split(' ')
        .filter(c => c && c !== 'hobson-inspect-highlight' && c !== 'hobson-inspect-mode')
        .join(' ');
      info.chain.push(entry);
    }

    el = el.parentElement;
  }

  return info;
}

/**
 * Enter inspect mode, wait for one click, return collected info.
 * Resolves with element info on click, or null if cancelled (Escape).
 */
export function inspectOnce(api) {
  return new Promise((resolve) => {
    document.body.classList.add('hobson-inspect-mode');

    function cleanup() {
      document.removeEventListener('click', clickHandler, true);
      document.removeEventListener('mouseover', mouseoverHandler, true);
      document.removeEventListener('mouseout', mouseoutHandler, true);
      document.removeEventListener('keydown', escHandler);
      document.body.classList.remove('hobson-inspect-mode');
      document.querySelectorAll('.hobson-inspect-highlight').forEach(el => {
        el.classList.remove('hobson-inspect-highlight');
      });
    }

    const mouseoverHandler = (e) => {
      e.target.classList.add('hobson-inspect-highlight');
    };
    const mouseoutHandler = (e) => {
      e.target.classList.remove('hobson-inspect-highlight');
    };
    const clickHandler = (e) => {
      e.preventDefault();
      e.stopPropagation();
      cleanup();
      resolve(collectElementInfo(e.target));
    };
    const escHandler = (e) => {
      if (e.key === 'Escape') {
        cleanup();
        resolve(null);
      }
    };

    document.addEventListener('click', clickHandler, true);
    document.addEventListener('mouseover', mouseoverHandler, true);
    document.addEventListener('mouseout', mouseoutHandler, true);
    document.addEventListener('keydown', escHandler);
  });
}

/**
 * Resolve an inspector link target and navigate to it.
 * Opens as sibling on spatial canvas if available.
 */
export async function resolveAndNavigate(api, { id, name, line, lang, binding }) {
  // Resolve target item ID
  let targetId = id;
  if (!targetId && name) {
    // Look up by name, stripping .js suffix if present
    const baseName = name.replace(/\.js$/, '');
    let items = await api.query({ name: baseName });
    // Fallback: try with original name if no match
    if (items.length === 0 && baseName !== name) {
      items = await api.query({ name });
    }
    if (items.length > 0) {
      targetId = items[0].id;
    } else {
      console.warn('Element inspector: could not find item with name:', name);
      return;
    }
  }

  if (!targetId) return;

  // Build navigation params for scroll-to-line or scroll-to-symbol support
  const field = lang === 'hob' ? 'hob' : 'code';
  let navigateTo = null;
  if (binding && lang === 'hob') {
    // Hob: navigate to symbol (binding name) in structural editor
    navigateTo = { field, symbol: binding };
  } else if (line) {
    navigateTo = { field, lines: line };
  }

  // Open as sibling on spatial canvas if possible
  const currentRoot = api.viewport.getRoot();
  if (currentRoot && currentRoot !== targetId) {
    try {
      const rootItem = await api.get(currentRoot);
      const existingChild = rootItem.attachments?.find(c => c.id === targetId);

      if (existingChild) {
        const updatedChildren = rootItem.attachments.map(c => {
          if (c.id === targetId) {
            return { ...c, view: { ...(c.view || {}), navigateTo, minimized: false } };
          }
          return c;
        });
        await api.set({ ...rootItem, attachments: updatedChildren, modified: Date.now() });
      } else {
        const newChild = { id: targetId, view: { navigateTo } };
        await api.set({
          ...rootItem,
          attachments: [...(rootItem.attachments || []), newChild],
          modified: Date.now()
        });
      }
      await api.navigate(currentRoot);
    } catch (err) {
      console.error('Error opening as sibling:', err);
      await api.navigate(targetId, navigateTo);
    }
  } else {
    await api.navigate(targetId, navigateTo);
  }
}

// Export for manual activation via REPL
export function inspect(element, api) {
  const info = collectElementInfo(element);
  console.log('Element inspection:', info);
  return info;
}

// App Page View - renders app-page items as a CSS grid with shared widget state
// Supports design mode toggle for visual layout editing

// [BEGIN:render]
export async function render(pageItem, api) {
  // --- Page State (runtime only, not persisted) ---
  const pageState = {};
  const stateListeners = {};  // key -> [callback]

  const pageContext = {
    getState(key) {
      return pageState[key];
    },
    setState(key, value) {
      pageState[key] = value;
      (stateListeners[key] || []).forEach(cb => {
        try { cb(value); } catch (e) { window.kernel?.captureError(e, { operation: 'app-page-state-listener', key }); }
      });
    },
    onStateChange(key, callback) {
      if (!stateListeners[key]) stateListeners[key] = [];
      stateListeners[key].push(callback);
      return () => {
        const arr = stateListeners[key];
        if (arr) {
          const idx = arr.indexOf(callback);
          if (idx >= 0) arr.splice(idx, 1);
        }
      };
    }
  };

  // --- Design mode state (runtime only) ---
  let designMode = false;

  // --- Outer wrapper (stable across re-renders) ---
  const wrapper = api.createElement('div', {
    style: 'display: flex; flex-direction: column; align-items: center; height: 100%; overflow-y: auto;'
  });

  // --- Render function (called on initial + after design operations) ---
  async function renderPage() {
    wrapper.innerHTML = '';

    // Always fresh-read so design mode changes are visible in live mode
    const currentPageItem = await api.get(pageItem.id);

    const columns = currentPageItem.content?.columns || 12;
    const gap = currentPageItem.content?.gap || 8;
    const rowHeight = currentPageItem.content?.rowHeight || 40;

    // --- Run onInit script (seeds pageContext before widgets render) ---
    if (currentPageItem.content?.onInit) {
      try {
        const fn = new Function('api', 'pageContext', `return (async () => { ${currentPageItem.content.onInit} })()`);
        await fn(api, pageContext);
      } catch (err) {
        window.kernel?.captureError(err, { operation: 'app-page-onInit', itemId: pageItem.id });
      }
    }

    // --- Design toolbar ---
    if (designMode) {
      let designLib;
      try {
        designLib = await api.require('app-page-design-lib');
      } catch (err) {
        window.kernel?.captureError(err, { operation: 'app-page-load-design-lib' });
        const errEl = api.createElement('div', {
          style: 'color: var(--color-danger); padding: 8px; font-size: 0.8125rem;'
        });
        errEl.textContent = 'Failed to load design library: ' + err.message;
        wrapper.appendChild(errEl);
        return;
      }

      const toolbar = designLib.renderToolbar(currentPageItem, api, {
        onToggle: () => {
          designMode = false;
          renderPage();
        },
        onAddWidget: async () => {
          const NOTE_TYPE = '871ae771-b9b1-4f40-8c7f-d9038bfb69c3';
          const NOTE_WIDGET_VIEW = 'b7f3a1d2-8e5c-4f6a-9d0b-1c2e3f4a5b6c';

          const result = await designLib.showWidgetPicker(api);
          if (!result) return;

          let childId, typeName;

          if (result.mode === 'create') {
            // Create new widget item
            const newId = crypto.randomUUID();
            const typeDef = await api.get(result.typeId);
            const newItem = {
              id: newId,
              name: (typeDef.name || 'widget') + '-' + newId.slice(0, 4),
              type: result.typeId,
              created: Date.now(),
              modified: Date.now(),
              content: {},
              attachments: []
            };
            await api.set(newItem);
            childId = newId;
            typeName = (typeDef.name || '').toLowerCase();
          } else {
            // Attach existing — no item creation
            childId = result.item.id;
            const typeDef = await api.get(result.item.type).catch(() => null);
            typeName = (typeDef?.name || '').toLowerCase();
          }

          // Add to page attachments
          const freshPage = await api.get(pageItem.id);
          const children = freshPage.attachments || [];
          // Calculate next row
          let maxRow = 0;
          for (const child of children) {
            const cv = (typeof child === 'object' ? child.view : null) || {};
            const r = cv.row || 0;
            const rs = cv.rowSpan || 1;
            if (r + rs > maxRow) maxRow = r + rs;
          }
          const nextRow = maxRow > 0 ? maxRow : children.length + 1;

          // Default rowSpan heuristic
          let defaultRowSpan = 2;
          if (typeName.includes('button')) defaultRowSpan = 1;
          else if (typeName.includes('markdown') || typeName === 'note') defaultRowSpan = 4;

          // Build attachment spec
          const spec = {
            id: childId,
            view: { col: 1, row: nextRow, colSpan: columns, rowSpan: defaultRowSpan }
          };

          // For notes, use note-widget-view via viewId override
          if (result.mode === 'attach' && result.item.type === NOTE_TYPE) {
            spec.view.viewId = NOTE_WIDGET_VIEW;
          }

          children.push(spec);
          await api.updateSilent({ ...freshPage, attachments: children, modified: Date.now() });
          renderPage();
        }
      });
      wrapper.appendChild(toolbar);
    }

    // --- Grid Container ---
    const grid = api.createElement('div', {
      style: `
        display: grid;
        grid-template-columns: repeat(${columns}, 1fr);
        grid-auto-rows: ${rowHeight}px;
        column-gap: ${gap}px;
        row-gap: 0;
        padding: 4px 16px 16px;
        max-width: 960px;
        width: 100%;
        align-content: start;
        position: relative;
      `
    });

    // --- Live mode: overlay Design button on grid ---
    if (!designMode) {
      const designBtn = api.createElement('button', {
        style: `
          position: absolute; top: 4px; right: 4px; z-index: 1;
          padding: 2px 8px; cursor: pointer; border: 1px solid var(--color-border, #444);
          background: transparent; color: var(--color-text-secondary, #888);
          border-radius: var(--border-radius, 4px); font-size: 0.6875rem; opacity: 0.6;
        `,
        title: 'Enter design mode'
      });
      designBtn.textContent = 'Design';
      designBtn.onmouseenter = () => { designBtn.style.opacity = '1'; };
      designBtn.onmouseleave = () => { designBtn.style.opacity = '0.6'; };
      designBtn.onclick = () => {
        designMode = true;
        renderPage();
      };
      grid.appendChild(designBtn);
    }

    // --- Column overlay in design mode ---
    if (designMode) {
      try {
        const designLib = await api.require('app-page-design-lib');
        const overlay = designLib.renderColumnOverlay(grid, columns, api);
        grid.appendChild(overlay);
      } catch (_) { /* overlay is non-essential */ }
    }

    // --- Render Each Child Widget ---
    const openIn = api.getParentId();
    const children = currentPageItem.attachments || [];

    for (const childSpec of children) {
      const childId = typeof childSpec === 'string' ? childSpec : childSpec.id;
      const viewConfig = (typeof childSpec === 'object' ? childSpec.view : null) || {};

      try {
        // Load child item
        const childItem = await api.get(childId);

        // Resolve view — use per-attachment override if specified, else preference hierarchy
        let viewItem;
        if (viewConfig.viewId) {
          try {
            viewItem = await api.get(viewConfig.viewId);
          } catch (_) { /* fall through to default resolution */ }
        }
        if (!viewItem) {
          viewItem = await api.getEffectiveView(childId);
        }
        if (!viewItem) {
          console.warn('App page: no view for child', childId);
          continue;
        }

        // Render the widget — use rendering system for Hob views, require for JS
        let widgetElement;
        try {
          if (viewItem.content?.hob && !viewItem.content?.code) {
            // Hob view: create a :render-child mount point (filled by api.fillMountPoints below)
            const mountAttrs = { 'data-render-child': '', 'data-child-item': childId };
            if (viewItem.id) mountAttrs['data-child-view'] = viewItem.id;
            const mountPoint = api.createElement('div', mountAttrs, []);
            mountPoint.__renderChildSpec = {
              itemId: childId,
              viewId: { type: viewItem.id, openIn },
              openIn,
              pageContext
            };
            widgetElement = mountPoint;
          } else {
            // JS view: load module and call render directly (supports pageContext injection)
            const viewModule = await api.require(viewItem.id);
            const widgetApi = Object.create(api);
            widgetApi.pageContext = pageContext;
            widgetApi.getViewId = () => viewItem.id;
            const parentViewConfig = await api.getViewConfig?.() || {};
            widgetApi.getViewConfig = async () => ({ ...parentViewConfig, openIn });
            widgetElement = await viewModule.render(childItem, widgetApi);
          }
        } catch (err) {
          window.kernel?.captureError(err, { operation: 'app-page-widget-render', itemId: childId, itemName: childItem.name });
          widgetElement = api.createElement('div', {
            style: 'color: var(--color-danger, #e74c3c); padding: 8px; border: 1px solid var(--color-danger, #e74c3c); border-radius: var(--border-radius, 4px); font-size: 0.8125rem;'
          });
          widgetElement.textContent = `Error rendering ${childItem.name || childId}: ${err.message}`;
        }

        if (designMode) {
          // Wrap widget with design overlay
          const designLib = await api.require('app-page-design-lib');
          const designCell = designLib.wrapWidgetForDesign(widgetElement, childSpec, childItem, currentPageItem, api, {
            onSelect: (id) => { /* selection state is visual-only for now */ },
            onMove: async (id, { col, row }) => {
              const freshPage = await api.get(pageItem.id);
              const freshChildren = freshPage.attachments || [];
              const updated = freshChildren.map(c => {
                if ((typeof c === 'string' ? c : c.id) === id) {
                  return { ...(typeof c === 'object' ? c : { id: c }), view: { ...(c.view || {}), col, row } };
                }
                return c;
              });
              await api.updateSilent({ ...freshPage, attachments: updated, modified: Date.now() });
              renderPage();
            },
            onResize: async (id, { colSpan, rowSpan }) => {
              const freshPage = await api.get(pageItem.id);
              const freshChildren = freshPage.attachments || [];
              const updated = freshChildren.map(c => {
                if ((typeof c === 'string' ? c : c.id) === id) {
                  return { ...(typeof c === 'object' ? c : { id: c }), view: { ...(c.view || {}), colSpan, rowSpan } };
                }
                return c;
              });
              await api.updateSilent({ ...freshPage, attachments: updated, modified: Date.now() });
              renderPage();
            },
            onDelete: async (id) => {
              const modalLib = await api.require('modal-lib');
              const widgetName = childItem.name || id.slice(0, 8);

              const action = await new Promise((resolve) => {
                let resolved = false;
                modalLib.showModal({
                  title: 'Remove Widget',
                  width: '420px',
                  onClose: () => { if (!resolved) resolve(null); },
                  content: ({ close }) => {
                    const el = api.createElement('div');

                    const msg = api.createElement('p');
                    msg.textContent = `What would you like to do with "${widgetName}"?`;
                    msg.style.cssText = 'margin: 0 0 16px 0; font-size: 0.875rem; color: var(--color-text); line-height: 1.5;';
                    el.appendChild(msg);

                    const btnRow = api.createElement('div');
                    btnRow.style.cssText = 'display: flex; gap: 8px; justify-content: flex-end; flex-wrap: wrap;';

                    const cancelBtn = api.createElement('button');
                    cancelBtn.textContent = 'Cancel';
                    cancelBtn.style.cssText = 'padding: 8px 16px; cursor: pointer; border: 1px solid var(--color-border); background: var(--color-bg-surface); color: var(--color-text); border-radius: var(--border-radius);';
                    cancelBtn.onclick = () => { resolved = true; close(); resolve(null); };
                    btnRow.appendChild(cancelBtn);

                    const removeBtn = api.createElement('button');
                    removeBtn.textContent = 'Remove from Page';
                    removeBtn.style.cssText = 'padding: 8px 16px; cursor: pointer; border: none; background: var(--color-primary, #7c3aed); color: white; border-radius: var(--border-radius);';
                    removeBtn.onclick = () => { resolved = true; close(); resolve('remove'); };
                    btnRow.appendChild(removeBtn);

                    const deleteBtn = api.createElement('button');
                    deleteBtn.textContent = 'Delete Permanently';
                    deleteBtn.style.cssText = 'padding: 8px 16px; cursor: pointer; border: none; background: var(--color-danger, #e74c3c); color: white; border-radius: var(--border-radius);';
                    deleteBtn.onclick = () => { resolved = true; close(); resolve('delete'); };
                    btnRow.appendChild(deleteBtn);

                    el.appendChild(btnRow);
                    return el;
                  }
                });
              });

              if (!action) return;

              const freshPage = await api.get(pageItem.id);
              const freshChildren = freshPage.attachments || [];
              const filtered = freshChildren.filter(c => (typeof c === 'string' ? c : c.id) !== id);
              await api.updateSilent({ ...freshPage, attachments: filtered, modified: Date.now() });

              if (action === 'delete') {
                await api.delete(id);
              }

              renderPage();
            },
            onEdit: async (id) => {
              const parentId = api.getParentId();
              if (parentId) {
                api.attach(parentId, id);
              } else {
                api.navigate(id);
              }
            }
          });
          grid.appendChild(designCell);
        } else {
          // Live mode: standard grid cell
          const col = viewConfig.col || 1;
          const row = viewConfig.row || 'auto';
          const colSpan = viewConfig.colSpan || columns;
          const rowSpan = viewConfig.rowSpan || 1;

          const cell = api.createElement('div', {
            style: `
              grid-column: ${col} / span ${colSpan};
              ${row !== 'auto' ? `grid-row: ${row} / span ${rowSpan};` : ''}
              min-width: 0;
              overflow: auto;
              padding: 4px 0;
            `,
            'data-item-id': childId
          });

          cell.appendChild(widgetElement);
          grid.appendChild(cell);
        }
      } catch (err) {
        window.kernel?.captureError(err, { operation: 'app-page-load-child', itemId: childId });
        const errorCell = api.createElement('div', {
          style: 'color: var(--color-danger, #e74c3c); padding: 8px; font-size: 0.8125rem;'
        });
        errorCell.textContent = `Failed to load widget ${childId}: ${err.message}`;
        grid.appendChild(errorCell);
      }
    }

    wrapper.appendChild(grid);

    // Fill :render-child mount points (Hob view widgets).
    // On initial render the rendering system also fills after render() returns,
    // but for design-mode re-renders we need to trigger it explicitly.
    if (api.fillMountPoints) {
      await api.fillMountPoints(wrapper);
    }
  }

  // Initial render
  await renderPage();

  return wrapper;
}
// [END:render]

// Selection Manager Library
// Handles item selection state via events, replacing kernel viewport selection

const SELECTION_CHANGED = "e0e00000-0003-0001-0000-000000000000";

// State lives on globalThis so it survives moduleSystem.clearCache()
const CACHE_KEY = '__selectionManager__';
if (!globalThis[CACHE_KEY]) {
  globalThis[CACHE_KEY] = {
    selectedItemId: null,
    selectedParentId: null,
    api: null,
  };
}
const S = globalThis[CACHE_KEY];

// Called at boot
export async function onKernelBootComplete({ safeMode }, _api) {
  if (safeMode) return;  // No selection in safe mode

  S.api = _api;

  // Emit initial selection state
  S.api.events.emit({
    type: SELECTION_CHANGED,
    content: {
      current: { itemId: null, parentId: null },
      previous: null
    }
  });
}

// Public API - called by views or other code
export function select(itemId, parentId = null) {
  const previous = { itemId: S.selectedItemId, parentId: S.selectedParentId };
  S.selectedItemId = itemId;
  S.selectedParentId = parentId;

  if (S.api) {
    S.api.events.emit({
      type: SELECTION_CHANGED,
      content: {
        current: { itemId: S.selectedItemId, parentId: S.selectedParentId },
        previous
      }
    });
  }
}

export function clearSelection() {
  select(null, null);
}

export function getSelection() {
  return S.selectedItemId;
}

export function getSelectionParent() {
  return S.selectedParentId;
}

// Viewport Manager Library
// Reads from URL (root) and viewport item (view config).
// RenderingSystem singleton is managed by viewport-rendering module.

const VIEWPORT_ID_DESKTOP = "88888888-0000-0000-0000-000000000000";
const VIEWPORT_ID_MOBILE = "88888888-0001-0000-0000-000000000000";
let activeViewportId = VIEWPORT_ID_DESKTOP;

export function getViewportId() { return activeViewportId; }

const VIEWPORT_RENDERING_ID = "f1111111-0008-0000-0000-000000000000";
const EVENT_IDS = {
  VIEWPORT_ROOT_CHANGED: "e0e00000-0003-0002-0000-000000000000",
  VIEWPORT_SELECTION_CHANGED: "e0e00000-0003-0001-0000-000000000000",
  VIEWPORT_READY: "e0e00000-0003-0003-0000-000000000000"
};

// ============================================================================
// Boot handler — initializes the rendering singleton and performs first render
// ============================================================================

export async function onKernelBootComplete({ safeMode, rootElement }, _api) {
  if (safeMode) return;

  // Load viewport-rendering and initialize its singleton
  const vpRendering = await window.kernel.moduleSystem.require(VIEWPORT_RENDERING_ID);
  const rs = vpRendering.getRendering();
  rs.rootElement = rootElement;

  // Resolve active viewport based on environment
  activeViewportId = (rs.env.touch || rs.env.pointer === 'coarse')
    ? VIEWPORT_ID_MOBILE : VIEWPORT_ID_DESKTOP;

  // Register popstate handler for browser back/forward
  if (!window._hobsonPopstateHandler) {
    window._hobsonPopstateHandler = handlePopstate;
    window.addEventListener('popstate', handlePopstate);
  }

  // Sync URL ↔ viewport item
  let urlRoot = getRoot();
  if (urlRoot) {
    const viewport = await window.kernel.storage.get(activeViewportId);
    const currentChild = viewport.attachments?.[0];
    if (currentChild?.id !== urlRoot) {
      await persistRootChange(urlRoot, currentChild?.id);
    }
  } else {
    // No ?root= in URL (Tauri default, direct file load) — populate from stored state
    const viewport = await window.kernel.storage.get(activeViewportId);
    const storedRoot = viewport.attachments?.[0]?.id
      || (typeof viewport.attachments?.[0] === 'string' ? viewport.attachments[0] : null);
    if (storedRoot) {
      const url = new URL(window.location);
      url.searchParams.set('root', storedRoot);
      window.history.replaceState({ itemId: storedRoot }, '', url);
      urlRoot = storedRoot;
    }
  }

  // Initial render
  await rs.renderViewport();

  // Signal that viewport infrastructure is ready (sticky: replays for late subscribers)
  window.kernel.events.emit({
    type: EVENT_IDS.VIEWPORT_READY,
    content: {
      rootElement,
      rootId: urlRoot || null
    }
  }, { sticky: true });
}

// ============================================================================
// Internal helpers
// ============================================================================

async function handlePopstate(e) {
  const urlRoot = getRoot();
  if (urlRoot) {
    const viewport = await window.kernel.storage.get(activeViewportId);
    const previous = viewport.attachments?.[0]?.id;

    if (previous !== urlRoot) {
      await persistRootChange(urlRoot, previous);
    }

    window.kernel.events.emit({
      type: EVENT_IDS.VIEWPORT_ROOT_CHANGED,
      content: { rootId: urlRoot, previous, initial: false, popstate: true }
    });

    const rs = await getRenderingAsync();
    if (rs) await rs.renderViewport();
  }
}

async function persistRootChange(newRootId, previousRootId, viewId) {
  const viewport = await window.kernel.storage.get(activeViewportId);
  if (newRootId === previousRootId && !viewId) return;

  const spec = newRootId ? { id: newRootId } : null;
  if (spec && viewId) spec.view = { type: viewId };

  viewport.attachments = spec ? [spec] : [];
  viewport.modified = Date.now();
  await window.kernel.saveItem(viewport, { silent: true });
}

async function getChildSpec() {
  try {
    const viewport = await window.kernel.storage.get(activeViewportId);
    return viewport.attachments?.[0] || null;
  } catch (e) {
    console.warn('[viewport-manager] Failed to read viewport item:', e);
    return null;
  }
}

async function updateChildSpec(updater) {
  try {
    const viewport = await window.kernel.storage.get(activeViewportId);
    const root = getRoot()
      || (viewport.attachments?.[0]?.id)
      || (typeof viewport.attachments?.[0] === 'string' ? viewport.attachments[0] : null);
    if (!root) return;

    let childSpec = viewport.attachments?.[0];
    if (!childSpec || childSpec.id !== root) {
      childSpec = { id: root };
    }

    const updated = updater(childSpec);
    viewport.attachments = [updated];
    viewport.modified = Date.now();
    await window.kernel.saveItem(viewport, { silent: true });
  } catch (e) {
    console.warn('[viewport-manager] Failed to update viewport item:', e);
  }
}

// ============================================================================
// Public API — exported functions delegate to the singleton
// ============================================================================

/** Get the RenderingSystem synchronously (returns null if not yet initialized). */
export function getRendering() {
  const vpRendering = window.kernel?.moduleSystem?.getCached(VIEWPORT_RENDERING_ID);
  return vpRendering?.getRendering() || null;
}

/** Get the RenderingSystem asynchronously (loads viewport-rendering if needed). */
async function getRenderingAsync() {
  const vpRendering = await window.kernel.moduleSystem.require(VIEWPORT_RENDERING_ID);
  return vpRendering.getRendering();
}

export async function navigate(itemId, params = {}) {
  const { view, ...urlParams } = params;

  const viewport = await window.kernel.storage.get(activeViewportId);
  const previous = viewport.attachments?.[0]?.id;

  const url = new URL(window.location);
  url.searchParams.set('root', itemId);
  url.searchParams.delete('field');
  url.searchParams.delete('line');
  url.searchParams.delete('col');
  url.searchParams.delete('symbol');
  url.searchParams.delete('region');

  if (urlParams.field) url.searchParams.set('field', urlParams.field);
  if (urlParams.line) url.searchParams.set('line', urlParams.line);
  if (urlParams.col) url.searchParams.set('col', urlParams.col);
  if (urlParams.symbol) url.searchParams.set('symbol', urlParams.symbol);
  if (urlParams.region) url.searchParams.set('region', urlParams.region);

  if (url.href !== window.location.href) {
    window.history.pushState({ itemId, ...urlParams }, '', url);
  }

  await persistRootChange(itemId, previous, view);

  window.kernel.events.emit({
    type: EVENT_IDS.VIEWPORT_ROOT_CHANGED,
    content: { rootId: itemId, previous, initial: false, popstate: false }
  });

  const rs = await getRenderingAsync();
  if (rs) await rs.renderViewport();
}

export function getRoot() {
  const params = new URLSearchParams(window.location.search);
  return params.get('root');
}

export async function getRootView() {
  const child = await getChildSpec();
  if (!child) return null;
  return child.view?.type || child.view || child.renderer || null;
}

export async function setRootView(viewId, storePrevious = true) {
  const childSpec = await getChildSpec();
  const currentViewType = childSpec?.view?.type;

  // No-op if already on this view
  if (currentViewType === viewId) return;

  // Look up saved state for target view
  const savedState = viewId ? childSpec?.savedViewStates?.[viewId] : null;

  // Update viewport spec atomically: save current state, set new view
  await updateChildSpec(child => {
    const newChild = { ...child };
    const savedViewStates = { ...(child.savedViewStates || {}) };

    // Save current view state to map
    if (storePrevious && currentViewType && child.view) {
      savedViewStates[currentViewType] = {
        viewConfig: { ...child.view }
      };
    }

    // Set new view (restore from saved or fresh)
    if (savedState) {
      newChild.view = { ...savedState.viewConfig };
      delete savedViewStates[viewId];
    } else if (viewId) {
      newChild.view = { type: viewId };
    } else {
      delete newChild.view;
    }

    newChild.savedViewStates = Object.keys(savedViewStates).length > 0 ? savedViewStates : undefined;
    if (currentViewType) newChild.previousViewType = currentViewType;
    delete newChild.previousView; // migrate away from legacy
    return newChild;
  });
}

export async function getRootViewConfig() {
  const child = await getChildSpec();
  if (!child?.view) return null;
  if (typeof child.view === 'object') return child.view;
  return { type: child.view };
}

export async function updateRootViewConfig(updates) {
  await updateChildSpec(child => {
    const currentView = child.view || {};
    return { ...child, view: { ...currentView, ...updates } };
  });
}

export async function restorePreviousRootView() {
  const child = await getChildSpec();
  // New mechanism: switch to the previous view type via savedViewStates
  if (child?.previousViewType) {
    await setRootView(child.previousViewType);
    return true;
  }
  // Legacy fallback: old previousView field
  if (child?.previousView) {
    await setRootView(child.previousView.type);
    return true;
  }
  return false;
}

export async function hasPreviousView() {
  const child = await getChildSpec();
  return !!(child?.previousViewType || child?.previousView);
}

// No-op — kept for API compatibility
export async function forcePersist() {}

